// src/i18n/catalogues/hi/ui.agents.descriptions.json
var ui_agents_descriptions_default4 = {
  "ui.agents.descriptions.aida": "\u0906\u092A\u0915\u0940 \u091A\u0940\u092B\u093C \u0911\u092B\u093C \u0938\u094D\u091F\u093E\u092B\u093C: \u0906\u092A\u0915\u0940 \u0913\u0930 \u0938\u0947 \u090F\u091C\u0947\u0902\u091F \u0914\u0930 \u091F\u0940\u092E\u0947\u0902 \u091A\u0932\u093E\u0924\u0940 \u0939\u0948\u0902, \u091A\u0932 \u0930\u0939\u0947 \u0939\u0930 \u0915\u093E\u092E \u092A\u0930 \u0928\u091C\u093C\u0930 \u0930\u0916\u0924\u0940 \u0939\u0948\u0902 \u0914\u0930 \u0906\u092A\u0915\u094B \u0939\u093E\u0932 \u092C\u0924\u093E\u0924\u0940 \u0939\u0948\u0902\u0964",
  "ui.agents.descriptions.architect": "\u0915\u094B\u0921\u092C\u0947\u0938 \u0915\u0940 \u092A\u0921\u093C\u0924\u093E\u0932 \u0915\u0930\u0915\u0947 \u0917\u0941\u0923-\u0926\u094B\u0937\u094B\u0902 \u0915\u0947 \u0938\u093E\u0925 \u0921\u093F\u091C\u093C\u093E\u0907\u0928 \u092F\u093E \u0924\u0915\u0928\u0940\u0915\u0940 \u092A\u094D\u0930\u0938\u094D\u0924\u093E\u0935 \u092C\u0928\u093E\u0924\u093E \u0939\u0948; \u0926\u0938\u094D\u0924\u093E\u0935\u0947\u091C\u093C\u094B\u0902 \u0915\u093E \u092E\u0938\u094C\u0926\u093E \u092C\u0928\u093E \u0938\u0915\u0924\u093E \u0939\u0948, \u092A\u0930 \u092E\u094C\u091C\u0942\u0926\u093E \u0938\u094D\u0930\u094B\u0924 \u0915\u094B\u0921 \u0915\u092D\u0940 \u0928\u0939\u0940\u0902 \u092C\u0926\u0932\u0924\u093E\u0964",
  "ui.agents.descriptions.coder": "\u092A\u0942\u0930\u0947 \u091F\u0942\u0932\u0938\u0947\u091F \u0915\u0947 \u0938\u093E\u0925 \u0915\u093E\u092E \u0915\u093E \u090F\u0915 \u0938\u0940\u092E\u093F\u0924 \u0939\u093F\u0938\u094D\u0938\u093E \u0936\u0941\u0930\u0942 \u0938\u0947 \u0905\u0902\u0924 \u0924\u0915 \u092A\u0942\u0930\u093E \u0915\u0930\u0924\u093E \u0939\u0948, \u092B\u093F\u0930 \u092C\u0924\u093E\u0924\u093E \u0939\u0948 \u0915\u093F \u0915\u094D\u092F\u093E \u092C\u0926\u0932\u093E \u0914\u0930 \u0909\u0938\u0947 \u0915\u0948\u0938\u0947 \u091C\u093E\u0901\u091A\u093E \u0917\u092F\u093E\u0964",
  "ui.agents.descriptions.copy_reviewer": "\u0930\u093F\u0932\u0940\u091C\u093C \u0938\u0947 \u092A\u0939\u0932\u0947 \u0932\u093F\u0916\u093F\u0924 \u0938\u093E\u092E\u0917\u094D\u0930\u0940 \u0915\u0940 \u0938\u092E\u0940\u0915\u094D\u0937\u093E: \u0909\u092A\u092F\u094B\u0917\u0915\u0930\u094D\u0924\u093E \u0915\u094B \u0926\u093F\u0916\u0928\u0947 \u0935\u093E\u0932\u093E \u092A\u094D\u0930\u094B\u0921\u0915\u094D\u091F \u091F\u0947\u0915\u094D\u0938\u094D\u091F \u0914\u0930 \u0906\u092E \u092A\u093E\u0920\u0915 \u0915\u0947 \u0932\u093F\u090F \u0917\u0926\u094D\u092F \u2014 \u0938\u092E\u091D, \u0932\u0939\u091C\u093E, \u0926\u093E\u0935\u094B\u0902 \u0915\u093E \u0906\u0927\u093E\u0930 \u0914\u0930 AI \u091C\u0948\u0938\u0940 \u092C\u0928\u093E\u0935\u091F\u0940 \u092C\u093E\u0924\u0947\u0902; \u092E\u0941\u0926\u094D\u0926\u0947 C-\u0909\u092A\u0938\u0930\u094D\u0917 \u0915\u0947 \u0938\u093E\u0925 \u092C\u0924\u093E\u0924\u093E \u0939\u0948\u0964",
  "ui.agents.descriptions.designer": "\u0909\u092A\u092F\u094B\u0917\u0915\u0930\u094D\u0924\u093E \u0915\u094B \u0926\u093F\u0916\u0928\u0947 \u0935\u093E\u0932\u0947 \u092C\u0926\u0932\u093E\u0935 \u0915\u0940 \u0921\u093F\u091C\u093C\u093E\u0907\u0928 \u0914\u0930 UX \u0938\u092E\u0940\u0915\u094D\u0937\u093E, \u0938\u094D\u0930\u094B\u0924 \u0915\u0947 \u092C\u091C\u093E\u092F \u0930\u0947\u0902\u0921\u0930 \u0915\u093F\u090F \u0917\u090F \u092B\u093C\u094D\u0930\u0947\u092E \u0938\u0947; \u092E\u0941\u0926\u094D\u0926\u0947 D-\u0909\u092A\u0938\u0930\u094D\u0917 \u0915\u0947 \u0938\u093E\u0925 \u092C\u0924\u093E\u0924\u093E \u0939\u0948\u0964",
  "ui.agents.descriptions.librarian": "\u0932\u093E\u0907\u092C\u094D\u0930\u0947\u0930\u0940 \u0915\u093E \u0935\u094D\u092F\u0935\u0938\u094D\u0925\u093E\u092A\u0915 \u090F\u091C\u0947\u0902\u091F: \u0911\u092A\u0930\u0947\u091F\u0930 \u0915\u0947 \u0930\u0916\u0947 \u090F\u0938\u0947\u091F\u094D\u0938 \u0915\u094B \u0928\u093E\u092E, \u0935\u093F\u0935\u0930\u0923 \u0914\u0930 \u091F\u0948\u0917 \u0926\u0947\u0924\u093E \u0939\u0948, \u0909\u0928\u0915\u0940 \u0936\u092C\u094D\u0926\u093E\u0935\u0932\u0940 \u0938\u0940\u0916\u0924\u093E \u0939\u0948 \u0914\u0930 \u0935\u0948\u0936\u094D\u0935\u093F\u0915 \u0915\u0948\u091F\u0932\u0949\u0917 \u0915\u094B \u0909\u092A\u092F\u094B\u0917\u0940 \u092C\u0928\u093E\u090F \u0930\u0916\u0924\u093E \u0939\u0948\u0964",
  "ui.agents.descriptions.manager": "\u0938\u094C\u0902\u092A\u0947 \u0917\u090F \u0915\u093E\u092E \u0915\u093E \u0938\u092E\u0928\u094D\u0935\u092F \u0915\u0930\u0924\u093E \u0939\u0948 \u0914\u0930 \u0938\u091A\u094D\u091A\u0940 \u0938\u094D\u0925\u093F\u0924\u093F \u092C\u0924\u093E\u0924\u093E \u0939\u0948: \u0915\u094D\u092F\u093E \u092A\u0942\u0930\u093E \u0939\u0941\u0906, \u0915\u094D\u092F\u093E \u091A\u0932 \u0930\u0939\u093E \u0939\u0948, \u0915\u094D\u092F\u093E \u0905\u091F\u0915\u093E \u0939\u0948 \u0914\u0930 \u0915\u093F\u0938 \u092A\u0930\u0964",
  "ui.agents.descriptions.qa_tester": "\u0915\u093F\u0938\u0940 \u092C\u0926\u0932\u093E\u0935 \u0915\u093E \u0938\u094D\u0935\u0924\u0902\u0924\u094D\u0930 \u0928\u093F\u0937\u094D\u092A\u093E\u0926\u0928 \u092A\u094D\u0930\u092E\u093E\u0923: \u0930\u093F\u0917 \u0915\u0940 \u092A\u0942\u0930\u094D\u0935-\u091C\u093E\u0901\u091A \u0915\u0930\u0924\u093E \u0939\u0948, \u0905\u0938\u0932\u0940 \u0930\u093E\u0938\u094D\u0924\u0947 \u0914\u0930 \u0928\u0915\u093E\u0930\u093E\u0924\u094D\u092E\u0915 \u092E\u093E\u092E\u0932\u0947 \u091A\u0932\u093E\u0924\u093E \u0939\u0948, \u0914\u0930 \u0930\u0947\u092A\u094B \u092C\u0926\u0932\u0947 \u092C\u093F\u0928\u093E \u0938\u0940\u092E\u093F\u0924 \u0926\u093E\u092F\u0930\u0947 \u0915\u093E QA \u092E\u0948\u091F\u094D\u0930\u093F\u0915\u094D\u0938 \u092C\u0924\u093E\u0924\u093E \u0939\u0948\u0964",
  "ui.agents.descriptions.reviewer": "diff, MR \u092F\u093E PR \u0915\u0940 \u0938\u094D\u0935\u0924\u0902\u0924\u094D\u0930 \u0915\u094B\u0921 \u0938\u092E\u0940\u0915\u094D\u0937\u093E: \u0916\u093E\u092E\u093F\u092F\u093E\u0901 \u0922\u0942\u0901\u0922\u0924\u093E \u0939\u0948, \u0917\u0902\u092D\u0940\u0930\u0924\u093E \u0915\u0947 \u0905\u0928\u0941\u0938\u093E\u0930 \u0909\u0928\u094D\u0939\u0947\u0902 \u0935\u0930\u094D\u0917\u0940\u0915\u0943\u0924 \u0915\u0930\u0924\u093E \u0939\u0948, \u0914\u0930 \u091C\u093F\u0938 \u0915\u094B\u0921 \u0915\u0940 \u0938\u092E\u0940\u0915\u094D\u0937\u093E \u0915\u0930\u0924\u093E \u0939\u0948 \u0909\u0938\u0947 \u0915\u092D\u0940 \u0928\u0939\u0940\u0902 \u092C\u0926\u0932\u0924\u093E\u0964",
  "ui.agents.descriptions.scout": "\u0915\u0947\u0935\u0932-\u092A\u0920\u0928 \u0936\u094B\u0927: \u0915\u093F\u0938\u0940 \u0938\u0935\u093E\u0932 \u0915\u0940 \u092A\u0921\u093C\u0924\u093E\u0932 \u0915\u093E\u0930\u094D\u092F\u0915\u094D\u0937\u0947\u0924\u094D\u0930 \u0914\u0930 \u0935\u0947\u092C \u092A\u0930 \u0915\u0930\u0924\u093E \u0939\u0948, \u0914\u0930 \u0938\u092C\u0942\u0924 \u0915\u0947 \u0938\u093E\u0925 \u0928\u0924\u0940\u091C\u0947 \u092C\u0924\u093E\u0924\u093E \u0939\u0948\u0964 \u0915\u0941\u091B \u0928\u0939\u0940\u0902 \u092C\u0926\u0932\u0924\u093E\u0964",
  "ui.agents.descriptions.tui_designer": "\u091F\u0930\u094D\u092E\u093F\u0928\u0932 \u0907\u0902\u091F\u0930\u092B\u093C\u0947\u0938 \u0915\u093E \u0921\u093F\u091C\u093C\u093E\u0907\u0928 \u0914\u0930 \u0938\u092E\u0940\u0915\u094D\u0937\u093E: \u0915\u0940\u092C\u094B\u0930\u094D\u0921 \u0938\u0947 \u091A\u0932\u0928\u0947 \u0935\u093E\u0932\u0947 \u092B\u093C\u094D\u0932\u094B, \u091B\u094B\u091F\u0947 \u0924\u092F \u0935\u094D\u092F\u0942\u092A\u094B\u0930\u094D\u091F \u092E\u0947\u0902 \u0918\u0928\u0924\u094D\u0935, \u0930\u0902\u0917 \u0914\u0930 unicode \u0915\u0947 \u092B\u093C\u0949\u0932\u092C\u0948\u0915, \u0928\u093E\u092A\u0940 \u0917\u0908 \u091C\u094D\u092F\u093E\u092E\u093F\u0924\u093F; \u092E\u0941\u0926\u094D\u0926\u0947 T-\u0909\u092A\u0938\u0930\u094D\u0917 \u0915\u0947 \u0938\u093E\u0925 \u092C\u0924\u093E\u0924\u093E \u0939\u0948\u0964",
  "ui.agents.descriptions.ux_reviewer": "\u0915\u093F\u0938\u0940 \u092C\u0926\u0932\u093E\u0935 \u0915\u0947 \u0905\u0938\u0932\u0940 \u092B\u093C\u094D\u0932\u094B \u0915\u094B \u0936\u0941\u0930\u0942 \u0938\u0947 \u0905\u0902\u0924 \u0924\u0915 \u091A\u0932\u0915\u0930 \u0926\u0947\u0916\u0924\u093E \u0939\u0948: \u092A\u0924\u093E \u0932\u0917\u0928\u0947 \u0915\u0940 \u0938\u0941\u0917\u092E\u0924\u093E, \u092B\u093C\u0940\u0921\u092C\u0948\u0915, \u0924\u094D\u0930\u0941\u091F\u093F \u0938\u0947 \u0909\u092C\u0930\u0928\u093E, \u0915\u0940\u092C\u094B\u0930\u094D\u0921 \u0915\u0947 \u0930\u093E\u0938\u094D\u0924\u0947 \u0914\u0930 \u091F\u0947\u0915\u094D\u0938\u094D\u091F; \u092E\u0941\u0926\u094D\u0926\u0947 U-\u0909\u092A\u0938\u0930\u094D\u0917 \u0915\u0947 \u0938\u093E\u0925 \u092C\u0924\u093E\u0924\u093E \u0939\u0948\u0964"
};

