  "ui.agents.settings.chat.random_number_seed_for_deterministic_generation": "\u0939\u0930 \u092C\u093E\u0930 \u090F\u0915 \u091C\u0948\u0938\u093E \u0906\u0909\u091F\u092A\u0941\u091F \u092C\u0928\u093E\u0928\u0947 \u0915\u0947 \u0932\u093F\u090F \u0930\u0948\u0902\u0921\u092E \u0928\u0902\u092C\u0930 \u0938\u0940\u0921\u0964",
