  "ui.agents.settings.chat.max_tokens": "\u0905\u0927\u093F\u0915\u0924\u092E \u091F\u094B\u0915\u0928",
  "ui.agents.settings.chat.maximum_tokens_to_generate_in_response": "\u091C\u0935\u093E\u092C \u092E\u0947\u0902 \u092C\u0928\u093E\u090F \u091C\u093E\u0928\u0947 \u0935\u093E\u0932\u0947 \u091F\u094B\u0915\u0928\u094B\u0902 \u0915\u0940 \u0905\u0927\u093F\u0915\u0924\u092E \u0938\u0902\u0916\u094D\u092F\u093E\u0964",
  "ui.agents.settings.chat.stop_sequences": "\u0930\u094B\u0915\u0928\u0947 \u0935\u093E\u0932\u0947 \u0915\u094D\u0930\u092E",
  "ui.agents.settings.chat.sequences_that_will_cause_the_model_to": "\u0910\u0938\u0947 \u0915\u094D\u0930\u092E \u091C\u093F\u0928\u0938\u0947 \u092E\u0949\u0921\u0932 \u091F\u0947\u0915\u094D\u0938\u094D\u091F \u092C\u0928\u093E\u0928\u093E \u0930\u094B\u0915 \u0926\u0947\u0917\u093E\u0964",
  "ui.agents.settings.chat.empty": "\u0916\u093E\u0932\u0940",
  "ui.agents.settings.chat.enter_stop_sequences_one_per_line": "\u0930\u094B\u0915\u0928\u0947 \u0935\u093E\u0932\u0947 \u0915\u094D\u0930\u092E \u0926\u0930\u094D\u091C \u0915\u0930\u0947\u0902 (\u0939\u0930 \u092A\u0902\u0915\u094D\u0924\u093F \u092E\u0947\u0902 \u090F\u0915)...",
  "ui.agents.settings.general.agent_name": "\u090F\u091C\u0947\u0902\u091F \u0915\u093E \u0928\u093E\u092E",
  "ui.agents.settings.general.enter_agent_name": "\u090F\u091C\u0947\u0902\u091F \u0915\u093E \u0928\u093E\u092E \u0926\u0930\u094D\u091C \u0915\u0930\u0947\u0902...",
  "ui.agents.settings.general.select_a_hosting_provider_first_and_then": "\u092A\u0939\u0932\u0947 \u0939\u094B\u0938\u094D\u091F\u093F\u0902\u0917 \u092A\u094D\u0930\u094B\u0935\u093E\u0907\u0921\u0930 \u091A\u0941\u0928\u0947\u0902, \u092B\u093F\u0930 \u0935\u0939 AI \u092E\u0949\u0921\u0932 \u091A\u0941\u0928\u0947\u0902 \u091C\u093F\u0938\u0947 \u0906\u092A \u0907\u0938\u094D\u0924\u0947\u092E\u093E\u0932 \u0915\u0930\u0928\u093E \u091A\u093E\u0939\u0924\u0947 \u0939\u0948\u0902\u0964  \u0939\u0930 \u092E\u0949\u0921\u0932 \u0915\u0940 \u0915\u094D\u0937\u092E\u0924\u093E\u090F\u0901 \u0914\u0930 \u0932\u093E\u0917\u0924 \u0905\u0932\u0917 \u0939\u0948\u0902\u0964  \u0938\u0941\u091D\u093E\u0935: \u0905\u092A\u0928\u0947-\u0906\u092A",
  "ui.agents.settings.general.model": "\u092E\u0949\u0921\u0932",
