  "ui.agents.settings.general.add_category": "\u0936\u094D\u0930\u0947\u0923\u0940 \u091C\u094B\u0921\u093C\u0947\u0902...",
  "ui.agents.settings.general.id": "ID",
  "ui.agents.settings.general.created": "\u092C\u0928\u093E\u092F\u093E \u0917\u092F\u093E",
  "ui.agents.settings.general.version": "\u0938\u0902\u0938\u094D\u0915\u0930\u0923",
  "ui.agents.settings.security.security_instructions": "\u0938\u0941\u0930\u0915\u094D\u0937\u093E \u0928\u093F\u0930\u094D\u0926\u0947\u0936",
  "ui.agents.settings.security.about_security_instructions": "\u0938\u0941\u0930\u0915\u094D\u0937\u093E \u0928\u093F\u0930\u094D\u0926\u0947\u0936\u094B\u0902 \u0915\u0947 \u092C\u093E\u0930\u0947 \u092E\u0947\u0902",
  "ui.agents.settings.security.this_prompt_is_directed_to_the_ai": '\u092F\u0939 \u092A\u094D\u0930\u0949\u092E\u094D\u092A\u094D\u091F AI \u0938\u0941\u0930\u0915\u094D\u0937\u093E \u0938\u092E\u0940\u0915\u094D\u0937\u0915 \u0915\u0947 \u0932\u093F\u090F \u0939\u0948\u0964 \u0907\u0938\u0938\u0947 \u0938\u092E\u0940\u0915\u094D\u0937\u0915 \u0938\u0941\u0930\u0915\u094D\u0937\u093E \u0915\u0947 \u0906\u0927\u093E\u0930 \u092A\u0930 \u0915\u093E\u0930\u094D\u0930\u0935\u093E\u0907\u092F\u093E\u0901 \u0930\u094B\u0915\u0928\u0947 \u092F\u093E \u0905\u0928\u0941\u092E\u0924\u093F \u0926\u0947\u0928\u0947 \u0915\u093E \u092B\u093C\u0948\u0938\u0932\u093E \u0915\u0930\u0924\u093E \u0939\u0948\u0964 \u0910\u0938\u0947 \u0932\u093F\u0916\u0947\u0902 \u091C\u0948\u0938\u0947 \u0907\u0938 \u090F\u091C\u0947\u0902\u091F \u092A\u0930 \u0928\u091C\u093C\u0930 \u0930\u0916\u0928\u0947 \u0935\u093E\u0932\u0947 \u0915\u093F\u0938\u0940 \u0926\u0942\u0938\u0930\u0947 \u090F\u091C\u0947\u0902\u091F \u0938\u0947 \u092C\u093E\u0924 \u0915\u0930 \u0930\u0939\u0947 \u0939\u094B\u0902 (\u091C\u0948\u0938\u0947 "\u0938\u092D\u0940 git \u0915\u093E\u0930\u094D\u0930\u0935\u093E\u0907\u092F\u094B\u0902 \u0915\u0940 \u0905\u0928\u0941\u092E\u0924\u093F \u0926\u0947\u0902", "\u090F\u091C\u0947\u0902\u091F \u0915\u094B \u092A\u094D\u0930\u0924\u093F\u092C\u0902\u0927\u093F\u0924 \u092B\u093C\u094B\u0932\u094D\u0921\u0930 \u092E\u0947\u0902 drive \u092B\u093C\u093E\u0907\u0932\u0947\u0902 \u0928 \u0916\u094B\u0932\u0928\u0947 \u0926\u0947\u0902")\u0964 \u0905\u0917\u0930 \u0938\u0941\u0930\u0915\u094D\u0937\u093E \u0915\u0947 \u0915\u093E\u0930\u0923 \u092C\u093E\u0930-\u092C\u093E\u0930 \u0930\u094B\u0915 \u0932\u0917 \u0930\u0939\u0940 \u0939\u0948, \u0924\u094B \u090F\u091C\u0947\u0902\u091F \u0915\u094B \u0915\u093E\u0930\u094D\u0930\u0935\u093E\u0907\u092F\u094B\u0902 \u0915\u0940 \u0905\u0928\u0941\u092E\u0924\u093F \u0926\u0947\u0928\u0947 \u0915\u0947 \u0932\u093F\u090F \u0907\u0938\u0947 \u0905\u092A\u0921\u0947\u091F \u0915\u0930\u0947\u0902\u0964',
  "ui.agents.settings.security.enter_instructions_for_the_security_agent": "\u0938\u0941\u0930\u0915\u094D\u0937\u093E \u090F\u091C\u0947\u0902\u091F \u0915\u0947 \u0932\u093F\u090F \u0928\u093F\u0930\u094D\u0926\u0947\u0936 \u0926\u0930\u094D\u091C \u0915\u0930\u0947\u0902...",
  "ui.agents.settings.system_prompt.agent_instructions": "\u090F\u091C\u0947\u0902\u091F \u0915\u0947 \u0928\u093F\u0930\u094D\u0926\u0947\u0936",
  "ui.agents.settings.system_prompt.about_agent_instructions": "\u090F\u091C\u0947\u0902\u091F \u0915\u0947 \u0928\u093F\u0930\u094D\u0926\u0947\u0936\u094B\u0902 \u0915\u0947 \u092C\u093E\u0930\u0947 \u092E\u0947\u0902",
  "ui.agents.settings.system_prompt.define_the_agent_s_role_personality_or": '\u090F\u091C\u0947\u0902\u091F \u0915\u0940 \u092D\u0942\u092E\u093F\u0915\u093E, \u0935\u094D\u092F\u0915\u094D\u0924\u093F\u0924\u094D\u0935 \u0924\u092F \u0915\u0930\u0947\u0902 \u092F\u093E \u0938\u0902\u0926\u0930\u094D\u092D \u0926\u0947\u0902\u0964 \u0910\u0938\u0947 \u0932\u093F\u0916\u0947\u0902 \u091C\u0948\u0938\u0947 \u090F\u091C\u0947\u0902\u091F \u0938\u0947 \u092C\u093E\u0924 \u0915\u0930 \u0930\u0939\u0947 \u0939\u094B\u0902 (\u091C\u0948\u0938\u0947, "\u0906\u092A \u090F\u0915 \u0935\u093F\u0936\u0947\u0937\u091C\u094D\u091E \u0936\u094B\u0927\u0915\u0930\u094D\u0924\u093E \u0939\u0948\u0902") \u0914\u0930/\u092F\u093E \u0905\u092A\u0928\u0947 \u092C\u093E\u0930\u0947 \u092E\u0947\u0902 \u092C\u0924\u093E \u0930\u0939\u0947 \u0939\u094B\u0902 (\u091C\u0948\u0938\u0947, "\u092E\u0947\u0930\u093E \u0928\u093E\u092E John \u0939\u0948")\u0964',
  "ui.agents.settings.system_prompt.loading_system_prompt": "\u0938\u093F\u0938\u094D\u091F\u092E \u092A\u094D\u0930\u0949\u092E\u094D\u092A\u094D\u091F \u0932\u094B\u0921 \u0939\u094B \u0930\u0939\u093E \u0939\u0948...",
  "ui.agents.settings.system_prompt.enter_instructions_for_the_agent": "\u090F\u091C\u0947\u0902\u091F \u0915\u0947 \u0932\u093F\u090F \u0928\u093F\u0930\u094D\u0926\u0947\u0936 \u0926\u0930\u094D\u091C \u0915\u0930\u0947\u0902...",
  "ui.agents.settings.agent.no_agent_selected": "\u0915\u094B\u0908 \u090F\u091C\u0947\u0902\u091F \u0928\u0939\u0940\u0902 \u091A\u0941\u0928\u093E \u0917\u092F\u093E",
  "ui.agents.settings.agent.select_an_agent_from_the_list_on": "\u090F\u091C\u0947\u0902\u091F \u0915\u093E \u0915\u0949\u0928\u094D\u092B\u093C\u093F\u0917\u0930\u0947\u0936\u0928 \u0914\u0930 \u091C\u093E\u0928\u0915\u093E\u0930\u0940 \u0926\u0947\u0916\u0928\u0947 \u0915\u0947 \u0932\u093F\u090F \u092C\u093E\u0908\u0902 \u0938\u0942\u091A\u0940 \u0938\u0947 \u090F\u091C\u0947\u0902\u091F \u091A\u0941\u0928\u0947\u0902\u0964",
