  "ui.agents.skills.action.remove_confirm": "\u0939\u091F\u093E\u090F\u0901",
  "ui.agents.skills.alert.builtin_body": "\u092F\u0939 Local Operator \u0915\u0947 \u0938\u093E\u0925 \u0906\u0924\u093E \u0939\u0948 \u0914\u0930 \u092F\u0939\u093E\u0901 \u092C\u0926\u0932\u093E \u0928\u0939\u0940\u0902 \u091C\u093E \u0938\u0915\u0924\u093E\u0964 \u0910\u0938\u093E \u0938\u0902\u0938\u094D\u0915\u0930\u0923 \u092A\u093E\u0928\u0947 \u0915\u0947 \u0932\u093F\u090F \u091C\u093F\u0938\u0947 \u0906\u092A \u0938\u0902\u092A\u093E\u0926\u093F\u0924 \u0915\u0930 \u0938\u0915\u0947\u0902 \u092F\u093E \u0915\u093F\u0938\u0940 \u090F\u091C\u0947\u0902\u091F \u0938\u0947 \u092C\u0926\u0932\u0935\u093E \u0938\u0915\u0947\u0902, \u0907\u0938\u0947 \u0905\u092A\u0928\u0947 \u0915\u094C\u0936\u0932 \u092E\u0947\u0902 \u0915\u0949\u092A\u0940 \u0915\u0930\u0947\u0902\u0964",
  "ui.agents.skills.alert.builtin_body_no_copy": "\u092F\u0939 Local Operator \u0915\u0947 \u0938\u093E\u0925 \u0906\u0924\u093E \u0939\u0948 \u0914\u0930 \u092F\u0939\u093E\u0901 \u092C\u0926\u0932\u093E \u0928\u0939\u0940\u0902 \u091C\u093E \u0938\u0915\u0924\u093E\u0964",
  "ui.agents.skills.alert.builtin_title": "\u092C\u093F\u0932\u094D\u091F-\u0907\u0928 \u0915\u094C\u0936\u0932",
  "ui.agents.skills.alert.bundle_body": "\u092F\u0939 \u0915\u094C\u0936\u0932 \u090F\u0915 \u092B\u093C\u094B\u0932\u094D\u0921\u0930 \u092C\u0902\u0921\u0932 \u0939\u0948, \u091C\u093F\u0938\u0947 \u0905\u092D\u0940 \u092F\u0939\u093E\u0901 \u0938\u0902\u092A\u093E\u0926\u093F\u0924 \u0928\u0939\u0940\u0902 \u0915\u093F\u092F\u093E \u091C\u093E \u0938\u0915\u0924\u093E\u0964 \u090F\u091C\u0947\u0902\u091F \u0939\u092C \u0938\u0947 \u0905\u092A\u0921\u0947\u091F \u092B\u093F\u0930 \u092D\u0940 \u0932\u093E\u0917\u0942 \u0939\u094B\u0924\u0947 \u0939\u0948\u0902\u0964",
  "ui.agents.skills.alert.bundle_local_body": "\u092F\u0939 \u0915\u094C\u0936\u0932 \u092B\u093C\u093E\u0907\u0932\u094B\u0902 \u0915\u093E \u090F\u0915 \u092B\u093C\u094B\u0932\u094D\u0921\u0930 \u0939\u0948, \u091C\u093F\u0938\u0947 \u092F\u0939\u093E\u0901 \u0938\u0902\u092A\u093E\u0926\u093F\u0924 \u0928\u0939\u0940\u0902 \u0915\u093F\u092F\u093E \u091C\u093E \u0938\u0915\u0924\u093E\u0964 \u0907\u0938\u0947 \u0938\u0940\u0927\u0947 \u0921\u093F\u0938\u094D\u0915 \u092A\u0930 \u0909\u0938\u0940 \u092B\u093C\u094B\u0932\u094D\u0921\u0930 \u092E\u0947\u0902 \u092C\u0926\u0932\u0947\u0902\u0964 \u0909\u0938\u0915\u093E \u092A\u093E\u0925 \u201C\u0935\u093F\u0935\u0930\u0923\u201D \u092E\u0947\u0902 \u0939\u0948\u0964",
  "ui.agents.skills.alert.bundle_title": "\u092B\u093C\u094B\u0932\u094D\u0921\u0930 \u092C\u0902\u0921\u0932",
  "ui.agents.skills.alert.conflict_body": "\u0906\u092A\u0915\u0947 \u0907\u0938\u0947 \u0916\u094B\u0932\u0928\u0947 \u0915\u0947 \u092C\u093E\u0926 \u0915\u093F\u0938\u0940 \u0914\u0930 \u091A\u0940\u091C\u093C, \u091C\u0948\u0938\u0947 \u0915\u0949\u0928\u094D\u092B\u093C\u093F\u0917\u0930\u0947\u0936\u0928 \u0930\u0928 \u092F\u093E \u0926\u0942\u0938\u0930\u0940 \u0935\u093F\u0902\u0921\u094B, \u0928\u0947 \u0907\u0938 \u0915\u094C\u0936\u0932 \u0915\u094B \u092C\u0926\u0932 \u0926\u093F\u092F\u093E\u0964 \u0906\u092A\u0915\u0947 \u0938\u0902\u092A\u093E\u0926\u0928 \u0930\u0916\u0947 \u0917\u090F \u0939\u0948\u0902\u0964 \u0921\u093F\u0938\u094D\u0915 \u092A\u0930 \u091C\u094B \u0939\u0948, \u0935\u0939\u0940\u0902 \u0938\u0947 \u092B\u093F\u0930 \u0936\u0941\u0930\u0942 \u0915\u0930\u0928\u0947 \u0915\u0947 \u0932\u093F\u090F \u0938\u0939\u0947\u091C\u093E \u0917\u092F\u093E \u0938\u0902\u0938\u094D\u0915\u0930\u0923 \u092B\u093F\u0930 \u0932\u094B\u0921 \u0915\u0930\u0947\u0902\u0964",
  "ui.agents.skills.alert.external_body": "\u092F\u0939 \u0915\u093F\u0938\u0940 \u0905\u0928\u094D\u092F \u091F\u0942\u0932 \u0915\u0947 \u0915\u094C\u0936\u0932 \u092B\u093C\u094B\u0932\u094D\u0921\u0930 \u092E\u0947\u0902 \u0939\u0948, \u0907\u0938\u0932\u093F\u090F Local Operator \u0907\u0938\u0947 \u0938\u093F\u0930\u094D\u092B\u093C \u092A\u0922\u093C\u0924\u093E \u0939\u0948\u0964 \u0907\u0938\u0947 \u0909\u0938\u0940 \u091F\u0942\u0932 \u092E\u0947\u0902 \u092C\u0926\u0932\u0947\u0902, \u092F\u093E \u0905\u092A\u0928\u0947 \u0915\u094C\u0936\u0932 \u092E\u0947\u0902 \u0915\u0949\u092A\u0940 \u0915\u0930\u0947\u0902\u0964",
