  "ui.chat.aside.continuation_escape": "\u092F\u0939 \u0905\u0932\u0917 \u092C\u093E\u0924\u091A\u0940\u0924 \u0906\u0917\u0947 \u0928\u0939\u0940\u0902 \u092C\u0922\u093C \u0938\u0915\u0924\u0940\u0964 \u0907\u0938\u0947 \u092C\u0902\u0926 \u0915\u0930\u0928\u0947 \u0915\u0947 \u0932\u093F\u090F Esc \u0926\u092C\u093E\u090F\u0901, \u091C\u093F\u0938\u0938\u0947 \u092F\u0939 \u0938\u0935\u093E\u0932-\u091C\u0935\u093E\u092C \u0939\u091F \u091C\u093E\u090F\u0917\u093E, \u092B\u093F\u0930 /btw \u0938\u0947 \u0928\u0908 \u0936\u0941\u0930\u0942 \u0915\u0930\u0947\u0902\u0964",
  "ui.chat.aside.declined_options": "\u0907\u0938 \u0938\u0935\u093E\u0932-\u091C\u0935\u093E\u092C \u0915\u094B \u0930\u0916\u0928\u0947 \u0915\u0947 \u0932\u093F\u090F \u092F\u0939\u0940\u0902 \u092B\u093F\u0930 \u092A\u0942\u091B\u0947\u0902, \u092F\u093E \u0905\u0932\u0917 \u092C\u093E\u0924\u091A\u0940\u0924 \u092C\u0902\u0926 \u0915\u0930\u0915\u0947 \u0909\u0938\u0947 \u0939\u091F\u093E\u0928\u0947 \u0915\u0947 \u0932\u093F\u090F Esc \u0926\u092C\u093E\u090F\u0901\u0964",
