  "ui.chat.device.picker.heading.start": "\u092C\u093E\u0924\u091A\u0940\u0924 \u0936\u0941\u0930\u0942 \u0915\u0930\u0928\u0947 \u0915\u0947 \u0932\u093F\u090F \u0921\u093F\u0935\u093E\u0907\u0938 \u091A\u0941\u0928\u0947\u0902",
