  "ui.chat.error_block.rate_limit.all_after": "\u0916\u094B\u0932\u0947\u0902 \u2014 \u092C\u093F\u0928\u093E \u0930\u0947\u091F \u0938\u0940\u092E\u093E \u0915\u0947 \u0938\u092D\u0940 AI \u092E\u0949\u0921\u0932 \u0915\u092E \u0926\u093E\u092E \u092A\u0930 \u092A\u093E\u0928\u0947 \u0915\u0947 \u0932\u093F\u090F\u0964",
