  "ui.chat.error_block.unavailable.after": "\u092E\u0947\u0902 \u091C\u093E\u090F\u0901, \u092F\u093E \u0938\u0948\u0915\u0921\u093C\u094B\u0902 AI \u092E\u0949\u0921\u0932 \u092C\u093F\u0928\u093E \u0930\u0947\u091F \u0938\u0940\u092E\u093E \u0915\u0947 \u092A\u093E\u0928\u0947 \u0915\u0947 \u0932\u093F\u090F Radient \u0907\u0938\u094D\u0924\u0947\u092E\u093E\u0932 \u0915\u0930\u0947\u0902",
  "ui.chat.error_block.schema.before": "\u092E\u0949\u0921\u0932 \u0928\u0947 \u0915\u094B\u0908 \u0915\u093E\u0930\u094D\u0930\u0935\u093E\u0908 \u0915\u0930\u0928\u0940 \u091A\u093E\u0939\u0940, \u0932\u0947\u0915\u093F\u0928 \u091C\u093C\u0930\u0942\u0930\u0940 \u0938\u094D\u0915\u0940\u092E\u093E \u092E\u0947\u0902 \u0905\u092A\u0928\u093E \u0907\u0930\u093E\u0926\u093E \u0928\u0939\u0940\u0902 \u092C\u0924\u093E \u0938\u0915\u093E\u0964 \u0910\u0938\u093E \u0906\u092E \u0924\u094C\u0930 \u092A\u0930 \u0907\u0938\u0932\u093F\u090F \u0939\u094B\u0924\u093E \u0939\u0948 \u0915\u093F \u092E\u0949\u0921\u0932 \u090F\u091C\u0947\u0902\u091F\u093F\u0915 AI \u0915\u0947 \u0932\u093F\u090F \u091C\u093C\u0930\u0942\u0930\u0940 \u091C\u091F\u093F\u0932 \u0928\u093F\u0930\u094D\u0926\u0947\u0936 \u0928\u0939\u0940\u0902 \u0928\u093F\u092D\u093E \u092A\u093E\u0924\u093E\u0964",
  "ui.chat.error_block.schema.after_before": "\u0907\u0938\u0947 \u0920\u0940\u0915 \u0915\u0930\u0928\u0947 \u0915\u0947 \u0932\u093F\u090F",
  "ui.chat.error_block.schema.after": "\u092E\u0947\u0902 \u0905\u092A\u0928\u093E \u092E\u0949\u0921\u0932 \u092C\u0926\u0932\u0947\u0902\u0964 \u0939\u092E Radient Automatic \u0907\u0938\u094D\u0924\u0947\u092E\u093E\u0932 \u0915\u0930\u0928\u0947 \u0915\u0940 \u0938\u0932\u093E\u0939 \u0926\u0947\u0924\u0947 \u0939\u0948\u0902, \u0924\u093E\u0915\u093F \u0906\u092A\u0915\u0947 \u0905\u0928\u0941\u0930\u094B\u0927\u094B\u0902 \u0915\u0947 \u0906\u0927\u093E\u0930 \u092A\u0930 \u0938\u0938\u094D\u0924\u0947 \u0914\u0930 \u0938\u092E\u091D\u0926\u093E\u0930 \u092E\u0949\u0921\u0932 \u0915\u093E \u0938\u092C\u0938\u0947 \u0905\u091A\u094D\u091B\u093E \u092E\u0947\u0932 \u0906\u092A\u0915\u0947 \u0932\u093F\u090F \u091A\u0941\u0928\u093E \u091C\u093E\u090F (\u0906\u092E \u0924\u094C\u0930 \u092A\u0930 \u0905\u092A\u0928\u0940 \u0915\u0941\u0902\u091C\u0940 \u0932\u093E\u0928\u0947 \u0938\u0947 \u0938\u0938\u094D\u0924\u093E), \u092F\u093E \u0938\u094D\u091F\u093E\u0930 \u0906\u0907\u0915\u0928 \u0935\u093E\u0932\u0947 \u0938\u0941\u091D\u093E\u090F \u0917\u090F \u092E\u0949\u0921\u0932 \u092E\u0947\u0902 \u0938\u0947 \u0915\u094B\u0908 \u091A\u0941\u0928\u0947\u0902\u0964",
  "ui.chat.approval.reply_required": "\u0938\u094D\u0935\u0940\u0915\u0943\u0924\u093F \u0915\u0947 \u0905\u0928\u0941\u0930\u094B\u0927 \u0915\u093E \u091C\u0935\u093E\u092C \u0926\u0947\u0928\u0947 \u0915\u0947 \u0932\u093F\u090F yes \u092F\u093E no \u0932\u093F\u0916\u0947\u0902\u0964",
  "ui.chat.question_dock.hint.approval": "\u090A\u092A\u0930 \u0915\u0947 \u092C\u091F\u0928 \u0938\u0947 \u0938\u094D\u0935\u0940\u0915\u0943\u0924\u093F \u0926\u0947\u0902 \u092F\u093E \u0905\u0938\u094D\u0935\u0940\u0915\u093E\u0930 \u0915\u0930\u0947\u0902, \u092F\u093E yes, no, 1, \u092F\u093E 2 \u091F\u093E\u0907\u092A \u0915\u0930\u0915\u0947 \u092D\u0947\u091C\u0947\u0902, \u092F\u093E \u091F\u0930\u094D\u0928 \u0930\u094B\u0915\u0928\u0947 \u0915\u0947 \u0932\u093F\u090F \u0938\u0902\u0926\u0947\u0936 \u092C\u0949\u0915\u094D\u0938 \u092E\u0947\u0902 Escape \u0926\u092C\u093E\u090F\u0901\u0964",
  "ui.chat.question_dock.hint.approval_held": "\u0907\u0938\u0915\u0947 \u092C\u091C\u093E\u092F \u0915\u0902\u092A\u094B\u091C\u093C\u0930 \u0938\u0947 \u091C\u0935\u093E\u092C \u0926\u0947\u0902: yes, no, 1, \u092F\u093E 2 \u091F\u093E\u0907\u092A \u0915\u0930\u0915\u0947 \u092D\u0947\u091C\u0947\u0902, \u092F\u093E \u091F\u0930\u094D\u0928 \u0930\u094B\u0915\u0928\u0947 \u0915\u0947 \u0932\u093F\u090F \u0938\u0902\u0926\u0947\u0936 \u092C\u0949\u0915\u094D\u0938 \u092E\u0947\u0902 Escape \u0926\u092C\u093E\u090F\u0901\u0964",
