  "ui.chat.pickers.destination_pickers.attach_team": "\u091F\u0940\u092E \u091C\u094B\u0921\u093C\u0947\u0902",
  "ui.chat.pickers.destination_pickers.skills_discoverable_from_this_session_s_working_directory_scope_listed_i": "\u0907\u0938 \u0938\u0924\u094D\u0930 \u0915\u0940 \u0935\u0930\u094D\u0915\u093F\u0902\u0917 \u0921\u093E\u092F\u0930\u0947\u0915\u094D\u091F\u0930\u0940 \u0938\u0947 \u092E\u093F\u0932\u0928\u0947 \u0935\u093E\u0932\u0947 \u0915\u094C\u0936\u0932 ({value} \u0926\u093E\u092F\u0930\u093E)\u0964 \u0938\u0942\u091A\u0940 \u092E\u0947\u0902 \u0939\u094B\u0928\u0947 \u0915\u093E \u0905\u0930\u094D\u0925 \u092A\u094D\u0930\u0949\u092E\u094D\u092A\u094D\u091F \u092E\u0947\u0902 \u091A\u0941\u0928\u093E \u091C\u093E\u0928\u093E \u0928\u0939\u0940\u0902 \u0939\u0948\u0964",
  "ui.chat.pickers.destination_pickers.no_skills_are_discoverable_from_this_session_s_directory": "\u0907\u0938 \u0938\u0924\u094D\u0930 \u0915\u0940 \u0921\u093E\u092F\u0930\u0947\u0915\u094D\u091F\u0930\u0940 \u0938\u0947 \u0915\u094B\u0908 \u0915\u094C\u0936\u0932 \u0928\u0939\u0940\u0902 \u092E\u093F\u0932\u0924\u093E\u0964",
  "ui.chat.pickers.destination_pickers.skill": "skill://",
  "ui.chat.pickers.destination_pickers.no_detail_returned": "\u0915\u094B\u0908 \u0935\u093F\u0935\u0930\u0923 \u0928\u0939\u0940\u0902 \u0932\u094C\u091F\u093E\u092F\u093E \u0917\u092F\u093E\u0964",
  "ui.chat.pickers.destination_pickers.if_that_message_was_sent_just_now_it_may_not_be_in_the_conversation_s_hi": "\u0905\u0917\u0930 \u0935\u0939 \u0938\u0902\u0926\u0947\u0936 \u0905\u092D\u0940-\u0905\u092D\u0940 \u092D\u0947\u091C\u093E \u0917\u092F\u093E \u0925\u093E, \u0924\u094B \u0936\u093E\u092F\u0926 \u0935\u0939 \u0905\u092C \u0924\u0915 \u092C\u093E\u0924\u091A\u0940\u0924 \u0915\u0947 \u0907\u0924\u093F\u0939\u093E\u0938 \u092E\u0947\u0902 \u0928 \u0906\u092F\u093E \u0939\u094B\u0964",
  "ui.chat.pickers.destination_pickers.forked_from_this_message_everything_after_it_stays_in_the_original_which": "\u0907\u0938 \u0938\u0902\u0926\u0947\u0936 \u0938\u0947 \u092B\u093C\u094B\u0930\u094D\u0915 \u0915\u093F\u092F\u093E \u0917\u092F\u093E\u0964 \u0907\u0938\u0915\u0947 \u092C\u093E\u0926 \u0915\u093E \u0938\u092C \u0915\u0941\u091B \u092E\u0942\u0932 \u092C\u093E\u0924\u091A\u0940\u0924 \u092E\u0947\u0902 \u0930\u0939\u0924\u093E \u0939\u0948, \u091C\u094B \u0905\u092A\u0930\u093F\u0935\u0930\u094D\u0924\u093F\u0924 \u0939\u0948\u0964",
  "ui.chat.pickers.destination_pickers.forked_at_the_next_safe_boundary_into_a_new_conversation_the_original_co": "\u0905\u0917\u0932\u0940 \u0938\u0941\u0930\u0915\u094D\u0937\u093F\u0924 \u0938\u0940\u092E\u093E \u092A\u0930 \u0928\u0908 \u092C\u093E\u0924\u091A\u0940\u0924 \u092E\u0947\u0902 \u092B\u093C\u094B\u0930\u094D\u0915 \u0915\u093F\u092F\u093E \u0917\u092F\u093E\u0964 \u092E\u0942\u0932 \u092C\u093E\u0924\u091A\u0940\u0924 \u0905\u092A\u0930\u093F\u0935\u0930\u094D\u0924\u093F\u0924 \u0939\u0948\u0964",
  "ui.chat.pickers.destination_pickers.the_fork_starts_before_the_message_you_chose_a_cut_cannot_separate_a_too": "\n\u092B\u093C\u094B\u0930\u094D\u0915 \u0906\u092A\u0915\u0947 \u091A\u0941\u0928\u0947 \u0938\u0902\u0926\u0947\u0936 \u0938\u0947 \u092A\u0939\u0932\u0947 \u0936\u0941\u0930\u0942 \u0939\u094B\u0924\u093E \u0939\u0948: \u090F\u0915 \u0915\u091F \u091F\u0942\u0932 \u0915\u0949\u0932 \u0915\u094B \u0909\u0938\u0915\u0947 \u092A\u0930\u093F\u0923\u093E\u092E\u094B\u0902 \u0938\u0947 \u0905\u0932\u0917 \u0928\u0939\u0940\u0902 \u0915\u0930 \u0938\u0915\u0924\u093E\u0964",
  "ui.chat.pickers.destination_pickers.your_message_was_admitted_once": "\n\u0906\u092A\u0915\u093E \u0938\u0902\u0926\u0947\u0936 \u090F\u0915 \u092C\u093E\u0930 \u0938\u094D\u0935\u0940\u0915\u093E\u0930 \u0915\u093F\u092F\u093E \u0917\u092F\u093E: {detail}\u0964",
  "ui.chat.pickers.destination_pickers.fork_from_this_message": "\u0907\u0938 \u0938\u0902\u0926\u0947\u0936 \u0938\u0947 \u092B\u093C\u094B\u0930\u094D\u0915 \u0915\u0930\u0947\u0902",
  "ui.chat.pickers.destination_pickers.fork_this_conversation": "\u092F\u0939 \u092C\u093E\u0924\u091A\u0940\u0924 \u092B\u093C\u094B\u0930\u094D\u0915 \u0915\u0930\u0947\u0902",
  "ui.chat.pickers.destination_pickers.copies_this_conversation_up_to_and_including_everything_after_it_is_left": "\u0907\u0938 \u092C\u093E\u0924\u091A\u0940\u0924 \u0915\u094B {value} \u0924\u0915, \u0909\u0938\u0947 \u0936\u093E\u092E\u093F\u0932 \u0915\u0930\u0915\u0947, \u0915\u0949\u092A\u0940 \u0915\u0930\u0924\u093E \u0939\u0948\u0964 \u0909\u0938\u0915\u0947 \u092C\u093E\u0926 \u0915\u093E \u0938\u092C \u0915\u0941\u091B \u092A\u0940\u091B\u0947 \u091B\u0942\u091F \u091C\u093E\u0924\u093E \u0939\u0948 \u0914\u0930 \u092E\u0942\u0932 \u092C\u093E\u0924\u091A\u0940\u0924 \u092C\u093F\u0928\u093E \u092C\u0926\u0932\u0947 \u091A\u0932\u0924\u0940 \u0930\u0939\u0924\u0940 \u0939\u0948\u0964",
  "ui.chat.pickers.destination_pickers.copies_the_complete_history_into_a_new_conversation_at_the_next_safe_bou": "\u0905\u0917\u0932\u0940 \u0938\u0941\u0930\u0915\u094D\u0937\u093F\u0924 \u0938\u0940\u092E\u093E \u092A\u0930 (\u092E\u094C\u091C\u0942\u0926\u093E \u0905\u0938\u093F\u0938\u094D\u091F\u0947\u0902\u091F \u091A\u0930\u0923 \u0914\u0930 \u0909\u0938\u0915\u0947 \u091F\u0942\u0932 \u092A\u0930\u093F\u0923\u093E\u092E\u094B\u0902 \u0915\u0947 \u092C\u093E\u0926) \u092A\u0942\u0930\u093E \u0907\u0924\u093F\u0939\u093E\u0938 \u0928\u0908 \u092C\u093E\u0924\u091A\u0940\u0924 \u092E\u0947\u0902 \u0915\u0949\u092A\u0940 \u0915\u0930\u0924\u093E \u0939\u0948\u0964 \u092E\u0942\u0932 \u092C\u093E\u0924\u091A\u0940\u0924 \u091A\u0932\u0924\u0940 \u0930\u0939\u0924\u0940 \u0939\u0948 \u0914\u0930 \u0928\u0939\u0940\u0902 \u092C\u0926\u0932\u0924\u0940\u0964",
  "ui.chat.pickers.destination_pickers.first_message_in_the_fork_optional": "\u092B\u093C\u094B\u0930\u094D\u0915 \u0915\u093E \u092A\u0939\u0932\u093E \u0938\u0902\u0926\u0947\u0936 (\u0935\u0948\u0915\u0932\u094D\u092A\u093F\u0915)",
  "ui.chat.pickers.destination_pickers.delivered_exactly_once_to_the_new_conversation": "\u0928\u0908 \u092C\u093E\u0924\u091A\u0940\u0924 \u092E\u0947\u0902 \u0920\u0940\u0915 \u090F\u0915 \u092C\u093E\u0930 \u0921\u093F\u0932\u0940\u0935\u0930 \u0915\u093F\u092F\u093E \u0917\u092F\u093E\u0964",
