  "ui.chat.run_details.mcp_auth.upgrade": "MCP \u0915\u0941\u0902\u091C\u093F\u092F\u093E\u0901 \u0938\u0941\u0930\u0915\u094D\u0937\u093F\u0924 \u0930\u0942\u092A \u0938\u0947 \u0926\u0930\u094D\u091C \u0915\u0930\u0928\u0947 \u0915\u0947 \u0932\u093F\u090F \u092C\u0948\u0915\u090F\u0902\u0921 \u0905\u092A\u0921\u0947\u091F \u0915\u0930\u0947\u0902\u0964 OAuth \u0914\u0930 \u0938\u0930\u094D\u0935\u0930 \u0938\u0942\u091A\u0940 \u0909\u092A\u0932\u092C\u094D\u0927 \u0939\u0948\u0902\u0964",
