  "ui.chat.run_details.mcp_failure.cancel_lead": "\u0930\u0926\u094D\u0926 \u0915\u093F\u090F \u091C\u093E\u0928\u0947 \u0915\u0940 \u092A\u0941\u0937\u094D\u091F\u093F \u0928\u0939\u0940\u0902 \u0939\u094B \u0938\u0915\u0940",
  "ui.chat.run_details.mcp_failure.busy": "{lead}: \u0907\u0938 \u092C\u093E\u0924\u091A\u0940\u0924 \u0915\u0947 \u0932\u093F\u090F \u0938\u093E\u0907\u0928 \u0907\u0928 \u092A\u0939\u0932\u0947 \u0938\u0947 \u091A\u0932 \u0930\u0939\u093E \u0939\u0948, \u0914\u0930 \u090F\u0915 \u0938\u092E\u092F \u092E\u0947\u0902 \u090F\u0915 \u0939\u0940 \u091A\u0932 \u0938\u0915\u0924\u093E \u0939\u0948\u0964 \u0907\u0938\u0915\u0947 \u092A\u0942\u0930\u093E \u0939\u094B\u0928\u0947 \u0915\u093E \u0907\u0902\u0924\u091C\u093C\u093E\u0930 \u0915\u0930\u0947\u0902, \u092F\u093E \u0938\u0930\u094D\u0935\u0930 \u0915\u0940 \u092A\u0902\u0915\u094D\u0924\u093F \u0938\u0947 \u0907\u0938\u0947 \u0930\u0926\u094D\u0926 \u0915\u0930\u0947\u0902\u0964",
