  "ui.chat.session_readout.access.owner_fallback": "\u092E\u093E\u0932\u093F\u0915 \u0921\u093F\u0935\u093E\u0907\u0938",
  "ui.chat.session_readout.access.owner_unavailable.description": "\u092F\u0939 \u0938\u0924\u094D\u0930 {owner} \u0938\u0947 {label} \u0915\u0940 \u092A\u0939\u0941\u0901\u091A \u0924\u092F \u0928\u0939\u0940\u0902 \u0915\u0930 \u0938\u0915\u093E\u0964 \u092A\u093F\u091B\u0932\u0940 \u092A\u0939\u0941\u0901\u091A \u0926\u094B\u092C\u093E\u0930\u093E \u0907\u0938\u094D\u0924\u0947\u092E\u093E\u0932 \u0928\u0939\u0940\u0902 \u0915\u0940 \u091C\u093E \u0938\u0915\u0924\u0940\u0964 \u092E\u093E\u0932\u093F\u0915 \u0915\u0940 \u092A\u0939\u0941\u0901\u091A \u092C\u0939\u093E\u0932 \u0939\u094B\u0928\u0947 \u0915\u0947 \u092C\u093E\u0926 \u092B\u093F\u0930 \u0915\u094B\u0936\u093F\u0936 \u0915\u0930\u0947\u0902, \u092F\u093E \u0926\u0942\u0938\u0930\u093E \u092E\u0949\u0921\u0932 \u091A\u0941\u0928\u0947\u0902\u0964",
  "ui.chat.session_readout.access.owner_unavailable.title": "{owner} \u092A\u0939\u0941\u0901\u091A \u0928\u0939\u0940\u0902 \u0926\u0947 \u0938\u0915\u0924\u093E",
  "ui.chat.session_readout.access.pending.description": "\u092A\u0939\u0941\u0901\u091A \u0905\u092D\u0940 \u0924\u092F \u0928\u0939\u0940\u0902 \u0939\u0941\u0908 \u0939\u0948\u0964 \u0905\u0917\u0932\u093E \u0905\u0928\u0941\u0930\u094B\u0927 \u092E\u093E\u0932\u093F\u0915 \u0915\u094B \u0905\u092A\u0928\u0947 \u0906\u092A \u091C\u093E\u0901\u091A\u0947\u0917\u093E; \u092F\u0939\u093E\u0901 \u0905\u0932\u0917 \u0938\u0947 \u0938\u093E\u0907\u0928-\u0907\u0928 \u0915\u0940 \u091C\u093C\u0930\u0942\u0930\u0924 \u0928\u0939\u0940\u0902 \u0939\u0948\u0964",
  "ui.chat.session_readout.access.pending.title": "{label} \u0915\u0940 \u092A\u0939\u0941\u0901\u091A \u091C\u093E\u0901\u091A\u0940 \u091C\u093E \u0930\u0939\u0940 \u0939\u0948",
  "ui.chat.session_readout.access.withdrawn.description": "\u092E\u093E\u0932\u093F\u0915 \u0905\u092D\u0940 \u0909\u0927\u093E\u0930 \u0915\u0940 \u092A\u0939\u0941\u0901\u091A \u0928\u0939\u0940\u0902 \u0926\u0947 \u0938\u0915\u0924\u093E, \u092F\u093E \u0909\u0927\u093E\u0930 \u0932\u0947\u0928\u0947 \u0915\u0940 \u0905\u0928\u0941\u092E\u0924\u093F \u0909\u092A\u0932\u092C\u094D\u0927 \u0928\u0939\u0940\u0902 \u0939\u0948\u0964 \u092B\u093F\u0930 \u0915\u094B\u0936\u093F\u0936 \u0915\u0930\u0928\u0947 \u0938\u0947 \u092A\u0939\u0932\u0947 \u092E\u093E\u0932\u093F\u0915 \u0915\u0940 \u092A\u0939\u0941\u0901\u091A \u092F\u093E \u0905\u0928\u0941\u092E\u0924\u093F \u092C\u0939\u093E\u0932 \u0915\u0930\u0947\u0902, \u092F\u093E \u0926\u0942\u0938\u0930\u093E \u092E\u0949\u0921\u0932 \u091A\u0941\u0928\u0947\u0902\u0964",
  "ui.chat.session_readout.access.withdrawn.title": "{label} \u0915\u0940 \u092A\u0939\u0941\u0901\u091A \u092A\u0930 \u0927\u094D\u092F\u093E\u0928 \u0926\u0947\u0928\u093E \u091C\u093C\u0930\u0942\u0930\u0940 \u0939\u0948",
  "ui.chat.session_readout.draft.confirm_effort_changed": "\u092F\u0939 \u092C\u093E\u0924\u091A\u0940\u0924 {selector} \u092A\u0930 \u091A\u0932\u0947\u0917\u0940\u0964 \u0907\u0938\u0915\u093E \u092A\u094D\u0930\u092F\u093E\u0938 \u0905\u092C {level} \u0939\u0948, \u0915\u094D\u092F\u094B\u0902\u0915\u093F {wanted} \u0909\u0938 \u092E\u0949\u0921\u0932 \u0915\u0947 \u0938\u094D\u0924\u0930\u094B\u0902 \u092E\u0947\u0902 \u0928\u0939\u0940\u0902 \u0939\u0948\u0964",
  "ui.chat.session_readout.draft.confirm_effort_unset": "\u092F\u0939 \u092C\u093E\u0924\u091A\u0940\u0924 {selector} \u092A\u0930 \u091A\u0932\u0947\u0917\u0940\u0964 \u0907\u0938 \u092A\u0930 \u0915\u094B\u0908 \u092A\u094D\u0930\u092F\u093E\u0938 \u0938\u094D\u0924\u0930 \u0924\u092F \u0928\u0939\u0940\u0902 \u0939\u0948, \u0915\u094D\u092F\u094B\u0902\u0915\u093F {wanted} \u0909\u0938 \u092E\u0949\u0921\u0932 \u0915\u0947 \u0938\u094D\u0924\u0930\u094B\u0902 \u092E\u0947\u0902 \u0928\u0939\u0940\u0902 \u0939\u0948\u0964",
  "ui.chat.session_readout.draft.confirm_model": "\u092F\u0939 \u092C\u093E\u0924\u091A\u0940\u0924 {selector} \u092A\u0930 \u091A\u0932\u0947\u0917\u0940\u0964",
  "ui.chat.session_readout.draft.confirm_model_effort": "\u092F\u0939 \u092C\u093E\u0924\u091A\u0940\u0924 {selector} \u092A\u0930 {effort} \u092A\u094D\u0930\u092F\u093E\u0938 \u0915\u0947 \u0938\u093E\u0925 \u091A\u0932\u0947\u0917\u0940\u0964",
  "ui.chat.session_readout.draft.refusal_ladder_unread": "\u0915\u0941\u091B \u0928\u0939\u0940\u0902 \u092C\u0926\u0932\u093E \u0917\u092F\u093E, \u0915\u094D\u092F\u094B\u0902\u0915\u093F \u0909\u0938 \u092E\u0949\u0921\u0932 \u0915\u0947 \u092A\u094D\u0930\u092F\u093E\u0938 \u0938\u094D\u0924\u0930 \u092A\u0922\u093C\u0947 \u0928\u0939\u0940\u0902 \u091C\u093E \u0938\u0915\u0947\u0964 \u092B\u093F\u0930 \u0915\u094B\u0936\u093F\u0936 \u0915\u0930\u0947\u0902\u0964",
  "ui.chat.session_readout.effort.detail.auto": "\u0915\u094B\u0908 \u0938\u094D\u0924\u0930 \u0924\u092F \u0928\u0939\u0940\u0902 \u0939\u0948, \u0907\u0938\u0932\u093F\u090F \u092F\u0939 \u092E\u0949\u0921\u0932 \u0905\u092A\u0928\u0947 \u0921\u093F\u092B\u093C\u0949\u0932\u094D\u091F \u092A\u0930 \u091A\u0932\u0924\u093E \u0939\u0948\u0964 \u0907\u0938\u092E\u0947\u0902 {levels} \u0909\u092A\u0932\u092C\u094D\u0927 \u0939\u0948\u0902\u0964",
  "ui.chat.session_readout.effort.detail.auto_with_default": "\u0915\u094B\u0908 \u0938\u094D\u0924\u0930 \u0924\u092F \u0928\u0939\u0940\u0902 \u0939\u0948, \u0907\u0938\u0932\u093F\u090F \u092F\u0939 \u092E\u0949\u0921\u0932 \u0905\u092A\u0928\u0947 \u0921\u093F\u092B\u093C\u0949\u0932\u094D\u091F ({default}) \u092A\u0930 \u091A\u0932\u0924\u093E \u0939\u0948\u0964 \u0907\u0938\u092E\u0947\u0902 {levels} \u0909\u092A\u0932\u092C\u094D\u0927 \u0939\u0948\u0902\u0964",
  "ui.chat.session_readout.effort.detail.default_only": "\u092F\u0939 \u0935\u0939 \u0938\u094D\u0924\u0930 \u0939\u0948 \u091C\u093F\u0938 \u092A\u0930 \u092F\u0939 \u092E\u0949\u0921\u0932 \u0921\u093F\u092B\u093C\u0949\u0932\u094D\u091F \u0930\u0942\u092A \u0938\u0947 \u091A\u0932\u0924\u093E \u0939\u0948\u0964 \u092F\u0939 \u092C\u0948\u0915\u090F\u0902\u0921 \u0928\u0939\u0940\u0902 \u092C\u0924\u093E\u0924\u093E \u0915\u093F \u0935\u0939 \u0914\u0930 \u0915\u094C\u0928-\u0938\u0947 \u0938\u094D\u0924\u0930 \u0938\u094D\u0935\u0940\u0915\u093E\u0930 \u0915\u0930\u0924\u093E \u0939\u0948\u0964",
  "ui.chat.session_readout.effort.detail.no_levels": "\u092F\u0939 \u092E\u0949\u0921\u0932 \u0924\u0930\u094D\u0915 \u0915\u0930\u0924\u093E \u0939\u0948, \u092A\u0930 \u091A\u0941\u0928\u0928\u0947 \u0915\u0947 \u0932\u093F\u090F \u0915\u094B\u0908 \u092A\u094D\u0930\u092F\u093E\u0938 \u0938\u094D\u0924\u0930 \u0928\u0939\u0940\u0902 \u0926\u0947\u0924\u093E\u0964",
  "ui.chat.session_readout.effort.detail.not_reported": "\u0907\u0938 \u0938\u0924\u094D\u0930 \u0928\u0947 \u0905\u092D\u0940 \u0924\u0930\u094D\u0915 \u0915\u093E \u092A\u094D\u0930\u092F\u093E\u0938 \u0928\u0939\u0940\u0902 \u092C\u0924\u093E\u092F\u093E \u0939\u0948\u0964 \u0935\u0939 \u0905\u0917\u0932\u0947 \u091F\u0930\u094D\u0928 \u0915\u0947 \u092C\u093E\u0926 \u0926\u093F\u0916\u0947\u0917\u093E, \u092F\u093E \u0905\u092D\u0940 \u0924\u092F \u0915\u0930\u0928\u0947 \u0915\u0947 \u0932\u093F\u090F {command} \u091A\u0932\u093E\u090F\u0901\u0964",
  "ui.chat.session_readout.effort.detail.offers": "\u0924\u0930\u094D\u0915 \u0915\u093E \u092A\u094D\u0930\u092F\u093E\u0938\u0964 \u0907\u0938 \u092E\u0949\u0921\u0932 \u092E\u0947\u0902 {levels} \u0909\u092A\u0932\u092C\u094D\u0927 \u0939\u0948\u0902\u0964",
  "ui.chat.session_readout.effort.detail.session": "\u0907\u0938 \u0938\u0924\u094D\u0930 \u0915\u0947 \u0932\u093F\u090F \u0924\u0930\u094D\u0915 \u0915\u093E \u092A\u094D\u0930\u092F\u093E\u0938\u0964",
