  "ui.chat.session_readout.strip.fast_mode_on": "\u092B\u093C\u093E\u0938\u094D\u091F \u092E\u094B\u0921 \u091A\u093E\u0932\u0942",
  "ui.chat.session_readout.strip.model_switching": "\u092E\u0949\u0921\u0932 \u092C\u0926\u0932\u093E \u091C\u093E \u0930\u0939\u093E \u0939\u0948; \u0938\u0924\u094D\u0930 \u0915\u0940 \u092A\u0941\u0937\u094D\u091F\u093F \u0915\u093E \u0907\u0902\u0924\u091C\u093C\u093E\u0930 \u0939\u0948",
  "ui.chat.session_readout.strip.readings_dropped": "\u0915\u0928\u0947\u0915\u094D\u0936\u0928 \u091F\u0942\u091F\u0928\u0947 \u092A\u0930 \u0930\u0940\u0921\u093F\u0902\u0917 \u0939\u091F \u0917\u0908\u0902\u0964"
