  "ui.common.account.request_new_link": "\u0928\u092F\u093E \u0932\u093F\u0902\u0915 \u092E\u093E\u0901\u0917\u0947\u0902",
  "ui.common.account.verify_none": "\u0907\u0938 \u0916\u093E\u0924\u0947 \u0938\u0947 \u0915\u094B\u0908 \u0938\u093E\u0907\u0928-\u0905\u092A \u0917\u094D\u0930\u093E\u0902\u091F \u0928\u0939\u0940\u0902 \u091C\u0941\u0921\u093C\u093E \u0939\u0948\u0964 \u0916\u093E\u0924\u093E \u091C\u093E\u0901\u091A\u0928\u0947 \u0915\u0947 \u0932\u093F\u090F \u0938\u0924\u094D\u092F\u093E\u092A\u0928 \u092A\u0947\u091C \u0916\u094B\u0932\u0947\u0902\u0964",
  "ui.common.account.out_unknown_verify": "\u0906\u092A\u0915\u0947 \u0915\u094D\u0930\u0947\u0921\u093F\u091F \u0916\u0924\u094D\u092E \u0939\u094B \u0917\u090F \u0939\u0948\u0902\u0964 \u0905\u0917\u0930 \u0906\u092A\u0928\u0947 \u0905\u092D\u0940 \u0924\u0915 \u0908\u092E\u0947\u0932 \u0938\u0924\u094D\u092F\u093E\u092A\u093F\u0924 \u0928\u0939\u0940\u0902 \u0915\u093F\u092F\u093E \u0939\u0948, \u0924\u094B \u092E\u0941\u092B\u093C\u094D\u0924 \u0915\u094D\u0930\u0947\u0921\u093F\u091F \u092A\u093E\u0928\u0947 \u0914\u0930 Local Operator \u092E\u0941\u092B\u093C\u094D\u0924 \u0907\u0938\u094D\u0924\u0947\u092E\u093E\u0932 \u0915\u0930\u0928\u0947 \u0915\u0947 \u0932\u093F\u090F \u0909\u0938\u0947 \u0938\u0924\u094D\u092F\u093E\u092A\u093F\u0924 \u0915\u0930\u0947\u0902\u0964",
  "ui.common.account.out_unknown_top_up": "\u0935\u0930\u0928\u093E Radient Console \u092E\u0947\u0902 \u0915\u094D\u0930\u0947\u0921\u093F\u091F \u091C\u094B\u0921\u093C\u0947\u0902\u0964",
  "ui.common.account.out_unverified_none": "\u0906\u092A\u0928\u0947 \u0905\u092D\u0940 \u0924\u0915 \u0908\u092E\u0947\u0932 \u0938\u0924\u094D\u092F\u093E\u092A\u093F\u0924 \u0928\u0939\u0940\u0902 \u0915\u093F\u092F\u093E \u0939\u0948\u0964 \u0905\u092A\u0928\u0947 \u0916\u093E\u0924\u0947 \u092E\u0947\u0902 \u092E\u0941\u092B\u093C\u094D\u0924 \u0915\u094D\u0930\u0947\u0921\u093F\u091F \u0909\u092A\u0932\u092C\u094D\u0927 \u0939\u0948\u0902 \u092F\u093E \u0928\u0939\u0940\u0902, \u092F\u0939 \u091C\u093E\u0901\u091A\u0928\u0947 \u0915\u0947 \u0932\u093F\u090F \u0938\u0924\u094D\u092F\u093E\u092A\u0928 \u092A\u0947\u091C \u0916\u094B\u0932\u0947\u0902\u0964",
  "ui.common.account.out_unverified_claim": "\u0906\u092A\u0928\u0947 \u0905\u092D\u0940 \u0924\u0915 \u0908\u092E\u0947\u0932 \u0938\u0924\u094D\u092F\u093E\u092A\u093F\u0924 \u0928\u0939\u0940\u0902 \u0915\u093F\u092F\u093E \u0939\u0948\u0964 {amount} \u092A\u093E\u0928\u0947 \u0914\u0930 Local Operator \u092E\u0941\u092B\u093C\u094D\u0924 \u0907\u0938\u094D\u0924\u0947\u092E\u093E\u0932 \u0915\u0930\u0928\u0947 \u0915\u0947 \u0932\u093F\u090F \u0938\u0924\u094D\u092F\u093E\u092A\u093F\u0924 \u0915\u0930\u0947\u0902\u0964",
  "ui.common.account.out_unverified_expired": "\u0906\u092A\u0915\u094B \u092D\u0947\u091C\u093E \u0917\u092F\u093E \u0932\u093F\u0902\u0915 \u0938\u092E\u093E\u092A\u094D\u0924 \u0939\u094B \u0917\u092F\u093E \u0939\u0948\u0964 \u0938\u0924\u094D\u092F\u093E\u092A\u0928 \u092A\u0947\u091C \u092A\u0930 \u0928\u092F\u093E \u0932\u093F\u0902\u0915 \u092E\u093E\u0901\u0917\u0947\u0902\u0964",
  "ui.common.account.out_unverified_inbox": "Radient \u0915\u093E \u092D\u0947\u091C\u093E \u0932\u093F\u0902\u0915 \u0905\u092A\u0928\u0947 \u0907\u0928\u092C\u0949\u0915\u094D\u0938 \u092E\u0947\u0902 \u0926\u0947\u0916\u0947\u0902\u0964",
  "ui.common.account.out_verified": "\u0906\u092A\u0915\u0947 \u0915\u094D\u0930\u0947\u0921\u093F\u091F \u0916\u0924\u094D\u092E \u0939\u094B \u0917\u090F \u0939\u0948\u0902\u0964 Radient Console \u092E\u0947\u0902 \u0915\u094D\u0930\u0947\u0921\u093F\u091F \u091C\u094B\u0921\u093C\u0947\u0902\u0964",
  "ui.common.account.first_top_up_bonus": "\u092A\u0939\u0932\u0940 \u092C\u093E\u0930 {minimum} \u092F\u093E \u0909\u0938\u0938\u0947 \u091C\u093C\u094D\u092F\u093E\u0926\u093E \u0915\u0947 \u0915\u094D\u0930\u0947\u0921\u093F\u091F \u091C\u094B\u0921\u093C\u0928\u0947 \u092A\u0930 {bonus} \u0905\u0924\u093F\u0930\u093F\u0915\u094D\u0924 \u092E\u0941\u092B\u093C\u094D\u0924 \u092A\u093E\u090F\u0901\u0964",
