  "ui.common.actions.agent_exported": "\u090F\u091C\u0947\u0902\u091F \u090F\u0915\u094D\u0938\u092A\u094B\u0930\u094D\u091F \u0915\u093F\u092F\u093E \u0917\u092F\u093E",
