  "ui.common.actions.variable_created": "\u0935\u0947\u0930\u093F\u090F\u092C\u0932 \u092C\u0928\u093E\u092F\u093E \u0917\u092F\u093E",
  "ui.common.actions.variable_updated": "\u0935\u0947\u0930\u093F\u090F\u092C\u0932 \u0905\u092A\u0921\u0947\u091F \u0915\u093F\u092F\u093E \u0917\u092F\u093E",
