var ui_common_connection_default4 = {
  "ui.common.connection.backend_compatibility_banner.the_backend_update_could_not_start_retry_or_update_from_settings_": "\u092C\u0948\u0915\u090F\u0902\u0921 \u0905\u092A\u0921\u0947\u091F \u0936\u0941\u0930\u0942 \u0928\u0939\u0940\u0902 \u0939\u094B \u0938\u0915\u093E\u0964 \u092B\u093F\u0930 \u0915\u094B\u0936\u093F\u0936 \u0915\u0930\u0947\u0902, \u092F\u093E \u0938\u0947\u091F\u093F\u0902\u0917\u094D\u0938 \u092E\u0947\u0902 \u0910\u092A \u0905\u092A\u0921\u0947\u091F \u0938\u0947 \u0905\u092A\u0921\u0947\u091F \u0915\u0930\u0947\u0902\u0964",
  "ui.common.connection.backend_compatibility_banner.update_backend": "\u092C\u0948\u0915\u090F\u0902\u0921 \u0905\u092A\u0921\u0947\u091F \u0915\u0930\u0947\u0902",
  "ui.common.connection.backend_compatibility_banner.updating": "\u0905\u092A\u0921\u0947\u091F \u0939\u094B \u0930\u0939\u093E \u0939\u0948",
  "ui.common.connection.connectivity_banner.a_connectivity_issue_has_been_detected": "\u0915\u0928\u0947\u0915\u094D\u0936\u0928 \u092E\u0947\u0902 \u0938\u092E\u0938\u094D\u092F\u093E \u092E\u093F\u0932\u0940 \u0939\u0948\u0964",
  "ui.common.connection.connectivity_banner.dismiss": "\u0939\u091F\u093E\u090F\u0901",
  "ui.common.connection.connectivity_banner.dismiss_inline": "\u0939\u091F\u093E\u090F\u0901",
  "ui.common.connection.connectivity_banner.this_app_s_updates_require": "\u0907\u0938 \u0910\u092A \u0915\u0947 \u0905\u092A\u0921\u0947\u091F \u0915\u0947 \u0932\u093F\u090F",
  "ui.common.connection.connectivity_banner.you_are_offline": "\u0906\u092A \u0911\u092B\u093C\u0932\u093E\u0907\u0928 \u0939\u0948\u0902\u0964 {detail} \u0907\u0902\u091F\u0930\u0928\u0947\u091F \u0915\u0928\u0947\u0915\u094D\u0936\u0928 \u091C\u093C\u0930\u0942\u0930\u0940 \u0939\u0948\u0964",
  "ui.common.connection.floating_alert.dismiss": "\u0939\u091F\u093E\u090F\u0901",
  "ui.common.connection.provider.requires": "\u0906\u092A\u0915\u0947 \u091A\u0941\u0928\u0947 \u0939\u0941\u090F \u0939\u094B\u0938\u094D\u091F\u093F\u0902\u0917 \u092A\u094D\u0930\u094B\u0935\u093E\u0907\u0921\u0930 ({provider}) \u0915\u0947 \u0932\u093F\u090F",
  "ui.common.connection.transport_failure": "\u0938\u0930\u094D\u0935\u0930 \u0924\u0915 \u092A\u0939\u0941\u0901\u091A\u093E \u0928\u0939\u0940\u0902 \u091C\u093E \u0938\u0915\u093E\u0964 \u091C\u093E\u0901\u091A\u0947\u0902 \u0915\u093F \u0935\u0939 \u091A\u0932 \u0930\u0939\u093E \u0939\u0948, \u092B\u093F\u0930 \u0915\u094B\u0936\u093F\u0936 \u0915\u0930\u0947\u0902\u0964",
  "ui.common.connection.backend.remedy_outdated": "\u0938\u0930\u094D\u0935\u0930 \u0905\u092A\u0921\u0947\u091F \u0915\u0930\u0947\u0902 \u0914\u0930 \u092B\u093F\u0930 \u0915\u094B\u0936\u093F\u0936 \u0915\u0930\u0947\u0902\u0964",
  "ui.common.connection.backend.diagnosis_unreachable": "Local Operator \u0938\u0930\u094D\u0935\u0930 \u091C\u0935\u093E\u092C \u0928\u0939\u0940\u0902 \u0926\u0947 \u0930\u0939\u093E\u0964",
  "ui.common.connection.backend.diagnosis_deadline": "Local Operator \u0938\u0930\u094D\u0935\u0930 \u0928\u0947 \u0938\u092E\u092F \u092A\u0930 \u091C\u0935\u093E\u092C \u0928\u0939\u0940\u0902 \u0926\u093F\u092F\u093E\u0964",
  "ui.common.connection.backend.diagnosis_unauthorized": "\u092F\u0939 \u0910\u092A \u091A\u0932 \u0930\u0939\u0947 Local Operator \u0938\u0930\u094D\u0935\u0930 \u092A\u0930 \u092A\u094D\u0930\u092E\u093E\u0923\u0940\u0915\u0930\u0923 \u0928\u0939\u0940\u0902 \u0915\u0930 \u0938\u0915\u0924\u093E\u0964",
  "ui.common.connection.backend.diagnosis_outdated": "Local Operator \u0938\u0930\u094D\u0935\u0930 \u0907\u0938 \u0910\u092A \u0915\u0940 \u0909\u092E\u094D\u092E\u0940\u0926 \u0938\u0947 \u092A\u0941\u0930\u093E\u0928\u093E \u0939\u0948\u0964",
  "ui.common.connection.backend.pairing_successor": "\u0910\u092A \u0915\u0947 \u091A\u0932\u0924\u0947-\u091A\u0932\u0924\u0947 Local Operator \u0938\u0930\u094D\u0935\u0930 \u092C\u0926\u0932 \u0917\u092F\u093E\u0964 \u0928\u090F \u0938\u0930\u094D\u0935\u0930 \u0938\u0947 \u092A\u0947\u092F\u0930 \u0915\u093F\u092F\u093E \u091C\u093E \u0930\u0939\u093E \u0939\u0948\u0964",
  "ui.common.connection.backend.pairing_governed": "\u0907\u0938 \u092E\u0936\u0940\u0928 \u0915\u0947 Local Operator \u0938\u0930\u094D\u0935\u0930 \u0915\u094B \u092A\u0939\u0932\u0947 \u0938\u0947 \u0926\u0942\u0938\u0930\u093E \u092A\u094D\u0930\u094B\u0917\u094D\u0930\u093E\u092E \u092A\u094D\u0930\u092C\u0902\u0927\u093F\u0924 \u0915\u0930 \u0930\u0939\u093E \u0939\u0948, \u0907\u0938\u0932\u093F\u090F \u092F\u0939 \u0910\u092A \u0909\u0938\u0915\u0940 \u0938\u0947\u091F\u093F\u0902\u0917\u094D\u0938, \u092A\u094D\u0930\u094B\u0935\u093E\u0907\u0921\u0930 \u0938\u093E\u0907\u0928-\u0907\u0928, \u0938\u094D\u0932\u0948\u0936 \u0915\u092E\u093E\u0902\u0921 \u092F\u093E MCP \u092A\u094D\u0930\u092C\u0902\u0927\u0928 \u0907\u0938\u094D\u0924\u0947\u092E\u093E\u0932 \u0928\u0939\u0940\u0902 \u0915\u0930 \u0938\u0915\u0924\u093E\u0964",
  "ui.common.connection.backend.pairing_pre_handshake": "\u0907\u0938 \u092E\u0936\u0940\u0928 \u0915\u093E Local Operator \u0938\u0930\u094D\u0935\u0930 \u0907\u0938 \u0910\u092A \u0915\u0947 \u092A\u0947\u092F\u0930\u093F\u0902\u0917 \u0939\u0948\u0902\u0921\u0936\u0947\u0915 \u0938\u0947 \u092A\u0941\u0930\u093E\u0928\u093E \u0939\u0948, \u0907\u0938\u0932\u093F\u090F \u0910\u092A \u0909\u0938\u0915\u0947 \u0915\u0902\u091F\u094D\u0930\u094B\u0932 \u0928\u0939\u0940\u0902 \u091A\u0932\u093E \u0938\u0915\u0924\u093E\u0964 \u0938\u0930\u094D\u0935\u0930 \u0914\u0930 \u091F\u0930\u094D\u092E\u093F\u0928\u0932 \u0938\u0947 \u0909\u0938 \u092A\u0930 \u091A\u0932\u093E\u0908 \u091C\u093E\u0928\u0947 \u0935\u093E\u0932\u0940 \u091A\u0940\u091C\u093C\u0947\u0902 \u0905\u092A\u094D\u0930\u092D\u093E\u0935\u093F\u0924 \u0939\u0948\u0902\u0964",
  "ui.common.connection.backend.pairing_credential_refused": "\u091A\u0932 \u0930\u0939\u0947 Local Operator \u0938\u0930\u094D\u0935\u0930 \u0915\u0947 \u0932\u093F\u090F \u0907\u0938 \u0910\u092A \u0915\u093E \u0915\u094D\u0930\u0947\u0921\u0947\u0902\u0936\u093F\u092F\u0932 \u0905\u0938\u094D\u0935\u0940\u0915\u093E\u0930 \u0939\u094B \u0917\u092F\u093E, \u0907\u0938\u0932\u093F\u090F \u092A\u094D\u0930\u094B\u0935\u093E\u0907\u0921\u0930 \u0938\u093E\u0907\u0928-\u0907\u0928, \u0938\u0947\u091F\u093F\u0902\u0917\u094D\u0938, \u0938\u094D\u0932\u0948\u0936 \u0915\u092E\u093E\u0902\u0921 \u0914\u0930 MCP \u092A\u094D\u0930\u092C\u0902\u0927\u0928 \u0909\u092A\u0932\u092C\u094D\u0927 \u0928\u0939\u0940\u0902 \u0939\u0948\u0902\u0964",
  "ui.common.connection.backend.pairing_unpaired": "\u092F\u0939 \u0910\u092A \u091A\u0932 \u0930\u0939\u0947 Local Operator \u0938\u0930\u094D\u0935\u0930 \u0938\u0947 \u092A\u0947\u092F\u0930 \u0928\u0939\u0940\u0902 \u0939\u0948, \u0907\u0938\u0932\u093F\u090F \u092A\u094D\u0930\u094B\u0935\u093E\u0907\u0921\u0930 \u0938\u093E\u0907\u0928-\u0907\u0928, \u0938\u0947\u091F\u093F\u0902\u0917\u094D\u0938, \u0938\u094D\u0932\u0948\u0936 \u0915\u092E\u093E\u0902\u0921 \u0914\u0930 MCP \u092A\u094D\u0930\u092C\u0902\u0927\u0928 \u0909\u092A\u0932\u092C\u094D\u0927 \u0928\u0939\u0940\u0902 \u0939\u0948\u0902\u0964",
  "ui.common.connection.backend.pane_successor": "\u0928\u090F \u0938\u0930\u094D\u0935\u0930 \u0938\u0947 \u0910\u092A \u0915\u093E \u092A\u0947\u092F\u0930 \u0939\u094B\u0928\u0947 \u0924\u0915 \u092F\u0939 \u092C\u093E\u0924\u091A\u0940\u0924 \u092F\u0939\u093E\u0901 \u0928\u0939\u0940\u0902 \u092A\u0922\u093C\u0940 \u091C\u093E \u0938\u0915\u0924\u0940\u0964 \u0906\u092A\u0915\u0940 \u091A\u0948\u091F \u0905\u092C \u092D\u0940 \u0909\u0938\u0940 \u0938\u0930\u094D\u0935\u0930 \u092A\u0930 \u0939\u0948\u0902\u0964",
  "ui.common.connection.backend.pane_governed": "\u092F\u0939 \u092C\u093E\u0924\u091A\u0940\u0924 \u092F\u0939\u093E\u0901 \u0928\u0939\u0940\u0902 \u092A\u0922\u093C\u0940 \u091C\u093E \u0938\u0915\u0924\u0940: \u0938\u0930\u094D\u0935\u0930 \u0915\u0947 \u0921\u0947\u0938\u094D\u0915\u091F\u0949\u092A \u0915\u0902\u091F\u094D\u0930\u094B\u0932 \u0926\u0942\u0938\u0930\u0947 \u092A\u094D\u0930\u094B\u0917\u094D\u0930\u093E\u092E \u0915\u0947 \u092A\u093E\u0938 \u0939\u0948\u0902\u0964 \u0906\u092A\u0915\u0940 \u091A\u0948\u091F \u0905\u092C \u092D\u0940 \u0909\u0938\u0940 \u0938\u0930\u094D\u0935\u0930 \u092A\u0930 \u0939\u0948\u0902\u0964",
  "ui.common.connection.backend.pane_pre_handshake": "\u092F\u0939 \u092C\u093E\u0924\u091A\u0940\u0924 \u092F\u0939\u093E\u0901 \u0928\u0939\u0940\u0902 \u092A\u0922\u093C\u0940 \u091C\u093E \u0938\u0915\u0924\u0940: \u0935\u0939 \u0938\u0930\u094D\u0935\u0930 \u0907\u0938 \u0910\u092A \u0915\u0947 \u092A\u0947\u092F\u0930\u093F\u0902\u0917 \u0939\u0948\u0902\u0921\u0936\u0947\u0915 \u0938\u0947 \u092A\u0941\u0930\u093E\u0928\u093E \u0939\u0948\u0964 \u0906\u092A\u0915\u0940 \u091A\u0948\u091F \u0905\u092C \u092D\u0940 \u0909\u0938\u0940 \u0938\u0930\u094D\u0935\u0930 \u092A\u0930 \u0939\u0948\u0902\u0964",
  "ui.common.connection.backend.pane_credential_refused": "\u092F\u0939 \u092C\u093E\u0924\u091A\u0940\u0924 \u092F\u0939\u093E\u0901 \u0928\u0939\u0940\u0902 \u092A\u0922\u093C\u0940 \u091C\u093E \u0938\u0915\u0924\u0940: \u0938\u0930\u094D\u0935\u0930 \u0928\u0947 \u0907\u0938 \u0910\u092A \u0915\u093E \u0915\u094D\u0930\u0947\u0921\u0947\u0902\u0936\u093F\u092F\u0932 \u0905\u0938\u094D\u0935\u0940\u0915\u093E\u0930 \u0915\u093F\u092F\u093E\u0964 \u0906\u092A\u0915\u0940 \u091A\u0948\u091F \u0905\u092C \u092D\u0940 \u0909\u0938\u0940 \u0938\u0930\u094D\u0935\u0930 \u092A\u0930 \u0939\u0948\u0902\u0964",
  "ui.common.connection.backend.pane_unpaired": "\u092F\u0939 \u092C\u093E\u0924\u091A\u0940\u0924 \u092F\u0939\u093E\u0901 \u0928\u0939\u0940\u0902 \u092A\u0922\u093C\u0940 \u091C\u093E \u0938\u0915\u0924\u0940: \u0910\u092A \u091A\u0932 \u0930\u0939\u0947 \u0938\u0930\u094D\u0935\u0930 \u0938\u0947 \u092A\u0947\u092F\u0930 \u0928\u0939\u0940\u0902 \u0939\u0948\u0964 \u0906\u092A\u0915\u0940 \u091A\u0948\u091F \u0905\u092C \u092D\u0940 \u0909\u0938\u0940 \u0938\u0930\u094D\u0935\u0930 \u092A\u0930 \u0939\u0948\u0902\u0964",
  "ui.common.connection.backend.compatibility_unreachable": "{diagnosis} \u092A\u094D\u0930\u094B\u0935\u093E\u0907\u0921\u0930 \u0938\u093E\u0907\u0928-\u0907\u0928, \u0938\u0947\u091F\u093F\u0902\u0917\u094D\u0938, \u0938\u094D\u0932\u0948\u0936 \u0915\u092E\u093E\u0902\u0921 \u0914\u0930 MCP \u092A\u094D\u0930\u092C\u0902\u0927\u0928 \u0915\u0947 \u0932\u093F\u090F \u0938\u0930\u094D\u0935\u0930 \u0915\u093E \u091A\u0932\u0928\u093E \u091C\u093C\u0930\u0942\u0930\u0940 \u0939\u0948\u0964",
  "ui.common.connection.backend.compatibility_unauthorized": "\u092F\u0939 \u0910\u092A \u091A\u0932 \u0930\u0939\u0947 Local Operator \u0938\u0930\u094D\u0935\u0930 \u092A\u0930 \u092A\u094D\u0930\u092E\u093E\u0923\u0940\u0915\u0930\u0923 \u0928\u0939\u0940\u0902 \u0915\u0930 \u0938\u0915\u0924\u093E, \u0907\u0938\u0932\u093F\u090F \u092A\u094D\u0930\u094B\u0935\u093E\u0907\u0921\u0930 \u0938\u093E\u0907\u0928-\u0907\u0928, \u0938\u0947\u091F\u093F\u0902\u0917\u094D\u0938, \u0938\u094D\u0932\u0948\u0936 \u0915\u092E\u093E\u0902\u0921 \u0914\u0930 MCP \u092A\u094D\u0930\u092C\u0902\u0927\u0928 \u0909\u092A\u0932\u092C\u094D\u0927 \u0928\u0939\u0940\u0902 \u0939\u0948\u0902\u0964",
  "ui.common.connection.backend.compatibility_deadline": "{diagnosis} \u092A\u094D\u0930\u094B\u0935\u093E\u0907\u0921\u0930 \u0938\u093E\u0907\u0928-\u0907\u0928, \u0938\u0947\u091F\u093F\u0902\u0917\u094D\u0938, \u0938\u094D\u0932\u0948\u0936 \u0915\u092E\u093E\u0902\u0921 \u0914\u0930 MCP \u092A\u094D\u0930\u092C\u0902\u0927\u0928 \u0915\u0947 \u0932\u093F\u090F \u0938\u0930\u094D\u0935\u0930 \u0915\u093E \u091C\u0935\u093E\u092C \u0926\u0947\u0928\u093E \u091C\u093C\u0930\u0942\u0930\u0940 \u0939\u0948\u0964",
  "ui.common.connection.backend.compatibility_outdated": "Local Operator \u0938\u0930\u094D\u0935\u0930 \u0907\u0938 \u0910\u092A \u0915\u0940 \u0909\u092E\u094D\u092E\u0940\u0926 \u0938\u0947 \u092A\u0941\u0930\u093E\u0928\u093E \u0939\u0948, \u0907\u0938\u0932\u093F\u090F \u092A\u094D\u0930\u094B\u0935\u093E\u0907\u0921\u0930 \u0938\u093E\u0907\u0928-\u0907\u0928, \u0938\u0947\u091F\u093F\u0902\u0917\u094D\u0938, \u0938\u094D\u0932\u0948\u0936 \u0915\u092E\u093E\u0902\u0921 \u0914\u0930 MCP \u092A\u094D\u0930\u092C\u0902\u0927\u0928 \u092C\u0902\u0926 \u0939\u0948\u0902\u0964 {remedy}",
  "ui.common.connection.backend.compatibility_unknown": "Local Operator \u0938\u0930\u094D\u0935\u0930 \u0928\u0947 \u0909\u092E\u094D\u092E\u0940\u0926 \u0915\u0947 \u092E\u0941\u0924\u093E\u092C\u093F\u0915 \u091C\u0935\u093E\u092C \u0928\u0939\u0940\u0902 \u0926\u093F\u092F\u093E, \u0907\u0938\u0932\u093F\u090F \u092A\u094D\u0930\u094B\u0935\u093E\u0907\u0921\u0930 \u0938\u093E\u0907\u0928-\u0907\u0928, \u0938\u0947\u091F\u093F\u0902\u0917\u094D\u0938, \u0938\u094D\u0932\u0948\u0936 \u0915\u092E\u093E\u0902\u0921 \u0914\u0930 MCP \u092A\u094D\u0930\u092C\u0902\u0927\u0928 \u0909\u092A\u0932\u092C\u094D\u0927 \u0928\u0939\u0940\u0902 \u0939\u0948\u0902\u0964",
  "ui.common.connection.backend.compatibility_missing": "Local Operator \u0938\u0930\u094D\u0935\u0930 \u092E\u0947\u0902 {features} \u0915\u093E \u0938\u092E\u0930\u094D\u0925\u0928 \u0928\u0939\u0940\u0902 \u0939\u0948\u0964 \u0909\u0928 \u0938\u0930\u092B\u093C\u0947\u0938\u094B\u0902 \u0915\u094B \u091A\u093E\u0932\u0942 \u0915\u0930\u0928\u0947 \u0915\u0947 \u0932\u093F\u090F \u0907\u0938\u0947 \u0905\u092A\u0921\u0947\u091F \u0915\u0930\u0947\u0902\u0964",
  "ui.common.connection.backend.card_successor": "\u0906\u092A\u0915\u0940 \u0938\u0947\u091F\u093F\u0902\u0917\u094D\u0938 \u0932\u094B\u0921 \u0928\u0939\u0940\u0902 \u0939\u094B \u0938\u0915\u0940\u0902: \u0910\u092A \u0909\u0938 \u0938\u0930\u094D\u0935\u0930 \u0938\u0947 \u092A\u0947\u092F\u0930 \u0939\u094B \u0930\u0939\u093E \u0939\u0948 \u091C\u093F\u0938\u0928\u0947 \u092A\u093F\u091B\u0932\u0947 \u0938\u0930\u094D\u0935\u0930 \u0915\u0940 \u091C\u0917\u0939 \u0932\u0940 \u0939\u0948\u0964",
  "ui.common.connection.backend.card_governed": "\u0906\u092A\u0915\u0940 \u0938\u0947\u091F\u093F\u0902\u0917\u094D\u0938 \u0932\u094B\u0921 \u0928\u0939\u0940\u0902 \u0939\u094B \u0938\u0915\u0940\u0902: \u0907\u0938 \u092E\u0936\u0940\u0928 \u0915\u0947 Local Operator \u0938\u0930\u094D\u0935\u0930 \u0915\u094B \u0926\u0942\u0938\u0930\u093E \u092A\u094D\u0930\u094B\u0917\u094D\u0930\u093E\u092E \u092A\u094D\u0930\u092C\u0902\u0927\u093F\u0924 \u0915\u0930 \u0930\u0939\u093E \u0939\u0948, \u0907\u0938\u0932\u093F\u090F \u092F\u0939 \u092A\u0947\u091C \u0909\u0928\u094D\u0939\u0947\u0902 \u092F\u0939\u093E\u0901 \u092A\u0922\u093C \u092F\u093E \u092C\u0926\u0932 \u0928\u0939\u0940\u0902 \u0938\u0915\u0924\u093E\u0964",
  "ui.common.connection.backend.card_pre_handshake": "\u0906\u092A\u0915\u0940 \u0938\u0947\u091F\u093F\u0902\u0917\u094D\u0938 \u0932\u094B\u0921 \u0928\u0939\u0940\u0902 \u0939\u094B \u0938\u0915\u0940\u0902: \u091C\u093F\u0938 \u0938\u0930\u094D\u0935\u0930 \u0938\u0947 \u092F\u0939 \u0910\u092A \u091C\u0941\u0921\u093C\u093E \u0939\u0948 \u0935\u0939 \u092A\u0947\u092F\u0930\u093F\u0902\u0917 \u0939\u0948\u0902\u0921\u0936\u0947\u0915 \u0938\u0947 \u092A\u0941\u0930\u093E\u0928\u093E \u0939\u0948, \u0907\u0938\u0932\u093F\u090F \u092F\u0939 \u092A\u0947\u091C \u0909\u0938\u0938\u0947 \u0909\u0928\u094D\u0939\u0947\u0902 \u092A\u0922\u093C \u0928\u0939\u0940\u0902 \u0938\u0915\u0924\u093E\u0964",
  "ui.common.connection.backend.card_credential_refused": "\u0906\u092A\u0915\u0940 \u0938\u0947\u091F\u093F\u0902\u0917\u094D\u0938 \u0932\u094B\u0921 \u0928\u0939\u0940\u0902 \u0939\u094B \u0938\u0915\u0940\u0902: \u0938\u0930\u094D\u0935\u0930 \u0928\u0947 \u0907\u0938 \u0910\u092A \u0915\u093E \u0915\u094D\u0930\u0947\u0921\u0947\u0902\u0936\u093F\u092F\u0932 \u0905\u0938\u094D\u0935\u0940\u0915\u093E\u0930 \u0915\u093F\u092F\u093E, \u0907\u0938\u0932\u093F\u090F \u092F\u0939 \u092A\u0947\u091C \u0909\u0938\u0938\u0947 \u0909\u0928\u094D\u0939\u0947\u0902 \u092A\u0922\u093C \u0928\u0939\u0940\u0902 \u0938\u0915\u0924\u093E\u0964",
  "ui.common.connection.backend.card_unpaired": "\u0906\u092A\u0915\u0940 \u0938\u0947\u091F\u093F\u0902\u0917\u094D\u0938 \u0932\u094B\u0921 \u0928\u0939\u0940\u0902 \u0939\u094B \u0938\u0915\u0940\u0902: \u092F\u0939 \u0910\u092A \u091A\u0932 \u0930\u0939\u0947 \u0938\u0930\u094D\u0935\u0930 \u0938\u0947 \u092A\u0947\u092F\u0930 \u0928\u0939\u0940\u0902 \u0939\u0948, \u0907\u0938\u0932\u093F\u090F \u092F\u0939 \u092A\u0947\u091C \u0909\u0938\u0938\u0947 \u0909\u0928\u094D\u0939\u0947\u0902 \u092A\u0922\u093C \u0928\u0939\u0940\u0902 \u0938\u0915\u0924\u093E\u0964",
  "ui.common.connection.session_loss.frame_too_large": "\u0907\u0938 \u092C\u093E\u0924\u091A\u0940\u0924 \u0915\u0947 \u0905\u092A\u0921\u0947\u091F \u0926\u093F\u0916\u093E\u0928\u0947 \u0915\u0947 \u0932\u093F\u090F \u092C\u0939\u0941\u0924 \u092C\u0921\u093C\u0947 \u0925\u0947 \u2014 \u0926\u094B\u092C\u093E\u0930\u093E \u0915\u0928\u0947\u0915\u094D\u091F \u0915\u0930\u0947\u0902, \u092B\u093F\u0930 \u0915\u094B\u0936\u093F\u0936 \u0915\u0930\u0947\u0902\u0964",
  "ui.common.connection.session_loss.history_unreadable": "\u0907\u0938 \u092C\u093E\u0924\u091A\u0940\u0924 \u0915\u093E \u0907\u0924\u093F\u0939\u093E\u0938 \u0932\u094B\u0921 \u0928\u0939\u0940\u0902 \u0939\u094B \u0938\u0915\u093E \u2014 \u0926\u094B\u092C\u093E\u0930\u093E \u0915\u0928\u0947\u0915\u094D\u091F \u0915\u0930\u0947\u0902, \u092B\u093F\u0930 \u0915\u094B\u0936\u093F\u0936 \u0915\u0930\u0947\u0902\u0964",
  "ui.common.connection.session_loss.lost": "\u0907\u0938 \u092C\u093E\u0924\u091A\u0940\u0924 \u0938\u0947 \u0915\u0928\u0947\u0915\u094D\u0936\u0928 \u091F\u0942\u091F \u0917\u092F\u093E \u2014 \u092A\u0922\u093C\u0924\u0947 \u0930\u0939\u0928\u0947 \u0915\u0947 \u0932\u093F\u090F \u0926\u094B\u092C\u093E\u0930\u093E \u0915\u0928\u0947\u0915\u094D\u091F \u0915\u0930\u0947\u0902\u0964",
  "ui.common.connection.session_loss.not_paired": "\u092F\u0939 \u0910\u092A Local Operator \u0938\u0930\u094D\u0935\u0930 \u0938\u0947 \u092A\u0947\u092F\u0930 \u0928\u0939\u0940\u0902 \u0939\u0948, \u0907\u0938\u0932\u093F\u090F \u092F\u0939 \u092C\u093E\u0924\u091A\u0940\u0924 \u0905\u092D\u0940 \u092A\u0922\u093C\u0940 \u0928\u0939\u0940\u0902 \u091C\u093E \u0938\u0915\u0924\u0940\u0964",
  "ui.common.connection.session_loss.server_down": "Local Operator \u0938\u0930\u094D\u0935\u0930 \u0928\u0939\u0940\u0902 \u091A\u0932 \u0930\u0939\u093E \u0939\u0948 \u2014 \u0935\u093E\u092A\u0938 \u0906\u0928\u0947 \u092A\u0930 \u0926\u094B\u092C\u093E\u0930\u093E \u0915\u0928\u0947\u0915\u094D\u091F \u0915\u0930\u0947\u0902, \u092F\u093E \u0935\u0939 \u092C\u0902\u0926 \u0939\u0940 \u0930\u0939\u0947 \u0924\u094B \u0910\u092A \u092B\u093F\u0930 \u0938\u0947 \u0936\u0941\u0930\u0942 \u0915\u0930\u0947\u0902\u0964"
};

