  "ui.common.updates.install.verifying": "\u092C\u0926\u0932\u0947 \u091C\u093E\u0928\u0947 \u0935\u093E\u0932\u0947 \u0910\u092A \u0915\u0947 \u092E\u0941\u0915\u093E\u092C\u0932\u0947 \u0905\u092A\u0921\u0947\u091F \u0915\u0940 \u091C\u093E\u0901\u091A\u2026",
