  "ui.common.updates.error.install": "\u0905\u092A\u0921\u0947\u091F \u0907\u0902\u0938\u094D\u091F\u0949\u0932 \u0928\u0939\u0940\u0902 \u0939\u094B \u0938\u0915\u093E\u0964 \u0907\u0938 \u092E\u0936\u0940\u0928 \u0915\u093E \u0915\u0928\u0947\u0915\u094D\u0936\u0928 \u091C\u093E\u0901\u091A\u0947\u0902, \u092B\u093F\u0930 \u0905\u092A\u0921\u0947\u091F \u092A\u0948\u0928\u0932 \u0938\u0947 \u0907\u0938\u0947 \u0926\u094B\u092C\u093E\u0930\u093E \u0936\u0941\u0930\u0942 \u0915\u0930\u0947\u0902\u0964",
  "ui.common.updates.error.quit": "\u0907\u0902\u0938\u094D\u091F\u0949\u0932 \u092A\u0942\u0930\u093E \u0915\u0930\u0928\u0947 \u0915\u0947 \u0932\u093F\u090F \u0910\u092A \u092C\u0902\u0926 \u0928\u0939\u0940\u0902 \u0939\u094B \u0938\u0915\u093E\u0964 \u0910\u092A \u0916\u0941\u0926 \u092C\u0902\u0926 \u0915\u0930\u0947\u0902, \u092B\u093F\u0930 \u0905\u092A\u0921\u0947\u091F \u092A\u0942\u0930\u093E \u0939\u094B\u0928\u0947 \u0926\u0947\u0902\u0964",
  "ui.common.updates.error.check_incomplete": "\u0905\u092A\u0921\u0947\u091F \u091C\u093E\u0901\u091A \u092A\u0942\u0930\u0940 \u0928\u0939\u0940\u0902 \u0939\u094B \u0938\u0915\u0940\u0964 \u0910\u092A \u0905\u0917\u0932\u0940 \u091C\u093E\u0901\u091A \u092E\u0947\u0902 \u092B\u093F\u0930 \u0915\u094B\u0936\u093F\u0936 \u0915\u0930\u0947\u0917\u093E\u0964",
  "ui.common.updates.error.version_unknown_required": "\u0905\u091C\u094D\u091E\u093E\u0924 (\u0905\u092A\u0921\u0947\u091F \u091C\u093C\u0930\u0942\u0930\u0940)",
  "ui.common.updates.update_foot_icon.sessions_keep_running": "\u0905\u092A\u0921\u0947\u091F \u0915\u0930\u0928\u0947 \u0938\u0947 \u091A\u0932 \u0930\u0939\u0947 \u0938\u0924\u094D\u0930 \u0928\u0939\u0940\u0902 \u0930\u0941\u0915\u0924\u0947\u0964",
  "ui.common.updates.update_notification.remedy_managed_app_owned": "\u091A\u0932 \u0930\u0939\u0947 \u0938\u0924\u094D\u0930 \u092C\u0940\u091A \u092E\u0947\u0902 \u0928\u0939\u0940\u0902 \u0930\u0941\u0915\u0924\u0947\u0964 \u0910\u092A \u0928\u092F\u093E \u092C\u093F\u0932\u094D\u0921 \u0938\u0930\u094D\u0935\u0930 \u0915\u0947 \u092E\u094C\u091C\u0942\u0926\u093E \u092C\u093F\u0932\u094D\u0921 \u0915\u0947 \u092C\u0917\u0932 \u092E\u0947\u0902 \u092A\u094D\u0930\u0915\u093E\u0936\u093F\u0924 \u0915\u0930\u0924\u093E \u0939\u0948 \u0914\u0930 \u092B\u093F\u0930 \u0938\u0930\u094D\u0935\u0930 \u0915\u094B \u0909\u0938 \u092A\u0930 \u0932\u0947 \u091C\u093E\u0924\u093E \u0939\u0948\u0964 \u0915\u093E\u092E \u0915\u0930 \u0930\u0939\u0947 \u0938\u0924\u094D\u0930 \u0905\u0917\u0932\u0940 \u092C\u093E\u0930 \u0930\u0941\u0915\u0928\u0947 \u092F\u093E \u0928\u093F\u0937\u094D\u0915\u094D\u0930\u093F\u092F \u0939\u094B\u0928\u0947 \u092A\u0930 \u0928\u090F \u092C\u093F\u0932\u094D\u0921 \u092A\u0930 \u0906 \u091C\u093E\u0924\u0947 \u0939\u0948\u0902\u0964 \u0907\u0938\u092E\u0947\u0902 \u090F\u0915-\u0926\u094B \u092E\u093F\u0928\u091F \u0932\u0917 \u0938\u0915\u0924\u0947 \u0939\u0948\u0902\u0964",
  "ui.common.updates.update_notification.remedy_managed_global": "\u091A\u0932 \u0930\u0939\u0947 \u0938\u0924\u094D\u0930 \u092C\u0940\u091A \u092E\u0947\u0902 \u0928\u0939\u0940\u0902 \u0930\u0941\u0915\u0924\u0947\u0964 \u0910\u092A \u0928\u092F\u093E \u092C\u093F\u0932\u094D\u0921 \u0907\u0938\u094D\u0924\u0947\u092E\u093E\u0932 \u092E\u0947\u0902 \u092E\u094C\u091C\u0942\u0926 \u092C\u093F\u0932\u094D\u0921 \u0915\u0947 \u092C\u0917\u0932 \u092E\u0947\u0902 \u0907\u0902\u0938\u094D\u091F\u0949\u0932 \u0915\u0930\u0924\u093E \u0939\u0948 \u0914\u0930 \u0938\u0930\u094D\u0935\u0930 \u0915\u094B \u0924\u0941\u0930\u0902\u0924 \u0909\u0938 \u092A\u0930 \u0932\u0947 \u091C\u093E\u0924\u093E \u0939\u0948\u0964 \u0938\u0924\u094D\u0930 \u0905\u0917\u0932\u0940 \u092C\u093E\u0930 \u0928\u093F\u0937\u094D\u0915\u094D\u0930\u093F\u092F \u0939\u094B\u0928\u0947 \u092A\u0930 \u0928\u090F \u092C\u093F\u0932\u094D\u0921 \u092A\u0930 \u0906 \u091C\u093E\u0924\u0947 \u0939\u0948\u0902\u0964"
