  "ui.hub.pages.viewer_unknown": "\u0906\u092A\u0915\u0947 \u0932\u093E\u0907\u0915 \u0914\u0930 \u092A\u0938\u0902\u0926\u0940\u0926\u093E \u092A\u0922\u093C\u0947 \u0928\u0939\u0940\u0902 \u091C\u093E \u0938\u0915\u0947, \u0907\u0938\u0932\u093F\u090F \u0915\u093F\u0938\u0940 \u092D\u0940 \u0915\u093E\u0930\u094D\u0921 \u092A\u0930 \u0932\u093E\u0907\u0915 \u092F\u093E \u092A\u0938\u0902\u0926\u0940\u0926\u093E \u0915\u0940 \u0938\u094D\u0925\u093F\u0924\u093F \u0928\u0939\u0940\u0902 \u0926\u093F\u0916\u093E\u0908 \u0917\u0908 \u0939\u0948\u0964",
  "ui.hub.pages.signed_out.title": "\u0939\u092C \u0907\u0938\u094D\u0924\u0947\u092E\u093E\u0932 \u0915\u0930\u0928\u0947 \u0915\u0947 \u0932\u093F\u090F \u0938\u093E\u0907\u0928 \u0907\u0928 \u0915\u0930\u0947\u0902",
  "ui.hub.pages.signed_out.body": "\u0906\u092A Radient \u092E\u0947\u0902 \u0938\u093E\u0907\u0928 \u0907\u0928 \u0928\u0939\u0940\u0902 \u0939\u0948\u0902, \u0907\u0938\u0932\u093F\u090F \u090F\u091C\u0947\u0902\u091F \u0938\u0942\u091A\u0940 \u092A\u0922\u093C\u0928\u0947 \u0915\u0947 \u0932\u093F\u090F \u0939\u092C \u0915\u0947 \u092A\u093E\u0938 \u0915\u094B\u0908 \u0915\u094D\u0930\u0947\u0921\u0947\u0902\u0936\u093F\u092F\u0932 \u0928\u0939\u0940\u0902 \u0939\u0948\u0964 \u0938\u0947\u091F\u093F\u0902\u0917\u094D\u0938 \u092A\u0947\u091C \u092A\u0930 \u0938\u093E\u0907\u0928 \u0907\u0928 \u0915\u0930\u0947\u0902, \u092B\u093F\u0930 \u0915\u094B\u0936\u093F\u0936 \u0915\u0930\u0947\u0902\u0964",
  "ui.hub.pages.load_failed.title": "\u0939\u092C \u0932\u094B\u0921 \u0928\u0939\u0940\u0902 \u0915\u093F\u092F\u093E \u091C\u093E \u0938\u0915\u093E",
  "ui.hub.pages.list_unreadable": "\u090F\u091C\u0947\u0902\u091F \u0938\u0942\u091A\u0940 \u0932\u094B\u0921 \u0928\u0939\u0940\u0902 \u0939\u094B \u0938\u0915\u0940\u0964",
  "ui.hub.pages.org.plan_headline": "\u0909\u0938 \u0938\u0902\u0917\u0920\u0928 \u0915\u0947 \u0932\u093F\u090F \u0938\u0915\u094D\u0930\u093F\u092F Radient Team \u092A\u094D\u0932\u093E\u0928 \u091C\u093C\u0930\u0942\u0930\u0940 \u0939\u0948",
  "ui.hub.pages.org.no_access_headline": "\u0906\u092A\u0915\u0947 \u092A\u093E\u0938 \u0909\u0938 \u0938\u0902\u0917\u0920\u0928 \u0924\u0915 \u092A\u0939\u0941\u0901\u091A \u0928\u0939\u0940\u0902 \u0939\u0948",
  "ui.hub.pages.org.plan_body": "\u0938\u0902\u0917\u0920\u0928 \u0915\u0947 \u0905\u0902\u0926\u0930 \u090F\u091C\u0947\u0902\u091F \u0938\u093E\u091D\u093E \u0915\u0930\u0928\u093E Radient Team \u092A\u094D\u0932\u093E\u0928 \u0915\u093E \u0939\u093F\u0938\u094D\u0938\u093E \u0939\u0948\u0964 {org} \u0915\u093E \u0915\u094B\u0908 \u092E\u093E\u0932\u093F\u0915 \u0907\u0938\u0947 Radient \u0915\u0902\u0938\u094B\u0932 \u092E\u0947\u0902 \u091A\u093E\u0932\u0942 \u0915\u0930 \u0938\u0915\u0924\u093E \u0939\u0948, \u0914\u0930 \u092B\u093F\u0930 \u0909\u0938\u0915\u0947 \u090F\u091C\u0947\u0902\u091F \u092F\u0939\u093E\u0901 \u0938\u0942\u091A\u0940\u092C\u0926\u094D\u0927 \u0939\u094B\u0902\u0917\u0947\u0964",
  "ui.hub.pages.org.no_access_body": "\u0906\u092A {org} \u0915\u0947 \u0938\u0926\u0938\u094D\u092F \u0928\u0939\u0940\u0902 \u0939\u0948\u0902, \u0907\u0938\u0932\u093F\u090F \u0909\u0938\u0915\u0947 \u090F\u091C\u0947\u0902\u091F \u092F\u0939\u093E\u0901 \u0938\u0942\u091A\u0940\u092C\u0926\u094D\u0927 \u0928\u0939\u0940\u0902 \u0939\u0948\u0902\u0964 \u0915\u094B\u0908 \u092E\u093E\u0932\u093F\u0915 \u0906\u092A\u0915\u094B \u092B\u093F\u0930 \u0938\u0947 \u0906\u092E\u0902\u0924\u094D\u0930\u093F\u0924 \u0915\u0930 \u0938\u0915\u0924\u093E \u0939\u0948\u0964",
