  "ui.miniView.hotkey_needs_modifier": "\u0917\u094D\u0932\u094B\u092C\u0932 \u0936\u0949\u0930\u094D\u091F\u0915\u091F \u092E\u0947\u0902 \u092E\u0949\u0921\u093F\u092B\u093C\u093E\u092F\u0930 \u091C\u093C\u0930\u0942\u0930\u0940 \u0939\u0948 \u2014 \u0935\u0930\u0928\u093E \u091F\u093E\u0907\u092A \u0915\u0930\u0924\u0947 \u0938\u092E\u092F \u092D\u0940 \u0935\u0939 \u091A\u0932 \u092A\u0921\u093C\u0947\u0917\u093E\u0964",
