  "ui.ownerAudit.title": "\u0906\u092A\u0915\u0947 \u091A\u0940\u092B\u093C \u0911\u092B\u093C \u0938\u094D\u091F\u093E\u092B\u093C \u0915\u0947 \u0938\u0902\u0926\u0947\u0936",
