  "ui.ownerAudit.empty_replies": "\u0907\u0938 \u0911\u0921\u093F\u091F \u0905\u0935\u0927\u093F \u092E\u0947\u0902 \u0915\u094B\u0908 \u091C\u0935\u093E\u092C \u0928\u0939\u0940\u0902 \u0939\u0948\u0964",
  "ui.ownerAudit.page_cutoff": "\u092A\u0941\u0930\u093E\u0928\u0947 \u0938\u0902\u0926\u0947\u0936 \u0905\u092D\u0940 \u0928\u0939\u0940\u0902 \u0926\u093F\u0916\u093E\u090F \u0917\u090F \u0939\u0948\u0902\u0964 \u0907\u0938\u0938\u0947 \u092A\u0939\u0932\u0947 \u0915\u0947 \u0938\u0902\u0926\u0947\u0936 \u092A\u0922\u093C\u0928\u0947 \u0915\u0947 \u0932\u093F\u090F \u092A\u0941\u0930\u093E\u0928\u0947 \u0938\u0902\u0926\u0947\u0936 \u0932\u094B\u0921 \u0915\u0930\u0947\u0902\u0964",
  "ui.ownerAudit.admitted": "\u0906\u092A\u0915\u0947 \u091A\u0940\u092B\u093C \u0911\u092B\u093C \u0938\u094D\u091F\u093E\u092B\u093C \u0928\u0947 \u0938\u094D\u0935\u0940\u0915\u093E\u0930 \u0915\u093F\u092F\u093E",
