  "ui.ownerAudit.not_screened": "\u0906\u092A\u0915\u0947 \u091A\u0940\u092B\u093C \u0911\u092B\u093C \u0938\u094D\u091F\u093E\u092B\u093C \u0928\u0947 \u091C\u093E\u0901\u091A \u0928\u0939\u0940\u0902 \u0915\u0940",
  "ui.ownerAudit.held_review": "\u0906\u092A\u0915\u0947 \u091A\u0940\u092B\u093C \u0911\u092B\u093C \u0938\u094D\u091F\u093E\u092B\u093C \u0915\u0947 \u0938\u0924\u094D\u0930 \u092E\u0947\u0902 \u0906\u092A\u0915\u0940 \u0938\u092E\u0940\u0915\u094D\u0937\u093E \u0915\u0947 \u0932\u093F\u090F \u0930\u094B\u0915\u093E \u0917\u092F\u093E",
  "ui.ownerAudit.screening": "\u0906\u092A\u0915\u0947 \u091A\u0940\u092B\u093C \u0911\u092B\u093C \u0938\u094D\u091F\u093E\u092B\u093C \u091C\u093E\u0901\u091A \u0915\u0930 \u0930\u0939\u0947 \u0939\u0948\u0902",
  "ui.ownerAudit.screening_retry": "\u0906\u092A\u0915\u0947 \u091A\u0940\u092B\u093C \u0911\u092B\u093C \u0938\u094D\u091F\u093E\u092B\u093C \u0905\u092D\u0940 \u0907\u0938\u0915\u0940 \u091C\u093E\u0901\u091A \u0928\u0939\u0940\u0902 \u0915\u0930 \u0938\u0915\u0947; \u0926\u094B\u092C\u093E\u0930\u093E \u0915\u094B\u0936\u093F\u0936 \u091C\u093E\u0930\u0940",
  "ui.ownerAudit.delivery_pending": "\u091C\u093E\u0901\u091A \u0939\u094B \u0917\u0908; \u0906\u092A\u0915\u0947 \u091A\u0940\u092B\u093C \u0911\u092B\u093C \u0938\u094D\u091F\u093E\u092B\u093C \u0924\u0915 \u092A\u0939\u0941\u0901\u091A\u0928\u093E \u092C\u093E\u0915\u0940",
  "ui.ownerAudit.unknown_status": "\u0938\u094D\u0925\u093F\u0924\u093F \u0905\u091C\u094D\u091E\u093E\u0924",
  "ui.ownerAudit.body_unavailable": "\u0938\u0902\u0926\u0947\u0936 \u0915\u093E \u092A\u093E\u0920 \u0909\u092A\u0932\u092C\u094D\u0927 \u0928\u0939\u0940\u0902 \u0939\u0948\u0964",
  "ui.ownerAudit.attachment_expired": "\u0905\u091F\u0948\u091A\u092E\u0947\u0902\u091F \u0915\u0940 \u0938\u092E\u092F-\u0938\u0940\u092E\u093E \u0938\u092E\u093E\u092A\u094D\u0924; \u0938\u093E\u092E\u0917\u094D\u0930\u0940 \u0909\u092A\u0932\u092C\u094D\u0927 \u0928\u0939\u0940\u0902 \u0939\u0948\u0964",
  "ui.ownerAudit.attachment_unavailable": "\u0905\u091F\u0948\u091A\u092E\u0947\u0902\u091F \u092E\u094C\u091C\u0942\u0926 \u0939\u0948; \u0907\u0938 \u0926\u0943\u0936\u094D\u092F \u092E\u0947\u0902 \u0921\u093E\u0909\u0928\u0932\u094B\u0921 \u0909\u092A\u0932\u092C\u094D\u0927 \u0928\u0939\u0940\u0902 \u0939\u0948\u0964",
  "ui.ownerAudit.unknown_sender": "\u0905\u091C\u094D\u091E\u093E\u0924 \u092A\u094D\u0930\u0947\u0937\u0915",
  "ui.ownerAudit.active": "\u0906\u092A\u0915\u0947 \u091A\u0940\u092B\u093C \u0911\u092B\u093C \u0938\u094D\u091F\u093E\u092B\u093C \u0905\u092C \u092D\u0940 \u0938\u0926\u0938\u094D\u092F \u0939\u0948\u0902\u0964",
  "ui.ownerAudit.left": "\u0911\u0921\u093F\u091F \u092F\u0939\u093E\u0901 \u0938\u092E\u093E\u092A\u094D\u0924 \u0939\u094B\u0924\u093E \u0939\u0948\u0964 \u0906\u092A\u0915\u0947 \u091A\u0940\u092B\u093C \u0911\u092B\u093C \u0938\u094D\u091F\u093E\u092B\u093C \u0907\u0938 \u092C\u093E\u0924\u091A\u0940\u0924 \u0938\u0947 \u0928\u093F\u0915\u0932 \u0917\u090F, \u0907\u0938\u0932\u093F\u090F \u092C\u093E\u0926 \u0915\u0947 \u0938\u0902\u0926\u0947\u0936 \u0907\u0938 \u0911\u0921\u093F\u091F \u092E\u0947\u0902 \u0936\u093E\u092E\u093F\u0932 \u0928\u0939\u0940\u0902 \u0939\u0948\u0902\u0964",
  "ui.ownerAudit.removed": "\u0911\u0921\u093F\u091F \u092F\u0939\u093E\u0901 \u0938\u092E\u093E\u092A\u094D\u0924 \u0939\u094B\u0924\u093E \u0939\u0948\u0964 \u0906\u092A\u0915\u0947 \u091A\u0940\u092B\u093C \u0911\u092B\u093C \u0938\u094D\u091F\u093E\u092B\u093C \u0915\u094B \u0907\u0938 \u092C\u093E\u0924\u091A\u0940\u0924 \u0938\u0947 \u0939\u091F\u093E \u0926\u093F\u092F\u093E \u0917\u092F\u093E, \u0907\u0938\u0932\u093F\u090F \u092C\u093E\u0926 \u0915\u0947 \u0938\u0902\u0926\u0947\u0936 \u0907\u0938 \u0911\u0921\u093F\u091F \u092E\u0947\u0902 \u0936\u093E\u092E\u093F\u0932 \u0928\u0939\u0940\u0902 \u0939\u0948\u0902\u0964",
  "ui.ownerAudit.window_unconfirmed": "\u0907\u0938 \u0911\u0921\u093F\u091F \u0915\u093E \u0905\u0902\u0924 \u091C\u094D\u091E\u093E\u0924 \u0928\u0939\u0940\u0902 \u0939\u0948\u0964 \u0907\u0938 \u092C\u093E\u0924\u091A\u0940\u0924 \u092E\u0947\u0902 \u0906\u092A\u0915\u0947 \u091A\u0940\u092B\u093C \u0911\u092B\u093C \u0938\u094D\u091F\u093E\u092B\u093C \u0915\u0940 \u0938\u0926\u0938\u094D\u092F\u0924\u093E \u0915\u0940 \u092A\u0941\u0937\u094D\u091F\u093F \u0928\u0939\u0940\u0902 \u0939\u094B \u0938\u0915\u0940\u0964",
  "ui.ownerAudit.disclosure": "\u0906\u092A \u092F\u0939 \u0911\u0921\u093F\u091F \u0926\u0947\u0916 \u0938\u0915\u0924\u0947 \u0939\u0948\u0902 \u0915\u094D\u092F\u094B\u0902\u0915\u093F \u091C\u093F\u0938 \u091A\u0940\u092B\u093C \u0911\u092B\u093C \u0938\u094D\u091F\u093E\u092B\u093C \u0915\u093E \u092F\u0939 \u0911\u0921\u093F\u091F \u0939\u0948, \u0909\u0938\u0915\u0947 \u092E\u093E\u0932\u093F\u0915 \u0906\u092A \u0939\u0948\u0902\u0964 \u092C\u093E\u0915\u0940 \u0938\u0926\u0938\u094D\u092F\u094B\u0902 \u0915\u094B \u092C\u0924\u093E\u092F\u093E \u091C\u093E\u0924\u093E \u0939\u0948 \u0915\u093F \u090F\u091C\u0947\u0902\u091F \u0915\u0947 \u092E\u093E\u0932\u093F\u0915 \u092C\u093E\u0924\u091A\u0940\u0924 \u0915\u093E \u0911\u0921\u093F\u091F \u0915\u0930 \u0938\u0915\u0924\u0947 \u0939\u0948\u0902\u0964",
  "ui.ownerAudit.viewers_label": "\u0905\u0928\u094D\u092F \u092A\u093E\u0920\u0915",
  "ui.ownerAudit.replies": "\u0925\u094D\u0930\u0947\u0921 \u0915\u0947 \u0909\u0924\u094D\u0924\u0930 \u092A\u0922\u093C\u0947\u0902",
  "ui.ownerAudit.auth_required": "\u0911\u0921\u093F\u091F \u0915\u093F\u090F \u0917\u090F \u0938\u0902\u0926\u0947\u0936 \u092A\u0922\u093C\u0928\u0947 \u0915\u0947 \u0932\u093F\u090F \u0938\u093E\u0907\u0928 \u0907\u0928 \u0915\u0930\u0947\u0902\u0964 \u0939\u094B \u0938\u0915\u0924\u093E \u0939\u0948 \u0915\u093F \u0906\u092A\u0915\u0947 \u0938\u0924\u094D\u0930 \u0915\u0940 \u0938\u092E\u092F-\u0938\u0940\u092E\u093E \u0938\u092E\u093E\u092A\u094D\u0924 \u0939\u094B \u0917\u0908 \u0939\u094B\u0964",
  "ui.ownerAudit.permission_refused": "\u0906\u092A\u0915\u094B \u0907\u0938 \u0911\u0921\u093F\u091F \u0907\u0924\u093F\u0939\u093E\u0938 \u0915\u094B \u0926\u0947\u0916\u0928\u0947 \u0915\u0940 \u0905\u0928\u0941\u092E\u0924\u093F \u0928\u0939\u0940\u0902 \u0939\u0948\u0964",
  "ui.ownerAudit.not_found": "\u0911\u0921\u093F\u091F \u0915\u0940 \u0917\u0908 \u092F\u0939 \u092C\u093E\u0924\u091A\u0940\u0924 \u0928\u0939\u0940\u0902 \u092E\u093F\u0932\u0940\u0964",
  "ui.ownerAudit.unavailable": "\u0911\u0921\u093F\u091F \u0938\u0947\u0935\u093E \u0907\u0928 \u0938\u0902\u0926\u0947\u0936\u094B\u0902 \u0915\u094B \u0932\u094B\u0921 \u0928\u0939\u0940\u0902 \u0915\u0930 \u0938\u0915\u0940\u0964 \u092B\u093F\u0930 \u0938\u0947 \u0915\u094B\u0936\u093F\u0936 \u0915\u0930\u0947\u0902\u0964",
  "ui.ownerAudit.sign_in": "\u0938\u093E\u0907\u0928 \u0907\u0928 \u0915\u0930\u0947\u0902",
  "ui.ownerAudit.inspect_body": "\u0938\u0902\u0926\u0947\u0936 \u0915\u093E \u092A\u093E\u0920 \u091C\u093E\u0901\u091A\u0947\u0902",
  "ui.ownerAudit.inline_image_receipt": "\u0907\u0928\u0932\u093E\u0907\u0928 \u091B\u0935\u093F \u0921\u0947\u091F\u093E \xB7 {mime} \xB7 {count} \u0935\u0930\u094D\u0923",
