  "ui.settings.account.radient_account_section.loading_your_radient_account_details": "\u0906\u092A\u0915\u0947 Radient \u0916\u093E\u0924\u0947 \u0915\u0940 \u091C\u093E\u0928\u0915\u093E\u0930\u0940 \u0932\u094B\u0921 \u0939\u094B \u0930\u0939\u0940 \u0939\u0948\u2026",
  "ui.settings.account.radient_account_section.not_provided": "\u0928\u0939\u0940\u0902 \u0926\u093F\u092F\u093E \u0917\u092F\u093E",
