  "ui.settings.appearance.layers.palette_meta_both": "\u0915\u0902\u091F\u094D\u0930\u093E\u0938\u094D\u091F: {contrast}, \u0906\u092A\u0915\u093E \u090F\u0915\u094D\u0938\u0947\u0902\u091F",
  "ui.settings.appearance.contrast.background_ceiling": "\u0907\u0938 \u0925\u0940\u092E \u0915\u0940 \u092A\u0943\u0937\u094D\u0920\u092D\u0942\u092E\u093F \u092A\u0939\u0932\u0947 \u0939\u0940 \u0938\u092C\u0938\u0947 \u091C\u093C\u094D\u092F\u093E\u0926\u093E \u091A\u092E\u0915\u0940\u0932\u0940 \u0939\u0948, \u0907\u0938\u0932\u093F\u090F \u0915\u0902\u091F\u094D\u0930\u093E\u0938\u094D\u091F \u0914\u0930 \u092C\u0922\u093C\u093E\u0928\u0947 \u092A\u0930 \u091F\u0947\u0915\u094D\u0938\u094D\u091F \u0917\u0939\u0930\u093E \u0939\u094B \u091C\u093E\u0924\u093E \u0939\u0948\u0964",
  "ui.settings.appearance.contrast.capped_hint": "\u092F\u0939 \u0925\u0940\u092E \u0909\u0938 \u0915\u0902\u091F\u094D\u0930\u093E\u0938\u094D\u091F \u0938\u0940\u092E\u093E \u0924\u0915 \u092A\u0939\u0941\u0901\u091A \u0917\u0908 \u0939\u0948 \u091C\u0939\u093E\u0901 \u091F\u0947\u0915\u094D\u0938\u094D\u091F \u092A\u0922\u093C\u0928\u0947 \u0932\u093E\u092F\u0915 \u0930\u0939\u0924\u093E \u0939\u0948, \u0907\u0938\u0932\u093F\u090F \u0938\u092C\u0938\u0947 \u0928\u091C\u093C\u0926\u0940\u0915\u0940 \u0910\u0938\u0940 \u0938\u0947\u091F\u093F\u0902\u0917 \u0926\u093F\u0916\u093E\u0908 \u0917\u0908 \u0939\u0948 \u091C\u093F\u0938\u092E\u0947\u0902 \u091F\u0947\u0915\u094D\u0938\u094D\u091F \u092A\u0922\u093C\u093E \u091C\u093E \u0938\u0915\u0947\u0964",
