// src/i18n/catalogues/hi/ui.settings.appearance.window_glass.json
var ui_settings_appearance_window_glass_default4 = {
  "ui.settings.appearance.window_glass.label": "\u092A\u093E\u0930\u092D\u093E\u0938\u0940 \u0935\u093F\u0902\u0921\u094B",
  "ui.settings.appearance.window_glass.description": "\u0910\u092A \u0915\u0940 \u0935\u093F\u0902\u0921\u094B \u0915\u0947 \u092A\u0940\u091B\u0947 \u0906\u092A\u0915\u093E \u0921\u0947\u0938\u094D\u0915\u091F\u0949\u092A \u0926\u093F\u0916\u093E\u0924\u093E \u0939\u0948, \u091C\u093F\u0938\u0947 \u0938\u093F\u0938\u094D\u091F\u092E \u0927\u0941\u0902\u0927\u0932\u093E \u0915\u0930\u0924\u093E \u0939\u0948\u0964 macOS \u092A\u0930 \u0938\u093F\u0938\u094D\u091F\u092E \u0915\u093E \u0938\u092A\u094B\u0930\u094D\u091F \u0939\u094B\u0928\u0947 \u092A\u0930 \u092F\u0939 \u0921\u093F\u092B\u093C\u0949\u0932\u094D\u091F \u0930\u0942\u092A \u0938\u0947 \u091A\u093E\u0932\u0942 \u0939\u0948, \u0914\u0930 \u092C\u093E\u0915\u0940 \u091C\u0917\u0939 \u092C\u0902\u0926 \u0939\u0948\u0964 \u0939\u0930 \u0925\u0940\u092E \u092E\u0947\u0902 \u091F\u0947\u0915\u094D\u0938\u094D\u091F \u092A\u0922\u093C\u0928\u0947 \u0932\u093E\u092F\u0915 \u0930\u0939\u0924\u093E \u0939\u0948: \u0915\u093F\u0938\u0940 \u092D\u0940 \u0925\u0940\u092E \u0915\u093E \u091F\u0947\u0915\u094D\u0938\u094D\u091F \u092A\u0922\u093C\u0928\u093E \u092E\u0941\u0936\u094D\u0915\u093F\u0932 \u0939\u094B\u0928\u0947 \u0938\u0947 \u092A\u0939\u0932\u0947 \u0938\u094D\u0932\u093E\u0907\u0921\u0930 \u0930\u0941\u0915 \u091C\u093E\u0924\u093E \u0939\u0948\u0964",
  "ui.settings.appearance.window_glass.restart_needed": "\u092F\u0939 \u092C\u0926\u0932\u093E\u0935 \u0932\u093E\u0917\u0942 \u0915\u0930\u0928\u0947 \u0915\u0947 \u0932\u093F\u090F Local Operator \u0926\u094B\u092C\u093E\u0930\u093E \u0936\u0941\u0930\u0942 \u0915\u0930\u0947\u0902\u0964 \u0924\u092C \u0924\u0915 \u0935\u093F\u0902\u0921\u094B \u0915\u0940 \u092E\u094C\u091C\u0942\u0926\u093E \u0926\u093F\u0916\u093E\u0935\u091F \u092C\u0928\u0940 \u0930\u0939\u0947\u0917\u0940\u0964",
  "ui.settings.appearance.window_glass.unsupported_reduced_transparency": "\u092A\u093E\u0930\u092D\u093E\u0938\u0940 \u0935\u093F\u0902\u0921\u094B \u0909\u092A\u0932\u092C\u094D\u0927 \u0928\u0939\u0940\u0902 \u0939\u0948, \u0915\u094D\u092F\u094B\u0902\u0915\u093F \u0906\u092A\u0915\u0947 \u0938\u093F\u0938\u094D\u091F\u092E \u0915\u0940 \u0938\u0941\u0932\u092D\u0924\u093E \u0938\u0947\u091F\u093F\u0902\u0917\u094D\u0938 \u092E\u0947\u0902 \u092A\u093E\u0930\u0926\u0930\u094D\u0936\u093F\u0924\u093E \u0915\u092E \u0915\u0930\u0928\u0947 \u0915\u0940 \u0938\u0947\u091F\u093F\u0902\u0917 \u091A\u093E\u0932\u0942 \u0939\u0948\u0964 \u0907\u0938 \u0915\u0902\u091F\u094D\u0930\u094B\u0932 \u0915\u094B \u091A\u093E\u0932\u0942 \u0915\u0930\u0928\u0947 \u0915\u0947 \u0932\u093F\u090F \u0935\u0939\u093E\u0901 \u0909\u0938\u0947 \u092C\u0902\u0926 \u0915\u0930\u0947\u0902\u0964",
  "ui.settings.appearance.window_glass.unsupported_windows_too_old": "\u092A\u093E\u0930\u092D\u093E\u0938\u0940 \u0935\u093F\u0902\u0921\u094B \u0915\u0947 \u0932\u093F\u090F Windows 11 \u0938\u0902\u0938\u094D\u0915\u0930\u0923 22H2 \u092F\u093E \u092C\u093E\u0926 \u0915\u093E \u0938\u0902\u0938\u094D\u0915\u0930\u0923 \u091A\u093E\u0939\u093F\u090F\u0964",
  "ui.settings.appearance.window_glass.unsupported_linux": "Linux \u092A\u0930 \u092A\u093E\u0930\u092D\u093E\u0938\u0940 \u0935\u093F\u0902\u0921\u094B \u0909\u092A\u0932\u092C\u094D\u0927 \u0928\u0939\u0940\u0902 \u0939\u0948: \u0910\u092A \u0938\u093F\u0938\u094D\u091F\u092E \u0938\u0947 \u0935\u093F\u0902\u0921\u094B \u0927\u0941\u0902\u0927\u0932\u0940 \u0915\u0930\u0928\u0947 \u0915\u0947 \u0932\u093F\u090F \u0928\u0939\u0940\u0902 \u0915\u0939 \u0938\u0915\u0924\u093E\u0964 \u0935\u0939\u093E\u0901 \u0921\u0947\u0938\u094D\u0915\u091F\u0949\u092A \u0915\u0940 \u092A\u093E\u0930\u092D\u093E\u0938\u093F\u0924\u093E \u0915\u0902\u092A\u094B\u091C\u093C\u093F\u091F\u0930 (X11 \u092F\u093E Wayland) \u092A\u0930 \u0928\u093F\u0930\u094D\u092D\u0930 \u0915\u0930\u0924\u0940 \u0939\u0948 \u0914\u0930 \u0938\u0949\u092B\u093C\u094D\u091F\u0935\u0947\u092F\u0930 \u0938\u0947 \u0927\u0941\u0902\u0927\u0932\u093E \u0915\u0930\u0928\u0947 \u0915\u093E \u0938\u0939\u093E\u0930\u093E \u0932\u0947 \u0938\u0915\u0924\u0940 \u0939\u0948, \u091C\u093F\u0938\u0938\u0947 \u0921\u0947\u0938\u094D\u0915\u091F\u0949\u092A \u0915\u093E \u091F\u0947\u0915\u094D\u0938\u094D\u091F \u0910\u092A \u0915\u0947 \u091F\u0947\u0915\u094D\u0938\u094D\u091F \u0915\u0947 \u092A\u0940\u091B\u0947 \u0926\u093F\u0916\u0947\u0917\u093E\u0964",
  "ui.settings.appearance.window_glass.unsupported_other": "\u0907\u0938 \u092A\u094D\u0932\u0947\u091F\u092B\u093C\u0949\u0930\u094D\u092E \u092A\u0930 \u092A\u093E\u0930\u092D\u093E\u0938\u0940 \u0935\u093F\u0902\u0921\u094B \u0909\u092A\u0932\u092C\u094D\u0927 \u0928\u0939\u0940\u0902 \u0939\u0948: \u0938\u093F\u0930\u094D\u092B\u093C macOS \u092A\u0930 \u0927\u0941\u0902\u0927\u0932\u0940 \u0935\u093F\u0902\u0921\u094B \u092C\u0928\u093E\u0915\u0930 \u0926\u093F\u0916\u093E\u0928\u0947 \u0915\u0940 \u092A\u0941\u0937\u094D\u091F\u093F \u0939\u0941\u0908 \u0939\u0948, \u0914\u0930 Windows 11 \u0915\u0947 \u092E\u091F\u0940\u0930\u093F\u092F\u0932 \u0915\u094B \u0905\u092D\u0940 \u0905\u0938\u0932\u0940 \u092E\u0936\u0940\u0928 \u092A\u0930 \u0928\u0939\u0940\u0902 \u092A\u0930\u0916\u093E \u0917\u092F\u093E \u0939\u0948\u0964",
  "ui.settings.appearance.window_glass.coverage_label": "\u0917\u094D\u0932\u093E\u0938 \u0915\u0939\u093E\u0901 \u0932\u093E\u0917\u0942 \u0939\u094B",
  "ui.settings.appearance.window_glass.coverage_description": "\u0935\u093F\u0902\u0921\u094B \u0915\u0947 \u0915\u094C\u0928-\u0938\u0947 \u0939\u093F\u0938\u094D\u0938\u0947 \u092A\u093E\u0930\u092D\u093E\u0938\u0940 \u0939\u094B\u0902\u0964 \u0938\u093F\u0930\u094D\u092B\u093C \u0938\u093E\u0907\u0921\u092C\u093E\u0930 \u092E\u0947\u0902 \u092C\u093E\u0924\u091A\u0940\u0924 \u0914\u0930 \u092A\u0947\u091C \u0905\u092A\u093E\u0930\u0926\u0930\u094D\u0936\u0940 \u0930\u0939\u0924\u0947 \u0939\u0948\u0902\u0964 \u092A\u0942\u0930\u093E \u0910\u092A \u0909\u0928\u094D\u0939\u0947\u0902 \u0914\u0930 \u0938\u093E\u0907\u0921 \u092A\u0948\u0928\u0932\u094B\u0902 \u0915\u094B \u092D\u0940 \u0936\u093E\u092E\u093F\u0932 \u0915\u0930\u0924\u093E \u0939\u0948; \u0905\u0902\u0926\u0930 \u0926\u093F\u0916\u093E\u090F \u0917\u090F \u0935\u0947\u092C \u092A\u0947\u091C, \u0926\u0938\u094D\u0924\u093E\u0935\u0947\u091C\u093C \u0914\u0930 \u091A\u093F\u0924\u094D\u0930 \u0905\u092A\u093E\u0930\u0926\u0930\u094D\u0936\u0940 \u0930\u0939\u0924\u0947 \u0939\u0948\u0902\u0964",
  "ui.settings.appearance.window_glass.coverage_sidebars": "\u0938\u093F\u0930\u094D\u092B\u093C \u0938\u093E\u0907\u0921\u092C\u093E\u0930",
  "ui.settings.appearance.window_glass.coverage_full": "\u092A\u0942\u0930\u093E \u0910\u092A",
  "ui.settings.appearance.window_glass.intensity_label": "\u0927\u0941\u0902\u0927\u0932\u0947 \u0938\u0947 \u092A\u093E\u0930\u0926\u0930\u094D\u0936\u0940 \u0924\u0915",
  "ui.settings.appearance.window_glass.intensity_description": "\u092C\u093E\u0908\u0902 \u0913\u0930 \u0927\u0941\u0902\u0927\u0932\u093E \u0939\u0948: \u091C\u093C\u094D\u092F\u093E\u0926\u093E\u0924\u0930 \u0905\u092A\u093E\u0930\u0926\u0930\u094D\u0936\u0940, \u0921\u0947\u0938\u094D\u0915\u091F\u0949\u092A \u0915\u0940 \u0939\u0932\u094D\u0915\u0940 \u091D\u0932\u0915 \u0915\u0947 \u0938\u093E\u0925\u0964 \u0926\u093E\u0908\u0902 \u0913\u0930 \u092A\u093E\u0930\u0926\u0930\u094D\u0936\u0940 \u0939\u0948, \u0909\u0924\u0928\u093E \u0939\u0940 \u091C\u093F\u0924\u0928\u093E \u0939\u0930 \u0925\u0940\u092E \u0915\u0947 \u091F\u0947\u0915\u094D\u0938\u094D\u091F \u0915\u0947 \u0932\u093F\u090F \u0920\u0940\u0915 \u0939\u0948\u0964 \u0938\u0902\u0926\u0947\u0936 \u092C\u094D\u0932\u0949\u0915 \u0914\u0930 \u0915\u093E\u0930\u094D\u0921 \u0939\u0932\u094D\u0915\u0947 \u0930\u0902\u0917 \u0915\u0947 \u0939\u094B \u091C\u093E\u0924\u0947 \u0939\u0948\u0902, \u0907\u0928\u092A\u0941\u091F \u0917\u094D\u0932\u093E\u0938 \u0938\u0947 \u0905\u0932\u0917 \u0926\u093F\u0916\u0924\u0947 \u0939\u0948\u0902, \u0914\u0930 \u0915\u094B\u0921, \u0926\u0938\u094D\u0924\u093E\u0935\u0947\u091C\u093C \u0935 \u091A\u093F\u0924\u094D\u0930 \u0905\u092A\u093E\u0930\u0926\u0930\u094D\u0936\u0940 \u0930\u0939\u0924\u0947 \u0939\u0948\u0902\u0964",
  "ui.settings.appearance.window_glass.material_label": "\u092E\u091F\u0940\u0930\u093F\u092F\u0932",
  "ui.settings.appearance.window_glass.material_description": "\u0910\u092A \u0915\u0947 \u092A\u0940\u091B\u0947 \u0938\u093F\u0938\u094D\u091F\u092E \u0915\u093E \u092E\u091F\u0940\u0930\u093F\u092F\u0932\u0964 \u0907\u0938\u0938\u0947 \u092F\u0939 \u092D\u0940 \u0924\u092F \u0939\u094B\u0924\u093E \u0939\u0948 \u0915\u093F \u0915\u093F\u0924\u0928\u093E \u092A\u093E\u0930\u0926\u0930\u094D\u0936\u0940 \u0939\u094B \u0938\u0915\u0924\u093E \u0939\u0948\u0964",
  "ui.settings.appearance.window_glass.material_window": "Window",
  "ui.settings.appearance.window_glass.material_menu": "Menu",
  "ui.settings.appearance.window_glass.material_popover": "Popover",
  "ui.settings.appearance.window_glass.material_mica": "Mica",
  "ui.settings.appearance.window_glass.material_acrylic": "Acrylic",
  "ui.settings.appearance.window_glass.material_tabbed": "Tabbed",
  "ui.settings.appearance.window_glass.intensity_start": "\u0927\u0941\u0902\u0927\u0932\u093E",
  "ui.settings.appearance.window_glass.intensity_end": "\u092A\u093E\u0930\u0926\u0930\u094D\u0936\u0940",
  "ui.settings.appearance.window_glass.intensity_value": "\u092A\u093E\u0930\u0926\u0930\u094D\u0936\u093F\u0924\u093E \u0915\u0940 \u0913\u0930 {value}%",
  "ui.settings.appearance.window_glass.unsupported_windows_unverified": "Windows \u092A\u0930 \u092A\u093E\u0930\u092D\u093E\u0938\u0940 \u0935\u093F\u0902\u0921\u094B \u0905\u092D\u0940 \u0928\u0939\u0940\u0902 \u0926\u0940 \u091C\u093E\u0924\u0940: Mica \u0914\u0930 Acrylic \u092C\u0928\u093E\u090F \u0917\u090F \u0939\u0948\u0902, \u0932\u0947\u0915\u093F\u0928 \u0909\u0928\u094D\u0939\u0947\u0902 \u0905\u0938\u0932\u0940 Windows \u092E\u0936\u0940\u0928 \u092A\u0930 \u0928\u0939\u0940\u0902 \u092A\u0930\u0916\u093E \u0917\u092F\u093E \u0939\u0948, \u0907\u0938\u0932\u093F\u090F \u0909\u0938 \u091C\u093E\u0901\u091A \u0915\u0947 \u092A\u0942\u0930\u093E \u0939\u094B\u0928\u0947 \u0924\u0915 \u0915\u0902\u091F\u094D\u0930\u094B\u0932 \u092C\u0902\u0926 \u0930\u0939\u0947\u0917\u093E\u0964",
  "ui.settings.appearance.window_glass.unsupported_gpu": "\u092A\u093E\u0930\u092D\u093E\u0938\u0940 \u0935\u093F\u0902\u0921\u094B \u0909\u092A\u0932\u092C\u094D\u0927 \u0928\u0939\u0940\u0902 \u0939\u0948, \u0915\u094D\u092F\u094B\u0902\u0915\u093F GPU \u0905\u092D\u0940 \u0909\u0938\u0947 \u092C\u0928\u093E\u0915\u0930 \u0928\u0939\u0940\u0902 \u0926\u093F\u0916\u093E \u0938\u0915\u0924\u093E: \u0915\u0902\u092A\u094B\u091C\u093C\u093F\u091F\u093F\u0902\u0917 \u092F\u093E \u0930\u0948\u0938\u094D\u091F\u0930\u093E\u0907\u091C\u093C\u0947\u0936\u0928 \u092C\u0902\u0926 \u0939\u0948 \u092F\u093E \u0938\u0949\u092B\u093C\u094D\u091F\u0935\u0947\u092F\u0930 \u092E\u0947\u0902 \u091A\u0932 \u0930\u0939\u093E \u0939\u0948\u0964 \u0921\u094D\u0930\u093E\u0907\u0935\u0930 \u0905\u092A\u0921\u0947\u091F \u0915\u0930\u0928\u0947 \u092F\u093E \u0930\u093F\u092E\u094B\u091F \u0938\u0924\u094D\u0930 \u0938\u0947 \u092C\u093E\u0939\u0930 \u0928\u093F\u0915\u0932\u0928\u0947 \u092A\u0930 \u092C\u093F\u0928\u093E \u0926\u094B\u092C\u093E\u0930\u093E \u0936\u0941\u0930\u0942 \u0915\u093F\u090F \u0915\u0902\u091F\u094D\u0930\u094B\u0932 \u0935\u093E\u092A\u0938 \u0906 \u0938\u0915\u0924\u093E \u0939\u0948\u0964",
  "ui.settings.appearance.window_glass.unsupported_acceleration": "\u092A\u093E\u0930\u092D\u093E\u0938\u0940 \u0935\u093F\u0902\u0921\u094B \u0909\u092A\u0932\u092C\u094D\u0927 \u0928\u0939\u0940\u0902 \u0939\u0948, \u0915\u094D\u092F\u094B\u0902\u0915\u093F \u0907\u0938 \u092C\u093E\u0930 \u0939\u093E\u0930\u094D\u0921\u0935\u0947\u092F\u0930 \u090F\u0915\u094D\u0938\u0947\u0932\u0930\u0947\u0936\u0928 \u092C\u0902\u0926 \u0939\u0948 (--disable-gpu \u092F\u093E \u0915\u094D\u0930\u0948\u0936 \u0915\u0947 \u092C\u093E\u0926 \u0935\u0948\u0915\u0932\u094D\u092A\u093F\u0915 \u092E\u094B\u0921)\u0964 \u0907\u0938\u0947 \u0907\u0938\u094D\u0924\u0947\u092E\u093E\u0932 \u0915\u0930\u0928\u0947 \u0915\u0947 \u0932\u093F\u090F \u090F\u0915\u094D\u0938\u0947\u0932\u0930\u0947\u0936\u0928 \u091A\u093E\u0932\u0942 \u0915\u0930\u0915\u0947 \u0926\u094B\u092C\u093E\u0930\u093E \u0936\u0941\u0930\u0942 \u0915\u0930\u0947\u0902\u0964",
  "ui.settings.appearance.window_glass.unsupported_backdrop_filter": "\u092A\u093E\u0930\u092D\u093E\u0938\u0940 \u0935\u093F\u0902\u0921\u094B \u0909\u092A\u0932\u092C\u094D\u0927 \u0928\u0939\u0940\u0902 \u0939\u0948, \u0915\u094D\u092F\u094B\u0902\u0915\u093F \u092F\u0939 \u0930\u0947\u0902\u0921\u0930\u0930 \u092A\u0940\u091B\u0947 \u0915\u093E \u0926\u0943\u0936\u094D\u092F \u0927\u0941\u0902\u0927\u0932\u093E \u0928\u0939\u0940\u0902 \u0915\u0930 \u0938\u0915\u0924\u093E\u0964"
};

