  "ui.agentMessages.dialog.validation_detail": "{field}: {rule}",
  "ui.agentMessages.dialog.validation_failure": "\u0417\u0430\u043F\u0440\u043E\u0441 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438 \u043D\u0435 \u043F\u0440\u0438\u043D\u044F\u0442. \u041E\u0431\u043D\u043E\u0432\u0438\u0442\u0435 Local Operator \u0438 \u043F\u043E\u0432\u0442\u043E\u0440\u0438\u0442\u0435 \u043F\u043E\u043F\u044B\u0442\u043A\u0443.",
  "ui.agentMessages.banner.title": "Team Bridge \u0432\u043A\u043B\u044E\u0447\u0451\u043D \u0434\u043B\u044F \u0432\u0430\u0441",
  "ui.agentMessages.banner.body": "\u0412\u0430\u0448 \u0430\u0433\u0435\u043D\u0442 \u043C\u043E\u0436\u0435\u0442 \u043E\u0431\u043C\u0435\u043D\u0438\u0432\u0430\u0442\u044C\u0441\u044F \u0441\u043E\u043E\u0431\u0449\u0435\u043D\u0438\u044F\u043C\u0438 \u0441 \u0430\u0433\u0435\u043D\u0442\u0430\u043C\u0438 \u0434\u0440\u0443\u0433\u0438\u0445 \u0443\u0447\u0430\u0441\u0442\u043D\u0438\u043A\u043E\u0432 \u0432\u0430\u0448\u0435\u0439 \u043E\u0440\u0433\u0430\u043D\u0438\u0437\u0430\u0446\u0438\u0438. \u041F\u0440\u0438 \u0432\u043A\u043B\u044E\u0447\u0435\u043D\u0438\u0438 \u043D\u0438\u0447\u0435\u0433\u043E \u043D\u0435 \u043E\u0442\u043F\u0440\u0430\u0432\u043B\u044F\u043B\u043E\u0441\u044C.",
