  "ui.agents.detail.field.when_to_use": "\u041A\u043E\u0433\u0434\u0430 \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u0442\u044C \u044D\u0442\u043E\u0433\u043E \u0430\u0433\u0435\u043D\u0442\u0430",
  "ui.agents.detail.field.when_to_use_hint": "\u041E\u0434\u043D\u043E \u043F\u0440\u0435\u0434\u043B\u043E\u0436\u0435\u043D\u0438\u0435, \u043F\u043E \u043A\u043E\u0442\u043E\u0440\u043E\u043C\u0443 \u043C\u043E\u0434\u0435\u043B\u044C \u0440\u0435\u0448\u0430\u0435\u0442, \u043F\u043E\u0434\u0445\u043E\u0434\u0438\u0442 \u043B\u0438 \u044D\u0442\u043E\u0442 \u0430\u0433\u0435\u043D\u0442.",
  "ui.agents.detail.field.instructions_hint": "\u0427\u0442\u043E \u0430\u0433\u0435\u043D\u0442\u0443 \u043F\u043E\u0440\u0443\u0447\u0435\u043D\u043E \u0434\u0435\u043B\u0430\u0442\u044C. \u042D\u0442\u043E \u0438 \u0435\u0441\u0442\u044C \u0432\u0441\u0451 \u0435\u0433\u043E \u043F\u043E\u0432\u0435\u0434\u0435\u043D\u0438\u0435.",
  "ui.agents.detail.section.delegation_hint": "\u041C\u043E\u0436\u0435\u0442 \u043B\u0438 \u044D\u0442\u043E\u0442 \u0430\u0433\u0435\u043D\u0442 \u043F\u0435\u0440\u0435\u0434\u0430\u0432\u0430\u0442\u044C \u0440\u0430\u0431\u043E\u0442\u0443 \u0441\u0443\u0431\u0430\u0433\u0435\u043D\u0442\u0430\u043C \u0438 \u043D\u0430 \u043A\u0430\u043A\u043E\u043C \u0443\u0440\u043E\u0432\u043D\u0435 \u0443\u0441\u0438\u043B\u0438\u0439 \u043E\u043D \u0440\u0430\u0431\u043E\u0442\u0430\u0435\u0442.",
  "ui.agents.detail.field.effort_loading": "\u0417\u0430\u0433\u0440\u0443\u0437\u043A\u0430 \u0443\u0440\u043E\u0432\u043D\u0435\u0439 \u0443\u0441\u0438\u043B\u0438\u0439",
  "ui.agents.detail.field.effort_helper": "\u0423\u0440\u043E\u0432\u043D\u0438 \u0431\u0435\u0440\u0443\u0442\u0441\u044F \u0438\u0437 \u043D\u0430\u0441\u0442\u0440\u043E\u0435\u043A \u043C\u043E\u0434\u0435\u043B\u0435\u0439 \u0441\u0443\u0431\u0430\u0433\u0435\u043D\u0442\u043E\u0432 \u043D\u0430 \u0431\u044D\u043A\u0435\u043D\u0434\u0435.",
  "ui.agents.detail.field.effort_inherit_hint": "\u0418\u0441\u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u0442\u044C \u0443\u0441\u0438\u043B\u0438\u044F \u0441\u0430\u043C\u043E\u0439 \u0441\u0435\u0441\u0441\u0438\u0438",
  "ui.agents.detail.field.effort_configured_hint": "\u0423\u0440\u043E\u0432\u0435\u043D\u044C, \u0437\u0430\u0434\u0430\u043D\u043D\u044B\u0439 \u0432 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0430\u0445",
  "ui.agents.detail.field.how_it_works": "\u041A\u0430\u043A \u0432\u0437\u0430\u0438\u043C\u043E\u0434\u0435\u0439\u0441\u0442\u0432\u0443\u0435\u0442 \u0441 \u0434\u0440\u0443\u0433\u0438\u043C\u0438",
  "ui.agents.detail.empty.description": "\u041E\u043F\u0438\u0441\u0430\u043D\u0438\u044F \u043F\u043E\u043A\u0430 \u043D\u0435\u0442 \u2014 \u0434\u043E\u0431\u0430\u0432\u044C\u0442\u0435 \u0435\u0433\u043E, \u0447\u0442\u043E\u0431\u044B \u043C\u043E\u0434\u0435\u043B\u044C \u0437\u043D\u0430\u043B\u0430, \u043A\u043E\u0433\u0434\u0430 \u0432\u044B\u0431\u0438\u0440\u0430\u0442\u044C \u044D\u0442\u043E\u0433\u043E \u0430\u0433\u0435\u043D\u0442\u0430.",
  "ui.agents.detail.empty.instructions": "\u0418\u043D\u0441\u0442\u0440\u0443\u043A\u0446\u0438\u0439 \u043F\u043E\u043A\u0430 \u043D\u0435\u0442.",
  "ui.agents.detail.action.create_copy": "\u0421\u043E\u0437\u0434\u0430\u0442\u044C \u043A\u043E\u043F\u0438\u044E",
  "ui.agents.detail.action.creating": "\u0421\u043E\u0437\u0434\u0430\u043D\u0438\u0435\u2026",
