  "ui.browser.approval_queue_model.this_session_only": "\u0422\u043E\u043B\u044C\u043A\u043E \u044D\u0442\u0430 \u0441\u0435\u0441\u0441\u0438\u044F",
  "ui.browser.approval_queue_model.this_site": "\u042D\u0442\u043E\u0442 \u0441\u0430\u0439\u0442",
  "ui.browser.approval_queue_model.whole_domain": "\u0412\u0435\u0441\u044C \u0434\u043E\u043C\u0435\u043D",
  "ui.browser.browser_approvals_dock.agents_can_drive_tabs_in_this_app": "\u0410\u0433\u0435\u043D\u0442\u044B \u043C\u043E\u0433\u0443\u0442 \u0443\u043F\u0440\u0430\u0432\u043B\u044F\u0442\u044C \u0432\u043A\u043B\u0430\u0434\u043A\u0430\u043C\u0438 \u0432 \u044D\u0442\u043E\u043C \u043F\u0440\u0438\u043B\u043E\u0436\u0435\u043D\u0438\u0438. \u0421\u0430\u0439\u0442\u044B, \u0434\u043E\u0441\u0442\u0443\u043F\u043D\u044B\u0435 \u0430\u0433\u0435\u043D\u0442\u0443, \u0431\u044B\u043B\u0438 \u043E\u0434\u043E\u0431\u0440\u0435\u043D\u044B \u043D\u0430\u0436\u0430\u0442\u0438\u0435\u043C \u0432 \u044D\u0442\u043E\u043C \u043E\u043A\u043D\u0435, \u0438 \u0431\u0435\u0437 \u043D\u0435\u0433\u043E \u043D\u0438 \u043E\u0434\u0438\u043D \u0438\u0437 \u043D\u0438\u0445 \u043D\u0435\u0434\u043E\u0441\u0442\u0443\u043F\u0435\u043D.",
  "ui.browser.browser_approvals_dock.approvals": "\u041E\u0434\u043E\u0431\u0440\u0435\u043D\u0438\u044F",
  "ui.browser.browser_approvals_dock.approvals_are_kept_per_origin_and_are": "\u041E\u0434\u043E\u0431\u0440\u0435\u043D\u0438\u044F \u0445\u0440\u0430\u043D\u044F\u0442\u0441\u044F \u043E\u0442\u0434\u0435\u043B\u044C\u043D\u043E \u0434\u043B\u044F \u043A\u0430\u0436\u0434\u043E\u0433\u043E \u0438\u0441\u0442\u043E\u0447\u043D\u0438\u043A\u0430 \u0438 \u043D\u0435 \u0441\u0432\u044F\u0437\u0430\u043D\u044B \u0441 cookie. \u041E\u0442\u0437\u044B\u0432 \u043E\u0434\u043E\u0431\u0440\u0435\u043D\u0438\u044F \u043D\u0435 \u0432\u044B\u043F\u043E\u043B\u043D\u044F\u0435\u0442 \u0432\u044B\u0445\u043E\u0434; \u043E\u0447\u0438\u0441\u0442\u043A\u0430 cookie \u043D\u0435 \u043E\u0442\u043C\u0435\u043D\u044F\u0435\u0442 \u0437\u0430\u043F\u0440\u0435\u0442. \u0411\u0440\u0430\u0443\u0437\u0435\u0440 \u044D\u0442\u043E\u0433\u043E \u043F\u0440\u0438\u043B\u043E\u0436\u0435\u043D\u0438\u044F \u0441\u043E\u0445\u0440\u0430\u043D\u044F\u0435\u0442 \u0432\u0445\u043E\u0434 \u043C\u0435\u0436\u0434\u0443 \u0440\u0430\u0437\u0433\u043E\u0432\u043E\u0440\u0430\u043C\u0438 \u0438 \u043F\u0435\u0440\u0435\u0437\u0430\u043F\u0443\u0441\u043A\u0430\u043C\u0438, \u0430 \u043E\u0434\u043E\u0431\u0440\u0435\u043D\u0438\u0435 \u0437\u0434\u0435\u0441\u044C \u0434\u0435\u0439\u0441\u0442\u0432\u0443\u0435\u0442 \u0434\u043B\u044F \u0432\u0441\u0435\u0445 \u0440\u0430\u0437\u0433\u043E\u0432\u043E\u0440\u043E\u0432, \u0430 \u043D\u0435 \u0442\u043E\u043B\u044C\u043A\u043E \u0434\u043B\u044F \u0442\u043E\u0433\u043E, \u043A\u043E\u0442\u043E\u0440\u044B\u0439 \u0435\u0433\u043E \u0437\u0430\u043F\u0440\u043E\u0441\u0438\u043B. \u0417\u0430\u043F\u0440\u043E\u0441\u044B \u0436\u0434\u0443\u0442 \u0434\u0435\u0441\u044F\u0442\u044C \u043C\u0438\u043D\u0443\u0442; \u043F\u043E\u0441\u043B\u0435 \u044D\u0442\u043E\u0433\u043E \u0430\u0433\u0435\u043D\u0442\u0443 \u043F\u0440\u0438\u0434\u0451\u0442\u0441\u044F \u0441\u043F\u0440\u043E\u0441\u0438\u0442\u044C \u0441\u043D\u043E\u0432\u0430.",
