  "ui.browser.webauthn_chooser.a_site": "\u0421\u0430\u0439\u0442",
  "ui.browser.webauthn_chooser.nobody_chose_a_passkey_within_a_minute": "\u041D\u0438\u043A\u0442\u043E \u043D\u0435 \u0432\u044B\u0431\u0440\u0430\u043B \u043A\u043B\u044E\u0447 \u0434\u043E\u0441\u0442\u0443\u043F\u0430 \u0432 \u0442\u0435\u0447\u0435\u043D\u0438\u0435 \u043C\u0438\u043D\u0443\u0442\u044B, \u043F\u043E\u044D\u0442\u043E\u043C\u0443 \u0437\u0430\u043F\u0440\u043E\u0441 \u0441\u0430\u0439\u0442\u0430 \u043E\u0442\u043C\u0435\u043D\u0451\u043D. \u0417\u0430\u043F\u0440\u043E\u0441\u0438\u0442\u0435 \u043A\u043B\u044E\u0447 \u0434\u043E\u0441\u0442\u0443\u043F\u0430 \u0443 \u0441\u0430\u0439\u0442\u0430 \u0441\u043D\u043E\u0432\u0430.",
  "ui.browser.webauthn_chooser.passkey_anonymous_many": "{site} \u0437\u0430\u043F\u0440\u043E\u0441\u0438\u043B \u043A\u043B\u044E\u0447 \u0434\u043E\u0441\u0442\u0443\u043F\u0430. \u041D\u0430 \u044D\u0442\u043E\u043C Mac \u0445\u0440\u0430\u043D\u0438\u0442\u0441\u044F {count, plural, one {{count, number, ::group-off} \u043A\u043B\u044E\u0447 \u0434\u043E\u0441\u0442\u0443\u043F\u0430} few {{count, number, ::group-off} \u043A\u043B\u044E\u0447\u0430 \u0434\u043E\u0441\u0442\u0443\u043F\u0430} many {{count, number, ::group-off} \u043A\u043B\u044E\u0447\u0435\u0439 \u0434\u043E\u0441\u0442\u0443\u043F\u0430} other {{count, number, ::group-off} \u043A\u043B\u044E\u0447\u0430 \u0434\u043E\u0441\u0442\u0443\u043F\u0430}} \u0434\u043B\u044F \u044D\u0442\u043E\u0433\u043E \u0441\u0430\u0439\u0442\u0430 \u0431\u0435\u0437 \u0438\u043C\u0451\u043D, \u043F\u043E\u044D\u0442\u043E\u043C\u0443 \u0432\u044B\u0431\u0440\u0430\u043D\u043D\u044B\u0439 \u043A\u043B\u044E\u0447 \u043E\u043F\u0440\u0435\u0434\u0435\u043B\u0438\u0442 \u0443\u0447\u0451\u0442\u043D\u0443\u044E \u0437\u0430\u043F\u0438\u0441\u044C. \u0415\u0441\u043B\u0438 \u043E\u043D \u043D\u0435\u0432\u0435\u0440\u043D\u044B\u0439, \u0432\u044B\u0439\u0434\u0438\u0442\u0435 \u0438 \u0437\u0430\u043F\u0440\u043E\u0441\u0438\u0442\u0435 \u0443 \u0441\u0430\u0439\u0442\u0430 \u0441\u043D\u043E\u0432\u0430.",
  "ui.browser.webauthn_chooser.passkey_fallback": "\u041A\u043B\u044E\u0447 \u0434\u043E\u0441\u0442\u0443\u043F\u0430 {number, number, ::group-off}",
  "ui.browser.webauthn_chooser.passkey_named_many": "{site} \u0437\u0430\u043F\u0440\u043E\u0441\u0438\u043B \u043A\u043B\u044E\u0447 \u0434\u043E\u0441\u0442\u0443\u043F\u0430. \u041F\u043E\u0434\u0445\u043E\u0434\u0438\u0442 \u043D\u0435\u0441\u043A\u043E\u043B\u044C\u043A\u043E \u0432\u0430\u0448\u0438\u0445 \u043A\u043B\u044E\u0447\u0435\u0439, \u043F\u043E\u044D\u0442\u043E\u043C\u0443 \u0432\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u043D\u0443\u0436\u043D\u044B\u0439.",
  "ui.browser.webauthn_chooser.passkey_single": "{site} \u0437\u0430\u043F\u0440\u043E\u0441\u0438\u043B \u043A\u043B\u044E\u0447 \u0434\u043E\u0441\u0442\u0443\u043F\u0430. \u0412\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u0435\u0433\u043E, \u0447\u0442\u043E\u0431\u044B \u0432\u043E\u0439\u0442\u0438.",
  "ui.browser.webauthn_chooser.passkeys_waiting": "{count, plural, one {\u041E\u0436\u0438\u0434\u0430\u0435\u0442 \u0435\u0449\u0451 {count, number, ::group-off} \u0437\u0430\u043F\u0440\u043E\u0441 \u043A\u043B\u044E\u0447\u0430 \u0434\u043E\u0441\u0442\u0443\u043F\u0430.} few {\u041E\u0436\u0438\u0434\u0430\u044E\u0442 \u0435\u0449\u0451 {count, number, ::group-off} \u0437\u0430\u043F\u0440\u043E\u0441\u0430 \u043A\u043B\u044E\u0447\u0430 \u0434\u043E\u0441\u0442\u0443\u043F\u0430.} many {\u041E\u0436\u0438\u0434\u0430\u044E\u0442 \u0435\u0449\u0451 {count, number, ::group-off} \u0437\u0430\u043F\u0440\u043E\u0441\u043E\u0432 \u043A\u043B\u044E\u0447\u0430 \u0434\u043E\u0441\u0442\u0443\u043F\u0430.} other {\u041E\u0436\u0438\u0434\u0430\u044E\u0442 \u0435\u0449\u0451 {count, number, ::group-off} \u0437\u0430\u043F\u0440\u043E\u0441\u0430 \u043A\u043B\u044E\u0447\u0430 \u0434\u043E\u0441\u0442\u0443\u043F\u0430.}}",
  "ui.browser.webauthn_chooser.requesting_page": "\u0421\u0442\u0440\u0430\u043D\u0438\u0446\u0430, \u043E\u0442\u043F\u0440\u0430\u0432\u0438\u0432\u0448\u0430\u044F \u0437\u0430\u043F\u0440\u043E\u0441, \u2014 \xAB{title}\xBB.",
  "ui.browser.webauthn_chooser.that_passkey_was_not_offered": "\u042D\u0442\u043E\u0442 \u043A\u043B\u044E\u0447 \u0434\u043E\u0441\u0442\u0443\u043F\u0430 \u043D\u0435 \u043F\u0440\u0435\u0434\u043B\u0430\u0433\u0430\u043B\u0441\u044F",
  "ui.browser.webauthn_chooser.the_browser_tab_that_asked_went_away": "\u0412\u043A\u043B\u0430\u0434\u043A\u0430 \u0431\u0440\u0430\u0443\u0437\u0435\u0440\u0430, \u043E\u0442\u043F\u0440\u0430\u0432\u0438\u0432\u0448\u0430\u044F \u0437\u0430\u043F\u0440\u043E\u0441, \u0437\u0430\u043A\u0440\u044B\u043B\u0430\u0441\u044C \u0434\u043E \u0432\u044B\u0431\u043E\u0440\u0430 \u043A\u043B\u044E\u0447\u0430, \u043F\u043E\u044D\u0442\u043E\u043C\u0443 \u0437\u0430\u043F\u0440\u043E\u0441 \u043E\u0442\u043C\u0435\u043D\u0451\u043D.",
  "ui.browser.webauthn_chooser.the_choice_did_not_name_a_passkey": "\u0412\u044B\u0431\u043E\u0440 \u043D\u0435 \u0443\u043A\u0430\u0437\u0430\u043B \u043D\u0438 \u043D\u0430 \u043E\u0434\u0438\u043D \u043A\u043B\u044E\u0447 \u0434\u043E\u0441\u0442\u0443\u043F\u0430, \u043F\u0440\u0435\u0434\u043B\u043E\u0436\u0435\u043D\u043D\u044B\u0439 \u044D\u0442\u0438\u043C \u0441\u0430\u0439\u0442\u043E\u043C, \u043F\u043E\u044D\u0442\u043E\u043C\u0443 \u0437\u0430\u043F\u0440\u043E\u0441 \u043E\u0442\u043C\u0435\u043D\u0451\u043D. \u041F\u043E\u0432\u0442\u043E\u0440\u0438\u0442\u0435 \u043F\u043E\u043F\u044B\u0442\u043A\u0443 \u043D\u0430 \u0441\u0430\u0439\u0442\u0435.",
