  "ui.chat.aside.announce.answered_truncated": "\u041E\u0442\u0434\u0435\u043B\u044C\u043D\u044B\u0439 \u0432\u043E\u043F\u0440\u043E\u0441 \u043F\u043E\u043B\u0443\u0447\u0438\u043B \u043E\u0442\u0432\u0435\u0442: {text}\u2026",
