  "ui.chat.composer.suggestion.schedule_mornings": "\u0417\u0430\u043F\u043B\u0430\u043D\u0438\u0440\u0443\u0439\u0442\u0435 \u0437\u0430\u0434\u0430\u043D\u0438\u0435 \u043D\u0430 \u043A\u0430\u0436\u0434\u043E\u0435 \u0443\u0442\u0440\u043E",
  "ui.chat.composer.suggestion.wake_with_summary": "\u0420\u0430\u0437\u0431\u0443\u0434\u0438\u0442\u0435 \u043C\u0435\u043D\u044F \u0437\u0430\u0432\u0442\u0440\u0430 \u0443\u0442\u0440\u043E\u043C \u0441\u043E \u0441\u0432\u043E\u0434\u043A\u043E\u0439",
  "ui.chat.composer.tip.approvals": "\u0432\u0432\u0435\u0434\u0438\u0442\u0435 /approvals \u2014 \u043D\u0430\u0441\u0442\u0440\u043E\u0438\u0442\u044C, \u0441\u043F\u0440\u0430\u0448\u0438\u0432\u0430\u0442\u044C \u043B\u0438 \u043E\u0434\u043E\u0431\u0440\u0435\u043D\u0438\u0435",
  "ui.chat.composer.tip.ask_for_a_team": "\u043F\u043E\u043F\u0440\u043E\u0441\u0438\u0442\u0435 \u043A\u043E\u043C\u0430\u043D\u0434\u0443 \u2014 \u0438 \u043D\u0435\u0441\u043A\u043E\u043B\u044C\u043A\u043E \u0430\u0433\u0435\u043D\u0442\u043E\u0432 \u0440\u0430\u0437\u0434\u0435\u043B\u044F\u0442 \u043E\u0434\u0438\u043D \u0437\u0430\u043F\u0440\u043E\u0441",
  "ui.chat.composer.tip.attach_a_file": "\u043F\u0440\u0438\u043A\u0440\u0435\u043F\u0438\u0442\u0435 \u0444\u0430\u0439\u043B \u0441\u043A\u0440\u0435\u043F\u043A\u043E\u0439 \u0438\u043B\u0438 \u0432\u0441\u0442\u0430\u0432\u044C\u0442\u0435 \u0435\u0433\u043E",
  "ui.chat.composer.tip.canvas": "\u043E\u0442\u043A\u0440\u043E\u0439\u0442\u0435 \u0434\u043E\u043A\u0443\u043C\u0435\u043D\u0442 \u0432 \u0445\u043E\u043B\u0441\u0442\u0435, \u0447\u0442\u043E\u0431\u044B \u043E\u043D \u0431\u044B\u043B \u0440\u044F\u0434\u043E\u043C \u0441 \u0447\u0430\u0442\u043E\u043C",
  "ui.chat.composer.tip.mcp_tools": "\u043F\u043E\u0434\u043A\u043B\u044E\u0447\u0438\u0442\u0435 MCP \u0432 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0430\u0445 \u2014 \u0430\u0433\u0435\u043D\u0442 \u043F\u043E\u043B\u0443\u0447\u0438\u0442 \u0438\u043D\u0441\u0442\u0440\u0443\u043C\u0435\u043D\u0442\u044B",
  "ui.chat.composer.tip.mention_file": "\u0432\u0432\u0435\u0434\u0438\u0442\u0435 @, \u0447\u0442\u043E\u0431\u044B \u0443\u043A\u0430\u0437\u0430\u0442\u044C \u0430\u0433\u0435\u043D\u0442\u0443 \u043D\u0430 \u0444\u0430\u0439\u043B \u0432 \u044D\u0442\u043E\u043C \u043A\u0430\u0442\u0430\u043B\u043E\u0433\u0435",
  "ui.chat.composer.tip.parallel_work": "\u043F\u043E\u043F\u0440\u043E\u0441\u0438\u0442\u0435 \u043F\u0430\u0440\u0430\u043B\u043B\u0435\u043B\u044C\u043D\u0443\u044E \u0440\u0430\u0431\u043E\u0442\u0443 \u2014 \u0430\u0433\u0435\u043D\u0442 \u0437\u0430\u043F\u0443\u0441\u0442\u0438\u0442 \u0441\u0443\u0431\u0430\u0433\u0435\u043D\u0442\u043E\u0432",
  "ui.chat.composer.tip.phone_access": "\u043F\u043E\u043F\u0440\u043E\u0441\u0438\u0442\u0435 \u0434\u043E\u0441\u0442\u0443\u043F \u0441 \u0442\u0435\u043B\u0435\u0444\u043E\u043D\u0430 \u0434\u043B\u044F \u0443\u043F\u0440\u0430\u0432\u043B\u0435\u043D\u0438\u044F \u044D\u0442\u043E\u0439 \u0441\u0435\u0441\u0441\u0438\u0435\u0439",
  "ui.chat.composer.tip.run_panel": "\u043E\u0442\u043A\u0440\u043E\u0439\u0442\u0435 \u043F\u0430\u043D\u0435\u043B\u044C \u0432\u044B\u043F\u043E\u043B\u043D\u0435\u043D\u0438\u044F: \u043F\u043B\u0430\u043D \u0445\u043E\u0434\u0430 \u0438 \u0441\u0443\u0431\u0430\u0433\u0435\u043D\u0442\u044B",
  "ui.chat.composer.tip.schedule": "\u043D\u0430\u0441\u0442\u0440\u043E\u0439\u0442\u0435 \u0440\u0430\u0441\u043F\u0438\u0441\u0430\u043D\u0438\u0435, \u0447\u0442\u043E\u0431\u044B \u043F\u0440\u043E\u043C\u043F\u0442 \u0432\u044B\u043F\u043E\u043B\u043D\u044F\u043B\u0441\u044F \u043F\u043E \u0442\u0430\u0439\u043C\u0435\u0440\u0443",
  "ui.chat.composer.tip.search_past_work": "\u0438\u0449\u0438\u0442\u0435 \u043F\u043E \u0447\u0430\u0442\u0430\u043C \u0438 \u0430\u0433\u0435\u043D\u0442\u0430\u043C, \u0447\u0442\u043E\u0431\u044B \u043E\u0442\u043A\u0440\u044B\u0442\u044C \u043F\u0440\u0435\u0436\u043D\u044E\u044E \u0441\u0435\u0441\u0441\u0438\u044E",
  "ui.chat.composer.secret_closure_notice": "\u041E\u0442\u0432\u0435\u0442\u044C\u0442\u0435 \u043D\u0430 \u0437\u0430\u043F\u0440\u043E\u0441 \u0441\u0435\u043A\u0440\u0435\u0442\u0430 \u043D\u0430 \u043F\u0430\u043D\u0435\u043B\u0438 \u0437\u0430\u043F\u0440\u043E\u0441\u043E\u0432 \u2014 \u0432\u0432\u043E\u0434 \u0432 \u044D\u0442\u043E\u043C \u043F\u043E\u043B\u0435 \u043F\u0440\u0438\u043E\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D \u0434\u043E \u043E\u0442\u0432\u0435\u0442\u0430, \u0447\u0435\u0440\u043D\u043E\u0432\u0438\u043A \u0441\u043E\u0445\u0440\u0430\u043D\u0451\u043D."
