  "ui.chat.session_status.commands_off": "Slash-\u043A\u043E\u043C\u0430\u043D\u0434\u044B \u043E\u0442\u043A\u043B\u044E\u0447\u0435\u043D\u044B \u043D\u0430 \u044D\u0442\u043E\u043C \u0441\u0435\u0440\u0432\u0435\u0440\u0435, \u043F\u043E\u044D\u0442\u043E\u043C\u0443 \u043E\u0442\u043A\u0440\u044B\u0442\u044C \u044D\u0442\u043E\u0442 \u0437\u0430\u043C\u0435\u0440 \u043E\u0442\u0441\u044E\u0434\u0430 \u043D\u0435\u043B\u044C\u0437\u044F.",
  "ui.chat.session_status.context_click_breakdown_held": "\u041D\u0430\u0436\u043C\u0438\u0442\u0435, \u0447\u0442\u043E\u0431\u044B \u043E\u0442\u043A\u0440\u044B\u0442\u044C \u043F\u043E\u043B\u043D\u0443\u044E \u0440\u0430\u0437\u0431\u0438\u0432\u043A\u0443 \u2014 \u0432 \u043D\u0435\u0439 \u043E\u0446\u0435\u043D\u0438\u0432\u0430\u0435\u0442\u0441\u044F \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0438\u0439 \u0437\u0430\u043F\u0440\u043E\u0441.",
  "ui.chat.session_status.context_click_breakdown_held_plain": "\u041D\u0430\u0436\u043C\u0438\u0442\u0435, \u0447\u0442\u043E\u0431\u044B \u043E\u0442\u043A\u0440\u044B\u0442\u044C \u043F\u043E\u043B\u043D\u0443\u044E \u0440\u0430\u0437\u0431\u0438\u0432\u043A\u0443.",
  "ui.chat.session_status.context_measured_now": "\u0417\u0430\u043C\u0435\u0440 \u043D\u0430 \u0442\u0435\u043A\u0443\u0449\u0438\u0439 \u043C\u043E\u043C\u0435\u043D\u0442; \u043D\u0430\u0436\u043C\u0438\u0442\u0435, \u0447\u0442\u043E\u0431\u044B \u043E\u0442\u043A\u0440\u044B\u0442\u044C \u043F\u043E\u043B\u043D\u0443\u044E \u0440\u0430\u0437\u0431\u0438\u0432\u043A\u0443 \u2014 \u0432 \u043D\u0435\u0439 \u043E\u0446\u0435\u043D\u0438\u0432\u0430\u0435\u0442\u0441\u044F \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0438\u0439 \u0437\u0430\u043F\u0440\u043E\u0441",
  "ui.chat.session_status.context_estimated_now": "\u041E\u0446\u0435\u043D\u043A\u0430 \u043D\u0430 \u0442\u0435\u043A\u0443\u0449\u0438\u0439 \u043C\u043E\u043C\u0435\u043D\u0442; \u043D\u0430\u0436\u043C\u0438\u0442\u0435, \u0447\u0442\u043E\u0431\u044B \u043E\u0442\u043A\u0440\u044B\u0442\u044C \u043F\u043E\u043B\u043D\u0443\u044E \u0440\u0430\u0437\u0431\u0438\u0432\u043A\u0443 \u2014 \u0432 \u043D\u0435\u0439 \u043E\u0446\u0435\u043D\u0438\u0432\u0430\u0435\u0442\u0441\u044F \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0438\u0439 \u0437\u0430\u043F\u0440\u043E\u0441",
  "ui.chat.session_status.context_click_breakdown": "\u041D\u0430\u0436\u043C\u0438\u0442\u0435, \u0447\u0442\u043E\u0431\u044B \u043E\u0442\u043A\u0440\u044B\u0442\u044C \u043F\u043E\u043B\u043D\u0443\u044E \u0440\u0430\u0437\u0431\u0438\u0432\u043A\u0443",
  "ui.chat.session_status.model_click_choose_draft": "\u041D\u0430\u0436\u043C\u0438\u0442\u0435, \u0447\u0442\u043E\u0431\u044B \u0432\u044B\u0431\u0440\u0430\u0442\u044C \u0434\u0440\u0443\u0433\u0443\u044E \u043C\u043E\u0434\u0435\u043B\u044C. \u0412\u044B\u0431\u043E\u0440 \u043F\u0440\u0438\u043C\u0435\u043D\u0438\u0442\u0441\u044F \u043A \u044D\u0442\u043E\u043C\u0443 \u0440\u0430\u0437\u0433\u043E\u0432\u043E\u0440\u0443.",
