  "ui.chat.session_status.model_aria_pending": "\u041C\u043E\u0434\u0435\u043B\u044C: {selector}{fast, select, yes {, \u0431\u044B\u0441\u0442\u0440\u044B\u0439 \u0440\u0435\u0436\u0438\u043C \u0432\u043A\u043B\u044E\u0447\u0451\u043D} other {}}. \u0418\u0434\u0451\u0442 \u043F\u0435\u0440\u0435\u043A\u043B\u044E\u0447\u0435\u043D\u0438\u0435; \u043E\u0436\u0438\u0434\u0430\u0435\u0442\u0441\u044F \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0435\u043D\u0438\u0435 \u043E\u0442 \u0441\u0435\u0441\u0441\u0438\u0438.",
