  "ui.chat.pickers.destination_pickers.chars": "{length, plural, one {{length, number, ::group-off} \u0441\u0438\u043C\u0432\u043E\u043B} few {{length, number, ::group-off} \u0441\u0438\u043C\u0432\u043E\u043B\u0430} many {{length, number, ::group-off} \u0441\u0438\u043C\u0432\u043E\u043B\u043E\u0432} other {{length, number, ::group-off} \u0441\u0438\u043C\u0432\u043E\u043B\u0430}}",
  "ui.chat.pickers.destination_pickers.copied_characters": "\u0421\u043A\u043E\u043F\u0438\u0440\u043E\u0432\u0430\u043D\u043E: {length, plural, one {{length, number, ::group-off} \u0441\u0438\u043C\u0432\u043E\u043B} few {{length, number, ::group-off} \u0441\u0438\u043C\u0432\u043E\u043B\u0430} many {{length, number, ::group-off} \u0441\u0438\u043C\u0432\u043E\u043B\u043E\u0432} other {{length, number, ::group-off} \u0441\u0438\u043C\u0432\u043E\u043B\u0430}}.",
  "ui.chat.pickers.destination_pickers.clipboard_refused": "\u0411\u0443\u0444\u0435\u0440 \u043E\u0431\u043C\u0435\u043D\u0430 \u043E\u0442\u043A\u043B\u043E\u043D\u0438\u043B \u0437\u0430\u043F\u0440\u043E\u0441: {errortext}",
  "ui.chat.pickers.destination_pickers.pick_a_message_a_code_block_or_a_quoted_excerpt_it_goes_to_the_clipboard": "\u0412\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u0441\u043E\u043E\u0431\u0449\u0435\u043D\u0438\u0435, \u0431\u043B\u043E\u043A \u043A\u043E\u0434\u0430 \u0438\u043B\u0438 \u0446\u0438\u0442\u0430\u0442\u0443 \u2014 \u043E\u043D\u0438 \u043F\u043E\u043F\u0430\u0434\u0443\u0442 \u0432 \u0431\u0443\u0444\u0435\u0440 \u043E\u0431\u043C\u0435\u043D\u0430.",
