  "ui.chat.pickers.destination_pickers.cold_reopens_on_the_next_message": "\u0445\u043E\u043B\u043E\u0434\u043D\u0430\u044F, \u043E\u0442\u043A\u0440\u043E\u0435\u0442\u0441\u044F \u0441\u043E \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0438\u043C \u0441\u043E\u043E\u0431\u0449\u0435\u043D\u0438\u0435\u043C",
  "ui.chat.pickers.destination_pickers.resumed": "{sessionlabel}: \u0440\u0430\u0431\u043E\u0442\u0430 \u0432\u043E\u0437\u043E\u0431\u043D\u043E\u0432\u043B\u0435\u043D\u0430.",
  "ui.chat.pickers.destination_pickers.every_canonical_session_live_or_cold_picking_one_attaches_this_window_to": "\u0412\u0441\u0435 \u043A\u0430\u043D\u043E\u043D\u0438\u0447\u0435\u0441\u043A\u0438\u0435 \u0441\u0435\u0441\u0441\u0438\u0438, \u0430\u043A\u0442\u0438\u0432\u043D\u044B\u0435 \u0438\u043B\u0438 \u0445\u043E\u043B\u043E\u0434\u043D\u044B\u0435. \u0412\u044B\u0431\u043E\u0440 \u043F\u0440\u0438\u043A\u0440\u0435\u043F\u043B\u044F\u0435\u0442 \u044D\u0442\u043E \u043E\u043A\u043D\u043E \u043A \u0441\u0435\u0441\u0441\u0438\u0438; \u043D\u0438\u0447\u0435\u0433\u043E \u043D\u0435 \u043F\u0435\u0440\u0435\u0437\u0430\u043F\u0443\u0441\u043A\u0430\u0435\u0442\u0441\u044F, \u043F\u043E\u043A\u0430 \u0432\u044B \u043D\u0435 \u043E\u0442\u043F\u0440\u0430\u0432\u0438\u0442\u0435 \u0441\u043E\u043E\u0431\u0449\u0435\u043D\u0438\u0435.",
  "ui.chat.pickers.destination_pickers.search_by_title_or_id": "\u041F\u043E\u0438\u0441\u043A \u043F\u043E \u043D\u0430\u0437\u0432\u0430\u043D\u0438\u044E \u0438\u043B\u0438 id",
  "ui.chat.pickers.destination_pickers.resumed_2d9cda": "{label}: \u0440\u0430\u0431\u043E\u0442\u0430 \u0432\u043E\u0437\u043E\u0431\u043D\u043E\u0432\u043B\u0435\u043D\u0430.",
  "ui.chat.pickers.destination_pickers.new_conversation_the_previous_one_keeps_running": "\u041D\u043E\u0432\u044B\u0439 \u0440\u0430\u0437\u0433\u043E\u0432\u043E\u0440 {id}. \u041F\u0440\u0435\u0434\u044B\u0434\u0443\u0449\u0438\u0439 \u043F\u0440\u043E\u0434\u043E\u043B\u0436\u0430\u0435\u0442 \u0440\u0430\u0431\u043E\u0442\u0430\u0442\u044C.",
  "ui.chat.pickers.destination_pickers.starts_a_fresh_canonical_session_work_in_the_current_one_continues": "\u0417\u0430\u043F\u0443\u0441\u043A\u0430\u0435\u0442 \u043D\u043E\u0432\u0443\u044E \u043A\u0430\u043D\u043E\u043D\u0438\u0447\u0435\u0441\u043A\u0443\u044E \u0441\u0435\u0441\u0441\u0438\u044E. \u0420\u0430\u0431\u043E\u0442\u0430 \u0432 \u0442\u0435\u043A\u0443\u0449\u0435\u0439 \u043F\u0440\u043E\u0434\u043E\u043B\u0436\u0430\u0435\u0442\u0441\u044F.",
  "ui.chat.pickers.destination_pickers.working_directory": "\u0420\u0430\u0431\u043E\u0447\u0430\u044F \u043F\u0430\u043F\u043A\u0430",
  "ui.chat.pickers.destination_pickers.must_exist_on_this_machine": "\u0414\u043E\u043B\u0436\u0435\u043D \u0441\u0443\u0449\u0435\u0441\u0442\u0432\u043E\u0432\u0430\u0442\u044C \u043D\u0430 \u044D\u0442\u043E\u043C \u043A\u043E\u043C\u043F\u044C\u044E\u0442\u0435\u0440\u0435.",
