// src/i18n/catalogues/ru/ui.chat.session_readout.json
var ui_chat_session_readout_default5 = {
  "ui.chat.session_readout.access.absent.description_connect": "\u0423 \u0443\u0441\u0442\u0440\u043E\u0439\u0441\u0442\u0432\u0430, \u043E\u0431\u0441\u043B\u0443\u0436\u0438\u0432\u0430\u044E\u0449\u0435\u0433\u043E \u044D\u0442\u0443 \u0441\u0435\u0441\u0441\u0438\u044E, \u043D\u0435\u0442 \u0434\u0435\u0439\u0441\u0442\u0432\u0443\u044E\u0449\u0435\u0433\u043E \u0434\u043E\u0441\u0442\u0443\u043F\u0430 \u043A \u043F\u0440\u043E\u0432\u0430\u0439\u0434\u0435\u0440\u0443. \u041F\u043E\u0434\u043A\u043B\u044E\u0447\u0438\u0442\u0435 \u0443\u0447\u0451\u0442\u043D\u0443\u044E \u0437\u0430\u043F\u0438\u0441\u044C \u0438\u043B\u0438 \u0432\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u0434\u0440\u0443\u0433\u0443\u044E \u043C\u043E\u0434\u0435\u043B\u044C.",
  "ui.chat.session_readout.access.absent.description_remote": "\u0423 \u0443\u0441\u0442\u0440\u043E\u0439\u0441\u0442\u0432\u0430, \u043D\u0430 \u043A\u043E\u0442\u043E\u0440\u043E\u043C \u0440\u0430\u0431\u043E\u0442\u0430\u0435\u0442 \u044D\u0442\u0430 \u0441\u0435\u0441\u0441\u0438\u044F, \u043D\u0435\u0442 \u0434\u0435\u0439\u0441\u0442\u0432\u0443\u044E\u0449\u0435\u0433\u043E \u0434\u043E\u0441\u0442\u0443\u043F\u0430 \u043A \u043F\u0440\u043E\u0432\u0430\u0439\u0434\u0435\u0440\u0443. \u0412\u043E\u0439\u0434\u0438\u0442\u0435 \u0438\u043B\u0438 \u0432\u043E\u0441\u0441\u0442\u0430\u043D\u043E\u0432\u0438\u0442\u0435 \u0434\u043E\u0441\u0442\u0443\u043F \u043D\u0430 \u0442\u043E\u043C \u0443\u0441\u0442\u0440\u043E\u0439\u0441\u0442\u0432\u0435 \u043B\u0438\u0431\u043E \u0432\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u0434\u0440\u0443\u0433\u0443\u044E \u043C\u043E\u0434\u0435\u043B\u044C.",
  "ui.chat.session_readout.access.absent.title": "\u041D\u0435\u0442 \u0434\u043E\u0441\u0442\u0443\u043F\u0430 \u043A {label}",
  "ui.chat.session_readout.access.device_bound.description": "\u042D\u0442\u043E\u0442 \u0432\u0445\u043E\u0434 \u043D\u0435\u043B\u044C\u0437\u044F \u0437\u0430\u0438\u043C\u0441\u0442\u0432\u043E\u0432\u0430\u0442\u044C. \u0412\u043E\u0439\u0434\u0438\u0442\u0435 \u043D\u0430 \u0443\u0441\u0442\u0440\u043E\u0439\u0441\u0442\u0432\u0435, \u043D\u0430 \u043A\u043E\u0442\u043E\u0440\u043E\u043C \u0440\u0430\u0431\u043E\u0442\u0430\u0435\u0442 \u044D\u0442\u0430 \u0441\u0435\u0441\u0441\u0438\u044F, \u0438\u043B\u0438 \u0432\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u0434\u0440\u0443\u0433\u0443\u044E \u043C\u043E\u0434\u0435\u043B\u044C.",
  "ui.chat.session_readout.access.device_bound.title": "{label}: \u0442\u0440\u0435\u0431\u0443\u0435\u0442\u0441\u044F \u0432\u0445\u043E\u0434 \u043D\u0430 \u0443\u0441\u0442\u0440\u043E\u0439\u0441\u0442\u0432\u0435",
  "ui.chat.session_readout.access.effective_borrow.description": "\u0420\u0430\u043D\u0442\u0430\u0439\u043C \u043E\u043F\u0440\u0435\u0434\u0435\u043B\u0438\u043B \u0434\u043B\u044F \u044D\u0442\u043E\u0439 \u0441\u0435\u0441\u0441\u0438\u0438 \u0437\u0430\u0438\u043C\u0441\u0442\u0432\u043E\u0432\u0430\u043D\u043D\u044B\u0439 \u0434\u043E\u0441\u0442\u0443\u043F. \u041A\u0430\u0436\u0434\u044B\u0439 \u043D\u043E\u0432\u044B\u0439 \u0437\u0430\u043F\u0440\u043E\u0441 \u0441\u043D\u043E\u0432\u0430 \u043F\u0440\u043E\u0432\u0435\u0440\u044F\u0435\u0442 \u0432\u043B\u0430\u0434\u0435\u043B\u044C\u0446\u0430.",
  "ui.chat.session_readout.access.effective_borrow.title": "\u0414\u043E\u0441\u0442\u0443\u043F \u043A {label} \u0447\u0435\u0440\u0435\u0437 {owner}",
  "ui.chat.session_readout.access.eligible_borrow_unverified.description": "\u042D\u0442\u0430 \u0441\u0435\u0441\u0441\u0438\u044F \u043C\u043E\u0436\u0435\u0442 \u0437\u0430\u0438\u043C\u0441\u0442\u0432\u043E\u0432\u0430\u0442\u044C \u0434\u043E\u0441\u0442\u0443\u043F \u043A {label}, \u043D\u043E \u043F\u043E\u043A\u0430 \u043D\u0435 \u043E\u043F\u0440\u0435\u0434\u0435\u043B\u0438\u043B\u0430 \u0435\u0433\u043E. \u0421\u043B\u0435\u0434\u0443\u044E\u0449\u0438\u0439 \u0437\u0430\u043F\u0440\u043E\u0441 \u0430\u0432\u0442\u043E\u043C\u0430\u0442\u0438\u0447\u0435\u0441\u043A\u0438 \u043F\u0440\u043E\u0432\u0435\u0440\u0438\u0442 {owner}.",
  "ui.chat.session_readout.access.eligible_borrow_unverified.title": "\u041F\u0440\u043E\u0432\u0435\u0440\u043A\u0430 \u0434\u043E\u0441\u0442\u0443\u043F\u0430 \u0447\u0435\u0440\u0435\u0437 {owner}",
  "ui.chat.session_readout.access.expired.description": "\u0421\u0440\u043E\u043A \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u0435\u0433\u043E \u0437\u0430\u0438\u043C\u0441\u0442\u0432\u043E\u0432\u0430\u043D\u043D\u043E\u0433\u043E \u0434\u043E\u0441\u0442\u0443\u043F\u0430 \u0438\u0441\u0442\u0451\u043A, \u043D\u043E \u0440\u0430\u0437\u0440\u0435\u0448\u0435\u043D\u0438\u0435 \u0437\u0430\u0438\u043C\u0441\u0442\u0432\u043E\u0432\u0430\u0442\u044C \u0441\u043E\u0445\u0440\u0430\u043D\u044F\u0435\u0442\u0441\u044F. \u0421\u043B\u0435\u0434\u0443\u044E\u0449\u0438\u0439 \u0437\u0430\u043F\u0440\u043E\u0441 \u0430\u0432\u0442\u043E\u043C\u0430\u0442\u0438\u0447\u0435\u0441\u043A\u0438 \u0437\u0430\u043F\u0440\u043E\u0441\u0438\u0442 \u0443 \u0432\u043B\u0430\u0434\u0435\u043B\u044C\u0446\u0430 ({owner}) \u043D\u043E\u0432\u044B\u0439 \u0434\u043E\u0441\u0442\u0443\u043F.",
  "ui.chat.session_readout.access.expired.title": "\u041D\u0443\u0436\u0435\u043D \u043D\u043E\u0432\u044B\u0439 \u0434\u043E\u0441\u0442\u0443\u043F \u043A {label}",
  "ui.chat.session_readout.access.history.grant_expiry": "\u0417\u0430\u043F\u0438\u0441\u0430\u043D\u043D\u044B\u0439 \u0441\u0440\u043E\u043A \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u044F \u0434\u043E\u0441\u0442\u0443\u043F\u0430: {time}.",
  "ui.chat.session_readout.access.history.last_checked": "\u041F\u043E\u0441\u043B\u0435\u0434\u043D\u044F\u044F \u043F\u0440\u043E\u0432\u0435\u0440\u043A\u0430: {time}.",
  "ui.chat.session_readout.access.history.last_resolved": "\u041F\u043E\u0441\u043B\u0435\u0434\u043D\u0435\u0435 \u043E\u043F\u0440\u0435\u0434\u0435\u043B\u0435\u043D\u0438\u0435 \u0434\u043E\u0441\u0442\u0443\u043F\u0430: {time}.",
  "ui.chat.session_readout.access.history.only": "\u0422\u043E\u043B\u044C\u043A\u043E \u0438\u0441\u0442\u043E\u0440\u0438\u044F; \u044D\u0442\u043E \u043D\u0435 \u0440\u0430\u0437\u0440\u0435\u0448\u0435\u043D\u0438\u0435 \u043D\u0430 \u043F\u043E\u0432\u0442\u043E\u0440\u043D\u043E\u0435 \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u043D\u0438\u0435 \u0434\u043E\u0441\u0442\u0443\u043F\u0430.",
  "ui.chat.session_readout.access.local.description": "\u042D\u0442\u0430 \u0441\u0435\u0441\u0441\u0438\u044F \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u0443\u0435\u0442 \u0441\u043E\u0431\u0441\u0442\u0432\u0435\u043D\u043D\u044B\u0439 \u0434\u043E\u0441\u0442\u0443\u043F \u043A \u043F\u0440\u043E\u0432\u0430\u0439\u0434\u0435\u0440\u0443.",
  "ui.chat.session_readout.access.local.title": "\u0414\u043E\u0441\u0442\u0443\u043F \u043A {label} \u0435\u0441\u0442\u044C",
  "ui.chat.session_readout.access.owner_fallback": "\u0443\u0441\u0442\u0440\u043E\u0439\u0441\u0442\u0432\u043E-\u0432\u043B\u0430\u0434\u0435\u043B\u0435\u0446",
  "ui.chat.session_readout.access.owner_unavailable.description": "\u042D\u0442\u0430 \u0441\u0435\u0441\u0441\u0438\u044F \u043D\u0435 \u0441\u043C\u043E\u0433\u043B\u0430 \u043E\u043F\u0440\u0435\u0434\u0435\u043B\u0438\u0442\u044C \u0434\u043E\u0441\u0442\u0443\u043F \u043A {label} \u0447\u0435\u0440\u0435\u0437 {owner}. \u041F\u0440\u0435\u0436\u043D\u0438\u0439 \u0434\u043E\u0441\u0442\u0443\u043F \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u0442\u044C \u043D\u0435\u043B\u044C\u0437\u044F. \u041F\u043E\u0432\u0442\u043E\u0440\u0438\u0442\u0435 \u043F\u043E\u043F\u044B\u0442\u043A\u0443 \u043F\u043E\u0441\u043B\u0435 \u0432\u043E\u0441\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u044F \u0434\u043E\u0441\u0442\u0443\u043F\u0430 \u0443 \u0432\u043B\u0430\u0434\u0435\u043B\u044C\u0446\u0430 \u0438\u043B\u0438 \u0432\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u0434\u0440\u0443\u0433\u0443\u044E \u043C\u043E\u0434\u0435\u043B\u044C.",
  "ui.chat.session_readout.access.owner_unavailable.title": "\u0414\u043E\u0441\u0442\u0443\u043F \u0447\u0435\u0440\u0435\u0437 {owner} \u043D\u0435\u0434\u043E\u0441\u0442\u0443\u043F\u0435\u043D",
  "ui.chat.session_readout.access.pending.description": "\u0414\u043E\u0441\u0442\u0443\u043F \u0435\u0449\u0451 \u043D\u0435 \u0441\u043E\u0433\u043B\u0430\u0441\u043E\u0432\u0430\u043D. \u0421\u043B\u0435\u0434\u0443\u044E\u0449\u0438\u0439 \u0437\u0430\u043F\u0440\u043E\u0441 \u0430\u0432\u0442\u043E\u043C\u0430\u0442\u0438\u0447\u0435\u0441\u043A\u0438 \u043F\u0440\u043E\u0432\u0435\u0440\u0438\u0442 \u0432\u043B\u0430\u0434\u0435\u043B\u044C\u0446\u0430; \u0434\u043E\u043F\u043E\u043B\u043D\u0438\u0442\u0435\u043B\u044C\u043D\u044B\u0439 \u0432\u0445\u043E\u0434 \u0437\u0434\u0435\u0441\u044C \u043D\u0435 \u043D\u0443\u0436\u0435\u043D.",
  "ui.chat.session_readout.access.pending.title": "\u041F\u0440\u043E\u0432\u0435\u0440\u043A\u0430 \u0434\u043E\u0441\u0442\u0443\u043F\u0430 \u043A {label}",
  "ui.chat.session_readout.access.withdrawn.description": "\u0412\u043B\u0430\u0434\u0435\u043B\u0435\u0446 \u0441\u0435\u0439\u0447\u0430\u0441 \u043D\u0435 \u043C\u043E\u0436\u0435\u0442 \u043F\u0440\u0435\u0434\u043E\u0441\u0442\u0430\u0432\u0438\u0442\u044C \u0437\u0430\u0438\u043C\u0441\u0442\u0432\u043E\u0432\u0430\u043D\u043D\u044B\u0439 \u0434\u043E\u0441\u0442\u0443\u043F, \u0438\u043B\u0438 \u0440\u0430\u0437\u0440\u0435\u0448\u0435\u043D\u0438\u0435 \u0437\u0430\u0438\u043C\u0441\u0442\u0432\u043E\u0432\u0430\u0442\u044C \u043D\u0435\u0434\u043E\u0441\u0442\u0443\u043F\u043D\u043E. \u0412\u043E\u0441\u0441\u0442\u0430\u043D\u043E\u0432\u0438\u0442\u0435 \u0434\u043E\u0441\u0442\u0443\u043F \u0438\u043B\u0438 \u0440\u0430\u0437\u0440\u0435\u0448\u0435\u043D\u0438\u0435 \u0443 \u0432\u043B\u0430\u0434\u0435\u043B\u044C\u0446\u0430 \u0438 \u043F\u043E\u0432\u0442\u043E\u0440\u0438\u0442\u0435 \u043F\u043E\u043F\u044B\u0442\u043A\u0443 \u043B\u0438\u0431\u043E \u0432\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u0434\u0440\u0443\u0433\u0443\u044E \u043C\u043E\u0434\u0435\u043B\u044C.",
  "ui.chat.session_readout.access.withdrawn.title": "\u0414\u043E\u0441\u0442\u0443\u043F \u043A {label} \u0442\u0440\u0435\u0431\u0443\u0435\u0442 \u0432\u043D\u0438\u043C\u0430\u043D\u0438\u044F",
  "ui.chat.session_readout.draft.confirm_effort_changed": "\u042D\u0442\u043E\u0442 \u0440\u0430\u0437\u0433\u043E\u0432\u043E\u0440 \u0431\u0443\u0434\u0435\u0442 \u0440\u0430\u0431\u043E\u0442\u0430\u0442\u044C \u043D\u0430 {selector}. \u0413\u043B\u0443\u0431\u0438\u043D\u0430 \u0440\u0430\u0441\u0441\u0443\u0436\u0434\u0435\u043D\u0438\u0439 \u0442\u0435\u043F\u0435\u0440\u044C \u2014 {level}, \u043F\u043E\u0442\u043E\u043C\u0443 \u0447\u0442\u043E \xAB{wanted}\xBB \u043D\u0435 \u0432\u0445\u043E\u0434\u0438\u0442 \u0432 \u0443\u0440\u043E\u0432\u043D\u0438 \u044D\u0442\u043E\u0439 \u043C\u043E\u0434\u0435\u043B\u0438.",
  "ui.chat.session_readout.draft.confirm_effort_unset": "\u042D\u0442\u043E\u0442 \u0440\u0430\u0437\u0433\u043E\u0432\u043E\u0440 \u0431\u0443\u0434\u0435\u0442 \u0440\u0430\u0431\u043E\u0442\u0430\u0442\u044C \u043D\u0430 {selector}. \u0413\u043B\u0443\u0431\u0438\u043D\u0430 \u0440\u0430\u0441\u0441\u0443\u0436\u0434\u0435\u043D\u0438\u0439 \u0434\u043B\u044F \u043D\u0435\u0433\u043E \u043D\u0435 \u0437\u0430\u0434\u0430\u043D\u0430, \u043F\u043E\u0442\u043E\u043C\u0443 \u0447\u0442\u043E \xAB{wanted}\xBB \u043D\u0435 \u0432\u0445\u043E\u0434\u0438\u0442 \u0432 \u0443\u0440\u043E\u0432\u043D\u0438 \u044D\u0442\u043E\u0439 \u043C\u043E\u0434\u0435\u043B\u0438.",
  "ui.chat.session_readout.draft.confirm_model": "\u042D\u0442\u043E\u0442 \u0440\u0430\u0437\u0433\u043E\u0432\u043E\u0440 \u0431\u0443\u0434\u0435\u0442 \u0440\u0430\u0431\u043E\u0442\u0430\u0442\u044C \u043D\u0430 {selector}.",
  "ui.chat.session_readout.draft.confirm_model_effort": "\u042D\u0442\u043E\u0442 \u0440\u0430\u0437\u0433\u043E\u0432\u043E\u0440 \u0431\u0443\u0434\u0435\u0442 \u0440\u0430\u0431\u043E\u0442\u0430\u0442\u044C \u043D\u0430 {selector}; \u0433\u043B\u0443\u0431\u0438\u043D\u0430 \u0440\u0430\u0441\u0441\u0443\u0436\u0434\u0435\u043D\u0438\u0439 \u2014 {effort}.",
  "ui.chat.session_readout.draft.refusal_ladder_unread": "\u041D\u0438\u0447\u0435\u0433\u043E \u043D\u0435 \u0438\u0437\u043C\u0435\u043D\u0435\u043D\u043E, \u043F\u043E\u0442\u043E\u043C\u0443 \u0447\u0442\u043E \u043D\u0435 \u0443\u0434\u0430\u043B\u043E\u0441\u044C \u043F\u0440\u043E\u0447\u0438\u0442\u0430\u0442\u044C \u0443\u0440\u043E\u0432\u043D\u0438 \u0440\u0430\u0441\u0441\u0443\u0436\u0434\u0435\u043D\u0438\u0439 \u044D\u0442\u043E\u0439 \u043C\u043E\u0434\u0435\u043B\u0438. \u041F\u043E\u0432\u0442\u043E\u0440\u0438\u0442\u0435 \u043F\u043E\u043F\u044B\u0442\u043A\u0443.",
  "ui.chat.session_readout.effort.detail.auto": "\u0423\u0440\u043E\u0432\u0435\u043D\u044C \u043D\u0435 \u0437\u0430\u0434\u0430\u043D, \u043F\u043E\u044D\u0442\u043E\u043C\u0443 \u043C\u043E\u0434\u0435\u043B\u044C \u0440\u0430\u0431\u043E\u0442\u0430\u0435\u0442 \u0441\u043E \u0441\u0432\u043E\u0438\u043C \u0437\u043D\u0430\u0447\u0435\u043D\u0438\u0435\u043C \u043F\u043E \u0443\u043C\u043E\u043B\u0447\u0430\u043D\u0438\u044E. \u0414\u043E\u0441\u0442\u0443\u043F\u043D\u043E: {levels}.",
  "ui.chat.session_readout.effort.detail.auto_with_default": "\u0423\u0440\u043E\u0432\u0435\u043D\u044C \u043D\u0435 \u0437\u0430\u0434\u0430\u043D, \u043F\u043E\u044D\u0442\u043E\u043C\u0443 \u043C\u043E\u0434\u0435\u043B\u044C \u0440\u0430\u0431\u043E\u0442\u0430\u0435\u0442 \u0441\u043E \u0441\u0432\u043E\u0438\u043C \u0437\u043D\u0430\u0447\u0435\u043D\u0438\u0435\u043C \u043F\u043E \u0443\u043C\u043E\u043B\u0447\u0430\u043D\u0438\u044E ({default}). \u0414\u043E\u0441\u0442\u0443\u043F\u043D\u043E: {levels}.",
  "ui.chat.session_readout.effort.detail.default_only": "\u0423\u0440\u043E\u0432\u0435\u043D\u044C, \u043D\u0430 \u043A\u043E\u0442\u043E\u0440\u043E\u043C \u044D\u0442\u0430 \u043C\u043E\u0434\u0435\u043B\u044C \u0440\u0430\u0431\u043E\u0442\u0430\u0435\u0442 \u043F\u043E \u0443\u043C\u043E\u043B\u0447\u0430\u043D\u0438\u044E. \u042D\u0442\u043E\u0442 \u0431\u044D\u043A\u0435\u043D\u0434 \u043D\u0435 \u0441\u043E\u043E\u0431\u0449\u0430\u0435\u0442, \u043A\u0430\u043A\u0438\u0435 \u0435\u0449\u0451 \u0443\u0440\u043E\u0432\u043D\u0438 \u043E\u043D\u0430 \u043F\u0440\u0438\u043D\u0438\u043C\u0430\u0435\u0442.",
  "ui.chat.session_readout.effort.detail.no_levels": "\u042D\u0442\u0430 \u043C\u043E\u0434\u0435\u043B\u044C \u0440\u0430\u0441\u0441\u0443\u0436\u0434\u0430\u0435\u0442, \u043D\u043E \u043D\u0435 \u043F\u0440\u0435\u0434\u043B\u0430\u0433\u0430\u0435\u0442 \u0443\u0440\u043E\u0432\u043D\u0435\u0439 \u0433\u043B\u0443\u0431\u0438\u043D\u044B \u0440\u0430\u0441\u0441\u0443\u0436\u0434\u0435\u043D\u0438\u0439 \u043D\u0430 \u0432\u044B\u0431\u043E\u0440.",
  "ui.chat.session_readout.effort.detail.not_reported": "\u042D\u0442\u0430 \u0441\u0435\u0441\u0441\u0438\u044F \u0435\u0449\u0451 \u043D\u0435 \u0441\u043E\u043E\u0431\u0449\u0438\u043B\u0430 \u0433\u043B\u0443\u0431\u0438\u043D\u0443 \u0440\u0430\u0441\u0441\u0443\u0436\u0434\u0435\u043D\u0438\u0439. \u041E\u043D\u0430 \u043F\u043E\u044F\u0432\u0438\u0442\u0441\u044F \u043F\u043E\u0441\u043B\u0435 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0435\u0433\u043E \u0445\u043E\u0434\u0430, \u0438\u043B\u0438 \u0432\u044B\u043F\u043E\u043B\u043D\u0438\u0442\u0435 {command}, \u0447\u0442\u043E\u0431\u044B \u0437\u0430\u0434\u0430\u0442\u044C \u0435\u0451 \u0441\u0435\u0439\u0447\u0430\u0441.",
  "ui.chat.session_readout.effort.detail.offers": "\u0413\u043B\u0443\u0431\u0438\u043D\u0430 \u0440\u0430\u0441\u0441\u0443\u0436\u0434\u0435\u043D\u0438\u0439. \u042D\u0442\u0430 \u043C\u043E\u0434\u0435\u043B\u044C \u043F\u0440\u0435\u0434\u043B\u0430\u0433\u0430\u0435\u0442: {levels}.",
  "ui.chat.session_readout.effort.detail.session": "\u0413\u043B\u0443\u0431\u0438\u043D\u0430 \u0440\u0430\u0441\u0441\u0443\u0436\u0434\u0435\u043D\u0438\u0439 \u0434\u043B\u044F \u044D\u0442\u043E\u0439 \u0441\u0435\u0441\u0441\u0438\u0438.",
  "ui.chat.session_readout.effort.level.auto": "\u0410\u0432\u0442\u043E",
  "ui.chat.session_readout.effort.level.max": "\u041C\u0430\u043A\u0441\u0438\u043C\u0430\u043B\u044C\u043D\u044B\u0439",
  "ui.chat.session_readout.effort.level.minimal": "\u041C\u0438\u043D\u0438\u043C\u0430\u043B\u044C\u043D\u044B\u0439",
  "ui.chat.session_readout.effort.level.none": "\u041D\u0435\u0442",
  "ui.chat.session_readout.effort.level.reasoning": "\u0440\u0430\u0441\u0441\u0443\u0436\u0434\u0435\u043D\u0438\u044F",
  "ui.chat.session_readout.effort.level.unknown": "\u043D\u0435\u0438\u0437\u0432\u0435\u0441\u0442\u043D\u043E",
  "ui.chat.session_readout.effort.level.xhigh": "\u041E\u0447\u0435\u043D\u044C \u0432\u044B\u0441\u043E\u043A\u0438\u0439",
  "ui.chat.session_readout.model.router_auto": "\u0410\u0432\u0442\u043E",
  "ui.chat.session_readout.strip.draft_failed.detail": "\u041C\u043E\u0434\u0435\u043B\u044C \u0434\u043B\u044F \u043D\u0435\u0433\u043E \u043F\u043E\u043A\u0430 \u043D\u0435 \u0437\u0430\u0434\u0430\u043D\u0430",
  "ui.chat.session_readout.strip.draft_failed.retry": "\u041F\u043E\u0432\u0442\u043E\u0440\u0438\u0442\u044C",
  "ui.chat.session_readout.strip.draft_failed.title": "\u041C\u043E\u0434\u0435\u043B\u044C \u044D\u0442\u043E\u0433\u043E \u0440\u0430\u0437\u0433\u043E\u0432\u043E\u0440\u0430 \u043D\u0435 \u043E\u043F\u0440\u0435\u0434\u0435\u043B\u0435\u043D\u0430",
  "ui.chat.session_readout.strip.draft_pending.detail": "\u041E\u043F\u0440\u0435\u0434\u0435\u043B\u044F\u0435\u0442\u0441\u044F, \u043D\u0430 \u043A\u0430\u043A\u043E\u0439 \u043C\u043E\u0434\u0435\u043B\u0438 \u0431\u0443\u0434\u0435\u0442 \u0440\u0430\u0431\u043E\u0442\u0430\u0442\u044C \u044D\u0442\u043E\u0442 \u0440\u0430\u0437\u0433\u043E\u0432\u043E\u0440",
  "ui.chat.session_readout.strip.draft_pending.label": "\u041E\u043F\u0440\u0435\u0434\u0435\u043B\u0435\u043D\u0438\u0435 \u043C\u043E\u0434\u0435\u043B\u0438",
  "ui.chat.session_readout.strip.draft_pending.title": "\u041E\u043F\u0440\u0435\u0434\u0435\u043B\u0435\u043D\u0438\u0435",
  "ui.chat.session_readout.strip.effort_aria": "\u0413\u043B\u0443\u0431\u0438\u043D\u0430 \u0440\u0430\u0441\u0441\u0443\u0436\u0434\u0435\u043D\u0438\u0439: {level}.",
  "ui.chat.session_readout.strip.fast_mode_on": "\u0411\u044B\u0441\u0442\u0440\u044B\u0439 \u0440\u0435\u0436\u0438\u043C \u0432\u043A\u043B\u044E\u0447\u0451\u043D",
  "ui.chat.session_readout.strip.model_switching": "\u041F\u0435\u0440\u0435\u043A\u043B\u044E\u0447\u0435\u043D\u0438\u0435 \u043C\u043E\u0434\u0435\u043B\u0438; \u043E\u0436\u0438\u0434\u0430\u0435\u0442\u0441\u044F \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0435\u043D\u0438\u0435 \u043E\u0442 \u0441\u0435\u0441\u0441\u0438\u0438",
  "ui.chat.session_readout.strip.readings_dropped": "\u041F\u043E\u043A\u0430\u0437\u0430\u043D\u0438\u044F \u0441\u0431\u0440\u043E\u0448\u0435\u043D\u044B \u043F\u0440\u0438 \u043F\u043E\u0442\u0435\u0440\u0435 \u0441\u043E\u0435\u0434\u0438\u043D\u0435\u043D\u0438\u044F."
};

