  "ui.chat.session_spend.basis_unavailable": "\u0441\u043F\u043E\u0441\u043E\u0431 \u0443\u0447\u0451\u0442\u0430 \u043D\u0435\u0434\u043E\u0441\u0442\u0443\u043F\u0435\u043D",
  "ui.chat.session_spend.child_line": "\u0421\u0443\u0431\u0430\u0433\u0435\u043D\u0442\u044B {amount} \xB7 {bases}",
  "ui.chat.session_spend.context.estimate": "\u043E\u0446\u0435\u043D\u043A\u0430 \u2014 \u043F\u043E\u0434\u0441\u0447\u0438\u0442\u0430\u043D\u043E \u043F\u0440\u0438\u043B\u043E\u0436\u0435\u043D\u0438\u0435\u043C, \u043F\u0440\u043E\u0432\u0430\u0439\u0434\u0435\u0440 \u043F\u043E\u043A\u0430 \u043D\u0435 \u0441\u043E\u043E\u0431\u0449\u0438\u043B",
  "ui.chat.session_spend.context.model_maximum": "\u041C\u0430\u043A\u0441\u0438\u043C\u0443\u043C \u043C\u043E\u0434\u0435\u043B\u0438: {window}",
  "ui.chat.session_spend.context.no_reading": "\u0417\u0430\u043C\u0435\u0440\u0430 \u043F\u043E\u043A\u0430 \u043D\u0435\u0442. \u041F\u0435\u0440\u0432\u044B\u0439 \u0445\u043E\u0434 \u043F\u043E\u043A\u0430\u0436\u0435\u0442, \u0447\u0442\u043E \u0441\u043E\u0434\u0435\u0440\u0436\u0430\u043B \u0437\u0430\u043F\u0440\u043E\u0441.",
  "ui.chat.session_spend.context.title": "\u041A\u043E\u043D\u0442\u0435\u043A\u0441\u0442",
  "ui.chat.session_spend.context.tokens_of_window": "{tokens, number} \u0438\u0437 {window, number} \u0442\u043E\u043A\u0435\u043D\u043E\u0432 (\u043E\u043A\u043D\u043E {windowLabel})",
  "ui.chat.session_spend.context.window_unknown": "\u0422\u043E\u043A\u0435\u043D\u043E\u0432 \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u0443\u0435\u0442\u0441\u044F: {tokens}. \u0420\u0430\u0437\u043C\u0435\u0440 \u043E\u043A\u043D\u0430 \u044D\u0442\u043E\u0439 \u043C\u043E\u0434\u0435\u043B\u0438 \u043D\u0435\u0438\u0437\u0432\u0435\u0441\u0442\u0435\u043D, \u043F\u043E\u044D\u0442\u043E\u043C\u0443 \u043F\u043E\u043A\u0430\u0437\u0430\u0442\u044C \u043F\u0440\u043E\u0446\u0435\u043D\u0442 \u043D\u0435\u043B\u044C\u0437\u044F.",
  "ui.chat.session_spend.duration_explanation": "\u0412\u0440\u0435\u043C\u044F, \u043A\u043E\u0442\u043E\u0440\u043E\u0435 \u0430\u0433\u0435\u043D\u0442 \u043F\u0440\u043E\u0440\u0430\u0431\u043E\u0442\u0430\u043B \u0432 \u044D\u0442\u043E\u043C \u0440\u0430\u0437\u0433\u043E\u0432\u043E\u0440\u0435. \u041E\u0436\u0438\u0434\u0430\u043D\u0438\u0435 \u043C\u0435\u0436\u0434\u0443 \u0445\u043E\u0434\u0430\u043C\u0438 \u043D\u0435 \u0443\u0447\u0438\u0442\u044B\u0432\u0430\u0435\u0442\u0441\u044F.",
  "ui.chat.session_spend.included_api_equivalent": "\u0412\u043A\u043B\u044E\u0447\u0435\u043D\u043E \xB7 \u0432 \u044D\u043A\u0432\u0438\u0432\u0430\u043B\u0435\u043D\u0442\u0435 API",
  "ui.chat.session_spend.plan_clause": "\u0421\u044E\u0434\u0430 \u0432\u0445\u043E\u0434\u0438\u0442 {amount} \u0432 \u0440\u0430\u043C\u043A\u0430\u0445 \u0442\u0430\u0440\u0438\u0444\u0430 (\u0432 \u044D\u043A\u0432\u0438\u0432\u0430\u043B\u0435\u043D\u0442\u0435 API, \u043D\u0435 \u0441\u043F\u0438\u0441\u044B\u0432\u0430\u0435\u0442\u0441\u044F).",
  "ui.chat.session_spend.price_unknown": "\u0446\u0435\u043D\u0430 \u043D\u0435\u0438\u0437\u0432\u0435\u0441\u0442\u043D\u0430",
