  "ui.chat.slash.dispatch.below_version": "/{name} \u043D\u0435\u0434\u043E\u0441\u0442\u0443\u043F\u043D\u0430 \u0432 \u044D\u0442\u043E\u0439 \u0432\u0435\u0440\u0441\u0438\u0438 \u0441\u0435\u0440\u0432\u0435\u0440\u0430 Local Operator. \u041E\u0431\u043D\u043E\u0432\u0438\u0442\u0435 Local Operator \u0438 \u043F\u043E\u0432\u0442\u043E\u0440\u0438\u0442\u0435 \u043F\u043E\u043F\u044B\u0442\u043A\u0443.",
  "ui.chat.slash.dispatch.could_not_run": "\u041D\u0435 \u0443\u0434\u0430\u043B\u043E\u0441\u044C \u0432\u044B\u043F\u043E\u043B\u043D\u0438\u0442\u044C /{name}: {reason}",
  "ui.chat.slash.dispatch.dialog_missing": "/{name} \u0437\u0430\u043F\u0440\u043E\u0441\u0438\u043B\u0430 \u0434\u0438\u0430\u043B\u043E\u0433, \u043A\u043E\u0442\u043E\u0440\u043E\u0433\u043E \u043D\u0435\u0442 \u0432 \u044D\u0442\u043E\u0439 \u0441\u0431\u043E\u0440\u043A\u0435, \u043F\u043E\u044D\u0442\u043E\u043C\u0443 \u043D\u0438\u0447\u0435\u0433\u043E \u043D\u0435 \u0432\u044B\u043F\u043E\u043B\u043D\u0435\u043D\u043E. \u0417\u0430\u043F\u0443\u0441\u0442\u0438\u0442\u0435 \u043A\u043E\u043C\u0430\u043D\u0434\u0443 \u0432 \u0442\u0435\u0440\u043C\u0438\u043D\u0430\u043B\u0435 \u0447\u0435\u0440\u0435\u0437 local-operator.",
  "ui.chat.slash.dispatch.model_resolving": "/{name} \u0436\u0434\u0451\u0442, \u043F\u043E\u043A\u0430 \u043E\u043F\u0440\u0435\u0434\u0435\u043B\u0438\u0442\u0441\u044F \u043C\u043E\u0434\u0435\u043B\u044C \u044D\u0442\u043E\u0433\u043E \u0440\u0430\u0437\u0433\u043E\u0432\u043E\u0440\u0430. \u041F\u043E\u0432\u0442\u043E\u0440\u0438\u0442\u0435 \u0447\u0443\u0442\u044C \u043F\u043E\u0437\u0436\u0435.",
  "ui.chat.slash.dispatch.model_unresolved": "/{name} \u043D\u0443\u0436\u043D\u0430 \u043C\u043E\u0434\u0435\u043B\u044C \u044D\u0442\u043E\u0433\u043E \u0440\u0430\u0437\u0433\u043E\u0432\u043E\u0440\u0430, \u043D\u043E \u043E\u043D\u0430 \u043D\u0435 \u043E\u043F\u0440\u0435\u0434\u0435\u043B\u0435\u043D\u0430. \u041D\u0430\u0436\u043C\u0438\u0442\u0435 \xAB\u041F\u043E\u0432\u0442\u043E\u0440\u0438\u0442\u044C\xBB \u0438 \u043F\u043E\u043F\u0440\u043E\u0431\u0443\u0439\u0442\u0435 \u0441\u043D\u043E\u0432\u0430.",
  "ui.chat.slash.dispatch.move_hint": "\u0412\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u043F\u0430\u043F\u043A\u0443 \u043D\u0430 \u043A\u043D\u043E\u043F\u043A\u0435 \u0440\u0430\u0431\u043E\u0447\u0435\u0433\u043E \u043A\u0430\u0442\u0430\u043B\u043E\u0433\u0430 \u0432\u044B\u0448\u0435 \u0438\u043B\u0438 \u0432\u0432\u0435\u0434\u0438\u0442\u0435 {example}, \u0447\u0442\u043E\u0431\u044B \u043F\u0435\u0440\u0435\u0439\u0442\u0438 \u0442\u0443\u0434\u0430 \u0441\u0440\u0430\u0437\u0443.",
  "ui.chat.slash.dispatch.needs_conversation": "\u0414\u043B\u044F /{name} \u043D\u0443\u0436\u0435\u043D \u043E\u0442\u043A\u0440\u044B\u0442\u044B\u0439 \u0440\u0430\u0437\u0433\u043E\u0432\u043E\u0440. \u0421\u043D\u0430\u0447\u0430\u043B\u0430 \u043D\u0430\u0447\u043D\u0438\u0442\u0435 \u0435\u0433\u043E.",
  "ui.chat.slash.dispatch.needs_newer_backend": "\u0414\u043B\u044F /{name} \u043D\u0443\u0436\u0435\u043D \u0431\u043E\u043B\u0435\u0435 \u043D\u043E\u0432\u044B\u0439 \u0431\u044D\u043A\u0435\u043D\u0434. \u041E\u0431\u043D\u043E\u0432\u0438\u0442\u0435 \u0431\u044D\u043A\u0435\u043D\u0434 \u0438 \u043F\u043E\u0432\u0442\u043E\u0440\u0438\u0442\u0435 \u043F\u043E\u043F\u044B\u0442\u043A\u0443.",
  "ui.chat.slash.dispatch.no_argument_on_draft": "/{name} \u043D\u0435 \u043F\u0440\u0438\u043D\u0438\u043C\u0430\u0435\u0442 \u0430\u0440\u0433\u0443\u043C\u0435\u043D\u0442 \u0432 \u043D\u043E\u0432\u043E\u043C \u0447\u0430\u0442\u0435. \u0412\u0432\u0435\u0434\u0438\u0442\u0435 \u0442\u043E\u043B\u044C\u043A\u043E /{name}, \u0447\u0442\u043E\u0431\u044B \u0437\u0430\u0434\u0430\u0442\u044C \u0437\u043D\u0430\u0447\u0435\u043D\u0438\u0435 \u0434\u043B\u044F \u043F\u0435\u0440\u0432\u043E\u0433\u043E \u0441\u043E\u043E\u0431\u0449\u0435\u043D\u0438\u044F.",
  "ui.chat.slash.dispatch.not_in_desktop": "/{name} \u043F\u043E\u043A\u0430 \u043D\u0435\u0434\u043E\u0441\u0442\u0443\u043F\u043D\u0430 \u0432 \u043D\u0430\u0441\u0442\u043E\u043B\u044C\u043D\u043E\u043C \u043F\u0440\u0438\u043B\u043E\u0436\u0435\u043D\u0438\u0438. \u0417\u0430\u043F\u0443\u0441\u0442\u0438\u0442\u0435 \u043A\u043E\u043C\u0430\u043D\u0434\u0443 \u0432 \u0442\u0435\u0440\u043C\u0438\u043D\u0430\u043B\u0435 \u0447\u0435\u0440\u0435\u0437 local-operator.",
  "ui.chat.slash.dispatch.quit_hint": "\u0417\u0430\u043A\u0440\u043E\u0439\u0442\u0435 \u044D\u0442\u043E \u043E\u043A\u043D\u043E, \u0447\u0442\u043E\u0431\u044B \u0432\u044B\u0439\u0442\u0438. \u0420\u0430\u0437\u0433\u043E\u0432\u043E\u0440\u044B \u043F\u0440\u043E\u0434\u043E\u043B\u0436\u0430\u0442 \u0440\u0430\u0431\u043E\u0442\u0430\u0442\u044C \u0432 \u0444\u043E\u043D\u0435.",
