  "ui.console.pane.surfaces": "\u0422\u0435\u0440\u043C\u0438\u043D\u0430\u043B\u044B \u043A\u043E\u043D\u0441\u043E\u043B\u0438",
  "ui.console.secure": "\u0417\u0430\u0449\u0438\u0449\u0451\u043D\u043D\u044B\u0439 \u0432\u0432\u043E\u0434 \u0432\u043A\u043B\u044E\u0447\u0451\u043D: \u0432\u0432\u0435\u0434\u0451\u043D\u043D\u044B\u0439 \u0437\u0434\u0435\u0441\u044C \u0442\u0435\u043A\u0441\u0442 \u043D\u0435 \u0437\u0430\u043F\u0438\u0441\u044B\u0432\u0430\u0435\u0442\u0441\u044F.",
  "ui.console.unavailable.disabled.detail": "\u0412 \u043E\u043A\u0440\u0443\u0436\u0435\u043D\u0438\u0438 \u043F\u0440\u0438\u043B\u043E\u0436\u0435\u043D\u0438\u044F LOCAL_OPERATOR_UI_CONSOLE_HOST \u0437\u0430\u0434\u0430\u043D\u043E \u0437\u043D\u0430\u0447\u0435\u043D\u0438\u0435 0, \u043F\u043E\u044D\u0442\u043E\u043C\u0443 \u0442\u0435\u0440\u043C\u0438\u043D\u0430\u043B\u044B \u043D\u0435 \u0437\u0430\u043F\u0443\u0441\u043A\u0430\u044E\u0442\u0441\u044F \u0438 \u0441\u043E\u0437\u0434\u0430\u0442\u044C \u043D\u043E\u0432\u044B\u0439 \u0442\u0435\u0440\u043C\u0438\u043D\u0430\u043B \u043D\u0435\u043B\u044C\u0437\u044F. \u0423\u0434\u0430\u043B\u0438\u0442\u0435 \u044D\u0442\u0443 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0443, \u0447\u0442\u043E\u0431\u044B \u0441\u043D\u043E\u0432\u0430 \u0432\u043A\u043B\u044E\u0447\u0438\u0442\u044C \u043A\u043E\u043D\u0441\u043E\u043B\u044C.",
  "ui.console.unavailable.disabled.title": "\u041A\u043E\u043D\u0441\u043E\u043B\u044C \u043E\u0442\u043A\u043B\u044E\u0447\u0435\u043D\u0430 \u0432 \u044D\u0442\u043E\u043C \u0437\u0430\u043F\u0443\u0441\u043A\u0435",
  "ui.console.unavailable.pty.detail": "\u041F\u043E\u0434\u0434\u0435\u0440\u0436\u043A\u0430 \u0442\u0435\u0440\u043C\u0438\u043D\u0430\u043B\u0430 \u043D\u0435 \u0437\u0430\u0433\u0440\u0443\u0437\u0438\u043B\u0430\u0441\u044C \u043F\u0440\u0438 \u044D\u0442\u043E\u043C \u0437\u0430\u043F\u0443\u0441\u043A\u0435. \u041E\u0431\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u0435 Local Operator \u0432\u043E\u0441\u0441\u0442\u0430\u043D\u043E\u0432\u0438\u0442 \u0435\u0451; \u043F\u0440\u0438\u0447\u0438\u043D\u0430 \u0443\u043A\u0430\u0437\u0430\u043D\u0430 \u0432 \u0436\u0443\u0440\u043D\u0430\u043B\u0435 \u043F\u0440\u0438\u043B\u043E\u0436\u0435\u043D\u0438\u044F.",
  "ui.console.unavailable.title": "\u041A\u043E\u043D\u0441\u043E\u043B\u044C \u043D\u0435\u0434\u043E\u0441\u0442\u0443\u043F\u043D\u0430 \u0432 \u044D\u0442\u043E\u043C \u043F\u0440\u0438\u043B\u043E\u0436\u0435\u043D\u0438\u0438",
  "ui.console.unavailable.unknown.detail": "\u042D\u0442\u043E \u043E\u043A\u043D\u043E \u043D\u0435 \u0441\u043C\u043E\u0433\u043B\u043E \u043F\u043E\u0434\u043A\u043B\u044E\u0447\u0438\u0442\u044C\u0441\u044F \u043A \u043A\u043E\u043D\u0441\u043E\u043B\u0438 \u0438 \u043D\u0435 \u0441\u043E\u043E\u0431\u0449\u0438\u043B\u043E \u043F\u0440\u0438\u0447\u0438\u043D\u0443. \u041E\u043D\u0430 \u0443\u043A\u0430\u0437\u0430\u043D\u0430 \u0432 \u0436\u0443\u0440\u043D\u0430\u043B\u0435 \u043F\u0440\u0438\u043B\u043E\u0436\u0435\u043D\u0438\u044F.",
  "ui.console.tab.ended": "\u0437\u0430\u0432\u0435\u0440\u0448\u0451\u043D",
  "ui.console.tab.exit_code": "\u043A\u043E\u0434 {code}",
  "ui.console.tab.agent_opened": "\u0410\u0433\u0435\u043D\u0442 \u043E\u0442\u043A\u0440\u044B\u043B \u044D\u0442\u0443 \u043A\u043E\u043D\u0441\u043E\u043B\u044C",
  "ui.console.tab.agent_typed": "\u0410\u0433\u0435\u043D\u0442 \u0432\u0432\u043E\u0434\u0438\u043B \u0442\u0435\u043A\u0441\u0442 \u0432 \u044D\u0442\u043E\u0439 \u043A\u043E\u043D\u0441\u043E\u043B\u0438",
  "ui.console.tab.close_label": "\u0417\u0430\u043A\u0440\u044B\u0442\u044C {title}, \u0432\u043A\u043B\u0430\u0434\u043A\u0430 {index, number, ::group-off} \u0438\u0437 {total, number, ::group-off}",
  "ui.console.tab.clear_label": "\u041E\u0447\u0438\u0441\u0442\u0438\u0442\u044C {title}, \u0432\u043A\u043B\u0430\u0434\u043A\u0430 {index, number, ::group-off} \u0438\u0437 {total, number, ::group-off}",
  "ui.console.tab.clear_label_retained": "\u041E\u0447\u0438\u0441\u0442\u0438\u0442\u044C {title}, \u0432\u043A\u043B\u0430\u0434\u043A\u0430 {index, number, ::group-off} \u0438\u0437 {total, number, ::group-off} \u2014 \u0441\u043E\u0445\u0440\u0430\u043D\u0451\u043D\u043D\u044B\u0439 \u0432\u044B\u0432\u043E\u0434 \u0431\u0443\u0434\u0435\u0442 \u0443\u0434\u0430\u043B\u0451\u043D",
  "ui.console.secure_toggle.stop": "\u0412\u044B\u043A\u043B\u044E\u0447\u0438\u0442\u044C \u0437\u0430\u0449\u0438\u0449\u0451\u043D\u043D\u044B\u0439 \u0432\u0432\u043E\u0434",
  "ui.console.secure_toggle.start": "\u0417\u0430\u0449\u0438\u0449\u0451\u043D\u043D\u044B\u0439 \u0432\u0432\u043E\u0434",
  "ui.console.secure_toggle.start_tooltip": "\u0417\u0430\u0449\u0438\u0449\u0451\u043D\u043D\u044B\u0439 \u0432\u0432\u043E\u0434: \u043E\u0442\u043A\u043B\u044E\u0447\u0438\u0442\u044C \u0437\u0430\u043F\u0438\u0441\u044C \u044D\u0442\u043E\u0433\u043E \u0442\u0435\u0440\u043C\u0438\u043D\u0430\u043B\u0430",
  "ui.console.close.cancel": "\u041E\u0442\u043C\u0435\u043D\u0430",
  "ui.console.terminal.prompt_label": "\u0412\u0432\u043E\u0434 \u0432 \u0442\u0435\u0440\u043C\u0438\u043D\u0430\u043B\u0435",
  "ui.console.terminal.too_much_output": "\u0421\u043B\u0438\u0448\u043A\u043E\u043C \u043C\u043D\u043E\u0433\u043E \u0432\u044B\u0432\u043E\u0434\u0430 \u0434\u043B\u044F \u043E\u0437\u0432\u0443\u0447\u0438\u0432\u0430\u043D\u0438\u044F. \u0414\u043B\u044F \u0447\u0442\u0435\u043D\u0438\u044F \u043F\u0435\u0440\u0435\u0445\u043E\u0434\u0438\u0442\u0435 \u043F\u043E \u0441\u0442\u0440\u043E\u043A\u0430\u043C \u0432\u0440\u0443\u0447\u043D\u0443\u044E."
