  "ui.hub.subscriptions.saving": "\u0421\u043E\u0445\u0440\u0430\u043D\u0435\u043D\u0438\u0435 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438 {setting} \u0434\u043B\u044F {source}\u2026",
