  "ui.miniView.context_estimated": "\u041A\u043E\u043D\u0442\u0435\u043A\u0441\u0442 (\u0442\u043E\u043A\u0435\u043D\u044B, \u043E\u0446\u0435\u043D\u043A\u0430): {used}.",
