  "ui.miniView.context_window": "\u041A\u043E\u043D\u0442\u0435\u043A\u0441\u0442 (\u0442\u043E\u043A\u0435\u043D\u044B): {used} \u0438\u0437 {window}.",
  "ui.miniView.context_window_estimated": "\u041A\u043E\u043D\u0442\u0435\u043A\u0441\u0442 (\u0442\u043E\u043A\u0435\u043D\u044B, \u043E\u0446\u0435\u043D\u043A\u0430): {used} \u0438\u0437 {window}.",
  "ui.miniView.control_unavailable": "\u042D\u0442\u043E\u0442 \u044D\u043B\u0435\u043C\u0435\u043D\u0442 \u0443\u043F\u0440\u0430\u0432\u043B\u0435\u043D\u0438\u044F \u043D\u0435\u0434\u043E\u0441\u0442\u0443\u043F\u0435\u043D \u043F\u0440\u0438 \u0431\u044B\u0441\u0442\u0440\u043E\u0439 \u043E\u0442\u043F\u0440\u0430\u0432\u043A\u0435.",
  "ui.miniView.cwd_read_only": "\u0411\u044B\u0441\u0442\u0440\u0430\u044F \u043E\u0442\u043F\u0440\u0430\u0432\u043A\u0430 \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u0443\u0435\u0442 \u043F\u0430\u043F\u043A\u0443 \u0440\u0430\u0437\u0433\u043E\u0432\u043E\u0440\u0430.",
  "ui.miniView.hint": "Enter \u043E\u0442\u043F\u0440\u0430\u0432\u043B\u044F\u0435\u0442, Shift+Enter \u0434\u043E\u0431\u0430\u0432\u043B\u044F\u0435\u0442 \u0441\u0442\u0440\u043E\u043A\u0443, Esc \u0441\u043A\u0440\u044B\u0432\u0430\u0435\u0442",
  "ui.miniView.hotkey_needs_modifier": "\u0413\u043B\u043E\u0431\u0430\u043B\u044C\u043D\u043E\u043C\u0443 \u0441\u043E\u0447\u0435\u0442\u0430\u043D\u0438\u044E \u043D\u0443\u0436\u043D\u0430 \u043A\u043B\u0430\u0432\u0438\u0448\u0430-\u043C\u043E\u0434\u0438\u0444\u0438\u043A\u0430\u0442\u043E\u0440, \u0438\u043D\u0430\u0447\u0435 \u043E\u043D\u043E \u0431\u0443\u0434\u0435\u0442 \u0441\u0440\u0430\u0431\u0430\u0442\u044B\u0432\u0430\u0442\u044C \u043F\u0440\u0438 \u0432\u0432\u043E\u0434\u0435.",
  "ui.miniView.keep_text": "\u0412\u0430\u0448\u0435 \u0441\u043E\u043E\u0431\u0449\u0435\u043D\u0438\u0435 \u0441\u043E\u0445\u0440\u0430\u043D\u0438\u043B\u043E\u0441\u044C \u0437\u0434\u0435\u0441\u044C.",
  "ui.miniView.macos_detection_boundary": "\u0415\u0441\u043B\u0438 \u0441\u043E\u0447\u0435\u0442\u0430\u043D\u0438\u0435 \u043D\u0435 \u0441\u0440\u0430\u0431\u0430\u0442\u044B\u0432\u0430\u0435\u0442, \u0435\u0433\u043E \u0437\u0430\u043D\u044F\u043B\u043E \u0434\u0440\u0443\u0433\u043E\u0435 \u043F\u0440\u0438\u043B\u043E\u0436\u0435\u043D\u0438\u0435 \u0438\u043B\u0438 \u0441\u0438\u0441\u0442\u0435\u043C\u0430 \u2014 \u0432\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u0434\u0440\u0443\u0433\u043E\u0435.",
  "ui.miniView.placeholder": "\u0421\u043E\u043E\u0431\u0449\u0435\u043D\u0438\u0435 \u0434\u043B\u044F {name}",
  "ui.miniView.post_admission": "\u0421\u043E\u043E\u0431\u0449\u0435\u043D\u0438\u0435 \u043D\u0435 \u0434\u043E\u0448\u043B\u043E \u0434\u043E {name} \u2014 \u043F\u0440\u043E\u0432\u0435\u0440\u044C\u0442\u0435 \u0440\u0430\u0437\u0433\u043E\u0432\u043E\u0440.",
  "ui.miniView.prior_art_editors": "\u0412 \u043D\u0435\u043A\u043E\u0442\u043E\u0440\u044B\u0445 \u0440\u0435\u0434\u0430\u043A\u0442\u043E\u0440\u0430\u0445 {chord} \u043E\u0442\u043A\u0440\u044B\u0432\u0430\u0435\u0442 \u043F\u043E\u0434\u0441\u043A\u0430\u0437\u043A\u0438 \u043F\u0430\u0440\u0430\u043C\u0435\u0442\u0440\u043E\u0432, \u0430 \u0432 \u0442\u0435\u043A\u0441\u0442\u043E\u0432\u044B\u0445 \u043F\u0440\u043E\u0446\u0435\u0441\u0441\u043E\u0440\u0430\u0445 \u0432\u0441\u0442\u0430\u0432\u043B\u044F\u0435\u0442 \u043D\u0435\u0440\u0430\u0437\u0440\u044B\u0432\u043D\u044B\u0439 \u043F\u0440\u043E\u0431\u0435\u043B.",
  "ui.miniView.prior_art_launchers_mac": "Fantastical \u0438 Things Quick Entry \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u0443\u044E\u0442 Control+Option+Space; \u0432 \u043E\u0431\u043E\u0438\u0445 \u043C\u043E\u0436\u043D\u043E \u0438\u0437\u043C\u0435\u043D\u0438\u0442\u044C \u0441\u043E\u0447\u0435\u0442\u0430\u043D\u0438\u0435.",
  "ui.miniView.prior_art_launchers_other": "\u041D\u0435\u043A\u043E\u0442\u043E\u0440\u044B\u0435 \u043F\u0440\u0438\u043B\u043E\u0436\u0435\u043D\u0438\u044F \u0434\u043B\u044F \u0437\u0430\u0445\u0432\u0430\u0442\u0430 \u0440\u0435\u0437\u0435\u0440\u0432\u0438\u0440\u0443\u044E\u0442 \u043F\u043E\u0445\u043E\u0436\u0435\u0435 \u0441\u043E\u0447\u0435\u0442\u0430\u043D\u0438\u0435; \u0435\u0433\u043E \u043C\u043E\u0436\u043D\u043E \u0438\u0437\u043C\u0435\u043D\u0438\u0442\u044C \u0432 \u0438\u0445 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0430\u0445.",
  "ui.miniView.quick_send_scope": "\u0420\u0430\u0431\u043E\u0442\u0430\u0435\u0442, \u0434\u0430\u0436\u0435 \u043A\u043E\u0433\u0434\u0430 \u043F\u0440\u0438\u043B\u043E\u0436\u0435\u043D\u0438\u0435 \u043D\u0435 \u0432 \u0444\u043E\u043A\u0443\u0441\u0435.",
  "ui.miniView.recording": "\u0417\u0430\u043F\u0438\u0441\u044C. \u041A\u043E\u0433\u0434\u0430 \u0437\u0430\u043A\u043E\u043D\u0447\u0438\u0442\u0435, \u043D\u0430\u0436\u043C\u0438\u0442\u0435 \u043A\u043D\u043E\u043F\u043A\u0443 \u043E\u0441\u0442\u0430\u043D\u043E\u0432\u043A\u0438.",
  "ui.miniView.registration_invalid": "\u042D\u0442\u0443 \u043A\u043B\u0430\u0432\u0438\u0448\u0443 \u043D\u0435\u043B\u044C\u0437\u044F \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u0442\u044C \u0432 \u0433\u043B\u043E\u0431\u0430\u043B\u044C\u043D\u043E\u043C \u0441\u043E\u0447\u0435\u0442\u0430\u043D\u0438\u0438 \u0432 \u044D\u0442\u043E\u0439 \u0441\u0438\u0441\u0442\u0435\u043C\u0435.",
