var ui_notifications_bulk_default5 = {
  "ui.notifications.bulk.dismiss_all": "\u0421\u043A\u0440\u044B\u0442\u044C \u0432\u0441\u0435",
  "ui.notifications.bulk.read_hint": "\u041F\u0440\u043E\u0447\u0438\u0442\u0430\u043D\u043D\u044B\u0435 \u043E\u0431\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u044F \u043E\u0441\u0442\u0430\u044E\u0442\u0441\u044F \u0432\u043E \u0432\u043A\u043B\u0430\u0434\u043A\u0435 \xAB\u0412\u0441\u0435\xBB.",
  "ui.notifications.bulk.dismiss_hint": "\u0421\u043A\u0440\u044B\u0442\u0438\u0435 \u0443\u0431\u0438\u0440\u0430\u0435\u0442 \u043E\u0431\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u044F. \u041E\u0442\u043C\u0435\u043D\u0430 \u0432\u043E\u0437\u0432\u0440\u0430\u0449\u0430\u0435\u0442 \u0438\u0445.",
  "ui.notifications.bulk.frozen_hint": "\u0412\u044B\u0431\u043E\u0440 \u0437\u0430\u0444\u0438\u043A\u0441\u0438\u0440\u043E\u0432\u0430\u043D. \u041D\u043E\u0432\u044B\u0435 \u044D\u043B\u0435\u043C\u0435\u043D\u0442\u044B \u0432 \u043D\u0435\u0433\u043E \u043D\u0435 \u0432\u0445\u043E\u0434\u044F\u0442.",
  "ui.notifications.bulk.confirm_title": "{count, plural, one {\u0421\u043A\u0440\u044B\u0442\u044C # \u043E\u0431\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u0435?} few {\u0421\u043A\u0440\u044B\u0442\u044C # \u043E\u0431\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u044F?} many {\u0421\u043A\u0440\u044B\u0442\u044C # \u043E\u0431\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u0439?} other {\u0421\u043A\u0440\u044B\u0442\u044C # \u043E\u0431\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u044F?}}",
  "ui.notifications.bulk.beyond_page": "\u0414\u0435\u0439\u0441\u0442\u0432\u0438\u0435 \u0437\u0430\u0442\u0440\u043E\u043D\u0435\u0442 \u0438 \u043E\u0431\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u044F \u0437\u0430 \u043F\u0440\u0435\u0434\u0435\u043B\u0430\u043C\u0438 \u0437\u0430\u0433\u0440\u0443\u0436\u0435\u043D\u043D\u043E\u0439 \u0441\u0442\u0440\u0430\u043D\u0438\u0446\u044B.",
  "ui.notifications.bulk.asks_hint": "\u0412\u043E\u043F\u0440\u043E\u0441\u044B \u0431\u0435\u0437 \u043E\u0442\u0432\u0435\u0442\u0430 \u043E\u0441\u0442\u0430\u043D\u0443\u0442\u0441\u044F. \u0420\u0430\u0441\u0441\u043C\u043E\u0442\u0440\u0438\u0442\u0435 \u0438\u0445 \u043E\u0442\u0434\u0435\u043B\u044C\u043D\u043E: \u0437\u0430\u043A\u0440\u044B\u0442\u0438\u0435 \u0432\u043E\u043F\u0440\u043E\u0441\u0430 \u043D\u0435\u043B\u044C\u0437\u044F \u043E\u0442\u043C\u0435\u043D\u0438\u0442\u044C.",
  "ui.notifications.bulk.review_asks": "\u041F\u0440\u043E\u0441\u043C\u043E\u0442\u0440\u0435\u0442\u044C \u0432\u043E\u043F\u0440\u043E\u0441\u044B \u0431\u0435\u0437 \u043E\u0442\u0432\u0435\u0442\u0430",
  "ui.notifications.bulk.select_error": "\u041D\u0435 \u0443\u0434\u0430\u043B\u043E\u0441\u044C \u0432\u044B\u0431\u0440\u0430\u0442\u044C \u044D\u043B\u0435\u043C\u0435\u043D\u0442\u044B \u0432 \u044D\u0442\u043E\u043C \u043F\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u043B\u0435\u043D\u0438\u0438. \u041F\u043E\u043F\u0440\u043E\u0431\u0443\u0439\u0442\u0435 \u0435\u0449\u0451 \u0440\u0430\u0437.",
  "ui.notifications.bulk.update_required": "\u041E\u0431\u043D\u043E\u0432\u0438\u0442\u0435 Local Operator, \u0447\u0442\u043E\u0431\u044B \u0432\u044B\u0431\u0440\u0430\u0442\u044C \u0432\u0441\u0435 \u043F\u043E\u0434\u0445\u043E\u0434\u044F\u0449\u0438\u0435 \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442\u044B.",
  "ui.notifications.bulk.partial": "\u0418\u0437\u043C\u0435\u043D\u0435\u043D\u043E: {changed} \xB7 \u041F\u0440\u043E\u043F\u0443\u0449\u0435\u043D\u043E: {skipped}",
  "ui.notifications.bulk.exclusion_limit": "\u041C\u043E\u0436\u043D\u043E \u0438\u0441\u043A\u043B\u044E\u0447\u0438\u0442\u044C \u043D\u0435 \u0431\u043E\u043B\u0435\u0435 500 \u044D\u043B\u0435\u043C\u0435\u043D\u0442\u043E\u0432. \u0421\u043D\u0438\u043C\u0438\u0442\u0435 \u0432\u044B\u0434\u0435\u043B\u0435\u043D\u0438\u0435, \u0447\u0442\u043E\u0431\u044B \u0432\u044B\u0431\u0440\u0430\u0442\u044C \u044D\u043B\u0435\u043C\u0435\u043D\u0442\u044B \u043F\u043E \u043E\u0442\u0434\u0435\u043B\u044C\u043D\u043E\u0441\u0442\u0438."
};

