  "ui.ownerAudit.title": "\u0421\u043E\u043E\u0431\u0449\u0435\u043D\u0438\u044F \u0432\u0430\u0448\u0435\u0433\u043E \u043A\u043E\u043E\u0440\u0434\u0438\u043D\u0430\u0442\u043E\u0440\u0430",
