  "ui.ownerAudit.admitted": "\u041F\u0440\u0438\u043D\u044F\u0442\u043E \u0432\u0430\u0448\u0438\u043C \u043A\u043E\u043E\u0440\u0434\u0438\u043D\u0430\u0442\u043E\u0440\u043E\u043C",
