  "ui.settings.configuration.backend_settings_drafts.enter_a_whole_number": "\u0412\u0432\u0435\u0434\u0438\u0442\u0435 \u0446\u0435\u043B\u043E\u0435 \u0447\u0438\u0441\u043B\u043E.",
