  "ui.settings.profile.email.label": "\u0410\u0434\u0440\u0435\u0441 \u044D\u043B\u0435\u043A\u0442\u0440\u043E\u043D\u043D\u043E\u0439 \u043F\u043E\u0447\u0442\u044B",
  "ui.settings.profile.email.placeholder": "\u0412\u0432\u0435\u0434\u0438\u0442\u0435 \u0430\u0434\u0440\u0435\u0441 \u043F\u043E\u0447\u0442\u044B\u2026",
  "ui.settings.profile.title": "\u041F\u0440\u043E\u0444\u0438\u043B\u044C \u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u0442\u0435\u043B\u044F",
  "ui.settings.section.interface_language.help": "\u042F\u0437\u044B\u043A \u0438\u043D\u0442\u0435\u0440\u0444\u0435\u0439\u0441\u0430 \u2014 \u043E\u0431\u0449\u0430\u044F \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0430 \u043F\u0440\u0438\u043B\u043E\u0436\u0435\u043D\u0438\u044F \u0438 \u0442\u0435\u0440\u043C\u0438\u043D\u0430\u043B\u0430. auto \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u0443\u0435\u0442 \u044F\u0437\u044B\u043A \u043E\u043F\u0435\u0440\u0430\u0446\u0438\u043E\u043D\u043D\u043E\u0439 \u0441\u0438\u0441\u0442\u0435\u043C\u044B; \u0435\u0441\u043B\u0438 \u043E\u043D \u043D\u0435\u0434\u043E\u0441\u0442\u0443\u043F\u0435\u043D, \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u0443\u0435\u0442\u0441\u044F \u0430\u043D\u0433\u043B\u0438\u0439\u0441\u043A\u0438\u0439.",
  "ui.settings.section.interface_language.label": "\u042F\u0437\u044B\u043A \u0438\u043D\u0442\u0435\u0440\u0444\u0435\u0439\u0441\u0430",
  "ui.settings.tour.action": "\u041D\u0430\u0447\u0430\u0442\u044C \u043E\u0431\u0437\u043E\u0440",
  "ui.settings.tour.description": "\u041F\u0440\u043E\u043F\u0443\u0441\u0442\u0438\u043B\u0438 \u0437\u043D\u0430\u043A\u043E\u043C\u0441\u0442\u0432\u043E \u0441 \u043F\u0440\u0438\u043B\u043E\u0436\u0435\u043D\u0438\u0435\u043C \u0438\u043B\u0438 \u0445\u043E\u0442\u0438\u0442\u0435 \u043E\u0441\u0432\u0435\u0436\u0438\u0442\u044C \u043F\u0430\u043C\u044F\u0442\u044C? \u0417\u0434\u0435\u0441\u044C \u043C\u043E\u0436\u043D\u043E \u0437\u0430\u043F\u0443\u0441\u0442\u0438\u0442\u044C \u043E\u0431\u0437\u043E\u0440 \u0437\u0430\u043D\u043E\u0432\u043E.",
  "ui.settings.tour.title": "\u041E\u0431\u0437\u043E\u0440 \u043F\u0440\u0438\u043B\u043E\u0436\u0435\u043D\u0438\u044F",
  "ui.settings.profile.account_checking": "\u041F\u0440\u043E\u0432\u0435\u0440\u043A\u0430 \u0443\u0447\u0451\u0442\u043D\u043E\u0439 \u0437\u0430\u043F\u0438\u0441\u0438 Radient\u2026",
  "ui.settings.profile.account_read_failed_retry": "\u041D\u0435 \u0443\u0434\u0430\u043B\u043E\u0441\u044C \u043F\u0440\u043E\u0447\u0438\u0442\u0430\u0442\u044C \u0434\u0430\u043D\u043D\u044B\u0435 \u0443\u0447\u0451\u0442\u043D\u043E\u0439 \u0437\u0430\u043F\u0438\u0441\u0438 Radient, \u043F\u043E\u044D\u0442\u043E\u043C\u0443 \u0438\u043C\u044F \u0438 \u0430\u0434\u0440\u0435\u0441 \u043F\u043E\u0447\u0442\u044B \u043D\u0438\u0436\u0435 \u2014 \u043B\u0438\u0448\u044C \u043F\u0440\u0438\u043C\u0435\u0440\u044B, \u0430 \u043D\u0435 \u0434\u0430\u043D\u043D\u044B\u0435 \u0432\u0430\u0448\u0435\u0439 \u0443\u0447\u0451\u0442\u043D\u043E\u0439 \u0437\u0430\u043F\u0438\u0441\u0438. \u041F\u043E\u0432\u0442\u043E\u0440\u0438\u0442\u0435 \u043F\u043E\u043F\u044B\u0442\u043A\u0443.",
  "ui.settings.profile.account_read_failed_refused": "\u041D\u0435 \u0443\u0434\u0430\u043B\u043E\u0441\u044C \u043F\u0440\u043E\u0447\u0438\u0442\u0430\u0442\u044C \u0434\u0430\u043D\u043D\u044B\u0435 \u0443\u0447\u0451\u0442\u043D\u043E\u0439 \u0437\u0430\u043F\u0438\u0441\u0438 Radient, \u043F\u043E\u044D\u0442\u043E\u043C\u0443 \u0438\u043C\u044F \u0438 \u0430\u0434\u0440\u0435\u0441 \u043F\u043E\u0447\u0442\u044B \u043D\u0438\u0436\u0435 \u2014 \u043B\u0438\u0448\u044C \u043F\u0440\u0438\u043C\u0435\u0440\u044B, \u0430 \u043D\u0435 \u0434\u0430\u043D\u043D\u044B\u0435 \u0432\u0430\u0448\u0435\u0439 \u0443\u0447\u0451\u0442\u043D\u043E\u0439 \u0437\u0430\u043F\u0438\u0441\u0438. \u041F\u043E\u0432\u0442\u043E\u0440\u0438\u0442\u0435 \u043F\u043E\u043F\u044B\u0442\u043A\u0443 \u0438\u043B\u0438 \u0432\u043E\u0439\u0434\u0438\u0442\u0435 \u0432 Radient \u0437\u0430\u043D\u043E\u0432\u043E.",
  "ui.settings.profile.retry": "\u041F\u043E\u0432\u0442\u043E\u0440\u0438\u0442\u044C",
  "ui.settings.profile.retrying": "\u041F\u043E\u0432\u0442\u043E\u0440\u043D\u0430\u044F \u043F\u043E\u043F\u044B\u0442\u043A\u0430",
  "ui.settings.section.delegated_enabled.gate_label": "\u0430\u0432\u0442\u043E\u043C\u0430\u0442\u0438\u0447\u0435\u0441\u043A\u043E\u0435 \u0443\u0434\u0430\u043B\u0435\u043D\u0438\u0435",
  "ui.settings.section.delegated_enabled.help": "\u041F\u0440\u0438\u043C\u0435\u043D\u044F\u0435\u0442\u0441\u044F \u0442\u043E\u043B\u044C\u043A\u043E \u043A \u0437\u0430\u043F\u0443\u0441\u043A\u0430\u043C \u0441\u0443\u0431\u0430\u0433\u0435\u043D\u0442\u043E\u0432, \u043E\u0431\u043E\u043B\u043E\u0447\u043A\u0430\u043C \u0430\u0433\u0435\u043D\u0442\u043E\u0432 \u0438 \u0444\u043E\u043D\u043E\u0432\u044B\u043C \u0437\u0430\u043F\u0443\u0441\u043A\u0430\u043C.",
