  "ui.settings.notifications.error.too_large": "\u0424\u0430\u0439\u043B \xAB{file}\xBB \u0431\u043E\u043B\u044C\u0448\u0435 {megabytes, number} \u041C\u0411. \u0412\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u0444\u0440\u0430\u0433\u043C\u0435\u043D\u0442 \u043F\u043E\u043A\u043E\u0440\u043E\u0447\u0435.",
  "ui.settings.notifications.error.unsupported_format": "\u0424\u0430\u0439\u043B \xAB{file}\xBB \u043D\u0435 \u0432 \u0444\u043E\u0440\u043C\u0430\u0442\u0435 WAV, FLAC, MP3 \u0438\u043B\u0438 OGG. \u041F\u0440\u0435\u043E\u0431\u0440\u0430\u0437\u0443\u0439\u0442\u0435 \u0435\u0433\u043E \u0432 WAV \u0438\u043B\u0438 FLAC \u0438 \u0434\u043E\u0431\u0430\u0432\u044C\u0442\u0435 \u0441\u043D\u043E\u0432\u0430.",
  "ui.settings.notifications.error.unsupported_codec": "\u0424\u0430\u0439\u043B\u044B Opus \u0438 M4A \u043D\u0435 \u0447\u0438\u0442\u0430\u044E\u0442\u0441\u044F. \u041F\u0440\u0435\u043E\u0431\u0440\u0430\u0437\u0443\u0439\u0442\u0435 \xAB{file}\xBB \u0432 WAV \u0438\u043B\u0438 FLAC \u0438 \u0434\u043E\u0431\u0430\u0432\u044C\u0442\u0435 \u0441\u043D\u043E\u0432\u0430.",
  "ui.settings.notifications.error.too_long": "\u0414\u043B\u0438\u0442\u0435\u043B\u044C\u043D\u043E\u0441\u0442\u044C \xAB{file}\xBB \u2014 {seconds} \u0441. \u0417\u0432\u0443\u043A \u043C\u043E\u0436\u0435\u0442 \u0434\u043B\u0438\u0442\u044C\u0441\u044F \u043D\u0435 \u0431\u043E\u043B\u044C\u0448\u0435 {limit, number} \u0441.",
  "ui.settings.notifications.error.undecodable": "\u041D\u0435 \u0443\u0434\u0430\u043B\u043E\u0441\u044C \u043F\u0440\u043E\u0447\u0438\u0442\u0430\u0442\u044C \xAB{file}\xBB. \u0412\u043E\u0437\u043C\u043E\u0436\u043D\u043E, \u0444\u0430\u0439\u043B \u043F\u043E\u0432\u0440\u0435\u0436\u0434\u0451\u043D \u0438\u043B\u0438 \u044D\u0442\u043E \u043D\u0435 \u0430\u0443\u0434\u0438\u043E\u0444\u0430\u0439\u043B.",
  "ui.settings.notifications.error.network": "\u041D\u0435 \u0443\u0434\u0430\u043B\u043E\u0441\u044C \u0434\u043E\u0431\u0430\u0432\u0438\u0442\u044C \xAB{file}\xBB. \u0423\u0431\u0435\u0434\u0438\u0442\u0435\u0441\u044C, \u0447\u0442\u043E Local Operator \u0437\u0430\u043F\u0443\u0449\u0435\u043D, \u0438 \u043F\u043E\u0432\u0442\u043E\u0440\u0438\u0442\u0435 \u043F\u043E\u043F\u044B\u0442\u043A\u0443.",
  "ui.settings.notifications.error.choose_another": "\u0412\u044B\u0431\u0440\u0430\u0442\u044C \u0434\u0440\u0443\u0433\u043E\u0439 \u0444\u0430\u0439\u043B",
  "ui.settings.notifications.error.dismiss": "\u0421\u043A\u0440\u044B\u0442\u044C",
  "ui.settings.notifications.test.action": "\u041E\u0442\u043F\u0440\u0430\u0432\u0438\u0442\u044C \u0442\u0435\u0441\u0442\u043E\u0432\u043E\u0435 \u0443\u0432\u0435\u0434\u043E\u043C\u043B\u0435\u043D\u0438\u0435",
  "ui.settings.notifications.test.sent": "\u041E\u0442\u043F\u0440\u0430\u0432\u043B\u0435\u043D\u043E. \u041D\u0435\u0442 \u0437\u0432\u0443\u043A\u0430? \u041F\u0440\u043E\u0432\u0435\u0440\u044C\u0442\u0435 \u0440\u0435\u0436\u0438\u043C \xAB\u0424\u043E\u043A\u0443\u0441\u0438\u0440\u043E\u0432\u0430\u043D\u0438\u0435\xBB \u0438\u043B\u0438 \xAB\u041D\u0435 \u0431\u0435\u0441\u043F\u043E\u043A\u043E\u0438\u0442\u044C\xBB \u0438 \u0433\u0440\u043E\u043C\u043A\u043E\u0441\u0442\u044C \u0441\u0438\u0433\u043D\u0430\u043B\u043E\u0432.",
  "ui.settings.notifications.test.failed": "\u041D\u0435 \u0443\u0434\u0430\u043B\u043E\u0441\u044C \u043F\u043E\u043A\u0430\u0437\u0430\u0442\u044C \u0442\u0435\u0441\u0442\u043E\u0432\u043E\u0435 \u0443\u0432\u0435\u0434\u043E\u043C\u043B\u0435\u043D\u0438\u0435 \u0437\u0434\u0435\u0441\u044C.",
