var ui_updates_panel_default5 = {
  "ui.updates.panel.dismiss.not_now": "\u041D\u0435 \u0441\u0435\u0439\u0447\u0430\u0441",
  "ui.updates.panel.seal.startup.heading": "\u042D\u0442\u0443 \u043A\u043E\u043F\u0438\u044E Local Operator \u043D\u0443\u0436\u043D\u043E \u0437\u0430\u043C\u0435\u043D\u0438\u0442\u044C",
  "ui.updates.panel.seal.startup.message": "\u042D\u0442\u0430 \u043A\u043E\u043F\u0438\u044F Local Operator \u043D\u0435 \u043F\u0440\u043E\u0448\u043B\u0430 \u043F\u0440\u043E\u0432\u0435\u0440\u043A\u0443 \u0446\u0435\u043B\u043E\u0441\u0442\u043D\u043E\u0441\u0442\u0438, \u043F\u043E\u044D\u0442\u043E\u043C\u0443 \u043D\u0435 \u043C\u043E\u0436\u0435\u0442 \u0441\u0435\u0431\u044F \u0432\u043E\u0441\u0441\u0442\u0430\u043D\u043E\u0432\u0438\u0442\u044C.",
  "ui.updates.panel.seal.update.message": "\u042D\u0442\u0443 \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043A\u0443 Local Operator \u043D\u0435\u043B\u044C\u0437\u044F \u043E\u0431\u043D\u043E\u0432\u0438\u0442\u044C \u043D\u0430 \u043C\u0435\u0441\u0442\u0435, \u043F\u043E\u044D\u0442\u043E\u043C\u0443 \u043E\u0431\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u0435 \u043E\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D\u043E \u0435\u0449\u0451 \u0434\u043E \u0437\u0430\u043A\u0440\u044B\u0442\u0438\u044F \u043F\u0440\u0438\u043B\u043E\u0436\u0435\u043D\u0438\u044F.",
  "ui.updates.panel.seal.update.message_version": "\u042D\u0442\u0443 \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043A\u0443 Local Operator \u043D\u0435\u043B\u044C\u0437\u044F \u043E\u0431\u043D\u043E\u0432\u0438\u0442\u044C \u043D\u0430 \u043C\u0435\u0441\u0442\u0435, \u043F\u043E\u044D\u0442\u043E\u043C\u0443 \u043E\u0431\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u0435 \u0434\u043E \u0432\u0435\u0440\u0441\u0438\u0438 {version} \u043E\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D\u043E \u0435\u0449\u0451 \u0434\u043E \u0437\u0430\u043A\u0440\u044B\u0442\u0438\u044F \u043F\u0440\u0438\u043B\u043E\u0436\u0435\u043D\u0438\u044F.",
  "ui.updates.panel.seal.remedy": "\u0412\u044B\u0439\u0434\u0438\u0442\u0435 \u0438\u0437 Local Operator, \u0441\u043A\u0430\u0447\u0430\u0439\u0442\u0435 \u0441\u0432\u0435\u0436\u0443\u044E \u043A\u043E\u043F\u0438\u044E \u0438 \u0437\u0430\u043C\u0435\u043D\u0438\u0442\u0435 \u043F\u0440\u0438\u043B\u043E\u0436\u0435\u043D\u0438\u0435 \u0432 \u043F\u0430\u043F\u043A\u0435 \xAB\u041F\u0440\u043E\u0433\u0440\u0430\u043C\u043C\u044B\xBB.",
  "ui.updates.panel.artifact.metadata_missing.message": "\u0421\u043A\u0430\u0447\u0430\u043D\u043D\u043E\u0435 \u043E\u0431\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u0435 \u043E\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0443\u0435\u0442 \u0432 \u043C\u0435\u0442\u0430\u0434\u0430\u043D\u043D\u044B\u0445 \u0432\u044B\u043F\u0443\u0441\u043A\u0430, \u043F\u043E\u044D\u0442\u043E\u043C\u0443 \u043D\u0435 \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D\u043E.",
  "ui.updates.panel.artifact.metadata_missing.message_version": "\u0421\u043A\u0430\u0447\u0430\u043D\u043D\u043E\u0435 \u043E\u0431\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u0435 \u0434\u043E \u0432\u0435\u0440\u0441\u0438\u0438 {version} \u043E\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0443\u0435\u0442 \u0432 \u043C\u0435\u0442\u0430\u0434\u0430\u043D\u043D\u044B\u0445 \u0432\u044B\u043F\u0443\u0441\u043A\u0430, \u043F\u043E\u044D\u0442\u043E\u043C\u0443 \u043D\u0435 \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D\u043E.",
  "ui.updates.panel.artifact.mismatch.message": "\u0421\u043A\u0430\u0447\u0430\u043D\u043D\u043E\u0435 \u043E\u0431\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u0435 \u043D\u0435 \u0441\u043E\u0432\u043F\u0430\u0434\u0430\u0435\u0442 \u0441 \u043E\u043F\u0443\u0431\u043B\u0438\u043A\u043E\u0432\u0430\u043D\u043D\u044B\u043C \u0432\u044B\u043F\u0443\u0441\u043A\u043E\u043C, \u043F\u043E\u044D\u0442\u043E\u043C\u0443 \u043D\u0435 \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D\u043E.",
  "ui.updates.panel.artifact.mismatch.message_version": "\u0421\u043A\u0430\u0447\u0430\u043D\u043D\u043E\u0435 \u043E\u0431\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u0435 \u0434\u043E \u0432\u0435\u0440\u0441\u0438\u0438 {version} \u043D\u0435 \u0441\u043E\u0432\u043F\u0430\u0434\u0430\u0435\u0442 \u0441 \u043E\u043F\u0443\u0431\u043B\u0438\u043A\u043E\u0432\u0430\u043D\u043D\u044B\u043C \u0432\u044B\u043F\u0443\u0441\u043A\u043E\u043C, \u043F\u043E\u044D\u0442\u043E\u043C\u0443 \u043D\u0435 \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D\u043E.",
  "ui.updates.panel.artifact.unreadable.message": "\u041D\u0435 \u0443\u0434\u0430\u043B\u043E\u0441\u044C \u043F\u0440\u043E\u0447\u0438\u0442\u0430\u0442\u044C \u0441\u043A\u0430\u0447\u0430\u043D\u043D\u043E\u0435 \u043E\u0431\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u0435, \u043F\u043E\u044D\u0442\u043E\u043C\u0443 \u043E\u043D\u043E \u043D\u0435 \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D\u043E.",
  "ui.updates.panel.artifact.unreadable.message_version": "\u041D\u0435 \u0443\u0434\u0430\u043B\u043E\u0441\u044C \u043F\u0440\u043E\u0447\u0438\u0442\u0430\u0442\u044C \u0441\u043A\u0430\u0447\u0430\u043D\u043D\u043E\u0435 \u043E\u0431\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u0435 \u0434\u043E \u0432\u0435\u0440\u0441\u0438\u0438 {version}, \u043F\u043E\u044D\u0442\u043E\u043C\u0443 \u043E\u043D\u043E \u043D\u0435 \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D\u043E.",
  "ui.updates.panel.artifact.missing_on_disk.message": "\u0421\u043A\u0430\u0447\u0430\u043D\u043D\u043E\u0435 \u043E\u0431\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u0435 \u043D\u0435 \u043D\u0430\u0439\u0434\u0435\u043D\u043E \u043D\u0430 \u0434\u0438\u0441\u043A\u0435, \u043F\u043E\u044D\u0442\u043E\u043C\u0443 \u043D\u0435 \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D\u043E.",
  "ui.updates.panel.artifact.missing_on_disk.message_version": "\u0421\u043A\u0430\u0447\u0430\u043D\u043D\u043E\u0435 \u043E\u0431\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u0435 \u0434\u043E \u0432\u0435\u0440\u0441\u0438\u0438 {version} \u043D\u0435 \u043D\u0430\u0439\u0434\u0435\u043D\u043E \u043D\u0430 \u0434\u0438\u0441\u043A\u0435, \u043F\u043E\u044D\u0442\u043E\u043C\u0443 \u043D\u0435 \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D\u043E.",
  "ui.updates.panel.artifact.not_this_app.message": "\u0421\u043A\u0430\u0447\u0430\u043D\u043D\u043E\u0435 \u043E\u0431\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u0435 \u043E\u0442\u043D\u043E\u0441\u0438\u0442\u0441\u044F \u043A \u0434\u0440\u0443\u0433\u043E\u043C\u0443 \u043F\u0440\u0438\u043B\u043E\u0436\u0435\u043D\u0438\u044E, \u043F\u043E\u044D\u0442\u043E\u043C\u0443 \u043D\u0435 \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D\u043E.",
  "ui.updates.panel.artifact.not_this_app.message_version": "\u0421\u043A\u0430\u0447\u0430\u043D\u043D\u043E\u0435 \u043E\u0431\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u0435 \u0434\u043E \u0432\u0435\u0440\u0441\u0438\u0438 {version} \u043E\u0442\u043D\u043E\u0441\u0438\u0442\u0441\u044F \u043A \u0434\u0440\u0443\u0433\u043E\u043C\u0443 \u043F\u0440\u0438\u043B\u043E\u0436\u0435\u043D\u0438\u044E, \u043F\u043E\u044D\u0442\u043E\u043C\u0443 \u043D\u0435 \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D\u043E.",
  "ui.updates.panel.artifact.damaged.message": "\u0421\u043A\u0430\u0447\u0430\u043D\u043D\u043E\u0435 \u043E\u0431\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u0435 \u043F\u043E\u0432\u0440\u0435\u0436\u0434\u0435\u043D\u043E, \u043F\u043E\u044D\u0442\u043E\u043C\u0443 \u043D\u0435 \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D\u043E.",
  "ui.updates.panel.artifact.damaged.message_version": "\u0421\u043A\u0430\u0447\u0430\u043D\u043D\u043E\u0435 \u043E\u0431\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u0435 \u0434\u043E \u0432\u0435\u0440\u0441\u0438\u0438 {version} \u043F\u043E\u0432\u0440\u0435\u0436\u0434\u0435\u043D\u043E, \u043F\u043E\u044D\u0442\u043E\u043C\u0443 \u043D\u0435 \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D\u043E.",
  "ui.updates.panel.artifact.remedy": "\u041F\u0440\u043E\u0432\u0435\u0440\u044C\u0442\u0435 \u043E\u0431\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u044F \u0435\u0449\u0451 \u0440\u0430\u0437, \u0447\u0442\u043E\u0431\u044B \u0441\u043A\u0430\u0447\u0430\u0442\u044C \u0432\u044B\u043F\u0443\u0441\u043A \u0437\u0430\u043D\u043E\u0432\u043E.",
  "ui.updates.panel.disk.message": "\u041D\u0435 \u0445\u0432\u0430\u0442\u0430\u0435\u0442 \u0441\u0432\u043E\u0431\u043E\u0434\u043D\u043E\u0433\u043E \u043C\u0435\u0441\u0442\u0430 \u043D\u0430 \u0434\u0438\u0441\u043A\u0435 \u0434\u043B\u044F \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043A\u0438 \u043E\u0431\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u044F, \u043F\u043E\u044D\u0442\u043E\u043C\u0443 \u043E\u043D\u043E \u043D\u0435 \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D\u043E.",
  "ui.updates.panel.disk.message_version": "\u041D\u0435 \u0445\u0432\u0430\u0442\u0430\u0435\u0442 \u0441\u0432\u043E\u0431\u043E\u0434\u043D\u043E\u0433\u043E \u043C\u0435\u0441\u0442\u0430 \u043D\u0430 \u0434\u0438\u0441\u043A\u0435 \u0434\u043B\u044F \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043A\u0438 \u043E\u0431\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u044F \u0434\u043E \u0432\u0435\u0440\u0441\u0438\u0438 {version}, \u043F\u043E\u044D\u0442\u043E\u043C\u0443 \u043E\u043D\u043E \u043D\u0435 \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D\u043E.",
  "ui.updates.panel.disk.remedy": "\u041E\u0441\u0432\u043E\u0431\u043E\u0434\u0438\u0442\u0435 \u043E\u043A\u043E\u043B\u043E {size}, \u0437\u0430\u0442\u0435\u043C \u0441\u043D\u043E\u0432\u0430 \u043F\u0440\u043E\u0432\u0435\u0440\u044C\u0442\u0435 \u043E\u0431\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u044F.",
  "ui.updates.panel.launch.heading": "\u041D\u0435 \u0443\u0434\u0430\u043B\u043E\u0441\u044C \u043F\u0440\u043E\u0432\u0435\u0440\u0438\u0442\u044C \u043E\u0431\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u0435",
  "ui.updates.panel.launch.check.message": "\u041D\u0435 \u0443\u0434\u0430\u043B\u043E\u0441\u044C \u043F\u0440\u043E\u0432\u0435\u0440\u0438\u0442\u044C \u0437\u0430\u043F\u0443\u0441\u043A \u0441\u043A\u0430\u0447\u0430\u043D\u043D\u043E\u0433\u043E \u043E\u0431\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u044F, \u043F\u043E\u044D\u0442\u043E\u043C\u0443 \u043E\u043D\u043E \u043D\u0435 \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D\u043E.",
  "ui.updates.panel.launch.check.message_version": "\u041D\u0435 \u0443\u0434\u0430\u043B\u043E\u0441\u044C \u043F\u0440\u043E\u0432\u0435\u0440\u0438\u0442\u044C \u0437\u0430\u043F\u0443\u0441\u043A \u043E\u0431\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u044F \u0434\u043E \u0432\u0435\u0440\u0441\u0438\u0438 {version}, \u043F\u043E\u044D\u0442\u043E\u043C\u0443 \u043E\u043D\u043E \u043D\u0435 \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D\u043E.",
  "ui.updates.panel.launch.open.message": "macOS \u043D\u0435 \u043C\u043E\u0436\u0435\u0442 \u0437\u0430\u043F\u0443\u0441\u0442\u0438\u0442\u044C \u0441\u043A\u0430\u0447\u0430\u043D\u043D\u043E\u0435 \u043E\u0431\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u0435, \u043F\u043E\u044D\u0442\u043E\u043C\u0443 \u043E\u043D\u043E \u043D\u0435 \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D\u043E.",
  "ui.updates.panel.launch.open.message_version": "macOS \u043D\u0435 \u043C\u043E\u0436\u0435\u0442 \u0437\u0430\u043F\u0443\u0441\u0442\u0438\u0442\u044C \u043E\u0431\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u0435 \u0434\u043E \u0432\u0435\u0440\u0441\u0438\u0438 {version}, \u043F\u043E\u044D\u0442\u043E\u043C\u0443 \u043E\u043D\u043E \u043D\u0435 \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D\u043E.",
  "ui.updates.panel.launch.keep.message": "\u041F\u0440\u043E\u0434\u043E\u043B\u0436\u0430\u0439\u0442\u0435 \u0440\u0430\u0431\u043E\u0442\u0430\u0442\u044C \u0441 \u044D\u0442\u043E\u0439 \u043A\u043E\u043F\u0438\u0435\u0439 \u2014 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0438\u0439 \u0432\u044B\u043F\u0443\u0441\u043A \u0431\u0443\u0434\u0435\u0442 \u043F\u0440\u0435\u0434\u043B\u043E\u0436\u0435\u043D \u0437\u0434\u0435\u0441\u044C \u043A\u0430\u043A \u043E\u0431\u044B\u0447\u043D\u043E.",
  "ui.updates.panel.launch.keep.message_version": "\u041F\u0440\u043E\u0434\u043E\u043B\u0436\u0430\u0439\u0442\u0435 \u0440\u0430\u0431\u043E\u0442\u0430\u0442\u044C \u0441 \u044D\u0442\u043E\u0439 \u043A\u043E\u043F\u0438\u0435\u0439 \u0438 \u043F\u0440\u043E\u043F\u0443\u0441\u0442\u0438\u0442\u0435 \u0432\u0435\u0440\u0441\u0438\u044E {version}, \u0435\u0441\u043B\u0438 \u0441\u043A\u0430\u0447\u0430\u0435\u0442\u0435 \u0435\u0451 \u0432\u0440\u0443\u0447\u043D\u0443\u044E, \u2014 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0438\u0439 \u0432\u044B\u043F\u0443\u0441\u043A \u0431\u0443\u0434\u0435\u0442 \u043F\u0440\u0435\u0434\u043B\u043E\u0436\u0435\u043D \u0437\u0434\u0435\u0441\u044C \u043A\u0430\u043A \u043E\u0431\u044B\u0447\u043D\u043E.",
  "ui.updates.panel.failure.cancelled.message": "\u041E\u0431\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u0435 \u0434\u043E \u0432\u0435\u0440\u0441\u0438\u0438 {target} \u043E\u0442\u043C\u0435\u043D\u0435\u043D\u043E, \u043F\u043E\u0442\u043E\u043C\u0443 \u0447\u0442\u043E Local Operator \u043E\u0442\u043A\u0440\u044B\u043B\u0438 \u0432\u043E \u0432\u0440\u0435\u043C\u044F \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043A\u0438. \u0412\u0435\u0440\u0441\u0438\u044F {running} \u043F\u043E-\u043F\u0440\u0435\u0436\u043D\u0435\u043C\u0443 \u0440\u0430\u0431\u043E\u0442\u0430\u0435\u0442.",
  "ui.updates.panel.failure.cancelled.remedy": "\u0412\u044B\u0439\u0434\u0438\u0442\u0435 \u0438\u0437 Local Operator \u0438 \u0437\u0430\u043C\u0435\u043D\u0438\u0442\u0435 \u0435\u0433\u043E \u0432 \u043F\u0430\u043F\u043A\u0435 \xAB\u041F\u0440\u043E\u0433\u0440\u0430\u043C\u043C\u044B\xBB \u0441\u0432\u0435\u0436\u0435\u0439 \u043A\u043E\u043F\u0438\u0435\u0439 \u043B\u0438\u0431\u043E \u043E\u0431\u043D\u043E\u0432\u0438\u0442\u0435\u0441\u044C \u0441\u043D\u043E\u0432\u0430 \u0438\u0437 \u043F\u0440\u0438\u043B\u043E\u0436\u0435\u043D\u0438\u044F \u2014 \u0438 \u043D\u0435 \u043E\u0442\u043A\u0440\u044B\u0432\u0430\u0439\u0442\u0435 \u0435\u0433\u043E, \u043F\u043E\u043A\u0430 \u043E\u0431\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u0435 \u043D\u0435 \u0437\u0430\u0432\u0435\u0440\u0448\u0438\u0442\u0441\u044F.",
  "ui.updates.panel.failure.unfinished.message": "\u041E\u0431\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u0435 \u0434\u043E \u0432\u0435\u0440\u0441\u0438\u0438 {target} \u043D\u0435 \u0437\u0430\u0432\u0435\u0440\u0448\u0438\u043B\u043E\u0441\u044C, \u043F\u043E\u044D\u0442\u043E\u043C\u0443 \u0432\u0435\u0440\u0441\u0438\u044F {running} \u043F\u043E-\u043F\u0440\u0435\u0436\u043D\u0435\u043C\u0443 \u0440\u0430\u0431\u043E\u0442\u0430\u0435\u0442.",
  "ui.updates.panel.failure.unfinished.remedy": "\u0412\u044B\u0439\u0434\u0438\u0442\u0435 \u0438\u0437 Local Operator \u0438 \u0437\u0430\u043C\u0435\u043D\u0438\u0442\u0435 \u0435\u0433\u043E \u0432 \u043F\u0430\u043F\u043A\u0435 \xAB\u041F\u0440\u043E\u0433\u0440\u0430\u043C\u043C\u044B\xBB \u0441\u0432\u0435\u0436\u0435\u0439 \u043A\u043E\u043F\u0438\u0435\u0439 \u043B\u0438\u0431\u043E \u043E\u0431\u043D\u043E\u0432\u0438\u0442\u0435\u0441\u044C \u0441\u043D\u043E\u0432\u0430 \u0438\u0437 \u043F\u0440\u0438\u043B\u043E\u0436\u0435\u043D\u0438\u044F.",
  "ui.updates.panel.service.restart.message": "\u0421\u0435\u0440\u0432\u0435\u0440 \u043F\u0435\u0440\u0435\u0437\u0430\u043F\u0443\u0441\u0442\u0438\u043B\u0441\u044F, \u043D\u043E \u043D\u0435 \u0441\u043E\u043E\u0431\u0449\u0438\u043B \u043E\u0431\u043D\u043E\u0432\u043B\u0451\u043D\u043D\u0443\u044E \u0432\u0435\u0440\u0441\u0438\u044E. \u041F\u0440\u043E\u0432\u0435\u0440\u044C\u0442\u0435 \u0436\u0443\u0440\u043D\u0430\u043B \u0441\u043B\u0443\u0436\u0431\u044B \u043E\u0431\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u0439, \u0437\u0430\u0442\u0435\u043C \u043F\u0435\u0440\u0435\u0437\u0430\u043F\u0443\u0441\u0442\u0438\u0442\u0435 Local Operator.",
  "ui.updates.panel.service.restart.message_version": "\u0421\u0435\u0440\u0432\u0435\u0440 \u043F\u0435\u0440\u0435\u0437\u0430\u043F\u0443\u0441\u0442\u0438\u043B\u0441\u044F, \u043D\u043E \u043D\u0435 \u0441\u043E\u043E\u0431\u0449\u0438\u043B \u0432\u0435\u0440\u0441\u0438\u044E {version}. \u041F\u0440\u043E\u0432\u0435\u0440\u044C\u0442\u0435 \u0436\u0443\u0440\u043D\u0430\u043B \u0441\u043B\u0443\u0436\u0431\u044B \u043E\u0431\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u0439, \u0437\u0430\u0442\u0435\u043C \u043F\u0435\u0440\u0435\u0437\u0430\u043F\u0443\u0441\u0442\u0438\u0442\u0435 Local Operator.",
  "ui.updates.panel.service.no_backend.message": "\u0421\u0441\u044B\u043B\u043A\u0430 \u043D\u0430 \u0441\u043B\u0443\u0436\u0431\u0443 \u0431\u044D\u043A\u0435\u043D\u0434\u0430 \u043D\u0435\u0434\u043E\u0441\u0442\u0443\u043F\u043D\u0430, \u043F\u043E\u044D\u0442\u043E\u043C\u0443 \u043E\u0431\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u0435 \u043D\u0435\u0432\u043E\u0437\u043C\u043E\u0436\u043D\u043E.",
  "ui.updates.panel.service.no_server.message": "\u0421\u0435\u0440\u0432\u0435\u0440 Python \u043D\u0435\u0434\u043E\u0441\u0442\u0443\u043F\u0435\u043D, \u043E\u0431\u043D\u043E\u0432\u043B\u044F\u0442\u044C \u043D\u0435\u0447\u0435\u0433\u043E.",
  "ui.updates.panel.service.check_unavailable.message": "\u041D\u0435 \u0443\u0434\u0430\u043B\u043E\u0441\u044C \u043E\u043F\u0440\u0435\u0434\u0435\u043B\u0438\u0442\u044C \u0432\u0435\u0440\u0441\u0438\u044E \u0431\u044D\u043A\u0435\u043D\u0434\u0430.",
  "ui.updates.panel.server.behind.remedy": "\u042D\u0442\u043E\u0442 \u0447\u0435\u043A\u0430\u0443\u0442 \u043E\u0442\u0441\u0442\u0430\u0451\u0442 \u043E\u0442 \u0443\u0434\u0430\u043B\u0451\u043D\u043D\u043E\u0433\u043E \u0440\u0435\u043F\u043E\u0437\u0438\u0442\u043E\u0440\u0438\u044F \u2014 \u0438\u043C\u0435\u043D\u043D\u043E \u043F\u043E\u044D\u0442\u043E\u043C\u0443 `lop-update` \u043E\u0442\u043A\u0430\u0437\u0430\u043B\u0441\u044F \u0438\u0437 \u043D\u0435\u0433\u043E \u0441\u043E\u0431\u0438\u0440\u0430\u0442\u044C. \u041E\u0431\u043D\u043E\u0432\u0438\u0442\u0435 \u0447\u0435\u043A\u0430\u0443\u0442, \u0438 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0435\u0435 \u043D\u0430\u0436\u0430\u0442\u0438\u0435 \u0437\u0434\u0435\u0441\u044C \u0437\u0430\u043F\u0443\u0441\u0442\u0438\u0442 \u0441\u0431\u043E\u0440\u043A\u0443.",
  "ui.updates.panel.server.rebuild.remedy": "\u041F\u0435\u0440\u0435\u0441\u0431\u043E\u0440\u043A\u0430 \u043C\u0435\u043D\u044F\u0435\u0442 \u044D\u0442\u0443 \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043A\u0443, \u0442\u043E\u043B\u044C\u043A\u043E \u0435\u0441\u043B\u0438 \u0437\u0430\u0432\u0435\u0440\u0448\u0438\u0442\u0441\u044F \u0443\u0441\u043F\u0435\u0448\u043D\u043E, \u043F\u043E\u044D\u0442\u043E\u043C\u0443 \u043D\u0438\u0447\u0435\u0433\u043E \u043D\u0435 \u0431\u044B\u043B\u043E \u043F\u0435\u0440\u0435\u0437\u0430\u043F\u0443\u0449\u0435\u043D\u043E.",
  "ui.updates.panel.server.norestart.remedy": "\u041D\u0438\u0447\u0435\u0433\u043E \u043D\u0435 \u0431\u044B\u043B\u043E \u043F\u0435\u0440\u0435\u0437\u0430\u043F\u0443\u0449\u0435\u043D\u043E: \u0440\u0430\u0431\u043E\u0442\u0430\u0435\u0442 \u0442\u0430 \u0436\u0435 \u0441\u0431\u043E\u0440\u043A\u0430, \u0447\u0442\u043E \u0438 \u0440\u0430\u043D\u044C\u0448\u0435."
};

// src/i18n/catalogues/ru/ui.updates.service.json
var ui_updates_service_default5 = {
  "ui.updates.service.release_publishing.message": "\u041D\u043E\u0432\u044B\u0439 \u0432\u044B\u043F\u0443\u0441\u043A \u0441\u0435\u0440\u0432\u0435\u0440\u0430 ({version}) \u0435\u0449\u0451 \u043F\u0443\u0431\u043B\u0438\u043A\u0443\u0435\u0442\u0441\u044F, \u043F\u043E\u044D\u0442\u043E\u043C\u0443 \u043E\u0431\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u0435 \u043F\u043E\u043A\u0430 \u043D\u0435 \u043F\u0440\u0435\u0434\u043B\u043E\u0436\u0435\u043D\u043E. \u041F\u0440\u043E\u0432\u0435\u0440\u044C\u0442\u0435 \u0441\u043D\u043E\u0432\u0430 \u0447\u0435\u0440\u0435\u0437 \u043D\u0435\u0441\u043A\u043E\u043B\u044C\u043A\u043E \u043C\u0438\u043D\u0443\u0442.",
  "ui.updates.service.version_unknown.message": "\u041D\u0435 \u0443\u0434\u0430\u043B\u043E\u0441\u044C \u043E\u043F\u0440\u0435\u0434\u0435\u043B\u0438\u0442\u044C \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D\u043D\u0443\u044E \u0432\u0435\u0440\u0441\u0438\u044E \u0441\u0435\u0440\u0432\u0435\u0440\u0430, \u043F\u043E\u044D\u0442\u043E\u043C\u0443 \u043E\u0431\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u0435 \u043D\u0435 \u043F\u0440\u0435\u0434\u043B\u043E\u0436\u0435\u043D\u043E. \u041F\u0435\u0440\u0435\u0437\u0430\u043F\u0443\u0441\u0442\u0438\u0442\u0435 \u043F\u0440\u0438\u043B\u043E\u0436\u0435\u043D\u0438\u0435 \u0438 \u043F\u043E\u043F\u0440\u043E\u0431\u0443\u0439\u0442\u0435 \u0441\u043D\u043E\u0432\u0430.",
  "ui.updates.service.attempt_running.message_unknown_age": "\u041E\u0431\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u0435 \u0441\u0435\u0440\u0432\u0435\u0440\u0430, \u0437\u0430\u043F\u0443\u0449\u0435\u043D\u043D\u043E\u0435 \u044D\u0442\u0438\u043C \u043F\u0440\u0438\u043B\u043E\u0436\u0435\u043D\u0438\u0435\u043C \u0432 \u043C\u043E\u043C\u0435\u043D\u0442, \u043A\u043E\u0442\u043E\u0440\u044B\u0439 \u043D\u0435 \u0443\u0434\u0430\u043B\u043E\u0441\u044C \u043E\u043F\u0440\u0435\u0434\u0435\u043B\u0438\u0442\u044C, \u0432\u0441\u0451 \u0435\u0449\u0451 \u0432\u044B\u043F\u043E\u043B\u043D\u044F\u0435\u0442\u0441\u044F (\u0433\u0440\u0443\u043F\u043F\u0430 \u043F\u0440\u043E\u0446\u0435\u0441\u0441\u043E\u0432 {group}), \u043F\u043E\u044D\u0442\u043E\u043C\u0443 \u0432\u0442\u043E\u0440\u043E\u0435 \u043F\u0430\u0440\u0430\u043B\u043B\u0435\u043B\u044C\u043D\u043E \u0437\u0430\u043F\u0443\u0441\u043A\u0430\u0442\u044C\u0441\u044F \u043D\u0435 \u0431\u0443\u0434\u0435\u0442. \u0415\u0441\u043B\u0438 \u044D\u0442\u043E \u043E\u0431\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u0435 \u043D\u0435 \u043E\u0442\u0432\u0435\u0447\u0430\u0435\u0442, \u0438\u0437 \u0436\u0443\u0440\u043D\u0430\u043B\u0430 \u0441\u043B\u0443\u0436\u0431\u044B \u043E\u0431\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u0439 \u043C\u043E\u0436\u043D\u043E \u0443\u0437\u043D\u0430\u0442\u044C, \u0447\u0435\u043C \u043E\u043D\u043E \u0437\u0430\u043D\u0438\u043C\u0430\u043B\u043E\u0441\u044C.",
  "ui.updates.service.attempt_running.message_moments": "\u041E\u0431\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u0435 \u0441\u0435\u0440\u0432\u0435\u0440\u0430, \u0437\u0430\u043F\u0443\u0449\u0435\u043D\u043D\u043E\u0435 \u044D\u0442\u0438\u043C \u043F\u0440\u0438\u043B\u043E\u0436\u0435\u043D\u0438\u0435\u043C \u0442\u043E\u043B\u044C\u043A\u043E \u0447\u0442\u043E, \u0432\u0441\u0451 \u0435\u0449\u0451 \u0432\u044B\u043F\u043E\u043B\u043D\u044F\u0435\u0442\u0441\u044F (\u0433\u0440\u0443\u043F\u043F\u0430 \u043F\u0440\u043E\u0446\u0435\u0441\u0441\u043E\u0432 {group}), \u043F\u043E\u044D\u0442\u043E\u043C\u0443 \u0432\u0442\u043E\u0440\u043E\u0435 \u043F\u0430\u0440\u0430\u043B\u043B\u0435\u043B\u044C\u043D\u043E \u0437\u0430\u043F\u0443\u0441\u043A\u0430\u0442\u044C\u0441\u044F \u043D\u0435 \u0431\u0443\u0434\u0435\u0442. \u0415\u0441\u043B\u0438 \u044D\u0442\u043E \u043E\u0431\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u0435 \u043D\u0435 \u043E\u0442\u0432\u0435\u0447\u0430\u0435\u0442, \u0438\u0437 \u0436\u0443\u0440\u043D\u0430\u043B\u0430 \u0441\u043B\u0443\u0436\u0431\u044B \u043E\u0431\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u0439 \u043C\u043E\u0436\u043D\u043E \u0443\u0437\u043D\u0430\u0442\u044C, \u0447\u0435\u043C \u043E\u043D\u043E \u0437\u0430\u043D\u0438\u043C\u0430\u043B\u043E\u0441\u044C.",
  "ui.updates.service.attempt_running.message_minutes": "\u041E\u0431\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u0435 \u0441\u0435\u0440\u0432\u0435\u0440\u0430, \u0437\u0430\u043F\u0443\u0449\u0435\u043D\u043D\u043E\u0435 \u044D\u0442\u0438\u043C \u043F\u0440\u0438\u043B\u043E\u0436\u0435\u043D\u0438\u0435\u043C {minutes, plural, one {# \u043C\u0438\u043D\u0443\u0442\u0443} few {# \u043C\u0438\u043D\u0443\u0442\u044B} many {# \u043C\u0438\u043D\u0443\u0442} other {# \u043C\u0438\u043D\u0443\u0442\u044B}} \u043D\u0430\u0437\u0430\u0434, \u0432\u0441\u0451 \u0435\u0449\u0451 \u0432\u044B\u043F\u043E\u043B\u043D\u044F\u0435\u0442\u0441\u044F (\u0433\u0440\u0443\u043F\u043F\u0430 \u043F\u0440\u043E\u0446\u0435\u0441\u0441\u043E\u0432 {group}), \u043F\u043E\u044D\u0442\u043E\u043C\u0443 \u0432\u0442\u043E\u0440\u043E\u0435 \u043F\u0430\u0440\u0430\u043B\u043B\u0435\u043B\u044C\u043D\u043E \u0437\u0430\u043F\u0443\u0441\u043A\u0430\u0442\u044C\u0441\u044F \u043D\u0435 \u0431\u0443\u0434\u0435\u0442. \u0415\u0441\u043B\u0438 \u044D\u0442\u043E \u043E\u0431\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u0435 \u043D\u0435 \u043E\u0442\u0432\u0435\u0447\u0430\u0435\u0442, \u0438\u0437 \u0436\u0443\u0440\u043D\u0430\u043B\u0430 \u0441\u043B\u0443\u0436\u0431\u044B \u043E\u0431\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u0439 \u043C\u043E\u0436\u043D\u043E \u0443\u0437\u043D\u0430\u0442\u044C, \u0447\u0435\u043C \u043E\u043D\u043E \u0437\u0430\u043D\u0438\u043C\u0430\u043B\u043E\u0441\u044C.",
  "ui.updates.service.already_running.message": "\u041E\u0431\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u0435 \u0441\u0435\u0440\u0432\u0435\u0440\u0430 \u0443\u0436\u0435 \u0432\u044B\u043F\u043E\u043B\u043D\u044F\u0435\u0442\u0441\u044F. \u0414\u043E\u0436\u0434\u0438\u0442\u0435\u0441\u044C \u0435\u0433\u043E \u0437\u0430\u0432\u0435\u0440\u0448\u0435\u043D\u0438\u044F, \u043F\u0440\u0435\u0436\u0434\u0435 \u0447\u0435\u043C \u0437\u0430\u043F\u0443\u0441\u043A\u0430\u0442\u044C \u0434\u0440\u0443\u0433\u043E\u0435.",
  "ui.updates.service.install_not_found.message": "\u0413\u043B\u043E\u0431\u0430\u043B\u044C\u043D\u0430\u044F \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043A\u0430 \u043D\u0435 \u043D\u0430\u0439\u0434\u0435\u043D\u0430 \u043D\u0430 \u044D\u0442\u043E\u043C \u043A\u043E\u043C\u043F\u044C\u044E\u0442\u0435\u0440\u0435, \u043F\u043E\u044D\u0442\u043E\u043C\u0443 \u043E\u0431\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u0435 \u043D\u0435 \u0437\u0430\u043F\u0443\u0441\u043A\u0430\u043B\u043E\u0441\u044C. \u0421\u043C\u043E\u0442\u0440\u0438\u0442\u0435 \u0436\u0443\u0440\u043D\u0430\u043B \u0441\u043B\u0443\u0436\u0431\u044B \u043E\u0431\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u0439.",
  "ui.updates.service.no_restart.message": "\u0421\u0435\u0440\u0432\u0435\u0440 \u043E\u0431\u043D\u043E\u0432\u043B\u0451\u043D, \u043D\u043E \u0431\u044D\u043A\u0435\u043D\u0434 \u043D\u0435 \u043F\u0435\u0440\u0435\u0437\u0430\u043F\u0443\u0441\u0442\u0438\u043B\u0441\u044F. \u041F\u0435\u0440\u0435\u0437\u0430\u043F\u0443\u0441\u0442\u0438\u0442\u0435 Local Operator, \u0447\u0442\u043E\u0431\u044B \u0437\u0430\u043F\u0443\u0441\u0442\u0438\u0442\u044C \u043D\u043E\u0432\u0443\u044E \u0432\u0435\u0440\u0441\u0438\u044E.",
  "ui.updates.service.no_restart_properly.message": "\u0421\u0435\u0440\u0432\u0435\u0440 \u043E\u0431\u043D\u043E\u0432\u043B\u0451\u043D, \u043D\u043E \u0431\u044D\u043A\u0435\u043D\u0434 \u043D\u0435 \u043F\u0435\u0440\u0435\u0437\u0430\u043F\u0443\u0441\u0442\u0438\u043B\u0441\u044F \u0434\u043E\u043B\u0436\u043D\u044B\u043C \u043E\u0431\u0440\u0430\u0437\u043E\u043C. \u041F\u0435\u0440\u0435\u0437\u0430\u043F\u0443\u0441\u0442\u0438\u0442\u0435 Local Operator, \u0447\u0442\u043E\u0431\u044B \u0437\u0430\u043F\u0443\u0441\u0442\u0438\u0442\u044C \u043D\u043E\u0432\u0443\u044E \u0432\u0435\u0440\u0441\u0438\u044E.",
  "ui.updates.service.start_mode_unknown.message": "\u041F\u0440\u0438\u043B\u043E\u0436\u0435\u043D\u0438\u044E \u043D\u0435 \u0443\u0434\u0430\u043B\u043E\u0441\u044C \u043E\u043F\u0440\u0435\u0434\u0435\u043B\u0438\u0442\u044C, \u043A\u0430\u043A \u0431\u044B\u043B \u0437\u0430\u043F\u0443\u0449\u0435\u043D \u044D\u0442\u043E\u0442 \u0441\u0435\u0440\u0432\u0435\u0440, \u043F\u043E\u044D\u0442\u043E\u043C\u0443 \u043E\u043D\u043E \u0435\u0433\u043E \u043D\u0435 \u043E\u0431\u043D\u043E\u0432\u043B\u044F\u043B\u043E. \u0421\u043C\u043E\u0442\u0440\u0438\u0442\u0435 \u0436\u0443\u0440\u043D\u0430\u043B \u0441\u043B\u0443\u0436\u0431\u044B \u043E\u0431\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u0439.",
  "ui.updates.service.no_server_reference.message": "\u0421\u0435\u0439\u0447\u0430\u0441 \u0443 \u043F\u0440\u0438\u043B\u043E\u0436\u0435\u043D\u0438\u044F \u043D\u0435\u0442 \u0441\u0435\u0440\u0432\u0435\u0440\u0430 \u0434\u043B\u044F \u043E\u0431\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u044F. \u041F\u0435\u0440\u0435\u0437\u0430\u043F\u0443\u0441\u0442\u0438\u0442\u0435 Local Operator \u0438 \u043F\u043E\u043F\u0440\u043E\u0431\u0443\u0439\u0442\u0435 \u0441\u043D\u043E\u0432\u0430.",
  "ui.updates.service.release_unreadable.message": "\u041F\u0440\u0438\u043B\u043E\u0436\u0435\u043D\u0438\u044E \u043D\u0435 \u0443\u0434\u0430\u043B\u043E\u0441\u044C \u043F\u0440\u043E\u0447\u0438\u0442\u0430\u0442\u044C, \u043A\u0430\u043A\u043E\u0439 \u0432\u044B\u043F\u0443\u0441\u043A \u0443\u0441\u0442\u0430\u043D\u0430\u0432\u043B\u0438\u0432\u0430\u0442\u044C, \u043F\u043E\u044D\u0442\u043E\u043C\u0443 \u043E\u043D\u043E \u043D\u0435 \u0442\u0440\u043E\u043D\u0443\u043B\u043E \u043E\u043A\u0440\u0443\u0436\u0435\u043D\u0438\u0435 \u0441\u0435\u0440\u0432\u0435\u0440\u0430. \u041F\u0440\u043E\u0432\u0435\u0440\u044C\u0442\u0435 \u043F\u043E\u0434\u043A\u043B\u044E\u0447\u0435\u043D\u0438\u0435 \u0438 \u043F\u043E\u043F\u0440\u043E\u0431\u0443\u0439\u0442\u0435 \u0441\u043D\u043E\u0432\u0430.",
  "ui.updates.service.disk_space.message": "\u0414\u043B\u044F \u043E\u0431\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u044F \u0441\u0435\u0440\u0432\u0435\u0440\u0430 \u043D\u0443\u0436\u043D\u043E \u043E\u043A\u043E\u043B\u043E {needed, number, ::group-off} \u041C\u0411 \u0441\u0432\u043E\u0431\u043E\u0434\u043D\u043E\u0433\u043E \u043C\u0435\u0441\u0442\u0430 \u043D\u0430 \u0434\u0438\u0441\u043A\u0435, \u0430 \u0441\u0432\u043E\u0431\u043E\u0434\u043D\u043E {free, number, ::group-off} \u041C\u0411, \u043F\u043E\u044D\u0442\u043E\u043C\u0443 \u043F\u0440\u0438\u043B\u043E\u0436\u0435\u043D\u0438\u0435 \u043D\u0435 \u0442\u0440\u043E\u043D\u0443\u043B\u043E \u043E\u043A\u0440\u0443\u0436\u0435\u043D\u0438\u0435, \u043E\u0431\u0441\u043B\u0443\u0436\u0438\u0432\u0430\u044E\u0449\u0435\u0435 \u044D\u0442\u043E \u043F\u0440\u0438\u043B\u043E\u0436\u0435\u043D\u0438\u0435. \u041E\u0441\u0432\u043E\u0431\u043E\u0434\u0438\u0442\u0435 \u043C\u0435\u0441\u0442\u043E \u0438 \u043F\u043E\u043F\u0440\u043E\u0431\u0443\u0439\u0442\u0435 \u0441\u043D\u043E\u0432\u0430.",
  "ui.updates.service.not_installed.message": "\u041E\u0431\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u0435 \u0441\u0435\u0440\u0432\u0435\u0440\u0430 \u043D\u0435 \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u0438\u043B\u043E\u0441\u044C, \u043F\u043E\u044D\u0442\u043E\u043C\u0443 \u043E\u043A\u0440\u0443\u0436\u0435\u043D\u0438\u0435, \u043E\u0431\u0441\u043B\u0443\u0436\u0438\u0432\u0430\u044E\u0449\u0435\u0435 \u044D\u0442\u043E \u043F\u0440\u0438\u043B\u043E\u0436\u0435\u043D\u0438\u0435, \u043E\u0441\u0442\u0430\u043B\u043E\u0441\u044C \u043F\u0440\u0435\u0436\u043D\u0438\u043C.",
  "ui.updates.service.install_in_flight.message": "\u0412\u0435\u0440\u0441\u0438\u044F {version} \u043D\u0435 \u0441\u043C\u043E\u0436\u0435\u0442 \u0437\u0430\u0432\u0435\u0440\u0448\u0438\u0442\u044C \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043A\u0443, \u043F\u043E\u043A\u0430 \u043E\u0442\u043A\u0440\u044B\u0442 Local Operator: \u0435\u0441\u043B\u0438 \u043E\u0441\u0442\u0430\u0432\u0438\u0442\u044C \u0435\u0433\u043E \u043E\u0442\u043A\u0440\u044B\u0442\u044B\u043C, \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043A\u0430 \u0431\u0443\u0434\u0435\u0442 \u043E\u0442\u043C\u0435\u043D\u0435\u043D\u0430. \u0412\u044B\u0439\u0434\u0438\u0442\u0435 \u0438\u0437 \u043F\u0440\u0438\u043B\u043E\u0436\u0435\u043D\u0438\u044F \u0438 \u043D\u0435 \u043E\u0442\u043A\u0440\u044B\u0432\u0430\u0439\u0442\u0435 \u0435\u0433\u043E, \u043F\u043E\u043A\u0430 \u043E\u043D\u043E \u043D\u0435 \u0437\u0430\u043F\u0443\u0441\u0442\u0438\u0442\u0441\u044F \u0441\u0430\u043C\u043E.",
  "ui.updates.service.server_failure.not_run": "\u041E\u0431\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u0435 \u0441\u0435\u0440\u0432\u0435\u0440\u0430 \u043D\u0435 \u0437\u0430\u0432\u0435\u0440\u0448\u0438\u043B\u043E\u0441\u044C: \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u0449\u0438\u043A \u043D\u0435 \u0443\u0434\u0430\u043B\u043E\u0441\u044C \u0434\u043E\u0432\u0435\u0441\u0442\u0438 \u0434\u043E \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442\u0430.",
  "ui.updates.service.server_failure.exited": "\u041E\u0431\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u0435 \u0441\u0435\u0440\u0432\u0435\u0440\u0430 \u043D\u0435 \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u0438\u043B\u043E\u0441\u044C: \u043A\u043E\u043C\u0430\u043D\u0434\u0430 `{command}` \u0437\u0430\u0432\u0435\u0440\u0448\u0438\u043B\u0430\u0441\u044C \u0441 \u043A\u043E\u0434\u043E\u043C {code}.",
  "ui.updates.service.server_failure.rebuild_unchanged": "\u041F\u0435\u0440\u0435\u0441\u0431\u043E\u0440\u043A\u0430 \u0437\u0430\u0432\u0435\u0440\u0448\u0438\u043B\u0430\u0441\u044C, \u043D\u043E \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043A\u0430 \u043D\u0435 \u0438\u0437\u043C\u0435\u043D\u0438\u043B\u0430\u0441\u044C: \u0432 `.lop-source` \u043F\u043E-\u043F\u0440\u0435\u0436\u043D\u0435\u043C\u0443 \u0443\u043A\u0430\u0437\u0430\u043D\u0430 \u0442\u0430 \u0436\u0435 \u0440\u0435\u0432\u0438\u0437\u0438\u044F.",
  "ui.updates.service.server_failure.not_effective": "\u041E\u0431\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u0435 \u0441\u0435\u0440\u0432\u0435\u0440\u0430 \u0434\u043E {target} \u043D\u0435 \u0432\u0441\u0442\u0443\u043F\u0438\u043B\u043E \u0432 \u0441\u0438\u043B\u0443: \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043A\u0430 \u043F\u043E-\u043F\u0440\u0435\u0436\u043D\u0435\u043C\u0443 \u0441\u043E\u043E\u0431\u0449\u0430\u0435\u0442 {installed}.",
  "ui.updates.service.server_failure.target_fallback": "\u043D\u043E\u0432\u043E\u0433\u043E \u0432\u044B\u043F\u0443\u0441\u043A\u0430",
  "ui.updates.service.server_failure.installed_fallback": "\u043F\u0440\u0435\u0434\u044B\u0434\u0443\u0449\u0443\u044E \u0432\u0435\u0440\u0441\u0438\u044E",
  "ui.updates.service.server_failure.stopped": "\u041F\u0440\u043E\u0433\u0440\u0430\u043C\u043C\u0430 \u043E\u0431\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u044F \u0431\u044B\u043B\u0430 \u043E\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D\u0430; \u0437\u0430\u043F\u0443\u0449\u0435\u043D\u043D\u044B\u0439 \u0435\u044E \u043F\u0440\u043E\u0446\u0435\u0441\u0441 \u0432\u0441\u0451 \u0435\u0449\u0451 \u043C\u043E\u0436\u0435\u0442 \u0437\u0430\u043C\u0435\u043D\u044F\u0442\u044C \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043A\u0443.",
  "ui.updates.service.server_failure.pointer_below": "\u0412\u044B\u0432\u043E\u0434 \u0441\u0430\u043C\u043E\u0433\u043E \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u0449\u0438\u043A\u0430 \u043F\u0440\u0438\u0432\u0435\u0434\u0451\u043D \u043D\u0438\u0436\u0435.",
  "ui.updates.service.server_failure.pointer_log": "\u0412\u044B\u0432\u043E\u0434 \u0441\u0430\u043C\u043E\u0433\u043E \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u0449\u0438\u043A\u0430 \u0435\u0441\u0442\u044C \u0432 \u0436\u0443\u0440\u043D\u0430\u043B\u0435 \u0441\u043B\u0443\u0436\u0431\u044B \u043E\u0431\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u0439.",
  "ui.updates.service.server_failure.run_yourself": "\u041C\u043E\u0436\u043D\u043E \u0442\u0430\u043A\u0436\u0435 \u0441\u0430\u043C\u043E\u0441\u0442\u043E\u044F\u0442\u0435\u043B\u044C\u043D\u043E \u0437\u0430\u043F\u0443\u0441\u0442\u0438\u0442\u044C `{command}` \u0432 \u0442\u0435\u0440\u043C\u0438\u043D\u0430\u043B\u0435.",
  "ui.updates.service.fleet.closing": "\u041D\u0438\u0447\u0435\u0433\u043E \u043D\u0435 \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D\u043E, \u0441\u0435\u0440\u0432\u0435\u0440 \u043F\u0440\u043E\u0434\u043E\u043B\u0436\u0430\u0435\u0442 \u0440\u0430\u0431\u043E\u0442\u0430\u0442\u044C \u043D\u0430 \u0443\u0436\u0435 \u0437\u0430\u043F\u0443\u0449\u0435\u043D\u043D\u043E\u0439 \u0441\u0431\u043E\u0440\u043A\u0435; \u043F\u0440\u0438\u043B\u043E\u0436\u0435\u043D\u0438\u0435 \u043F\u0440\u0435\u0434\u043B\u043E\u0436\u0438\u0442 \u044D\u0442\u043E \u043E\u0431\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u0435 \u0441\u043D\u043E\u0432\u0430.",
  "ui.updates.service.fleet.unknown.credentials_refused": "\u0421\u0435\u0440\u0432\u0435\u0440 \u043E\u0442\u043A\u043B\u043E\u043D\u0438\u043B \u0443\u0447\u0451\u0442\u043D\u044B\u0435 \u0434\u0430\u043D\u043D\u044B\u0435 \u043F\u0440\u0438\u043B\u043E\u0436\u0435\u043D\u0438\u044F, \u043F\u043E\u044D\u0442\u043E\u043C\u0443 \u043E\u043D\u043E \u043D\u0435 \u0441\u043C\u043E\u0433\u043B\u043E \u0443\u0437\u043D\u0430\u0442\u044C, \u043A\u0430\u043A\u0438\u0435 \u0441\u0435\u0441\u0441\u0438\u0438 \u0441\u0435\u0439\u0447\u0430\u0441 \u0432\u044B\u043F\u043E\u043B\u043D\u044F\u044E\u0442\u0441\u044F \u043D\u0430 \u044D\u0442\u043E\u043C \u043A\u043E\u043C\u043F\u044C\u044E\u0442\u0435\u0440\u0435.",
  "ui.updates.service.fleet.unknown.unreadable": "\u041F\u0440\u0438\u043B\u043E\u0436\u0435\u043D\u0438\u044E \u043D\u0435 \u0443\u0434\u0430\u043B\u043E\u0441\u044C \u0443\u0437\u043D\u0430\u0442\u044C, \u043A\u0430\u043A\u0438\u0435 \u0441\u0435\u0441\u0441\u0438\u0438 \u0432\u044B\u043F\u043E\u043B\u043D\u044F\u044E\u0442\u0441\u044F \u043D\u0430 \u044D\u0442\u043E\u043C \u043A\u043E\u043C\u043F\u044C\u044E\u0442\u0435\u0440\u0435, \u043F\u043E\u044D\u0442\u043E\u043C\u0443 \u043E\u043D\u043E \u043D\u0435 \u043E\u0431\u043D\u043E\u0432\u0438\u043B\u043E \u0441\u0435\u0440\u0432\u0435\u0440.",
  "ui.updates.service.fleet.unknown.body": "\u0415\u0441\u043B\u0438 \u043F\u0440\u0438\u043D\u044F\u0442\u044C \u043D\u0435\u0447\u0438\u0442\u0430\u0435\u043C\u043E\u0435 \u0441\u043E\u0441\u0442\u043E\u044F\u043D\u0438\u0435 \u0441\u0435\u0441\u0441\u0438\u0439 \u0437\u0430 \u043F\u0440\u043E\u0441\u0442\u043E\u0439, \u043C\u043E\u0436\u043D\u043E \u043F\u0440\u0435\u0440\u0432\u0430\u0442\u044C \u0445\u043E\u0434, \u043A\u043E\u0442\u043E\u0440\u044B\u0439 \u0435\u0449\u0451 \u0438\u0434\u0451\u0442, \u043F\u043E\u044D\u0442\u043E\u043C\u0443 \u043F\u0440\u0438\u043B\u043E\u0436\u0435\u043D\u0438\u0435 \u043F\u043E\u0434\u043E\u0436\u0434\u0430\u043B\u043E {minutes, plural, one {# \u043C\u0438\u043D\u0443\u0442\u0443} few {# \u043C\u0438\u043D\u0443\u0442\u044B} many {# \u043C\u0438\u043D\u0443\u0442} other {# \u043C\u0438\u043D\u0443\u0442\u044B}} \u0438 \u043E\u0441\u0442\u0430\u043D\u043E\u0432\u0438\u043B\u043E\u0441\u044C. {closing}",
  "ui.updates.service.fleet.busy.none_named": "\u041F\u0440\u0438\u043B\u043E\u0436\u0435\u043D\u0438\u044E \u043D\u0435 \u0443\u0434\u0430\u043B\u043E\u0441\u044C \u043E\u043F\u0440\u0435\u0434\u0435\u043B\u0438\u0442\u044C \u043D\u0430\u0437\u0432\u0430\u043D\u0438\u044F \u0441\u0435\u0441\u0441\u0438\u0439, \u043A\u043E\u0442\u043E\u0440\u044B\u0435 \u0435\u0449\u0451 \u0440\u0430\u0431\u043E\u0442\u0430\u043B\u0438.",
  "ui.updates.service.fleet.busy.lead": "\u0425\u043E\u0434 \u0435\u0449\u0451 \u0432\u044B\u043F\u043E\u043B\u043D\u044F\u0435\u0442\u0441\u044F \u0432 {count, plural, one {# \u0441\u0435\u0441\u0441\u0438\u0438} few {# \u0441\u0435\u0441\u0441\u0438\u044F\u0445} many {# \u0441\u0435\u0441\u0441\u0438\u044F\u0445} other {# \u0441\u0435\u0441\u0441\u0438\u044F\u0445}} \u043D\u0430 \u044D\u0442\u043E\u043C \u043A\u043E\u043C\u043F\u044C\u044E\u0442\u0435\u0440\u0435: {names}{extra, plural, =0 {} one { \u0438 \u0435\u0449\u0451 #} few { \u0438 \u0435\u0449\u0451 #} many { \u0438 \u0435\u0449\u0451 #} other { \u0438 \u0435\u0449\u0451 #}}.",
  "ui.updates.service.fleet.busy.body": "\u041F\u0440\u0438\u043B\u043E\u0436\u0435\u043D\u0438\u0435 \u0436\u0434\u0430\u043B\u043E {minutes, plural, one {# \u043C\u0438\u043D\u0443\u0442\u0443} few {# \u043C\u0438\u043D\u0443\u0442\u044B} many {# \u043C\u0438\u043D\u0443\u0442} other {# \u043C\u0438\u043D\u0443\u0442\u044B}}, \u043F\u043E\u043A\u0430 \u0432\u0441\u0451 \u0437\u0430\u0432\u0435\u0440\u0448\u0438\u0442\u0441\u044F, \u0430 \u0437\u0430\u0442\u0435\u043C \u043E\u0441\u0442\u0430\u043D\u043E\u0432\u0438\u043B\u043E\u0441\u044C, \u0447\u0442\u043E\u0431\u044B \u043D\u0435 \u043F\u0440\u0435\u0440\u044B\u0432\u0430\u0442\u044C \u0445\u043E\u0434. {closing}",
  "ui.updates.service.global.source_build.remedy": "\u0421\u0435\u0440\u0432\u0435\u0440 \u0437\u0430\u043F\u0443\u0449\u0435\u043D \u0438\u0437 \u0438\u0441\u0445\u043E\u0434\u043D\u043E\u0433\u043E \u0447\u0435\u043A\u0430\u0443\u0442\u0430 \u043D\u0430 \u044D\u0442\u043E\u043C \u043A\u043E\u043C\u043F\u044C\u044E\u0442\u0435\u0440\u0435, \u0430 \u043D\u0435 \u0438\u0437 \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D\u043D\u043E\u0439 \u043A\u043E\u043F\u0438\u0438, \u043F\u043E\u044D\u0442\u043E\u043C\u0443 \u043E\u0431\u043D\u043E\u0432\u0438\u0442\u0435 \u0435\u0433\u043E \u043A\u043E\u043C\u0430\u043D\u0434\u043E\u0439 lop-update \u043F\u043E\u0441\u043B\u0435 \u0441\u043B\u0438\u044F\u043D\u0438\u044F \u0432\u0430\u0448\u0435\u0433\u043E \u0438\u0437\u043C\u0435\u043D\u0435\u043D\u0438\u044F.",
  "ui.updates.service.global.pipx.remedy": "\u0421\u0435\u0440\u0432\u0435\u0440 \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D \u0447\u0435\u0440\u0435\u0437 pipx, \u043F\u043E\u044D\u0442\u043E\u043C\u0443 \u043E\u0431\u043D\u043E\u0432\u0438\u0442\u0435 \u0435\u0433\u043E \u0438\u0437 \u0442\u0435\u0440\u043C\u0438\u043D\u0430\u043B\u0430",
  "ui.updates.service.global.pip.remedy": "\u0421\u0435\u0440\u0432\u0435\u0440 \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D \u0447\u0435\u0440\u0435\u0437 pip, \u043F\u043E\u044D\u0442\u043E\u043C\u0443 \u043E\u0431\u043D\u043E\u0432\u0438\u0442\u0435 \u0435\u0433\u043E \u0438\u0437 \u0442\u0435\u0440\u043C\u0438\u043D\u0430\u043B\u0430",
  "ui.updates.service.global.unknown.remedy": "\u041F\u0440\u0438\u043B\u043E\u0436\u0435\u043D\u0438\u044E \u043D\u0435 \u0443\u0434\u0430\u043B\u043E\u0441\u044C \u043E\u043F\u0440\u0435\u0434\u0435\u043B\u0438\u0442\u044C, \u043A\u0430\u043A \u0431\u044B\u043B \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D \u044D\u0442\u043E\u0442 \u0441\u0435\u0440\u0432\u0435\u0440, \u043F\u043E\u044D\u0442\u043E\u043C\u0443 \u043E\u0431\u043D\u043E\u0432\u0438\u0442\u0435 \u0435\u0433\u043E \u0442\u0435\u043C \u0441\u0440\u0435\u0434\u0441\u0442\u0432\u043E\u043C, \u043A\u043E\u0442\u043E\u0440\u044B\u043C \u0432\u044B \u0435\u0433\u043E \u0443\u0441\u0442\u0430\u043D\u0430\u0432\u043B\u0438\u0432\u0430\u043B\u0438, \u2014 uv, pipx \u0438\u043B\u0438 pip",
  "ui.updates.service.global.source_rebuild.remedy": "\u041F\u0435\u0440\u0435\u0441\u043E\u0431\u0438\u0440\u0430\u0435\u0442 \u044D\u0442\u043E\u0442 \u0447\u0435\u043A\u0430\u0443\u0442 \u043A\u043E\u043C\u0430\u043D\u0434\u043E\u0439 `lop-update`. \u0421\u043D\u0430\u0447\u0430\u043B\u0430 \u043F\u0440\u0438\u043B\u043E\u0436\u0435\u043D\u0438\u0435 \u0434\u043E\u0436\u0438\u0434\u0430\u0435\u0442\u0441\u044F \u0437\u0430\u0432\u0435\u0440\u0448\u0435\u043D\u0438\u044F \u0445\u043E\u0434\u043E\u0432, \u0432\u044B\u043F\u043E\u043B\u043D\u044F\u044E\u0449\u0438\u0445\u0441\u044F \u043D\u0430 \u044D\u0442\u043E\u043C \u043A\u043E\u043C\u043F\u044C\u044E\u0442\u0435\u0440\u0435, \u0430 \u0437\u0430\u0442\u0435\u043C \u043F\u0435\u0440\u0435\u0441\u0431\u043E\u0440\u043A\u0430 \u043F\u0435\u0440\u0435\u0443\u0441\u0442\u0430\u043D\u0430\u0432\u043B\u0438\u0432\u0430\u0435\u0442 \u044D\u0442\u0443 \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043A\u0443 \u043D\u0430 \u043C\u0435\u0441\u0442\u0435 \u2014 \u043F\u043E\u044D\u0442\u043E\u043C\u0443 \u0445\u043E\u0434, \u043D\u0430\u0447\u0430\u0442\u044B\u0439 \u0432\u043E \u0432\u0440\u0435\u043C\u044F \u043D\u0435\u0451, \u0432\u0441\u0451 \u0440\u0430\u0432\u043D\u043E \u043C\u043E\u0436\u0435\u0442 \u0431\u044B\u0442\u044C \u043F\u0440\u0435\u0440\u0432\u0430\u043D, \u2014 \u0438 \u044D\u0442\u043E \u043C\u043E\u0436\u0435\u0442 \u0437\u0430\u043D\u044F\u0442\u044C \u0434\u043E \u043F\u043E\u043B\u0443\u0447\u0430\u0441\u0430. \u042D\u0442\u0430 \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043A\u0430 \u043F\u043E-\u043F\u0440\u0435\u0436\u043D\u0435\u043C\u0443 \u0441\u043E\u043E\u0431\u0449\u0430\u0435\u0442 \u0432\u0435\u0440\u0441\u0438\u044E \u0447\u0435\u043A\u0430\u0443\u0442\u0430, \u0430 \u043D\u0435 \u0432\u044B\u043F\u0443\u0441\u043A, \u043F\u0440\u0435\u0434\u043B\u043E\u0436\u0435\u043D\u043D\u044B\u0439 \u043F\u0440\u0438\u043B\u043E\u0436\u0435\u043D\u0438\u0435\u043C.",
  "ui.updates.service.global.legacy_installer.remedy": "\u042D\u0442\u0430 \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043A\u0430 \u0441\u043E\u0437\u0434\u0430\u043D\u0430 \u0434\u043E \u043F\u043E\u044F\u0432\u043B\u0435\u043D\u0438\u044F \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u0449\u0438\u043A\u0430, \u043D\u0435 \u043F\u0440\u0435\u0440\u044B\u0432\u0430\u044E\u0449\u0435\u0433\u043E \u0440\u0430\u0431\u043E\u0442\u0443 \u0441\u0435\u0441\u0441\u0438\u0439, \u043F\u043E\u044D\u0442\u043E\u043C\u0443 \u043E\u0431\u043D\u043E\u0432\u0438\u0442\u0435 \u0435\u0451 \u043E\u0434\u0438\u043D \u0440\u0430\u0437 \u0438\u0437 \u0442\u0435\u0440\u043C\u0438\u043D\u0430\u043B\u0430: \u043F\u0440\u043E\u0433\u0440\u0430\u043C\u043C\u0430 \u043E\u0431\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u044F \u043F\u0435\u0440\u0435\u0437\u0430\u043F\u0438\u0441\u044B\u0432\u0430\u0435\u0442 \u043E\u0431\u0449\u0435\u0435 \u043E\u043A\u0440\u0443\u0436\u0435\u043D\u0438\u0435 \u043D\u0430 \u043C\u0435\u0441\u0442\u0435 \u0438 \u043C\u043E\u0436\u0435\u0442 \u043F\u0440\u0435\u0440\u0432\u0430\u0442\u044C \u0441\u0435\u0441\u0441\u0438\u0438 \u043F\u043E\u0441\u0440\u0435\u0434\u0438 \u0445\u043E\u0434\u0430. \u0414\u0430\u043B\u044C\u0448\u0435 \u043E\u0431\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u044F\u043C\u0438 \u0437\u0430\u043D\u0438\u043C\u0430\u0435\u0442\u0441\u044F \u043F\u0440\u0438\u043B\u043E\u0436\u0435\u043D\u0438\u0435.",
  "ui.updates.service.global.app_owned.remedy": "\u042D\u0442\u043E\u0442 \u0441\u0435\u0440\u0432\u0435\u0440 \u0437\u0430\u043F\u0443\u0449\u0435\u043D \u0438\u0437 \u0441\u043E\u0431\u0441\u0442\u0432\u0435\u043D\u043D\u043E\u0433\u043E \u0443\u043F\u0440\u0430\u0432\u043B\u044F\u0435\u043C\u043E\u0433\u043E \u043E\u043A\u0440\u0443\u0436\u0435\u043D\u0438\u044F Local Operator, \u043A\u043E\u0442\u043E\u0440\u044B\u043C \u043D\u0435 \u0432\u043B\u0430\u0434\u0435\u0435\u0442 \u043D\u0438 \u043E\u0434\u0438\u043D \u043C\u0435\u043D\u0435\u0434\u0436\u0435\u0440 \u043F\u0430\u043A\u0435\u0442\u043E\u0432, \u043F\u043E\u044D\u0442\u043E\u043C\u0443 \u043A\u043E\u043C\u0430\u043D\u0434\u044B \u0434\u043B\u044F \u0442\u0435\u0440\u043C\u0438\u043D\u0430\u043B\u0430, \u043A\u043E\u0442\u043E\u0440\u0430\u044F \u043E\u0431\u043D\u043E\u0432\u0438\u043B\u0430 \u0431\u044B \u0435\u0433\u043E \u043F\u0440\u0430\u0432\u0438\u043B\u044C\u043D\u043E, \u043D\u0435 \u0441\u0443\u0449\u0435\u0441\u0442\u0432\u0443\u0435\u0442. \u041F\u0440\u0438\u043B\u043E\u0436\u0435\u043D\u0438\u0435 \u043C\u043E\u0436\u0435\u0442 \u043E\u0431\u043D\u043E\u0432\u043B\u044F\u0442\u044C \u0442\u043E\u043B\u044C\u043A\u043E \u0442\u043E\u0442 \u0441\u0435\u0440\u0432\u0435\u0440, \u043A\u043E\u0442\u043E\u0440\u044B\u0439 \u0437\u0430\u043F\u0443\u0441\u0442\u0438\u043B\u043E \u0441\u0430\u043C\u043E: \u043E\u0441\u0442\u0430\u043D\u043E\u0432\u0438\u0442\u0435 \u044D\u0442\u043E\u0442, \u0437\u0430\u0442\u0435\u043C \u0441\u043D\u043E\u0432\u0430 \u0437\u0430\u043F\u0443\u0441\u0442\u0438\u0442\u0435 Local Operator, \u0438 \u043F\u0440\u0438\u043B\u043E\u0436\u0435\u043D\u0438\u0435 \u0437\u0430\u043F\u0443\u0441\u0442\u0438\u0442 \u0441\u0432\u043E\u0439."
};

