  "ui.agentMessages.banner.read": "\u067E\u0691\u06BE\u06CC\u06BA \u06A9\u06C1 \u0627\u0633 \u06A9\u0627 \u06A9\u06CC\u0627 \u0645\u0637\u0644\u0628 \u06C1\u06D2",
  "ui.agentMessages.banner.hide": "\u062A\u0641\u0635\u06CC\u0644\u0627\u062A \u0686\u06BE\u067E\u0627\u0626\u06CC\u06BA",
