  "ui.agentMessages.banner.consent_unavailable": "\u0645\u06A9\u0645\u0644 \u0645\u062A\u0646 \u0627\u0628\u06BE\u06CC \u062F\u0633\u062A\u06CC\u0627\u0628 \u0646\u06C1\u06CC\u06BA\u06D4 \u06A9\u0686\u06BE \u062F\u06CC\u0631 \u0628\u0639\u062F \u062F\u0648\u0628\u0627\u0631\u06C1 \u06A9\u0648\u0634\u0634 \u06A9\u0631\u06CC\u06BA\u06D4",
  "ui.agentMessages.banner.turn_off_failed": "Team Bridge \u0628\u0646\u062F \u0646\u06C1\u06CC\u06BA \u06A9\u06CC\u0627 \u062C\u0627 \u0633\u06A9\u0627\u06D4 \u06A9\u0686\u06BE \u062A\u0628\u062F\u06CC\u0644 \u0646\u06C1\u06CC\u06BA \u06C1\u0648\u0627\u06D4 \u062F\u0648\u0628\u0627\u0631\u06C1 \u06A9\u0648\u0634\u0634 \u06A9\u0631\u06CC\u06BA\u06D4",
