  "ui.agentMessages.banner.turn_off_hint": "\u0627\u0633\u06D2 \u0628\u0646\u062F \u06A9\u0631\u0646\u06D2 \u0633\u06D2 \u0622\u067E \u06A9\u06CC Team Bridge \u06AF\u0641\u062A\u06AF\u0648\u0626\u06CC\u06BA \u0628\u06BE\u06CC \u0627\u0633 \u0648\u0642\u062A \u062A\u06A9 \u067E\u0648\u0634\u06CC\u062F\u06C1 \u0631\u06C1\u06CC\u06BA \u06AF\u06CC \u062C\u0628 \u062A\u06A9 \u0622\u067E \u0627\u0633\u06D2 \u062F\u0648\u0628\u0627\u0631\u06C1 \u0641\u0639\u0627\u0644 \u0646\u06C1\u06CC\u06BA \u06A9\u0631\u062A\u06D2\u06D4",
  "ui.agentMessages.page_off.title": "\u0627\u0633 \u0627\u06A9\u0627\u0624\u0646\u0679 \u06A9\u06D2 \u0644\u06CC\u06D2 Team Bridge \u0628\u0646\u062F \u06C1\u06D2",
  "ui.agentMessages.page_off.body": "\u0622\u067E \u06A9\u0627 \u0627\u06CC\u062C\u0646\u0679 \u0646\u06C1 \u067E\u06CC\u063A\u0627\u0645\u0627\u062A \u0628\u06BE\u06CC\u062C\u062A\u0627 \u06C1\u06D2 \u0646\u06C1 \u0648\u0635\u0648\u0644 \u06A9\u0631\u062A\u0627 \u06C1\u06D2\u060C \u0627\u0648\u0631 \u062C\u0628 \u062A\u06A9 \u0622\u067E \u0627\u0633\u06D2 \u062F\u0648\u0628\u0627\u0631\u06C1 \u0641\u0639\u0627\u0644 \u0646\u06C1\u06CC\u06BA \u06A9\u0631\u062A\u06D2 \u0622\u067E \u06A9\u06CC \u06AF\u0641\u062A\u06AF\u0648\u0626\u06CC\u06BA \u067E\u0648\u0634\u06CC\u062F\u06C1 \u0631\u06C1\u062A\u06CC \u06C1\u06CC\u06BA\u06D4 \u0641\u0639\u0627\u0644 \u06A9\u0631\u0646\u06D2 \u067E\u0631 \u067E\u06C1\u0644\u06D2 \u0622\u067E \u0633\u06D2 \u0631\u0636\u0627\u0645\u0646\u062F\u06CC \u0637\u0644\u0628 \u06A9\u06CC \u062C\u0627\u062A\u06CC \u06C1\u06D2\u06D4",
  "ui.agentMessages.page_off.local_title": "\u0627\u0633 \u0645\u0634\u06CC\u0646 \u067E\u0631 Team Bridge \u0628\u0646\u062F \u06C1\u06D2",
  "ui.agentMessages.page_off.local_body": "\u0622\u067E \u06A9\u0627 \u0627\u06A9\u0627\u0624\u0646\u0679 \u0627\u0628 \u0628\u06BE\u06CC \u0633\u06CC\u0679 \u0627\u067E \u06C1\u06D2\u060C \u0644\u06CC\u06A9\u0646 \u06CC\u06C1 \u0645\u0634\u06CC\u0646 \u0646\u06C1 \u067E\u06CC\u063A\u0627\u0645\u0627\u062A \u0628\u06BE\u06CC\u062C\u062A\u06CC \u06C1\u06D2 \u0646\u06C1 \u0648\u0635\u0648\u0644 \u06A9\u0631\u062A\u06CC \u06C1\u06D2\u060C \u0627\u0648\u0631 \u062C\u0628 \u062A\u06A9 \u0622\u067E \u0627\u0633\u06D2 \u062F\u0648\u0628\u0627\u0631\u06C1 \u0641\u0639\u0627\u0644 \u0646\u06C1\u06CC\u06BA \u06A9\u0631\u062A\u06D2 \u0622\u067E \u06A9\u06CC \u06AF\u0641\u062A\u06AF\u0648\u0626\u06CC\u06BA \u06CC\u06C1\u0627\u06BA \u067E\u0648\u0634\u06CC\u062F\u06C1 \u0631\u06C1\u062A\u06CC \u06C1\u06CC\u06BA\u06D4",
  "ui.agentMessages.page_off.action": "\u062A\u0631\u062A\u06CC\u0628\u0627\u062A \u06A9\u06BE\u0648\u0644\u06CC\u06BA"
