  "ui.agentMessages.settings.default_on.b_body": "\u0622\u067E \u06A9\u06CC \u062A\u0646\u0638\u06CC\u0645 \u062A\u06CC\u0627\u0631 \u06C1\u0648\u062A\u06D2 \u06C1\u06CC Team Bridge \u0622\u067E \u06A9\u06D2 \u0644\u06CC\u06D2 \u062E\u0648\u062F\u06A9\u0627\u0631 \u0637\u0648\u0631 \u067E\u0631 \u0641\u0639\u0627\u0644 \u06C1\u0648 \u062C\u0627\u0626\u06D2 \u06AF\u0627\u06D4 \u0641\u0639\u0627\u0644 \u06C1\u0648\u0646\u06D2 \u067E\u0631 \u06A9\u0686\u06BE \u0646\u06C1\u06CC\u06BA \u0628\u06BE\u06CC\u062C\u0627 \u062C\u0627\u062A\u0627\u06D4",
  "ui.agentMessages.settings.default_on.e_body": "\u0627\u0633 \u0627\u06A9\u0627\u0624\u0646\u0679 \u06A9\u06D2 \u0644\u06CC\u06D2 Team Bridge \u0628\u0646\u062F \u06C1\u06D2\u06D4 \u0646\u06CC\u0686\u06D2 \u0631\u0636\u0627\u0645\u0646\u062F\u06CC \u06A9\u0627 \u0645\u062A\u0646 \u067E\u0691\u06BE\u06CC\u06BA\u060C \u067E\u06BE\u0631 \u0627\u06AF\u0631 \u0622\u067E \u0627\u0633\u06D2 \u0648\u0627\u067E\u0633 \u0686\u0627\u06C1\u062A\u06D2 \u06C1\u06CC\u06BA \u062A\u0648 \u062F\u0648\u0628\u0627\u0631\u06C1 \u0641\u0639\u0627\u0644 \u06A9\u0631\u06CC\u06BA\u06D4",
  "ui.agentMessages.settings.action.turn_on_again": "\u062F\u0648\u0628\u0627\u0631\u06C1 \u0641\u0639\u0627\u0644 \u06A9\u0631\u06CC\u06BA",
  "ui.agentMessages.settings.consent.via_default_on": "\u0688\u06CC\u0641\u0627\u0644\u0679 \u0637\u0648\u0631 \u067E\u0631 \u0641\u0639\u0627\u0644",
  "ui.agentMessages.settings.share_typing.label": "\u0645\u06CC\u0631\u06D2 \u0679\u0627\u0626\u067E \u06A9\u0631\u0646\u06D2 \u06A9\u06CC \u0627\u0637\u0644\u0627\u0639 \u062F\u06A9\u06BE\u0627\u0626\u06CC\u06BA",
  "ui.agentMessages.settings.share_typing.description": "\u0622\u067E \u06A9\u06CC Team Bridge \u06AF\u0641\u062A\u06AF\u0648 \u0645\u06CC\u06BA \u0634\u0627\u0645\u0644 \u0644\u0648\u06AF \u0622\u067E \u06A9\u06D2 \u0644\u06A9\u06BE\u062A\u06D2 \u0648\u0642\u062A \u0627\u06CC\u06A9 \u0645\u062E\u062A\u0635\u0631 \u201C\u0679\u0627\u0626\u067E \u06A9\u0631 \u0631\u06C1\u06D2 \u06C1\u06CC\u06BA\u201D \u0644\u0627\u0626\u0646 \u062F\u06CC\u06A9\u06BE\u062A\u06D2 \u06C1\u06CC\u06BA\u06D4 \u0622\u067E \u062C\u0648 \u0644\u06A9\u06BE\u062A\u06D2 \u06C1\u06CC\u06BA \u0648\u06C1 \u06A9\u0628\u06BE\u06CC \u0634\u06CC\u0626\u0631 \u0646\u06C1\u06CC\u06BA \u06C1\u0648\u062A\u0627\u06D4"
