  "ui.agents.config.state.stopping": "\u0631\u0648\u06A9\u0627 \u062C\u0627 \u0631\u06C1\u0627 \u06C1\u06D2\u2026",
  "ui.agents.config.status.attached": "\u0627\u06CC\u06A9 \u0627\u0648\u0631 \u06A9\u0646\u0641\u06CC\u06AF\u0631\u06CC\u0634\u0646 \u0631\u0646 \u067E\u06C1\u0644\u06D2 \u0633\u06D2 \u062C\u0627\u0631\u06CC \u062A\u06BE\u0627\u060C \u0627\u0633 \u0644\u06CC\u06D2 \u06CC\u06C1 \u0635\u0641\u062D\u06C1 \u0627\u0633\u06CC \u0633\u06D2 \u0645\u0646\u0633\u0644\u06A9 \u06C1\u0648 \u06AF\u06CC\u0627\u06D4 \u0622\u067E \u06A9\u06CC \u062F\u0631\u062E\u0648\u0627\u0633\u062A \u0646\u06C1\u06CC\u06BA \u0628\u06BE\u06CC\u062C\u06CC \u06AF\u0626\u06CC \u2014 \u0648\u06C1 \u0627\u0628\u06BE\u06CC \u062E\u0627\u0646\u06D2 \u0645\u06CC\u06BA \u06C1\u06D2\u06D4",
  "ui.agents.config.stopped.kept": "\u0631\u0648\u06A9 \u062F\u06CC\u0627 \u06AF\u06CC\u0627\u06D4 \u0627\u0633 \u06A9\u06CC \u067E\u06C1\u0644\u06D2 \u06A9\u06CC \u06AF\u0626\u06CC \u062A\u0628\u062F\u06CC\u0644\u06CC\u0627\u06BA \u0628\u0631\u0642\u0631\u0627\u0631 \u0631\u06A9\u06BE\u06CC \u06AF\u0626\u06CC\u06BA\u06D4",
  "ui.agents.config.stopped.nothing": "\u0631\u0648\u06A9 \u062F\u06CC\u0627 \u06AF\u06CC\u0627\u06D4 \u0627\u0628\u06BE\u06CC \u06A9\u0686\u06BE \u0646\u06C1\u06CC\u06BA \u0628\u062F\u0644\u0627 \u06AF\u06CC\u0627 \u062A\u06BE\u0627\u06D4",
  "ui.agents.config.summary.created": "\u0628\u0646\u0627\u06CC\u0627 \u06AF\u06CC\u0627 {name}",
  "ui.agents.config.summary.hidden_changes": "\u0627\u0633 \u06A9\u06CC \u062A\u0631\u062A\u06CC\u0628\u0627\u062A \u0628\u062F\u0644 \u06AF\u0626\u06CC\u06BA\u06D4 \u0641\u06C1\u0631\u0633\u062A \u06C1\u062F\u0627\u06CC\u0627\u062A \u0646\u06C1\u06CC\u06BA \u062F\u06A9\u06BE\u0627\u062A\u06CC\u060C \u0627\u0633 \u0644\u06CC\u06D2 \u062C\u0648 \u06A9\u0686\u06BE \u0644\u06A9\u06BE\u0627 \u06AF\u06CC\u0627 \u06C1\u06D2 \u0648\u06C1 \u062F\u06CC\u06A9\u06BE\u0646\u06D2 \u06A9\u06D2 \u0644\u06CC\u06D2 \u0627\u0633\u06D2 \u06A9\u06BE\u0648\u0644\u06CC\u06BA\u06D4",
  "ui.agents.config.summary.no_changes": "\u0631\u0646 \u0646\u06D2 \u06A9\u0633\u06CC \u0627\u06CC\u062C\u0646\u0679 \u06CC\u0627 \u0679\u06CC\u0645 \u06A9\u0648 \u0628\u062F\u0644\u06D2 \u0628\u063A\u06CC\u0631 \u062C\u0648\u0627\u0628 \u062F\u06CC\u0627\u06D4",
  "ui.agents.config.summary.nothing_else": "\u0627\u0633 \u0631\u0646 \u0646\u06D2 \u0627\u0648\u0631 \u06A9\u0686\u06BE \u0646\u06C1\u06CC\u06BA \u0628\u062F\u0644\u0627\u06D4",
  "ui.agents.config.summary.updated": "\u0627\u067E \u0688\u06CC\u0679 \u06A9\u06CC\u0627 \u06AF\u06CC\u0627 {name}",
  "ui.agents.config.summary.you_asked": "\u0622\u067E \u06A9\u06CC \u062F\u0631\u062E\u0648\u0627\u0633\u062A: {topic}",
  "ui.agents.config.banner.unavailable": "\u0628\u06CC\u06A9 \u0627\u06CC\u0646\u0688 \u062A\u06A9 \u0631\u0633\u0627\u0626\u06CC \u0646\u06C1\u06CC\u06BA \u06C1\u0648 \u0633\u06A9\u06CC\u060C \u0627\u0633 \u0644\u06CC\u06D2 \u06A9\u0645\u067E\u0648\u0632\u0631 \u0641\u06CC \u0627\u0644\u062D\u0627\u0644 \u062F\u0633\u062A\u06CC\u0627\u0628 \u0646\u06C1\u06CC\u06BA \u06C1\u06D2\u06D4",
  "ui.agents.config.disabled_gate": "\u0627\u06CC\u062C\u0646\u0679\u0633 \u06A9\u06CC \u062A\u0631\u062A\u06CC\u0628 \u06AF\u0641\u062A\u06AF\u0648 \u06A9\u06D2 \u0630\u0631\u06CC\u0639\u06D2 \u06C1\u0648\u062A\u06CC \u06C1\u06D2",
