  "ui.agents.publication.category.mass_surveillance_or_privacy_abuse": "\u0644\u0648\u06AF\u0648\u06BA \u06A9\u06CC \u0631\u0636\u0627\u0645\u0646\u062F\u06CC \u06A9\u06D2 \u0628\u063A\u06CC\u0631 \u0627\u0646 \u06A9\u06CC \u0646\u06AF\u0631\u0627\u0646\u06CC \u06CC\u0627 \u067E\u0631\u0648\u0641\u0627\u0626\u0644\u0646\u06AF \u06A9\u06CC \u06C1\u062F\u0627\u06CC\u0627\u062A \u0634\u0627\u0626\u0639 \u0646\u06C1\u06CC\u06BA \u06A9\u06CC \u062C\u0627 \u0633\u06A9\u062A\u06CC\u06BA\u06D4",
  "ui.agents.publication.category.other_harmful": "\u06CC\u06C1 \u0627\u06CC\u062C\u0646\u0679 \u0645\u0633\u062A\u0631\u062F \u06A9\u0631 \u062F\u06CC\u0627 \u06AF\u06CC\u0627 \u06A9\u06CC\u0648\u0646\u06A9\u06C1 \u0627\u0633 \u06A9\u06CC \u06C1\u062F\u0627\u06CC\u0627\u062A \u0646\u0642\u0635\u0627\u0646 \u067E\u06C1\u0646\u0686\u0627\u0626\u06CC\u06BA \u06AF\u06CC\u06D4",
  "ui.agents.publication.category.prompt_injection": "\u06CC\u06C1 \u06C1\u062F\u0627\u06CC\u0627\u062A \u06A9\u0627 \u0645\u062C\u0645\u0648\u0639\u06C1 \u0627\u06CC\u062C\u0646\u0679 \u06A9\u0648 \u0628\u06CC\u0627\u0646 \u06A9\u0631\u0646\u06D2 \u06A9\u06D2 \u0628\u062C\u0627\u0626\u06D2 \u062C\u0627\u0626\u0632\u06C1 \u0644\u06CC\u0646\u06D2 \u0648\u0627\u0644\u06D2 \u06A9\u0648 \u06C1\u062F\u0627\u06CC\u062A \u062F\u06CC\u0646\u06D2 \u06A9\u06CC \u06A9\u0648\u0634\u0634 \u06A9\u0631\u062A\u0627 \u06C1\u06D2\u060C \u0627\u0633 \u0644\u06CC\u06D2 \u06CC\u06C1 \u0634\u0627\u0626\u0639 \u0646\u06C1\u06CC\u06BA \u06C1\u0648 \u0633\u06A9\u062A\u0627\u06D4",
  "ui.agents.publication.category.self_harm": "\u06CC\u06C1 \u0627\u06CC\u062C\u0646\u0679 \u0634\u0627\u0626\u0639 \u0646\u06C1\u06CC\u06BA \u06C1\u0648 \u0633\u06A9\u062A\u0627\u06D4 \u0627\u06AF\u0631 \u0622\u067E \u06A9\u06D2 \u062E\u06CC\u0627\u0644 \u0645\u06CC\u06BA \u06CC\u06C1 \u063A\u0644\u0637\u06CC \u06C1\u06D2 \u062A\u0648 \u0645\u0639\u0627\u0648\u0646\u062A \u0633\u06D2 \u0631\u0627\u0628\u0637\u06C1 \u06A9\u0631\u06CC\u06BA\u06D4",
  "ui.agents.publication.category.sexual_content": "\u0635\u0631\u06CC\u062D \u062C\u0646\u0633\u06CC \u0645\u0648\u0627\u062F \u0634\u0627\u0626\u0639 \u0646\u06C1\u06CC\u06BA \u06A9\u06CC\u0627 \u062C\u0627 \u0633\u06A9\u062A\u0627\u06D4",
  "ui.agents.publication.category.sexual_content_minors": "\u06CC\u06C1 \u0627\u06CC\u062C\u0646\u0679 \u0634\u0627\u0626\u0639 \u0646\u06C1\u06CC\u06BA \u06C1\u0648 \u0633\u06A9\u062A\u0627\u06D4 \u0627\u06AF\u0631 \u0622\u067E \u06A9\u06D2 \u062E\u06CC\u0627\u0644 \u0645\u06CC\u06BA \u06CC\u06C1 \u063A\u0644\u0637\u06CC \u06C1\u06D2 \u062A\u0648 \u0645\u0639\u0627\u0648\u0646\u062A \u0633\u06D2 \u0631\u0627\u0628\u0637\u06C1 \u06A9\u0631\u06CC\u06BA\u06D4",
  "ui.agents.publication.category.unclear_dual_use": "\u06C1\u0645 \u06CC\u06C1 \u0646\u06C1\u06CC\u06BA \u062C\u0627\u0646 \u0633\u06A9\u06D2 \u06A9\u06C1 \u06CC\u06C1 \u0622\u067E \u06A9\u06D2 \u0627\u067E\u0646\u06D2 \u0646\u0638\u0627\u0645\u0648\u06BA \u06A9\u06D2 \u0644\u06CC\u06D2 \u06C1\u06D2 \u06CC\u0627 \u06A9\u0633\u06CC \u0627\u0648\u0631 \u06A9\u06D2\u06D4 \u062F\u0627\u0626\u0631\u06C1 \u0627\u0648\u0631 \u06C1\u062F\u0641 \u0648\u0627\u0636\u062D \u06A9\u0631\u0646\u06D2 \u06A9\u06D2 \u0644\u06CC\u06D2 \u0627\u06CC\u06A9 \u062C\u0645\u0644\u06C1 \u0634\u0627\u0645\u0644 \u06A9\u0631\u06CC\u06BA\u060C \u067E\u06BE\u0631 \u062F\u0648\u0628\u0627\u0631\u06C1 \u0634\u0627\u0626\u0639 \u06A9\u0631\u06CC\u06BA\u06D4",
  "ui.agents.publication.category.violence_or_weapons": "\u06C1\u062A\u06BE\u06CC\u0627\u0631 \u0628\u0646\u0627\u0646\u06D2 \u06CC\u0627 \u0644\u0648\u06AF\u0648\u06BA \u06A9\u0648 \u0632\u062E\u0645\u06CC \u06A9\u0631\u0646\u06D2 \u06A9\u06CC \u06C1\u062F\u0627\u06CC\u0627\u062A \u0634\u0627\u0626\u0639 \u0646\u06C1\u06CC\u06BA \u06A9\u06CC \u062C\u0627 \u0633\u06A9\u062A\u06CC\u06BA\u06D4",
  "ui.agents.publication.fallback.headline": "\u06CC\u06C1 \u0627\u06CC\u062C\u0646\u0679 \u0634\u0627\u0626\u0639 \u0646\u06C1\u06CC\u06BA \u06C1\u0648 \u0633\u06A9\u0627",
  "ui.agents.publication.hub_unauthorized.body": "\u06A9\u0686\u06BE \u0628\u06BE\u06CC \u0634\u0627\u0626\u0639 \u0646\u06C1\u06CC\u06BA \u06C1\u0648\u0627\u06D4 \u06C1\u0628 \u0646\u06D2 \u062C\u0648 \u0627\u0633\u0646\u0627\u062F \u0645\u0633\u062A\u0631\u062F \u06A9\u06CC\u06BA\u060C \u0627\u0646\u06C1\u06CC\u06BA \u0628\u062F\u0644\u0646\u06D2 \u06A9\u06D2 \u0644\u06CC\u06D2 Radient \u0645\u06CC\u06BA \u062F\u0648\u0628\u0627\u0631\u06C1 \u0633\u0627\u0626\u0646 \u0627\u0646 \u06A9\u0631\u06CC\u06BA\u060C \u067E\u06BE\u0631 \u0634\u0627\u0626\u0639 \u06A9\u0631\u06CC\u06BA\u06D4",
  "ui.agents.publication.hub_unauthorized.body_pull": "\u06A9\u0686\u06BE \u0628\u06BE\u06CC pull \u0646\u06C1\u06CC\u06BA \u06C1\u0648\u0627\u06D4 \u06C1\u0628 \u0646\u06D2 \u062C\u0648 \u0627\u0633\u0646\u0627\u062F \u0645\u0633\u062A\u0631\u062F \u06A9\u06CC\u06BA\u060C \u0627\u0646\u06C1\u06CC\u06BA \u0628\u062F\u0644\u0646\u06D2 \u06A9\u06D2 \u0644\u06CC\u06D2 Radient \u0645\u06CC\u06BA \u062F\u0648\u0628\u0627\u0631\u06C1 \u0633\u0627\u0626\u0646 \u0627\u0646 \u06A9\u0631\u06CC\u06BA\u060C \u067E\u06BE\u0631 pull \u06A9\u0631\u06CC\u06BA\u06D4",
  "ui.agents.publication.hub_unauthorized.headline": "\u06C1\u0628 \u0646\u06D2 \u0627\u0633 \u0645\u0634\u06CC\u0646 \u06A9\u0627 \u0633\u0627\u0626\u0646 \u0627\u0646 \u0645\u0633\u062A\u0631\u062F \u06A9\u0631 \u062F\u06CC\u0627",
  "ui.agents.publication.hub_unavailable.body": "\u06A9\u0686\u06BE \u0628\u06BE\u06CC \u0634\u0627\u0626\u0639 \u0646\u06C1\u06CC\u06BA \u06C1\u0648\u0627\u06D4 \u062A\u06BE\u0648\u0691\u06CC \u062F\u06CC\u0631 \u0628\u0639\u062F \u062F\u0648\u0628\u0627\u0631\u06C1 \u06A9\u0648\u0634\u0634 \u06A9\u0631\u06CC\u06BA\u060C \u06CC\u0627 \u0627\u06AF\u0631 \u06C1\u0628 \u06A9\u0627 \u067E\u062A\u06C1 \u0628\u062F\u0644 \u06AF\u06CC\u0627 \u06C1\u0648 \u062A\u0648 \u0628\u06CC\u06A9 \u0627\u06CC\u0646\u0688 \u0627\u067E \u0688\u06CC\u0679 \u06A9\u0631\u06CC\u06BA\u06D4",
  "ui.agents.publication.hub_unavailable.body_pull": "\u06A9\u0686\u06BE \u0628\u06BE\u06CC pull \u0646\u06C1\u06CC\u06BA \u06C1\u0648\u0627\u06D4 \u062A\u06BE\u0648\u0691\u06CC \u062F\u06CC\u0631 \u0628\u0639\u062F \u062F\u0648\u0628\u0627\u0631\u06C1 \u06A9\u0648\u0634\u0634 \u06A9\u0631\u06CC\u06BA\u060C \u06CC\u0627 \u0627\u06AF\u0631 \u06C1\u0628 \u06A9\u0627 \u067E\u062A\u06C1 \u0628\u062F\u0644 \u06AF\u06CC\u0627 \u06C1\u0648 \u062A\u0648 \u0628\u06CC\u06A9 \u0627\u06CC\u0646\u0688 \u0627\u067E \u0688\u06CC\u0679 \u06A9\u0631\u06CC\u06BA\u06D4",
  "ui.agents.publication.hub_unavailable.headline": "\u0627\u0634\u0627\u0639\u062A \u0645\u06A9\u0645\u0644 \u0646\u06C1\u06CC\u06BA \u06C1\u0648 \u0633\u06A9\u06CC",
