  "ui.agents.publication.insufficient_role.body_pull": "\u062A\u0646\u0638\u06CC\u0645 \u06A9\u06CC \u0679\u06CC\u0645\u06CC\u06BA \u067E\u0691\u06BE\u0646\u06D2 \u06A9\u06D2 \u0644\u06CC\u06D2 \u0622\u067E \u06A9\u06D2 \u0639\u06C1\u062F\u06D2 \u0633\u06D2 \u0627\u0648\u0646\u0686\u0627 \u0639\u06C1\u062F\u06C1 \u062F\u0631\u06A9\u0627\u0631 \u06C1\u06D2\u06D4 \u062A\u0646\u0638\u06CC\u0645 \u06A9\u06D2 \u0645\u0627\u0644\u06A9 \u0633\u06D2 \u06A9\u06C1\u06CC\u06BA \u06A9\u06C1 \u0648\u06C1 \u0622\u067E \u06A9\u0627 \u0639\u06C1\u062F\u06C1 \u0628\u062F\u0644 \u062F\u06CC\u06BA\u060C \u067E\u06BE\u0631 \u062F\u0648\u0628\u0627\u0631\u06C1 pull \u06A9\u0631\u06CC\u06BA\u06D4",
  "ui.agents.publication.insufficient_role.body_with_role": "\u062A\u0646\u0638\u06CC\u0645 \u0645\u06CC\u06BA \u0634\u0627\u0626\u0639 \u06A9\u0631\u0646\u06D2 \u06A9\u06D2 \u0644\u06CC\u06D2 {required} \u0639\u06C1\u062F\u06C1 \u062F\u0631\u06A9\u0627\u0631 \u06C1\u06D2\u06D4 \u062A\u0646\u0638\u06CC\u0645 \u06A9\u06D2 \u0645\u0627\u0644\u06A9 \u0633\u06D2 \u06A9\u06C1\u06CC\u06BA \u06A9\u06C1 \u0648\u06C1 \u0622\u067E \u06A9\u0627 \u0639\u06C1\u062F\u06C1 \u0628\u062F\u0644 \u062F\u06CC\u06BA\u060C \u067E\u06BE\u0631 \u062F\u0648\u0628\u0627\u0631\u06C1 \u0634\u0627\u0626\u0639 \u06A9\u0631\u06CC\u06BA\u06D4",
  "ui.agents.publication.insufficient_role.body_with_role_pull": "\u062A\u0646\u0638\u06CC\u0645 \u06A9\u06CC \u0679\u06CC\u0645\u06CC\u06BA \u067E\u0691\u06BE\u0646\u06D2 \u06A9\u06D2 \u0644\u06CC\u06D2 {required} \u0639\u06C1\u062F\u06C1 \u062F\u0631\u06A9\u0627\u0631 \u06C1\u06D2\u06D4 \u062A\u0646\u0638\u06CC\u0645 \u06A9\u06D2 \u0645\u0627\u0644\u06A9 \u0633\u06D2 \u06A9\u06C1\u06CC\u06BA \u06A9\u06C1 \u0648\u06C1 \u0622\u067E \u06A9\u0627 \u0639\u06C1\u062F\u06C1 \u0628\u062F\u0644 \u062F\u06CC\u06BA\u060C \u067E\u06BE\u0631 \u062F\u0648\u0628\u0627\u0631\u06C1 pull \u06A9\u0631\u06CC\u06BA\u06D4",
