var ui_agents_refusals_default6 = {
  "ui.agents.refusals.name_taken": "\u201C{name}\u201D \u0646\u0627\u0645 \u06A9\u0627 \u0627\u06CC\u062C\u0646\u0679 \u067E\u06C1\u0644\u06D2 \u0633\u06D2 \u0645\u0648\u062C\u0648\u062F \u06C1\u06D2\u06D4 \u062F\u0648\u0633\u0631\u0627 \u0646\u0627\u0645 \u0645\u0646\u062A\u062E\u0628 \u06A9\u0631\u06CC\u06BA \u06CC\u0627 \u0645\u0648\u062C\u0648\u062F\u06C1 \u0627\u06CC\u062C\u0646\u0679 \u06A9\u06BE\u0648\u0644 \u06A9\u0631 \u0627\u0633\u06D2 \u0628\u062F\u0644\u06CC\u06BA\u06D4",
  "ui.agents.refusals.name_grammar": "\u0646\u0627\u0645\u0648\u06BA \u0645\u06CC\u06BA \u062E\u0627\u0644\u06CC \u062C\u06AF\u06C1 \u06CC\u0627 \u0633\u0644\u06CC\u0634 \u0646\u06C1\u06CC\u06BA \u06C1\u0648 \u0633\u06A9\u062A\u06D2\u06D4",
  "ui.agents.refusals.effort_unavailable": "\u201C{tier}\u201D \u06A9\u0648\u0634\u0634 \u06A9\u0627 \u062A\u0631\u062A\u06CC\u0628 \u0634\u062F\u06C1 \u062F\u0631\u062C\u06C1 \u0646\u06C1\u06CC\u06BA\u06D4 inherit \u0627\u0633\u062A\u0639\u0645\u0627\u0644 \u06A9\u0631\u06CC\u06BA \u06CC\u0627 \u062A\u0631\u062A\u06CC\u0628\u0627\u062A \u0645\u06CC\u06BA \u062F\u0631\u062C\u06C1 \u0634\u0627\u0645\u0644 \u06A9\u0631\u06CC\u06BA\u06D4",
  "ui.agents.refusals.team_name_bound": "\u0679\u06CC\u0645 \u06A9\u0627 \u0646\u0627\u0645 1-64 \u062D\u0631\u0648\u0641 \u06A9\u0627 \u06C1\u0648\u062A\u0627 \u06C1\u06D2\u06D4",
  "ui.agents.refusals.missing_manager": "\u201C{name}\u201D \u0627\u0633 \u0645\u0634\u06CC\u0646 \u067E\u0631 \u06A9\u0648\u0626\u06CC \u0627\u06CC\u062C\u0646\u0679 \u06CC\u0627 \u0679\u06CC\u0645 \u0646\u06C1\u06CC\u06BA \u06C1\u06D2\u06D4",
  "ui.agents.refusals.missing_member": "\u201C{name}\u201D \u0627\u0633 \u0645\u0634\u06CC\u0646 \u067E\u0631 \u06A9\u0648\u0626\u06CC \u0627\u06CC\u062C\u0646\u0679 \u06CC\u0627 \u0679\u06CC\u0645 \u0646\u06C1\u06CC\u06BA \u06C1\u06D2\u06D4",
  "ui.agents.refusals.team_nesting": "\u0648\u06C1 \u0679\u06CC\u0645 \u0628\u06C1\u062A \u0632\u06CC\u0627\u062F\u06C1 \u0627\u0646\u062F\u0631\u0648\u0646\u06CC \u0633\u0637\u062D\u06CC\u06BA \u0628\u0646\u0627\u0626\u06D2 \u06AF\u06CC \u06CC\u0627 \u062E\u0648\u062F \u06A9\u0648 \u0634\u0627\u0645\u0644 \u06A9\u0631\u06D2 \u06AF\u06CC\u06D4 \u0627\u0633 \u06A9\u06D2 \u0627\u0631\u06A9\u0627\u0646 \u062C\u0627\u0646\u0686\u06CC\u06BA\u06D4",
  "ui.agents.refusals.class.label.proactive": "\u067E\u06CC\u0634 \u0642\u062F\u0645",
  "ui.agents.refusals.class.label.reactive": "\u062C\u0648\u0627\u0628\u06CC",
  "ui.agents.refusals.class.meaning.proactive": "\u06CC\u06C1 \u062E\u0648\u062F \u0622\u067E \u06A9\u0648 \u067E\u06CC\u063A\u0627\u0645 \u0628\u06BE\u06CC\u062C \u0633\u06A9\u062A\u0627 \u06C1\u06D2\u061B \u06A9\u0686\u06BE \u0628\u06BE\u06CC\u062C\u0646\u06D2 \u06A9\u06D2 \u0628\u0639\u062F \u062C\u0648\u0627\u0628 \u06A9\u06D2 \u0644\u06CC\u06D2 \u0686\u0646\u062F \u0645\u0646\u0679 \u0627\u0646\u062A\u0638\u0627\u0631 \u06A9\u0631\u062A\u0627 \u06C1\u06D2\u060C \u067E\u06BE\u0631 \u0645\u0642\u0631\u0631\u06C1 \u062A\u0639\u062F\u0627\u062F \u062A\u06A9 \u0628\u0691\u06BE\u062A\u06D2 \u0648\u0642\u0641\u0648\u06BA \u0633\u06D2 \u062F\u0648\u0628\u0627\u0631\u06C1 \u06CC\u0627\u062F \u062F\u0644\u0627\u062A\u0627 \u06C1\u06D2\u060C \u0627\u0633 \u06A9\u06D2 \u0628\u0639\u062F \u0622\u067E \u06A9\u0627 \u0627\u0646\u062A\u0638\u0627\u0631 \u06A9\u0631\u062A\u0627 \u06C1\u06D2 \u2014 \u0627\u0648\u0631 \u0627\u067E\u0646\u06D2 \u0634\u06CC\u0688\u0648\u0644 \u067E\u0631 \u0628\u06BE\u06CC \u062C\u0627\u06AF \u0633\u06A9\u062A\u0627 \u06C1\u06D2\u06D4",
  "ui.agents.refusals.class.meaning.reactive": "\u062C\u0628 \u0622\u067E \u0627\u0633\u06D2 \u0644\u06A9\u06BE\u062A\u06D2 \u06C1\u06CC\u06BA \u062A\u0648 \u06CC\u06C1 \u062C\u0648\u0627\u0628 \u062F\u06CC\u062A\u0627 \u06C1\u06D2\u06D4 \u06CC\u06C1 \u0622\u067E \u06A9\u0648 \u06CC\u0627\u062F \u062F\u06C1\u0627\u0646\u06CC \u0646\u06C1\u06CC\u06BA \u0628\u06BE\u06CC\u062C\u062A\u0627 \u0627\u0648\u0631 \u0627\u067E\u0646\u06D2 \u0634\u06CC\u0688\u0648\u0644 \u067E\u0631 \u0646\u06C1\u06CC\u06BA \u062C\u0627\u06AF\u062A\u0627\u06D4",
  "ui.agents.refusals.class.effect.proactive": "\u0627\u0633\u06D2 \u0628\u0646\u062F \u06A9\u0631\u0646\u06D2 \u0633\u06D2 \u06CC\u0627\u062F \u062F\u06C1\u0627\u0646\u06CC\u0627\u06BA \u0627\u0648\u0631 \u0634\u06CC\u0688\u0648\u0644 \u06A9\u06CC \u0628\u06CC\u062F\u0627\u0631\u06CC\u0627\u06BA \u0631\u06A9 \u062C\u0627\u062A\u06CC \u06C1\u06CC\u06BA\u06D4 \u0622\u067E \u0644\u06A9\u06BE\u06CC\u06BA \u062A\u0648 \u06CC\u06C1 \u0627\u0628 \u0628\u06BE\u06CC \u062C\u0648\u0627\u0628 \u062F\u06CC\u062A\u0627 \u06C1\u06D2\u06D4",
  "ui.agents.refusals.class.effect.reactive": "\u0627\u0633\u06D2 \u0641\u0639\u0627\u0644 \u06A9\u0631\u0646\u06D2 \u0633\u06D2 \u06CC\u06C1 \u067E\u06C1\u0644\u06D2 \u0644\u06A9\u06BE \u0633\u06A9\u062A\u0627 \u06C1\u06D2\u061B \u0622\u067E \u06A9\u06D2 \u062C\u0648\u0627\u0628 \u06A9\u06D2 \u0644\u06CC\u06D2 \u0686\u0646\u062F \u0645\u0646\u0679 \u0627\u0646\u062A\u0638\u0627\u0631 \u06A9\u0631\u06D2 \u06AF\u0627\u060C \u0645\u0642\u0631\u0631\u06C1 \u062A\u0639\u062F\u0627\u062F \u062A\u06A9 \u062F\u0648\u0628\u0627\u0631\u06C1 \u06CC\u0627\u062F \u062F\u0644\u0627\u0626\u06D2 \u06AF\u0627 \u0627\u0648\u0631 \u0627\u067E\u0646\u06D2 \u0634\u06CC\u0688\u0648\u0644 \u067E\u0631 \u0628\u06BE\u06CC \u062C\u0627\u06AF \u0633\u06A9\u062A\u0627 \u06C1\u06D2\u06D4 \u0622\u067E \u0644\u06A9\u06BE\u06CC\u06BA \u062A\u0648 \u06CC\u06C1 \u0627\u0628 \u0628\u06BE\u06CC \u062C\u0648\u0627\u0628 \u062F\u06CC\u062A\u0627 \u06C1\u06D2\u06D4",
  "ui.agents.refusals.class.install_disclosure": "\u06CC\u06C1 \u0627\u06CC\u067E \u06A9\u06D2 \u0633\u0627\u062A\u06BE \u0622\u062A\u0627 \u06C1\u06D2 \u0627\u0648\u0631 \u0627\u0628\u06BE\u06CC \u0627\u0633 \u06A9\u06CC \u0627\u067E\u0646\u06CC \u0646\u0642\u0644 \u0646\u06C1\u06CC\u06BA\u060C \u0627\u0633 \u0644\u06CC\u06D2 \u062A\u0628\u062F\u06CC\u0644\u06CC \u0633\u06D2 \u067E\u06C1\u0644\u06D2 \u0627\u0633\u06D2 \u0627\u0646\u0633\u0679\u0627\u0644 \u06A9\u06CC\u0627 \u062C\u0627\u062A\u0627 \u06C1\u06D2 \u2014 \u0648\u06C1\u06CC \u0627\u06CC\u062C\u0646\u0679 \u0627\u0648\u0631 \u0648\u06C1\u06CC \u06C1\u062F\u0627\u06CC\u0627\u062A\u060C \u0627\u0628 \u0642\u0627\u0628\u0644 \u062A\u0631\u0645\u06CC\u0645 \u2014 \u067E\u06BE\u0631 \u0627\u0633 \u06A9\u06CC \u0642\u0633\u0645 \u0645\u0642\u0631\u0631 \u06C1\u0648\u062A\u06CC \u06C1\u06D2\u06D4",
  "ui.agents.refusals.class.error.no_reason": "\u0628\u06CC\u06A9 \u0627\u06CC\u0646\u0688 \u0646\u06D2 \u0627\u0633 \u06A9\u06CC \u06A9\u0648\u0626\u06CC \u0648\u062C\u06C1 \u0646\u06C1\u06CC\u06BA \u0628\u062A\u0627\u0626\u06CC\u06D4 \u062F\u0648\u0628\u0627\u0631\u06C1 \u062A\u0628\u062F\u06CC\u0644 \u06A9\u0631\u0646\u06D2 \u06A9\u06CC \u06A9\u0648\u0634\u0634 \u06A9\u0631\u06CC\u06BA\u06D4",
  "ui.agents.refusals.class.error.install_landed": "{reason} \u0627\u0646\u0633\u0679\u0627\u0644\u06CC\u0634\u0646 \u0645\u06A9\u0645\u0644 \u06C1\u0648 \u06AF\u0626\u06CC\u060C \u0627\u0633 \u0644\u06CC\u06D2 \u0627\u06CC\u062C\u0646\u0679 \u0627\u0628 \u0642\u0627\u0628\u0644 \u062A\u0631\u0645\u06CC\u0645 \u06C1\u06D2\u06D4"
};

