var ui_agents_routing_default6 = {
  "ui.agents.routing.aida": "\u06A9\u0633\u06CC \u062F\u0631\u062E\u0648\u0627\u0633\u062A \u06A9\u0648 \u0679\u06CC\u0645 \u06CC\u0627 \u06A9\u0633\u06CC \u0645\u0627\u06C1\u0631 \u06A9\u06D2 \u062D\u0648\u0627\u0644\u06D2 \u06A9\u0631\u0646\u0627\u060C \u0627\u06CC\u062C\u0646\u0679\u0633 \u06A9\u06D2 \u062F\u0631\u0645\u06CC\u0627\u0646 \u0645\u062A\u0648\u0627\u0632\u06CC \u06A9\u0627\u0645 \u0634\u0631\u0648\u0639 \u06A9\u0631\u0646\u0627\u060C \u06CC\u0627 \u06C1\u0631 \u062C\u0627\u0631\u06CC \u06A9\u0627\u0645 \u06A9\u06CC \u0645\u062C\u0645\u0648\u0639\u06CC \u0631\u067E\u0648\u0631\u0679 \u0637\u0644\u0628 \u06A9\u0631\u0646\u0627\u06D4",
  "ui.agents.routing.architect": "\u0644\u06A9\u06BE\u0646\u06D2 \u0633\u06D2 \u067E\u06C1\u0644\u06D2 \u06CC\u06C1 \u0637\u06D2 \u06A9\u0631\u0646\u0627 \u06A9\u06C1 \u06A9\u0648\u0626\u06CC \u0686\u06CC\u0632 \u06A9\u06CC\u0633\u06D2 \u0628\u0646\u06D2 \u06AF\u06CC: \u0637\u0631\u06CC\u0642\u0648\u06BA \u06CC\u0627 \u0622\u0631\u06A9\u06CC\u0679\u06CC\u06A9\u0686\u0631 \u06A9\u0627 \u0645\u0648\u0627\u0632\u0646\u06C1\u060C \u0641\u0648\u0627\u0626\u062F \u0648 \u0646\u0642\u0635\u0627\u0646\u0627\u062A \u067E\u0631 \u063A\u0648\u0631\u060C \u0631\u06CC\u0641\u06CC\u06A9\u0679\u0631\u0646\u06AF \u06A9\u06CC \u0645\u0646\u0635\u0648\u0628\u06C1 \u0628\u0646\u062F\u06CC\u060C \u06CC\u0627 RFC \u06CC\u0627 \u0688\u06CC\u0632\u0627\u0626\u0646 \u062F\u0633\u062A\u0627\u0648\u06CC\u0632 \u0644\u06A9\u06BE\u0646\u0627\u06D4",
  "ui.agents.routing.coder": "\u06A9\u0648\u0688 \u0644\u06A9\u06BE\u0646\u0627 \u06CC\u0627 \u0628\u062F\u0644\u0646\u0627: \u0679\u06A9\u0679 \u067E\u0631 \u0639\u0645\u0644 \u062F\u0631\u0622\u0645\u062F\u060C \u0641\u06CC\u0686\u0631 \u0628\u0646\u0627\u0646\u0627\u060C \u0628\u06AF \u062F\u0631\u0633\u062A \u06A9\u0631\u0646\u0627\u060C \u0641\u0646\u06A9\u0634\u0646 \u0634\u0627\u0645\u0644 \u06A9\u0631\u0646\u0627 \u2014 \u0627\u06CC\u06A9 \u0622\u0632\u0627\u062F\u060C \u0648\u0627\u0636\u062D \u0637\u0648\u0631 \u067E\u0631 \u0628\u06CC\u0627\u0646 \u06A9\u0631\u062F\u06C1 \u06A9\u0627\u0645 \u062C\u0648 \u0645\u0632\u06CC\u062F \u0641\u06CC\u0635\u0644\u0648\u06BA \u06A9\u06D2 \u0628\u063A\u06CC\u0631 \u0622\u06AF\u06D2 \u0628\u0691\u06BE \u0633\u06A9\u06D2\u06D4",
  "ui.agents.routing.copy_reviewer": "\u0627\u0634\u0627\u0639\u062A \u0633\u06D2 \u067E\u06C1\u0644\u06D2 \u0644\u06A9\u06BE\u06CC \u06AF\u0626\u06CC \u0639\u0628\u0627\u0631\u062A \u06A9\u0627 \u062C\u0627\u0626\u0632\u06C1: \u0635\u0627\u0631\u0641 \u06A9\u0648 \u0646\u0638\u0631 \u0622\u0646\u06D2 \u0648\u0627\u0644\u06CC \u067E\u0631\u0648\u0688\u06A9\u0679 \u0639\u0628\u0627\u0631\u062A (UI \u0627\u0633\u0679\u0631\u0646\u06AF\u0632\u060C \u0627\u06CC \u0645\u06CC\u0644\u0632\u060C \u0627\u0637\u0644\u0627\u0639\u0627\u062A\u060C \u0645\u062F\u062F/\u062F\u0633\u062A\u0627\u0648\u06CC\u0632\u0627\u062A)\u060C \u0627\u0648\u0631 \u0639\u0627\u0645 \u0642\u0627\u0631\u06CC \u06A9\u06D2 \u0644\u06CC\u06D2 \u0646\u062B\u0631 (\u0628\u0644\u0627\u06AF \u0645\u0636\u0627\u0645\u06CC\u0646\u060C LinkedIn \u0627\u0648\u0631 X \u067E\u0648\u0633\u0679\u0633)\u06D4 \u0642\u0627\u0631\u06CC \u06A9\u0627 \u062A\u062C\u0631\u0628\u06C1\u060C \u0633\u0645\u062C\u06BE\u060C \u0644\u06C1\u062C\u06C1\u060C \u0633\u0627\u062F\u06C1 \u0632\u0628\u0627\u0646\u060C \u062F\u0639\u0648\u0648\u06BA \u06A9\u06CC \u062A\u0627\u0626\u06CC\u062F \u0627\u0648\u0631 AI-isms \u06A9\u0627 \u062E\u0627\u062A\u0645\u06C1\u06D4 \u0635\u0627\u0631\u0641 \u06A9\u0648 \u0646\u0638\u0631 \u0622\u0646\u06D2 \u0648\u0627\u0644\u06CC \u0639\u0628\u0627\u0631\u062A \u067E\u0631 \u0627\u0633\u062A\u0639\u0645\u0627\u0644 \u06A9\u0631\u06CC\u06BA\u060C \u0627\u0646\u062C\u06CC\u0646\u0626\u0631\u0646\u06AF \u0646\u062B\u0631 \u06CC\u0627 \u06A9\u0648\u0688 \u06A9\u0645\u0646\u0679\u0633 \u067E\u0631 \u06A9\u0628\u06BE\u06CC \u0646\u06C1\u06CC\u06BA\u06D4",
  "ui.agents.routing.designer": "\u06CC\u06C1 \u062C\u0627\u0646\u0686\u0646\u0627 \u06A9\u06C1 \u06A9\u0648\u0626\u06CC \u0686\u06CC\u0632 \u0635\u0627\u0631\u0641 \u06A9\u0648 \u062F\u06A9\u06BE\u0646\u06D2 \u0645\u06CC\u06BA \u06A9\u06CC\u0633\u06CC \u0644\u06AF\u062A\u06CC \u06C1\u06D2: \u0627\u0633\u06A9\u0631\u06CC\u0646 \u06CC\u0627 \u0679\u0631\u0645\u06CC\u0646\u0644 UI \u06A9\u0627 \u062C\u0627\u0626\u0632\u06C1\u060C \u0644\u06D2 \u0622\u0624\u0679\u060C \u0627\u0633\u067E\u06CC\u0633\u0646\u06AF\u060C \u0631\u0646\u06AF \u06CC\u0627 \u0639\u0628\u0627\u0631\u062A \u06A9\u0627 \u0627\u0686\u06BE\u06CC \u0637\u0631\u062D \u067E\u0691\u06BE\u0627 \u062C\u0627\u0646\u0627\u060C \u0627\u0646\u0679\u0631\u0641\u06CC\u0633 \u06A9\u0648 \u0628\u06C1\u062A\u0631 \u0628\u0646\u0627\u0646\u0627 \u2014 \u0635\u0627\u0631\u0641 \u06A9\u0648 \u0646\u0638\u0631 \u0622\u0646\u06D2 \u0648\u0627\u0644\u06CC \u062A\u0628\u062F\u06CC\u0644\u06CC \u067E\u0631 \u0688\u06CC\u0632\u0627\u0626\u0646/UX \u06A9\u0627 \u0627\u06CC\u06A9 \u062F\u0648\u0631\u06D4",
  "ui.agents.routing.librarian": "\u0644\u0627\u0626\u0628\u0631\u06CC\u0631\u06CC \u06A9\u0648 \u0645\u0646\u0638\u0645 \u06A9\u0631\u0646\u0627 \u2014 \u0645\u062D\u0641\u0648\u0638 \u0627\u062B\u0627\u062B\u0648\u06BA \u06A9\u06D2 \u0646\u0627\u0645 \u0627\u0648\u0631 \u0679\u06CC\u06AF \u0628\u0646\u0627\u0646\u0627\u060C \u062A\u0648\u062C\u06C1 \u0637\u0644\u0628 \u0686\u06CC\u0632\u0648\u06BA \u06A9\u0648 \u0688\u06BE\u0648\u0646\u0688\u0646\u0627\u060C \u06CC\u0627 \u06CC\u06C1 \u067E\u0648\u0686\u06BE\u0646\u0627 \u06A9\u06C1 \u0644\u0627\u0626\u0628\u0631\u06CC\u0631\u06CC \u0645\u06CC\u06BA \u06A9\u06CC\u0627 \u0645\u0648\u062C\u0648\u062F \u06C1\u06D2\u06D4",
  "ui.agents.routing.manager": "\u06A9\u0626\u06CC \u0627\u06CC\u062C\u0646\u0679\u0633 \u06CC\u0627 \u0631\u06CC\u067E\u0648\u0632\u0679\u0631\u06CC\u0632 \u067E\u0631 \u067E\u06BE\u06CC\u0644\u06D2 \u06A9\u0627\u0645 \u06A9\u0648 \u0645\u0631\u0628\u0648\u0637 \u0627\u0648\u0631 \u0679\u0631\u06CC\u06A9 \u06A9\u0631\u0646\u0627\u060C \u062C\u0648 \u0631\u06A9\u0627 \u06C1\u0648 \u0627\u0633 \u06A9\u0627 \u067E\u06CC\u0686\u06BE\u0627 \u06A9\u0631\u0646\u0627\u060C \u06CC\u0627 \u0645\u062C\u0645\u0648\u0639\u06CC \u0635\u0648\u0631\u062A\u062D\u0627\u0644 \u06CC\u0627 \u067E\u06CC\u0634 \u0631\u0641\u062A \u0631\u067E\u0648\u0631\u0679 \u0628\u0646\u0627\u0646\u0627\u06D4",
  "ui.agents.routing.qa_tester": "\u0622\u0632\u0627\u062F\u0627\u0646\u06C1 \u062C\u0627\u0646\u0686\u0646\u0627 \u06A9\u06C1 PR\u060C \u067E\u06CC\u0686 \u06CC\u0627 \u0641\u06CC\u0686\u0631 \u0648\u0627\u0642\u0639\u06CC \u0634\u0631\u0648\u0639 \u0633\u06D2 \u0622\u062E\u0631 \u062A\u06A9 \u06A9\u0627\u0645 \u06A9\u0631\u062A\u0627 \u06C1\u06D2\u061B \u0628\u06AF \u062F\u0648\u0628\u0627\u0631\u06C1 \u067E\u06CC\u062F\u0627 \u06A9\u0631\u0646\u0627\u060C \u0636\u0645\u0646\u06CC \u0627\u062B\u0631\u0627\u062A \u06A9\u06CC \u062A\u0635\u062F\u06CC\u0642\u060C \u06CC\u0627 \u0627\u0635\u0644\u0627\u062D \u06A9\u06D2 \u0628\u0639\u062F \u0644\u0648\u0679 \u0622\u0646\u06D2 \u0648\u0627\u0644\u06D2 \u0646\u0642\u0627\u0626\u0635 \u06A9\u06CC \u062C\u0627\u0646\u0686\u06D4",
  "ui.agents.routing.reviewer": "PR\u060C MR\u060C diff\u060C commit \u0631\u06CC\u0646\u062C \u06CC\u0627 \u067E\u06CC\u0686 \u0645\u06CC\u06BA \u0646\u0642\u0627\u0626\u0635 \u0627\u0648\u0631 \u0628\u06AF\u0632 \u0688\u06BE\u0648\u0646\u0688\u0646\u06D2 \u06A9\u06D2 \u0644\u06CC\u06D2 \u062C\u0627\u0626\u0632\u06C1 \u0644\u06CC\u0646\u0627\u061B \u06A9\u0633\u06CC \u062F\u0648\u0633\u0631\u06D2 (\u06CC\u0627 \u06A9\u0633\u06CC \u0627\u0648\u0631 \u0627\u06CC\u062C\u0646\u0679) \u06A9\u06D2 \u0644\u06A9\u06BE\u06D2 \u06A9\u0648\u0688 \u06A9\u0627 \u0622\u0688\u0679 \u06A9\u0631\u0646\u0627 \u06CC\u0627 \u0627\u0633 \u067E\u0631 \u062A\u0646\u0642\u06CC\u062F\u06D4",
  "ui.agents.routing.scout": "\u06A9\u0633\u06CC \u0686\u06CC\u0632 \u06A9\u06D2 \u06A9\u0627\u0645 \u06A9\u0631\u0646\u06D2 \u06A9\u06D2 \u0637\u0631\u06CC\u0642\u06D2 \u06A9\u06D2 \u0628\u0627\u0631\u06D2 \u0645\u06CC\u06BA \u0633\u0648\u0627\u0644 \u06A9\u0627 \u062C\u0648\u0627\u0628 \u062F\u06CC\u0646\u0627\u060C \u06A9\u0648\u0688 \u062A\u0644\u0627\u0634 \u06A9\u0631\u0646\u0627\u060C \u0641\u0646\u06A9\u0634\u0646 \u06CC\u0627 \u06A9\u0644\u0627\u0633 \u06A9\u06C1\u0627\u06BA \u0645\u062A\u0639\u06CC\u0646 \u06C1\u06D2 \u06CC\u06C1 \u0688\u06BE\u0648\u0646\u0688\u0646\u0627\u060C \u06A9\u0633\u06CC \u0641\u0644\u0648 \u06A9\u0627 \u0633\u0631\u0627\u063A \u0644\u06AF\u0627\u0646\u0627\u060C \u0645\u0648\u062C\u0648\u062F\u06C1 \u0631\u0648\u06CC\u06D2 \u06A9\u0648 \u0633\u0645\u062C\u06BE\u0646\u0627\u060C \u0648\u06CC\u0628 \u067E\u0631 \u0644\u0627\u0626\u0628\u0631\u06CC\u0631\u06CC \u06CC\u0627 API \u06A9\u06CC \u062A\u062D\u0642\u06CC\u0642 \u06A9\u0631\u0646\u0627\u060C \u06CC\u0627 \u062B\u0628\u0648\u062A \u062C\u0645\u0639 \u06A9\u0631\u0646\u0627 \u2014 \u0635\u0631\u0641 \u067E\u0691\u06BE\u0646\u06D2 \u06A9\u06D2 \u0644\u06CC\u06D2\u060C \u06A9\u0686\u06BE \u062A\u0628\u062F\u06CC\u0644 \u0646\u06C1\u06CC\u06BA \u06C1\u0648\u062A\u0627\u06D4",
  "ui.agents.routing.tui_designer": "\u0679\u0631\u0645\u06CC\u0646\u0644 \u06CC\u0648\u0632\u0631 \u0627\u0646\u0679\u0631\u0641\u06CC\u0633\u0632 \u06A9\u06CC \u0688\u06CC\u0632\u0627\u0626\u0646\u0646\u06AF \u06CC\u0627 \u0627\u0646 \u06A9\u0627 \u062C\u0627\u0626\u0632\u06C1: \u06A9\u06CC \u0628\u0648\u0631\u0688 \u067E\u0631 \u0645\u0628\u0646\u06CC \u0641\u0644\u0648\u060C \u0686\u06BE\u0648\u0679\u06D2 \u06CC\u0627 \u0645\u0642\u0631\u0631\u06C1 \u0679\u0631\u0645\u06CC\u0646\u0644\u0632 \u0645\u06CC\u06BA \u0644\u06D2 \u0622\u0624\u0679 \u0627\u0648\u0631 \u0645\u0639\u0644\u0648\u0645\u0627\u062A \u06A9\u06CC \u06A9\u062B\u0627\u0641\u062A\u060C \u0631\u0646\u06AF \u0627\u0648\u0631 Unicode \u06A9\u06CC \u0645\u0637\u0627\u0628\u0642\u062A\u060C \u0628\u062A\u062F\u0631\u06CC\u062C \u0627\u0646\u06A9\u0634\u0627\u0641\u060C \u0627\u0648\u0631 CLI \u06A9\u0644\u0627\u0626\u0646\u0679 \u06A9\u06D2 \u0627\u0646\u0633\u0679\u0627\u0644\u0631\u0632\u060C \u0688\u06CC\u0645\u0646\u0632 \u0627\u0648\u0631 \u0627\u0633\u0679\u06CC\u0679\u0633 \u0688\u06CC\u0634 \u0628\u0648\u0631\u0688\u0632 \u06A9\u0627 UX\u06D4",
  "ui.agents.routing.ux_reviewer": "\u06A9\u0633\u06CC \u062A\u0628\u062F\u06CC\u0644\u06CC \u0645\u06CC\u06BA \u0635\u0627\u0631\u0641 \u06A9\u06D2 \u062A\u062C\u0631\u0628\u06D2 \u06C1\u06CC \u06A9\u0648 \u062C\u0627\u0646\u0686\u0646\u0627: \u0627\u0646\u0679\u0631\u0627\u06CC\u06A9\u0634\u0646 \u06A9\u0627 \u0641\u0644\u0648\u060C \u06A9\u06CC \u0628\u0648\u0631\u0688/\u0627\u0646 \u067E\u0679 \u06A9\u0627 \u0627\u0646\u062A\u0638\u0627\u0645\u060C \u062F\u0631\u06CC\u0627\u0641\u062A \u06A9\u06CC \u0633\u06C1\u0648\u0644\u062A\u060C \u0641\u06CC\u0688\u0628\u06CC\u06A9 \u0627\u0648\u0631 \u063A\u0644\u0637\u06CC\u0648\u06BA \u06A9\u06D2 \u067E\u06CC\u063A\u0627\u0645\u0627\u062A\u060C \u0639\u0628\u0627\u0631\u062A \u06A9\u0627 \u0644\u06C1\u062C\u06C1\u060C \u0627\u0648\u0631 \u06CC\u06C1 \u06A9\u06C1 \u06A9\u0627\u0645 \u0648\u0627\u0642\u0639\u06CC \u06C1\u0645\u0648\u0627\u0631 \u0637\u0631\u06CC\u0642\u06D2 \u0633\u06D2 \u0645\u06A9\u0645\u0644 \u06C1\u0648 \u0633\u06A9\u062A\u0627 \u06C1\u06D2 \u06CC\u0627 \u0646\u06C1\u06CC\u06BA \u2014 \u0627\u0633 \u0633\u06D2 \u0627\u0644\u06AF \u06A9\u06C1 \u0648\u06C1 \u062F\u06A9\u06BE\u062A\u06CC \u06A9\u06CC\u0633\u06CC \u06C1\u06D2\u060C \u06CC\u0639\u0646\u06CC \u0628\u0635\u0631\u06CC/\u0688\u06CC\u0632\u0627\u0626\u0646 \u062C\u0627\u0626\u0632\u06C1\u06D4"
};

