  "ui.agents.skills.alert.builtin_body": "\u06CC\u06C1 Local Operator \u06A9\u06D2 \u0633\u0627\u062A\u06BE \u0622\u062A\u06CC \u06C1\u06D2 \u0627\u0648\u0631 \u06CC\u06C1\u0627\u06BA \u062A\u0628\u062F\u06CC\u0644 \u0646\u06C1\u06CC\u06BA \u06A9\u06CC \u062C\u0627 \u0633\u06A9\u062A\u06CC\u06D4 \u0627\u06CC\u0633\u0627 \u0648\u0631\u0698\u0646 \u067E\u0627\u0646\u06D2 \u06A9\u06D2 \u0644\u06CC\u06D2 \u062C\u0633 \u0645\u06CC\u06BA \u0622\u067E \u062A\u0631\u0645\u06CC\u0645 \u06A9\u0631 \u0633\u06A9\u06CC\u06BA \u06CC\u0627 \u06A9\u0633\u06CC \u0627\u06CC\u062C\u0646\u0679 \u0633\u06D2 \u062A\u0628\u062F\u06CC\u0644\u06CC \u06A9\u0631\u0648\u0627 \u0633\u06A9\u06CC\u06BA\u060C \u0627\u0633\u06D2 \u0627\u067E\u0646\u06CC \u0645\u06C1\u0627\u0631\u062A\u0648\u06BA \u0645\u06CC\u06BA \u0646\u0642\u0644 \u06A9\u0631\u06CC\u06BA\u06D4",
