  "ui.chat.pickers.destination_pickers.fork_this_conversation": "\u0627\u0633 \u06AF\u0641\u062A\u06AF\u0648 \u06A9\u0648 \u0641\u0648\u0631\u06A9 \u06A9\u0631\u06CC\u06BA",
  "ui.chat.pickers.destination_pickers.copies_this_conversation_up_to_and_including_everything_after_it_is_left": "\u06CC\u06C1 \u06AF\u0641\u062A\u06AF\u0648 {value} \u062A\u06A9\u060C \u0628\u0634\u0645\u0648\u0644 \u0627\u0633 \u06A9\u06D2\u060C \u0646\u0642\u0644 \u06A9\u0631 \u062F\u06CC \u062C\u0627\u062A\u06CC \u06C1\u06D2\u06D4 \u0627\u0633 \u06A9\u06D2 \u0628\u0639\u062F \u06A9\u0627 \u0633\u0628 \u067E\u06CC\u0686\u06BE\u06D2 \u0631\u06C1 \u062C\u0627\u062A\u0627 \u06C1\u06D2\u060C \u0627\u0648\u0631 \u0627\u0635\u0644 \u06AF\u0641\u062A\u06AF\u0648 \u0686\u0644\u062A\u06CC \u0631\u06C1\u062A\u06CC \u06C1\u06D2 \u0627\u0648\u0631 \u0646\u06C1\u06CC\u06BA \u0628\u062F\u0644\u062A\u06CC\u06D4",
