  "ui.chat.session_readout.access.owner_unavailable.description": "\u06CC\u06C1 \u0633\u06CC\u0634\u0646 {owner} \u0633\u06D2 {label} \u06A9\u06CC \u0631\u0633\u0627\u0626\u06CC \u0645\u062A\u0639\u06CC\u0646 \u0646\u06C1\u06CC\u06BA \u06A9\u0631 \u0633\u06A9\u0627\u06D4 \u067E\u0686\u06BE\u0644\u06CC \u0631\u0633\u0627\u0626\u06CC \u062F\u0648\u0628\u0627\u0631\u06C1 \u0627\u0633\u062A\u0639\u0645\u0627\u0644 \u0646\u06C1\u06CC\u06BA \u06C1\u0648 \u0633\u06A9\u062A\u06CC\u06D4 \u0645\u0627\u0644\u06A9 \u06A9\u06CC \u0631\u0633\u0627\u0626\u06CC \u0628\u062D\u0627\u0644 \u06C1\u0648\u0646\u06D2 \u06A9\u06D2 \u0628\u0639\u062F \u062F\u0648\u0628\u0627\u0631\u06C1 \u06A9\u0648\u0634\u0634 \u06A9\u0631\u06CC\u06BA\u060C \u06CC\u0627 \u06A9\u0648\u0626\u06CC \u0627\u0648\u0631 \u0645\u0627\u0688\u0644 \u0645\u0646\u062A\u062E\u0628 \u06A9\u0631\u06CC\u06BA\u06D4",
  "ui.chat.session_readout.access.owner_unavailable.title": "{owner} \u0633\u06D2 \u0631\u0633\u0627\u0626\u06CC \u0646\u06C1\u06CC\u06BA \u0645\u0644 \u0633\u06A9\u062A\u06CC",
  "ui.chat.session_readout.access.pending.description": "\u0631\u0633\u0627\u0626\u06CC \u06A9\u06CC \u0635\u0648\u0631\u062A\u062D\u0627\u0644 \u0627\u0628\u06BE\u06CC \u0637\u06D2 \u0646\u06C1\u06CC\u06BA \u06C1\u0648\u0626\u06CC\u06D4 \u0627\u06AF\u0644\u06CC \u062F\u0631\u062E\u0648\u0627\u0633\u062A \u062E\u0648\u062F \u0628\u062E\u0648\u062F \u0645\u0627\u0644\u06A9 \u06A9\u0648 \u062C\u0627\u0646\u0686\u06D2 \u06AF\u06CC\u061B \u06CC\u06C1\u0627\u06BA \u0645\u0632\u06CC\u062F \u0633\u0627\u0626\u0646 \u0627\u0646 \u06A9\u06CC \u0636\u0631\u0648\u0631\u062A \u0646\u06C1\u06CC\u06BA\u06D4",
  "ui.chat.session_readout.access.pending.title": "{label} \u06A9\u06CC \u0631\u0633\u0627\u0626\u06CC \u062C\u0627\u0646\u0686\u06CC \u062C\u0627 \u0631\u06C1\u06CC \u06C1\u06D2",
  "ui.chat.session_readout.access.withdrawn.description": "\u0645\u0627\u0644\u06A9 \u0688\u06CC\u0648\u0627\u0626\u0633 \u0627\u0633 \u0648\u0642\u062A \u0645\u0633\u062A\u0639\u0627\u0631 \u0631\u0633\u0627\u0626\u06CC \u0641\u0631\u0627\u06C1\u0645 \u0646\u06C1\u06CC\u06BA \u06A9\u0631 \u0633\u06A9\u062A\u06CC\u060C \u06CC\u0627 \u0645\u0633\u062A\u0639\u0627\u0631 \u0644\u06CC\u0646\u06D2 \u06A9\u06CC \u0627\u062C\u0627\u0632\u062A \u062F\u0633\u062A\u06CC\u0627\u0628 \u0646\u06C1\u06CC\u06BA\u06D4 \u062F\u0648\u0628\u0627\u0631\u06C1 \u06A9\u0648\u0634\u0634 \u0633\u06D2 \u067E\u06C1\u0644\u06D2 \u0645\u0627\u0644\u06A9 \u06A9\u06CC \u0631\u0633\u0627\u0626\u06CC \u06CC\u0627 \u0627\u062C\u0627\u0632\u062A \u0628\u062D\u0627\u0644 \u06A9\u0631\u06CC\u06BA\u060C \u06CC\u0627 \u06A9\u0648\u0626\u06CC \u0627\u0648\u0631 \u0645\u0627\u0688\u0644 \u0645\u0646\u062A\u062E\u0628 \u06A9\u0631\u06CC\u06BA\u06D4",
  "ui.chat.session_readout.access.withdrawn.title": "{label} \u06A9\u06CC \u0631\u0633\u0627\u0626\u06CC \u067E\u0631 \u062A\u0648\u062C\u06C1 \u062F\u0631\u06A9\u0627\u0631 \u06C1\u06D2",
  "ui.chat.session_readout.draft.confirm_effort_changed": "\u06CC\u06C1 \u06AF\u0641\u062A\u06AF\u0648 {selector} \u067E\u0631 \u0686\u0644\u06D2 \u06AF\u06CC\u06D4 \u0627\u0633 \u06A9\u06CC \u06A9\u0648\u0634\u0634 \u0627\u0628 {level} \u06C1\u06D2\u060C \u06A9\u06CC\u0648\u0646\u06A9\u06C1 {wanted} \u0627\u0633 \u0645\u0627\u0688\u0644 \u06A9\u06CC \u0633\u0637\u062D\u0648\u06BA \u0645\u06CC\u06BA \u0634\u0627\u0645\u0644 \u0646\u06C1\u06CC\u06BA\u06D4",
  "ui.chat.session_readout.draft.confirm_effort_unset": "\u06CC\u06C1 \u06AF\u0641\u062A\u06AF\u0648 {selector} \u067E\u0631 \u0686\u0644\u06D2 \u06AF\u06CC\u06D4 \u0627\u0633 \u06A9\u06D2 \u0644\u06CC\u06D2 \u06A9\u0648\u0634\u0634 \u06A9\u06CC \u06A9\u0648\u0626\u06CC \u0633\u0637\u062D \u0645\u0642\u0631\u0631 \u0646\u06C1\u06CC\u06BA\u060C \u06A9\u06CC\u0648\u0646\u06A9\u06C1 {wanted} \u0627\u0633 \u0645\u0627\u0688\u0644 \u06A9\u06CC \u0633\u0637\u062D\u0648\u06BA \u0645\u06CC\u06BA \u0634\u0627\u0645\u0644 \u0646\u06C1\u06CC\u06BA\u06D4",
  "ui.chat.session_readout.draft.confirm_model": "\u06CC\u06C1 \u06AF\u0641\u062A\u06AF\u0648 {selector} \u067E\u0631 \u0686\u0644\u06D2 \u06AF\u06CC\u06D4",
  "ui.chat.session_readout.draft.confirm_model_effort": "\u06CC\u06C1 \u06AF\u0641\u062A\u06AF\u0648 {selector} \u067E\u0631 {effort} \u06A9\u0648\u0634\u0634 \u06A9\u06D2 \u0633\u0627\u062A\u06BE \u0686\u0644\u06D2 \u06AF\u06CC\u06D4",
  "ui.chat.session_readout.draft.refusal_ladder_unread": "\u06A9\u0686\u06BE \u0646\u06C1\u06CC\u06BA \u0628\u062F\u0644\u0627\u060C \u06A9\u06CC\u0648\u0646\u06A9\u06C1 \u0627\u0633 \u0645\u0627\u0688\u0644 \u06A9\u06CC \u06A9\u0648\u0634\u0634 \u06A9\u06CC \u0633\u0637\u062D\u06CC\u06BA \u067E\u0691\u06BE\u06CC \u0646\u06C1\u06CC\u06BA \u062C\u0627 \u0633\u06A9\u06CC\u06BA\u06D4 \u062F\u0648\u0628\u0627\u0631\u06C1 \u06A9\u0648\u0634\u0634 \u06A9\u0631\u06CC\u06BA\u06D4",
  "ui.chat.session_readout.effort.detail.auto": "\u06A9\u0648\u0626\u06CC \u0633\u0637\u062D \u0645\u0642\u0631\u0631 \u0646\u06C1\u06CC\u06BA\u060C \u0627\u0633 \u0644\u06CC\u06D2 \u06CC\u06C1 \u0645\u0627\u0688\u0644 \u0627\u067E\u0646\u06D2 \u0688\u06CC\u0641\u0627\u0644\u0679 \u067E\u0631 \u0686\u0644\u062A\u0627 \u06C1\u06D2\u06D4 \u0627\u0633 \u0645\u06CC\u06BA {levels} \u062F\u0633\u062A\u06CC\u0627\u0628 \u06C1\u06CC\u06BA\u06D4",
  "ui.chat.session_readout.effort.detail.auto_with_default": "\u06A9\u0648\u0626\u06CC \u0633\u0637\u062D \u0645\u0642\u0631\u0631 \u0646\u06C1\u06CC\u06BA\u060C \u0627\u0633 \u0644\u06CC\u06D2 \u06CC\u06C1 \u0645\u0627\u0688\u0644 \u0627\u067E\u0646\u06D2 \u0688\u06CC\u0641\u0627\u0644\u0679 ({default}) \u067E\u0631 \u0686\u0644\u062A\u0627 \u06C1\u06D2\u06D4 \u0627\u0633 \u0645\u06CC\u06BA {levels} \u062F\u0633\u062A\u06CC\u0627\u0628 \u06C1\u06CC\u06BA\u06D4",
  "ui.chat.session_readout.effort.detail.default_only": "\u0648\u06C1 \u0633\u0637\u062D \u062C\u0633 \u067E\u0631 \u06CC\u06C1 \u0645\u0627\u0688\u0644 \u0688\u06CC\u0641\u0627\u0644\u0679 \u0637\u0648\u0631 \u067E\u0631 \u0686\u0644\u062A\u0627 \u06C1\u06D2\u06D4 \u06CC\u06C1 \u0628\u06CC\u06A9 \u0627\u06CC\u0646\u0688 \u0646\u06C1\u06CC\u06BA \u0628\u062A\u0627\u062A\u0627 \u06A9\u06C1 \u0648\u06C1 \u0627\u0648\u0631 \u06A9\u0648\u0646 \u0633\u06CC \u0633\u0637\u062D\u06CC\u06BA \u0642\u0628\u0648\u0644 \u06A9\u0631\u062A\u0627 \u06C1\u06D2\u06D4",
  "ui.chat.session_readout.effort.detail.no_levels": "\u06CC\u06C1 \u0645\u0627\u0688\u0644 \u0627\u0633\u062A\u062F\u0644\u0627\u0644 \u06A9\u0631\u062A\u0627 \u06C1\u06D2\u060C \u0644\u06CC\u06A9\u0646 \u0645\u0646\u062A\u062E\u0628 \u06A9\u0631\u0646\u06D2 \u06A9\u06D2 \u0644\u06CC\u06D2 \u06A9\u0648\u0634\u0634 \u06A9\u06CC \u06A9\u0648\u0626\u06CC \u0633\u0637\u062D \u067E\u06CC\u0634 \u0646\u06C1\u06CC\u06BA \u06A9\u0631\u062A\u0627\u06D4",
  "ui.chat.session_readout.effort.detail.not_reported": "\u0627\u0633 \u0633\u06CC\u0634\u0646 \u0646\u06D2 \u0627\u0628\u06BE\u06CC \u0627\u067E\u0646\u06CC \u0627\u0633\u062A\u062F\u0644\u0627\u0644 \u06A9\u06CC \u06A9\u0648\u0634\u0634 \u0646\u06C1\u06CC\u06BA \u0628\u062A\u0627\u0626\u06CC\u06D4 \u06CC\u06C1 \u0627\u06AF\u0644\u06CC \u0628\u0627\u0631\u06CC \u06A9\u06D2 \u0628\u0639\u062F \u0646\u0638\u0631 \u0622\u0626\u06D2 \u06AF\u06CC\u060C \u06CC\u0627 \u0627\u0628\u06BE\u06CC \u0645\u0642\u0631\u0631 \u06A9\u0631\u0646\u06D2 \u06A9\u06D2 \u0644\u06CC\u06D2 {command} \u0686\u0644\u0627\u0626\u06CC\u06BA\u06D4",
  "ui.chat.session_readout.effort.detail.offers": "\u0627\u0633\u062A\u062F\u0644\u0627\u0644 \u06A9\u06CC \u06A9\u0648\u0634\u0634\u06D4 \u06CC\u06C1 \u0645\u0627\u0688\u0644 {levels} \u067E\u06CC\u0634 \u06A9\u0631\u062A\u0627 \u06C1\u06D2\u06D4",
