  "ui.chat.session_readout.strip.draft_failed.detail": "\u0627\u0628\u06BE\u06CC \u0627\u0633 \u06A9\u06D2 \u0644\u06CC\u06D2 \u06A9\u0648\u0626\u06CC \u0645\u0627\u0688\u0644 \u0645\u0642\u0631\u0631 \u0646\u06C1\u06CC\u06BA",
