  "ui.common.connection.backend.pairing_governed": "\u0627\u0633 \u0645\u0634\u06CC\u0646 \u06A9\u0627 Local Operator \u0633\u0631\u0648\u0631 \u067E\u06C1\u0644\u06D2 \u06C1\u06CC \u06A9\u0648\u0626\u06CC \u062F\u0648\u0633\u0631\u0627 \u067E\u0631\u0648\u06AF\u0631\u0627\u0645 \u0686\u0644\u0627 \u0631\u06C1\u0627 \u06C1\u06D2\u060C \u0627\u0633 \u0644\u06CC\u06D2 \u06CC\u06C1 \u0627\u06CC\u067E \u0627\u0633 \u06A9\u06CC \u062A\u0631\u062A\u06CC\u0628\u0627\u062A\u060C \u0641\u0631\u0627\u06C1\u0645 \u06A9\u0646\u0646\u062F\u06C1 \u0633\u0627\u0626\u0646 \u0627\u0646\u060C \u0633\u0644\u06CC\u0634 \u06A9\u0645\u0627\u0646\u0688\u0632 \u0627\u0648\u0631 MCP \u0627\u0646\u062A\u0638\u0627\u0645 \u0627\u0633\u062A\u0639\u0645\u0627\u0644 \u0646\u06C1\u06CC\u06BA \u06A9\u0631 \u0633\u06A9\u062A\u06CC\u06D4",
