  "ui.common.updates.update_notification.server_version_v3": "\u0633\u0631\u0648\u0631 \u06A9\u0627 \u0648\u0631\u0698\u0646 {latestversion} \u062F\u0633\u062A\u06CC\u0627\u0628 \u06C1\u06D2\u06D4",
  "ui.common.updates.update_notification.sessions_that_are_still_running_the_old_build_will_move_onto_the_": "\u062C\u0648 \u0633\u06CC\u0634\u0646 \u0627\u0628\u06BE\u06CC \u067E\u0631\u0627\u0646\u0627 \u0628\u0644\u0688 \u0686\u0644\u0627 \u0631\u06C1\u06D2 \u06C1\u06CC\u06BA \u0648\u06C1 \u0627\u06AF\u0644\u06CC \u0628\u0627\u0631 \u0631\u06A9\u0646\u06D2 \u06CC\u0627 \u063A\u06CC\u0631 \u0641\u0639\u0627\u0644 \u06C1\u0648\u0646\u06D2 \u067E\u0631 \u0646\u0626\u06D2 \u0628\u0644\u0688 \u067E\u0631 \u0645\u0646\u062A\u0642\u0644 \u06C1\u0648 \u062C\u0627\u0626\u06CC\u06BA \u06AF\u06D2\u06D4",
  "ui.common.updates.update_notification.still_checking_a_slow_or_stalled_connection_can_hold_this_for_abo": "\u062C\u0627\u0646\u0686 \u0627\u0628\u06BE\u06CC \u062C\u0627\u0631\u06CC \u06C1\u06D2\u06D4 \u0633\u0633\u062A \u06CC\u0627 \u0631\u06A9\u0627 \u06C1\u0648\u0627 \u06A9\u0646\u06A9\u0634\u0646 \u062A\u0642\u0631\u06CC\u0628\u0627\u064B \u0688\u06CC\u0691\u06BE \u0645\u0646\u0679 \u0644\u06AF\u0627 \u0633\u06A9\u062A\u0627 \u06C1\u06D2 \u2014 \u0627\u06CC\u067E \u062E\u0648\u062F \u0627\u0646\u062A\u0638\u0627\u0631 \u062E\u062A\u0645 \u06A9\u0631 \u062F\u06CC\u062A\u06CC \u06C1\u06D2\u06D4",
  "ui.common.updates.update_notification.still_downloading_a_download_that_stops_making_progress_is_cancel": "\u0688\u0627\u0624\u0646 \u0644\u0648\u0688 \u0627\u0628\u06BE\u06CC \u062C\u0627\u0631\u06CC \u06C1\u06D2\u06D4 \u067E\u06CC\u0634 \u0631\u0641\u062A \u0631\u06A9\u0646\u06D2 \u067E\u0631 \u0688\u0627\u0624\u0646 \u0644\u0648\u0688 \u062A\u0642\u0631\u06CC\u0628\u0627\u064B 90 \u0633\u06CC\u06A9\u0646\u0688 \u0628\u0639\u062F \u0645\u0646\u0633\u0648\u062E \u06C1\u0648 \u062C\u0627\u062A\u0627 \u06C1\u06D2\u06D4",
  "ui.common.updates.update_notification.still_installing_a_slow_connection_or_a_cold_cache_can_hold_this_": "\u062A\u0646\u0635\u06CC\u0628 \u0627\u0628\u06BE\u06CC \u062C\u0627\u0631\u06CC \u06C1\u06D2\u06D4 \u0633\u0633\u062A \u06A9\u0646\u06A9\u0634\u0646 \u06CC\u0627 \u062E\u0627\u0644\u06CC \u06A9\u06CC\u0634 \u0632\u06CC\u0627\u062F\u06C1 \u0648\u0642\u062A \u0644\u06AF\u0627 \u0633\u06A9\u062A\u0627 \u06C1\u06D2 \u2014 \u0627\u06CC\u067E \u062E\u0648\u062F \u0627\u0646\u062A\u0638\u0627\u0631 \u062E\u062A\u0645 \u06A9\u0631 \u062F\u06CC\u062A\u06CC \u06C1\u06D2\u06D4",
  "ui.common.updates.update_notification.the_app_cannot_update_this_server": "\u0627\u06CC\u067E \u0627\u0633 \u0633\u0631\u0648\u0631 \u06A9\u0648 \u0627\u067E \u0688\u06CC\u0679 \u0646\u06C1\u06CC\u06BA \u06A9\u0631 \u0633\u06A9\u062A\u06CC",
