  "ui.agents.descriptions.aida": "\u4F60\u7684\u9996\u5E2D\u52A9\u7406\uFF1A\u66FF\u4F60\u8C03\u5EA6\u667A\u80FD\u4F53\u548C\u56E2\u961F\uFF0C\u7167\u770B\u4E00\u5207\u8FDB\u884C\u4E2D\u7684\u5DE5\u4F5C\uFF0C\u5E76\u968F\u65F6\u6C47\u62A5\u3002",
  "ui.agents.descriptions.architect": "\u63A2\u7D22\u4EE3\u7801\u5E93\uFF0C\u4EA7\u51FA\u5E26\u6743\u8861\u53D6\u820D\u7684\u8BBE\u8BA1\u6216\u6280\u672F\u65B9\u6848\uFF1B\u53EF\u4EE5\u8D77\u8349\u6587\u6863\uFF0C\u4F46\u4ECE\u4E0D\u6539\u52A8\u73B0\u6709\u6E90\u7801\u3002",
  "ui.agents.descriptions.coder": "\u7528\u5B8C\u6574\u5DE5\u5177\u96C6\u7AEF\u5230\u7AEF\u5B8C\u6210\u4E00\u9879\u8303\u56F4\u660E\u786E\u7684\u4EFB\u52A1\uFF0C\u7136\u540E\u6C47\u62A5\u6539\u4E86\u4EC0\u4E48\u3001\u5982\u4F55\u9A8C\u8BC1\u7684\u3002",
  "ui.agents.descriptions.copy_reviewer": "\u53D1\u5E03\u524D\u7684\u6587\u5B57\u5BA1\u67E5\uFF1A\u68C0\u67E5\u9762\u5411\u7528\u6237\u7684\u6587\u6848\u548C\u4E3A\u666E\u901A\u8BFB\u8005\u5199\u7684\u6587\u5B57\uFF0C\u5173\u6CE8\u53EF\u7406\u89E3\u6027\u3001\u8BED\u6C14\u3001\u8BF4\u6CD5\u6709\u65E0\u4F9D\u636E\uFF0C\u4EE5\u53CA\u6709\u6CA1\u6709AI\u8154\uFF1B\u95EE\u9898\u7F16\u53F7\u4EE5C\u5F00\u5934\u3002",
  "ui.agents.descriptions.designer": "\u5BF9\u7528\u6237\u53EF\u89C1\u7684\u6539\u52A8\u505A\u8BBE\u8BA1\u4E0EUX\u5BA1\u67E5\uFF0C\u4F9D\u636E\u5B9E\u9645\u6E32\u67D3\u7684\u753B\u9762\u800C\u975E\u6E90\u7801\u5224\u65AD\uFF1B\u95EE\u9898\u7F16\u53F7\u4EE5D\u5F00\u5934\u3002",
  "ui.agents.descriptions.librarian": "\u8D44\u6E90\u5E93\u7684\u6574\u7406\u667A\u80FD\u4F53\uFF1A\u4E3A\u7528\u6237\u4FDD\u5B58\u7684\u8D44\u6E90\u547D\u540D\u3001\u64B0\u5199\u63CF\u8FF0\u5E76\u6253\u6807\u7B7E\uFF0C\u5B66\u4E60\u5176\u4E2D\u7684\u7528\u8BCD\uFF0C\u8BA9\u5168\u5C40\u76EE\u5F55\u4FDD\u6301\u53EF\u7528\u3002",
  "ui.agents.descriptions.manager": "\u534F\u8C03\u59D4\u6D3E\u51FA\u53BB\u7684\u5DE5\u4F5C\uFF0C\u5982\u5B9E\u6C47\u62A5\u72B6\u6001\uFF1A\u54EA\u4E9B\u5DF2\u5B8C\u6210\u3001\u54EA\u4E9B\u5728\u8FDB\u884C\u3001\u54EA\u4E9B\u5361\u4F4F\u4E86\u3001\u5728\u7B49\u8C01\u3002",
  "ui.agents.descriptions.qa_tester": "\u4E3A\u6539\u52A8\u63D0\u4F9B\u72EC\u7ACB\u7684\u6267\u884C\u9A8C\u8BC1\uFF1A\u5148\u9884\u68C0\u6D4B\u8BD5\u73AF\u5883\uFF0C\u8DD1\u4E00\u904D\u771F\u5B9E\u8DEF\u5F84\u548C\u53CD\u4F8B\uFF0C\u7136\u540E\u4EA4\u51FA\u8303\u56F4\u660E\u786E\u7684QA\u77E9\u9635\uFF0C\u5168\u7A0B\u4E0D\u6539\u52A8\u4ED3\u5E93\u3002",
  "ui.agents.descriptions.reviewer": "\u5BF9diff\u3001MR\u6216PR\u505A\u72EC\u7ACB\u7684\u4EE3\u7801\u5BA1\u67E5\uFF1A\u627E\u51FA\u7F3A\u9677\u3001\u6309\u4E25\u91CD\u7A0B\u5EA6\u5206\u7EA7\uFF0C\u7EDD\u4E0D\u6539\u52A8\u6240\u5BA1\u67E5\u7684\u4EE3\u7801\u3002",
  "ui.agents.descriptions.scout": "\u53EA\u8BFB\u8C03\u7814\uFF1A\u5728\u5DE5\u4F5C\u533A\u548C\u7F51\u7EDC\u4E0A\u67E5\u8BC1\u95EE\u9898\uFF0C\u5E26\u7740\u8BC1\u636E\u6C47\u62A5\u53D1\u73B0\uFF0C\u4E0D\u6539\u52A8\u4EFB\u4F55\u5185\u5BB9\u3002",
  "ui.agents.descriptions.tui_designer": "\u8BBE\u8BA1\u4E0E\u5BA1\u67E5\u7EC8\u7AEF\u754C\u9762\uFF1A\u4EE5\u952E\u76D8\u4E3A\u5148\u7684\u64CD\u4F5C\u6D41\u3001\u5728\u56FA\u5B9A\u5C0F\u89C6\u53E3\u4E2D\u4FDD\u6301\u4FE1\u606F\u5BC6\u5EA6\u3001\u989C\u8272\u4E0EUnicode\u5B57\u5F62\u56DE\u9000\u3001\u5B9E\u6D4B\u7684\u51E0\u4F55\u6570\u636E\uFF1B\u95EE\u9898\u7F16\u53F7\u4EE5T\u5F00\u5934\u3002",
