  "ui.agents.routing.designer": "\u68C0\u67E5\u4E1C\u897F\u5728\u7528\u6237\u773C\u91CC\u201C\u957F\u4EC0\u4E48\u6837\u201D\uFF1A\u5BA1\u67E5\u9875\u9762\u6216\u7EC8\u7AEF\u754C\u9762\uFF0C\u770B\u5E03\u5C40\u3001\u95F4\u8DDD\u3001\u989C\u8272\u6216\u6587\u6848\u662F\u5426\u59A5\u5F53\uFF0C\u628A\u754C\u9762\u505A\u5F97\u66F4\u597D\u770B\u2014\u2014\u9488\u5BF9\u7528\u6237\u53EF\u89C1\u6539\u52A8\u7684\u4E00\u8F6E\u8BBE\u8BA1\u4E0EUX\u5BA1\u67E5\u3002",
  "ui.agents.routing.librarian": "\u6574\u7406\u8D44\u6E90\u5E93\uFF1A\u4E3A\u4FDD\u5B58\u7684\u8D44\u6E90\u547D\u540D\u3001\u6253\u6807\u7B7E\uFF0C\u627E\u51FA\u9700\u8981\u5904\u7406\u7684\u5185\u5BB9\uFF0C\u6216\u56DE\u7B54\u5E93\u91CC\u90FD\u5B58\u4E86\u4EC0\u4E48\u3002",
  "ui.agents.routing.manager": "\u534F\u8C03\u5E76\u8DDF\u8E2A\u8DE8\u591A\u4E2A\u667A\u80FD\u4F53\u6216\u4ED3\u5E93\u7684\u591A\u73AF\u8282\u5DE5\u4F5C\u3001\u8DDF\u8FDB\u5361\u4F4F\u7684\u73AF\u8282\uFF0C\u6216\u4EA7\u51FA\u72B6\u6001\u6C47\u603B\u4E0E\u8FDB\u5EA6\u62A5\u544A\u3002",
  "ui.agents.routing.qa_tester": "\u72EC\u7ACB\u9A8C\u8BC1PR\u3001\u8865\u4E01\u6216\u529F\u80FD\u662F\u5426\u771F\u7684\u80FD\u7AEF\u5230\u7AEF\u8DD1\u901A\uFF1B\u590D\u73B0bug\u3001\u9A8C\u8BC1\u526F\u4F5C\u7528\uFF0C\u6216\u68C0\u67E5\u6574\u6539\u662F\u5426\u5F15\u5165\u56DE\u5F52\u3002",
  "ui.agents.routing.reviewer": "\u5BA1\u67E5PR\u3001MR\u3001diff\u3001\u63D0\u4EA4\u8303\u56F4\u6216\u8865\u4E01\u91CC\u7684\u7F3A\u9677\u4E0Ebug\uFF1B\u5BA1\u8BA1\u6216\u70B9\u8BC4\u522B\u4EBA\uFF08\u6216\u5176\u4ED6\u667A\u80FD\u4F53\uFF09\u5199\u7684\u4EE3\u7801\u3002",
  "ui.agents.routing.scout": "\u56DE\u7B54\u67D0\u4E2A\u4E1C\u897F\u662F\u600E\u4E48\u8FD0\u4F5C\u7684\u3001\u5B9A\u4F4D\u4EE3\u7801\u3001\u627E\u5230\u51FD\u6570\u6216\u7C7B\u7684\u5B9A\u4E49\u3001\u8FFD\u4E00\u6761\u6D41\u7A0B\u3001\u7406\u89E3\u73B0\u6709\u884C\u4E3A\u3001\u4E0A\u7F51\u8C03\u7814\u67D0\u4E2A\u5E93\u6216API\uFF0C\u6216\u6536\u96C6\u8BC1\u636E\u2014\u2014\u53EA\u8BFB\uFF0C\u4E0D\u6539\u52A8\u4EFB\u4F55\u4E1C\u897F\u3002",
  "ui.agents.routing.tui_designer": "\u8BBE\u8BA1\u6216\u5BA1\u67E5\u7EC8\u7AEF\u754C\u9762\uFF1A\u4EE5\u952E\u76D8\u4E3A\u5148\u7684\u64CD\u4F5C\u6D41\u3001\u5C0F\u5C3A\u5BF8\u56FA\u5B9A\u7EC8\u7AEF\u91CC\u7684\u5E03\u5C40\u4E0E\u4FE1\u606F\u5BC6\u5EA6\u3001\u989C\u8272\u4E0EUnicode\u517C\u5BB9\u6027\u3001\u6E10\u8FDB\u5F0F\u62AB\u9732\uFF0C\u4EE5\u53CACLI\u5BA2\u6237\u7AEF\u5B89\u88C5\u7A0B\u5E8F\u3001\u5B88\u62A4\u8FDB\u7A0B\u4E0E\u72B6\u6001\u9762\u677F\u7684\u7528\u6237\u4F53\u9A8C\u3002",
  "ui.agents.routing.ux_reviewer": "\u5BA1\u67E5\u6539\u52A8\u7684\u7528\u6237\u201C\u4F53\u9A8C\u201D\u2014\u2014\u4EA4\u4E92\u6D41\u7A0B\u3001\u952E\u76D8\u4E0E\u8F93\u5165\u5904\u7406\u3001\u53EF\u53D1\u73B0\u6027\u3001\u53CD\u9988\u4E0E\u62A5\u9519\u4FE1\u606F\u3001\u6587\u6848\u8BED\u6C14\uFF0C\u4EE5\u53CA\u4EFB\u52A1\u80FD\u5426\u987A\u7545\u5B8C\u6210\u2014\u2014\u6709\u522B\u4E8E\u770B\u5916\u89C2\u7684\u89C6\u89C9\u4E0E\u8BBE\u8BA1\u5BA1\u67E5\u3002"
