  "ui.onboarding.tour.agent_options.body.1": "\u70B9\u51FB\u6B64\u5904\u67E5\u770B\u5F53\u524D\u6240\u9009\u667A\u80FD\u4F53\u7684\u9009\u9879\uFF0C\u4F8B\u5982\u67E5\u770B\u8BBE\u7F6E\u3001\u5BFC\u51FA\u6216\u5220\u9664\u3002",
