      title: z2.string().max(80).optional(),
      owner: z2.string().max(80).optional(),
      team: z2.string().max(80).optional(),
      description: z2.string().max(PROJECT_DESCRIPTION_MAX_CHARS).optional(),
      status: projectStatus.optional(),
      progress: z2.string().max(PROJECT_PROGRESS_MAX_CHARS).optional(),
