    warning: "#885A01",
    warningWash: "#E1E2E2",
    warningBorder: "#A6762D",
    // Primer red CF222E is 4.11:1 on `sunken` (< 4.5). Deepened along the same red.
    danger: "#C61226",
    dangerWash: "#FFEBE9",
    dangerBorder: "#E93F43",
