var definitions = [
  localOperatorDark,
  localOperatorLight,
  dracula,
  dune,
  sage,
  monokai,
  tokyoNight,
  iceberg,
  radient,
  neon,
  obsidian,
  synth,
  /* classics — the editor schemes users arrive knowing */
  catppuccinMocha,
  catppuccinLatte,
  tokyoNightStorm,
  gruvbox,
  nord,
  oneDark,
  solarizedDark,
  /* rosé pine — the three flavours, dark then light, as the TUI lists them */
  rosePine,
  rosePineMoon,
  rosePineDawn,
  /*
   * companions — the daylight half of a darker palette, plus the mid
   * flavours
   */
  alucard,
  gruvboxLight,
  tokyoNightDay,
  oneLight,
  catppuccinFrappe,
  catppuccinMacchiato,
  palenight,
  /* modern — the newer non-terminal schemes, several with a light sibling */
  everforest,
  everforestLight,
  kanagawaWave,
  kanagawaLotus,
  ayuDark,
  ayuMirage,
  ayuLight,
  nightfox,
  duskfox,
  /* neon/retro — after dark, and the loudest family in the set */
  synthwave,
  matrix,
  tron,
  cyberpunk,
  vaporwave,
  outrun,
  neonNoir,
  arcade,
  /*
   * nature — the earth tones. `radient` has no entry here: it is the brand
   * palette and the TUI's own radient family holds exactly this one ramp,
   * which already sits above with the palettes that shipped.
   */
  forest,
  ocean,
  desert,
  autumn,
  lavender,
  arctic,
  rosewood,
  /* lights — the day ramps, last, at the end of a dark terminal's scroll */
  solarizedLight,
  githubLight,
  paper,
  linen,
  highContrastLight,
  mintLight
];
var themes = Object.fromEntries(
  definitions.map((definition) => [
    definition.id,
    {
      id: definition.id,
      name: definition.name,
      /*
       * Resolve the description KEY here, at read time. The palette files are
       * colour data and carry no copy: a `t()` at their module scope froze
       * bootstrap English (and broke `check-design-kit`, whose esbuild fixture
       * has no i18n module to resolve). Reading here keeps the picker in step
       * with a live language switch for the same reason the earlier getter
       * existed.
       */
      get description() {
        return t(definition.descriptionKey);
      },
      theme: createBaseTheme(definition.palette)
    }
  ])
);
var definitionOf = (id2) => definitions.find((definition) => definition.id === id2);
var isThemeName = (id2) => Object.prototype.hasOwnProperty.call(themes, id2);
var DEFAULT_THEME = "localOperatorDark";
var getTheme = (themeName) => {
  return themes[themeName] || themes[DEFAULT_THEME];
};
var applyThemeToDocument = (themeName) => {
  const option = getTheme(themeName);
  const root = document.documentElement;
  root.dataset.theme = option.id;
  root.classList.toggle("dark", option.theme.palette.mode === "dark");
};
if (typeof document !== "undefined" && !document.documentElement.dataset.theme) {
  applyThemeToDocument(DEFAULT_THEME);
}

